def _extract_inside_door_arcs(svg_text: str) -> list[LineString]:
    """Return the drawn swing-arc curves of internal doors.

    Only ``inside door`` instances are considered — cabinet doors and
    every other door class are excluded. Sliding doors have no arc and
    are skipped naturally (their analysis entries carry no ``arc_geoms``).
    """
    result = analyze_door_open(
        svg_text, door_categories=_ARC_BLOCKING_DOOR_CATEGORIES,
    )
    if not result:
        return []
    arcs: list[LineString] = []
    for door in result["doors"]:
        for arc in door.get("arc_geoms", []):
            if arc is not None and not arc.is_empty and arc.length > 1e-9:
                arcs.append(arc)
    return arcs


