def _longest_cotation_line(
    segments: Sequence[Tuple[float, float, float, float]],
    words: Sequence[dict],
) -> Optional[dict]:
    """Return the longest horizontal dimension line of a page.

    A dimension line must be crossed by at least two oblique ticks and carry
    a numeric label centred above it. Returns a dict with the measured
    ``span`` (distance between the extreme ticks) and the ``label`` text.
    """
    h_lines = _horizontal_lines(segments)
    if not h_lines:
        return None
    ticks = _oblique_ticks(segments)
    if len(ticks) < 2:
        return None
    h_lines.sort(key=lambda l: l["length"], reverse=True)
    for line in h_lines:
        span = _measure_span_between_ticks(line, ticks)
        if span is None:
            continue
        midx = (line["xmin"] + line["xmax"]) / 2.0
        best_label: Optional[str] = None
        best_dist = float("inf")
        for w in words:
            text = (w.get("text") or "").strip()
            if not re.fullmatch(r"\d[\d ]*(?:[.,]\d{1,3})?", text):
                continue
            try:
                cx = (float(w["x0"]) + float(w["x1"])) / 2.0
                gap = line["y"] - float(w["bottom"])
            except (KeyError, TypeError, ValueError):
                continue
            if gap < -COTATION_LABEL_ABOVE_TOL_PT or gap > COTATION_LABEL_MAX_GAP_PT:
                continue
