};

const shouldPerfDebug = () => {
  if (!PERF_DEBUG_STATE.initialized) {
    PERF_DEBUG_STATE.enabled = isPerfDebugEnabled();
    PERF_DEBUG_STATE.initialized = true;
    if (PERF_DEBUG_STATE.enabled) {
      console.info('[perf] debug instrumentation enabled');
    }
