// --- Split selected primitives -----------------------------------------
// Decompose each selected primitive (path/polyline/polygon/line) into one
// new primitive per straight-line segment. Style, classId and overlays
// are propagated to every fragment so visual classification is preserved.
const _splitParseFloats = (s) =>
  (s || '').trim().split(/[\s,]+/).filter(Boolean).map(Number);

const _splitDecomposePathD = (d) => {
  // Returns an array of [[x1,y1],[x2,y2]] segments, or null if d contains
  // commands we don't safely split (curves, arcs, etc.).
  const tokens = (d || '').match(/[MmLlHhVvZz][^MmLlHhVvCcSsQqTtAaZz]*/g);
  if (!tokens) return null;
  if (/[CcSsQqTtAa]/.test(d)) return null;
  const segments = [];
  let cur = null;
  let start = null;
  for (const tok of tokens) {
    const cmd = tok[0];
    const args = _splitParseFloats(tok.slice(1));
    const abs = cmd === cmd.toUpperCase();
    if (cmd === 'M' || cmd === 'm') {
      if (args.length < 2) return null;
      let x = args[0], y = args[1];
      if (!abs && cur) { x += cur[0]; y += cur[1]; }
      cur = [x, y];
      start = [x, y];
      // Implicit Lineto for additional pairs after the moveto target
      for (let i = 2; i + 1 < args.length; i += 2) {
        let nx = args[i], ny = args[i + 1];
        if (!abs) { nx += cur[0]; ny += cur[1]; }
        segments.push([cur, [nx, ny]]);
        cur = [nx, ny];
      }
    } else if (cmd === 'L' || cmd === 'l') {
      for (let i = 0; i + 1 < args.length; i += 2) {
        if (!cur) return null;
        let nx = args[i], ny = args[i + 1];
        if (!abs) { nx += cur[0]; ny += cur[1]; }
        segments.push([cur, [nx, ny]]);
        cur = [nx, ny];
      }
    } else if (cmd === 'H' || cmd === 'h') {
      for (const v of args) {
        if (!cur) return null;
        const nx = abs ? v : cur[0] + v;
        segments.push([cur, [nx, cur[1]]]);
        cur = [nx, cur[1]];
      }
    } else if (cmd === 'V' || cmd === 'v') {
      for (const v of args) {
        if (!cur) return null;
        const ny = abs ? v : cur[1] + v;
        segments.push([cur, [cur[0], ny]]);
        cur = [cur[0], ny];
      }
    } else if (cmd === 'Z' || cmd === 'z') {
      if (cur && start && (cur[0] !== start[0] || cur[1] !== start[1])) {
        segments.push([cur, start]);
        cur = start;
      }
    }
  }
  return segments;
};

const _splitDecomposeElement = (el) => {
  const tag = el.tagName.toLowerCase();
  if (tag === 'line') {
    const x1 = parseFloat(el.getAttribute('x1') || '0');
    const y1 = parseFloat(el.getAttribute('y1') || '0');
    const x2 = parseFloat(el.getAttribute('x2') || '0');
    const y2 = parseFloat(el.getAttribute('y2') || '0');
    return [[[x1, y1], [x2, y2]]];
  }
  if (tag === 'polyline' || tag === 'polygon') {
    const pts = _splitParseFloats(el.getAttribute('points') || '');
    if (pts.length < 4) return null;
    const segments = [];
    for (let i = 2; i + 1 < pts.length; i += 2) {
      segments.push([[pts[i - 2], pts[i - 1]], [pts[i], pts[i + 1]]]);
    }
    if (tag === 'polygon' && pts.length >= 4) {
      segments.push([[pts[pts.length - 2], pts[pts.length - 1]], [pts[0], pts[1]]]);
    }
    return segments;
  }
  if (tag === 'path') {
    return _splitDecomposePathD(el.getAttribute('d') || '');
  }
  return null;
};

const _splitFmt = (n) => {
  if (!Number.isFinite(n)) return '0';
  const r = Math.round(n * 100000) / 100000;
  return Number.isInteger(r) ? String(r) : String(r);
};

const _splitNextUidFactory = (svg) => {
  let maxN = 0;
  svg.querySelectorAll('[data-uid]').forEach((el) => {
    const v = (el.getAttribute('data-uid') || '').trim();
    const n = parseInt(v, 10);
    if (Number.isFinite(n) && n > maxN) maxN = n;
  });
  let next = maxN + 1;
  return () => {
    const v = String(next);
    next += 1;
    return v;
  };
};

window.splitSelectedPrimitives = async () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return 0;
  const selected = Array.from(svg.querySelectorAll('[data-selected="true"]'));
  if (!selected.length) return 0;
  const allocUid = _splitNextUidFactory(svg);
  let totalCreated = 0;
  let totalReplaced = 0;
  const skipped = [];

  for (const el of selected) {
    const segments = _splitDecomposeElement(el);
    if (!segments || segments.length < 2) {
      // Nothing to split (already one segment or unsupported geometry)
      if (segments === null) skipped.push(el.tagName.toLowerCase());
      continue;
    }
    const oldUid = el.getAttribute('data-uid');
    if (window.removeClassOverlay) window.removeClassOverlay(el);
    // Belt-and-braces: also remove any leftover overlay still pointing to oldUid
    if (oldUid) {
      svg.querySelectorAll(
        `[data-class-overlay-for="${CSS.escape(oldUid)}"]`,
      ).forEach((n) => n.remove());
    }
    const parent = el.parentNode;
    const anchor = el.nextSibling;
    const newEls = [];
    for (const [a, b] of segments) {
      const seg = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      // Copy attrs but reset identity / selection / overlay markers
      for (const attr of Array.from(el.attributes)) {
        if (
          attr.name === 'd' || attr.name === 'points'
          || attr.name === 'x1' || attr.name === 'y1'
          || attr.name === 'x2' || attr.name === 'y2'
          || attr.name === 'id' || attr.name === 'data-uid'
          || attr.name === 'data-selected' || attr.name === 'data-selected-overlay'
          || attr.name === 'data-class-overlay' || attr.name === 'data-class-overlay-for'
        ) continue;
        seg.setAttribute(attr.name, attr.value);
      }
      seg.setAttribute('d', `M ${_splitFmt(a[0])} ${_splitFmt(a[1])} L ${_splitFmt(b[0])} ${_splitFmt(b[1])}`);
      seg.setAttribute('data-uid', allocUid());
      parent.insertBefore(seg, anchor);
      newEls.push(seg);
    }
    el.remove();
    for (const seg of newEls) {
      window.ensureElementClassOverlay?.(seg);
    }
    totalCreated += newEls.length;
    totalReplaced += 1;
  }

  if (totalReplaced > 0) {
    window.updateSelectionState?.();
    // Save in the "protected" version, mirroring the Save button:
    // - annotation mode: tile-based annotated save
    // - normal mode: overwrite the existing internal SVG (no timestamp)
    const isAnnot = typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE;
    try {
      if (isAnnot) {
        await window.annotManualSaveTile?.();
      } else {
        await window.saveInternalSvgOverwrite?.();
      }
    } catch (err) {
      console.error('[split] save failed', err);
    }
  }
  if (skipped.length) {
    console.warn(
      `[split] ${skipped.length} primitive(s) skipped (curves/arcs not split): ${skipped.join(', ')}`,
    );
  }
  return totalCreated;
};

// Sélection par rectangle (drag) ou lasso selon window.__lassoMode
window.handleSvgSelectionRect = (e) => {
  if (e.shiftKey || isCtrlOrCmd(e)) return;
  const container = e.currentTarget;
  const svg = container.tagName.toLowerCase() === 'svg' ? container : container.querySelector('svg');
  if (!svg) return;
  const t = e.target;
  const tag = (t?.tagName || '').toLowerCase();
  const primitives = ['path','line','polyline','polygon','rect','circle','ellipse','text'];
  // Allow rectangle/lasso selection to start on frozen primitives (they act as background)
  if (primitives.includes(tag)) {
    const tClassId = (t.getAttribute('classId') || t.getAttribute('classid') || '').trim().toLowerCase();
    if (tClassId !== 'frozen') return;
  }
  e.preventDefault();

  const toSvgPoint = (evt) => {
    const pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    const ctm = svg.getScreenCTM();
    if (!ctm) return {x: 0, y: 0};
    const p = pt.matrixTransform(ctm.inverse());
    return {x: p.x, y: p.y};
  };

  const lasso = !!window.__lassoMode;
  svg.__selectionMode = lasso ? 'lasso' : 'rect';

  // Cleanup any lingering visual from the other mode
  const cleanupVisuals = () => {
    if (svg.__selectionRect) {
      svg.__selectionRect.remove();
      svg.__selectionRect = null;
    }
    if (svg.__selectionLasso) {
      svg.__selectionLasso.remove();
      svg.__selectionLasso = null;
    }
    svg.querySelectorAll('[data-selection-rect="true"]').forEach((n) => n.remove());
    svg.querySelectorAll('[data-selection-lasso="true"]').forEach((n) => n.remove());
  };
  cleanupVisuals();

  const start = toSvgPoint(e);
  svg.__selectionActive = true;
  svg.__selectionStart = start;

  if (lasso) {
    const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    poly.setAttribute('id', '__selection_lasso');
    poly.setAttribute('data-selection-lasso', 'true');
    poly.setAttribute('fill', 'rgba(0,0,255,0.25)');
    poly.setAttribute('stroke', '#0000ff');
    poly.setAttribute('stroke-width', '0.1');
    poly.setAttribute('stroke-dasharray', '0.3 0.2');
    poly.setAttribute('vector-effect', 'non-scaling-stroke');
    poly.setAttribute('style', 'fill:rgba(0,0,255,0.25);stroke:#0000ff;stroke-width:0.1;stroke-dasharray:0.3 0.2;vector-effect:non-scaling-stroke;');
    poly.setAttribute('pointer-events', 'none');
    svg.appendChild(poly);
    svg.__selectionLasso = poly;
    svg.__selectionLassoPoints = [start];
    poly.setAttribute('points', `${start.x},${start.y}`);
    // Cache CTM scale so onMove can threshold in screen pixels (independent of zoom)
    const startCtm = svg.getScreenCTM();
    svg.__selectionLassoScaleX = startCtm ? startCtm.a : 1;
    svg.__selectionLassoScaleY = startCtm ? startCtm.d : 1;
  } else {
    const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    r.setAttribute('id', '__selection');
    r.setAttribute('data-selection-rect', 'true');
    r.setAttribute('fill', 'rgba(0,0,255,0.25)');
    r.setAttribute('stroke', '#0000ff');
    r.setAttribute('stroke-width', '0.1');
    r.setAttribute('stroke-dasharray', '0.3 0.2');
    r.setAttribute('vector-effect', 'non-scaling-stroke');
    r.setAttribute('style', 'fill:rgba(0,0,255,0.25);stroke:#0000ff;stroke-width:0.1;stroke-dasharray:0.3 0.2;vector-effect:non-scaling-stroke;');
    r.setAttribute('pointer-events', 'none');
    r.setAttribute('visibility', 'visible');
    svg.appendChild(r);
    svg.__selectionRect = r;
    r.setAttribute('x', start.x);
    r.setAttribute('y', start.y);
    r.setAttribute('width', 0);
    r.setAttribute('height', 0);
  }

  const finishSelectionFromCandidates = (candidates, predicate, label) => {
    const onUpStartedAt = performance.now();
    const selectionEpoch = (Number(svg.__selectionEpoch) || 0) + 1;
    svg.__selectionEpoch = selectionEpoch;
    if (!candidates.length) {
      cleanupVisuals();
      return;
    }
    withBusyGuard(label, 'Analyse des primitives', async () => {
      const historyEntries = [];
      let insideCount = 0;
      let selectedCount = 0;
      window.appendLoadingModalLog?.(`Candidats a evaluer: ${candidates.length}`);
      const loopStartedAt = performance.now();
      const select = (el) => {
        if (el.hasAttribute('data-selected')) return false;
        const historyEntry = window.createSelectionHistoryEntry?.(el, true) || null;
        const stroke = el.getAttribute('stroke');
        const fill = el.getAttribute('fill');
        const hasStroke = !!stroke && stroke !== 'none';
        const hasFill = !!fill && fill !== 'none';
        if (!hasStroke && !hasFill) return false;
        if (!el.hasAttribute('data-orig-stroke')) {
          el.setAttribute('data-orig-stroke', stroke ?? '');
        }
        el.setAttribute('data-selected', 'true');
        if (window.addSelectionOverlay) window.addSelectionOverlay(el);
        if (historyEntry) historyEntries.push(historyEntry);
        selectedCount += 1;
        return true;
      };
      const completed = await processInAnimationBatches(candidates, (entry) => {
        const el = entry.el;
        if (!el) return;
        if (el.getAttribute('data-hidden-by-class') === 'true' || el.style.display === 'none') return;
        // Frozen elements (overlap zone context) cannot be selected
        const elClassId = (el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
        if (elClassId === 'frozen') return;
        const bbox = entry.bbox || getSelectionLocalBBox(el);
        if (!bbox) return;
        if (predicate(bbox)) {
          insideCount += 1;
          select(el);
        }
      }, {
        batchSize: 50,
        shouldContinue: () => (Number(svg.__selectionEpoch) || 0) === selectionEpoch,
        onProgress: (done, total) => window.setLoadingModalStatus?.('En cours', `Selection: ${done}/${total} (${selectedCount} retenus)`),
      });
      if (!completed) return;
      const loopMs = performance.now() - loopStartedAt;
      cleanupVisuals();
      window.pushAnnotationHistoryEntries?.(historyEntries);
      if (window.updateSelectionState) window.updateSelectionState();
      window.appendLoadingModalLog?.(`${selectedCount} elements selectionnes en ${formatPerfMs(performance.now() - onUpStartedAt)}`);
      perfDebugLog(`${label}.onUp`, {
        scanned_count: candidates.length,
        inside_count: insideCount,
        selected_count: selectedCount,
        history_entries: historyEntries.length,
        loop_ms: roundPerfMs(loopMs),
        total_ms: roundPerfMs(performance.now() - onUpStartedAt),
      });
    });
  };

  if (!svg.__selectionListeners) {
    const onMove = (evt) => {
      if (!svg.__selectionActive) return;
      const cur = toSvgPoint(evt);
      if (svg.__selectionMode === 'lasso') {
        if (!svg.__selectionLasso) return;
        const pts = svg.__selectionLassoPoints || [];
        const last = pts[pts.length - 1];
        // Thinning in screen space (~0.5 pixel) — independent of zoom level
        if (last) {
          const sx = svg.__selectionLassoScaleX || 1;
          const sy = svg.__selectionLassoScaleY || 1;
          const sdx = (cur.x - last.x) * sx;
          const sdy = (cur.y - last.y) * sy;
          if ((sdx * sdx + sdy * sdy) < 0.25) return;
        }
        pts.push(cur);
        svg.__selectionLassoPoints = pts;
        // Incremental O(1) append via SVGPointList instead of rebuilding the
        // full `points` string each time (which was O(n²) over the drag).
        try {
          const svgPt = svg.createSVGPoint();
          svgPt.x = cur.x;
          svgPt.y = cur.y;
          svg.__selectionLasso.points.appendItem(svgPt);
        } catch (_) {
          svg.__selectionLasso.setAttribute(
            'points',
            pts.map((p) => `${p.x},${p.y}`).join(' '),
          );
        }
      } else {
        if (!svg.__selectionRect) return;
        const x = Math.min(svg.__selectionStart.x, cur.x);
        const y = Math.min(svg.__selectionStart.y, cur.y);
        const w = Math.abs(svg.__selectionStart.x - cur.x);
        const h = Math.abs(svg.__selectionStart.y - cur.y);
        svg.__selectionRect.setAttribute('x', x);
        svg.__selectionRect.setAttribute('y', y);
        svg.__selectionRect.setAttribute('width', w);
        svg.__selectionRect.setAttribute('height', h);
      }
    };

    const onUp = (evt) => {
      if (!svg.__selectionActive) return;
      svg.__selectionActive = false;
      const cur = toSvgPoint(evt);
      if (svg.__selectionMode === 'lasso') {
        const pts = (svg.__selectionLassoPoints || []).slice();
        // Append final point if it differs from the last one
        const last = pts[pts.length - 1];
        if (!last || last.x !== cur.x || last.y !== cur.y) pts.push(cur);
        // Need at least 3 points and a meaningful screen area to be a real lasso
        if (pts.length < 3) {
          cleanupVisuals();
          return;
        }
        const polyRect = polygonBoundingRect(pts);
        const ctm = svg.getScreenCTM();
        const screenW = ctm && polyRect ? polyRect.w * ctm.a : (polyRect?.w ?? 0);
        const screenH = ctm && polyRect ? polyRect.h * ctm.d : (polyRect?.h ?? 0);
        const MIN_RECT_PX = 2;
        if (Math.abs(screenW) < MIN_RECT_PX || Math.abs(screenH) < MIN_RECT_PX) {
          cleanupVisuals();
          return;
        }
        const candidates = querySelectionCandidates(svg, polyRect);
        finishSelectionFromCandidates(
          candidates,
          (bbox) => bboxInsidePolygon(bbox, pts),
          'Selection lasso',
        );
      } else {
        const x = Math.min(svg.__selectionStart.x, cur.x);
        const y = Math.min(svg.__selectionStart.y, cur.y);
        const w = Math.abs(svg.__selectionStart.x - cur.x);
        const h = Math.abs(svg.__selectionStart.y - cur.y);
        const rect = {x, y, w, h};
        const MIN_RECT_PX = 2;
        const ctm = svg.getScreenCTM();
        const screenW = ctm ? w * ctm.a : w;
        const screenH = ctm ? h * ctm.d : h;
        if (Math.abs(screenW) < MIN_RECT_PX || Math.abs(screenH) < MIN_RECT_PX) {
          if (svg.__selectionRect) {
            svg.__selectionRect.setAttribute('visibility', 'hidden');
          }
          return;
        }
        const candidates = querySelectionCandidates(svg, rect);
        finishSelectionFromCandidates(
          candidates,
          (bbox) => (
            bbox.left >= rect.x &&
            bbox.top >= rect.y &&
            bbox.right <= (rect.x + rect.w) &&
            bbox.bottom <= (rect.y + rect.h)
          ),
          'Selection rectangle',
        );
      }
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    svg.__selectionListeners = {onMove, onUp};
  }
};

// ── Annotation mode ─────────────────────────────────────────────────────────

window.__annotState = {
  tileName: null,
  tileIndex: -1,
  totalTiles: 0,
};

window.annotLoadCurrentTile = async () => {
  if (typeof ANNOT_MODE === 'undefined' || !ANNOT_MODE) return;
  // Cancel any pending debounced saves to prevent stale saves after tile switch
  if (window.__annotSaveTileTimer) {
    window.clearTimeout(window.__annotSaveTileTimer);
    window.__annotSaveTileTimer = null;
  }
  if (window._annotSaveTimer) {
    window.clearTimeout(window._annotSaveTimer);
    window._annotSaveTimer = null;
  }
  window.openLoadingModal?.({title: 'Chargement de la tuile', status: 'En cours', step: 'Récupération des métadonnées...'});
  // Block any concurrent save while we mutate the DOM. State is updated
  // only AFTER applySvgText so that on any throw between fetch and render,
  // state.tileName stays aligned with the DOM (still showing the previous
  // tile). Heartbeat/logout/manual saves are gated by this flag too.
  window.__annotTileSwitching = true;
  try {
    window.appendLoadingModalLog?.('Requête /annotation/current...');
    const res = await fetch('/annotation/current');
    if (window.handleAnnotAuthError(res)) return;
    if (!res.ok) {
      window.setLoadingModalStatus?.('Erreur', `Serveur: ${res.status}`);
      window.appendLoadingModalLog?.(`Erreur ${res.status}`, 'error');
      window.setTimeout(() => window.closeLoadingModal?.(), 2000);
      return;
    }
    const data = await res.json();
    if (!data?.ok) {
      window.closeLoadingModal?.();
      return;
    }
    if (data.done) {
      window.__annotState.tileName = null;
      window.annotUpdateInfoBar('All tiles are fully annotated.');
      window.setLoadingModalStatus?.('Terminé', 'Toutes les tuiles sont annotées');
      window.setTimeout(() => window.closeLoadingModal?.(), 400);
      return;
    }
    // Capture incoming tile data into locals — DON'T touch __annotState yet.
    const incomingName = data.tile_name;
    const incomingIndex = data.tile_index;
    const incomingTotal = data.total_tiles;
    const incomingSvgUrl = data.svg_url;

    window.setLoadingModalStatus?.('En cours', `Téléchargement SVG: ${incomingName}`);
    window.appendLoadingModalLog?.(`Tuile ${incomingIndex + 1}/${incomingTotal}: ${incomingName}`);
    const svgRes = await fetch(incomingSvgUrl, {cache: 'no-store'});
    const svgText = await svgRes.text();
    window.appendLoadingModalLog?.(`SVG reçu (${(svgText.length / 1024).toFixed(0)} KB)`);
    window.setLoadingModalStatus?.('En cours', 'Rendu SVG...');
    window.applySvgText(svgText);

    // DOM now reflects the new tile — safe to publish into state.
    window.__annotState.tileName = incomingName;
    window.__annotState.tileIndex = incomingIndex;
    window.__annotState.totalTiles = incomingTotal;
    try { localStorage.setItem(window.__annotStorageKey('annot_last_tile'), String(incomingIndex)); } catch (_) {}
    window.setCurrentSvgExportName(incomingName);

    window.annotReapplyClassVisibility();
    window.annotUpdateInfoBar();
    window.setLoadingModalStatus?.('Terminé', incomingName);
    window.appendLoadingModalLog?.('Tuile chargée');
    window.setTimeout(() => window.closeLoadingModal?.(), 400);
  } catch (err) {
    console.error('Annot: failed to load tile', err);
    window.setLoadingModalStatus?.('Erreur', String(err?.message || err));
    window.appendLoadingModalLog?.(String(err?.message || err), 'error');
  } finally {
    window.__annotTileSwitching = false;
  }
};

// Lazy-init save Web Worker (offloads string formatting from main thread)
let _saveWorker = null;
const _getSaveWorker = () => {
  if (!_saveWorker) {
    _saveWorker = new Worker('/assets/save-worker.js');
  }
  return _saveWorker;
};

// Namespace localStorage keys by ANNOT_USER_KEY (basename of
// --annotation-dir, e.g. "user1"). In production each container has
// its own origin so the value is the same across containers; in dev
// running multiple users in the same browser would otherwise share
// state and cause out-of-range tile indexes / poison pending saves.
window.__annotStorageKey = (base) => {
  const k = (typeof ANNOT_USER_KEY === 'string') ? ANNOT_USER_KEY : '';
  return k ? `${base}:${k}` : base;
};

// One-shot migration of pre-namespaced keys. Reads the legacy bare
// key, copies it into the namespaced key, then removes the legacy.
// Idempotent — runs once per page load before any read.
window.__annotMigrateKey = (base) => {
  const target = window.__annotStorageKey(base);
  if (target === base) return;
  try {
    if (localStorage.getItem(target) === null) {
      const legacy = localStorage.getItem(base);
      if (legacy !== null) {
        localStorage.setItem(target, legacy);
        localStorage.removeItem(base);
      }
    }
  } catch (_) {}
};

// localStorage key used to recover an annotation tile save that didn't reach
// the server (auth expiry, network error, page reload). Replayed at the next
// init before any tile loads — see initAppUiAfterAuth.
window.__ANNOT_PENDING_SAVE_KEY = window.__annotStorageKey('annot_pending_save');

// Save button state in the main toolbar — driven by every save path
// (manual, debounced, navigation flush, logout flush).
window.setAnnotSaveStatus = (state, payload = {}) => {
  const btn = document.getElementById('annot-save-btn');
  const label = document.getElementById('annot-save-label');
  if (!btn || !label) return;
  btn.classList.toggle('is-saving', state === 'saving');
  label.classList.toggle('is-saving', state === 'saving');
  label.classList.toggle('is-saved', state === 'saved');
  label.classList.toggle('is-error', state === 'error');
  if (state === 'saving') {
    label.textContent = 'Saving...';
    btn.title = 'Sauvegarde en cours';
  } else if (state === 'saved') {
    const ts = payload.ts instanceof Date ? payload.ts : new Date();
    const hh = String(ts.getHours()).padStart(2, '0');
    const mm = String(ts.getMinutes()).padStart(2, '0');
    const ss = String(ts.getSeconds()).padStart(2, '0');
    label.textContent = `Saved ${hh}:${mm}:${ss}`;
    btn.title = `Dernière sauvegarde à ${hh}:${mm}:${ss}`;
  } else if (state === 'error') {
    label.textContent = `Erreur (${payload.reason || '?'})`;
    btn.title = 'Échec de la sauvegarde — cliquer pour réessayer';
  } else {
    label.textContent = 'Save';
    btn.title = 'Sauvegarder maintenant';
  }
};

const _stashPendingSave = (tileName, svgText, reason) => {
  try {
    localStorage.setItem(window.__ANNOT_PENDING_SAVE_KEY, JSON.stringify({
      tile_name: tileName,
      svg_text: svgText,
      ts: Date.now(),
      reason,
    }));
    console.warn(`[annotSave] stashed for recovery (${reason}): ${tileName}`);
  } catch (e) {
    console.error('[annotSave] failed to stash pending save', e);
  }
};

const _clearPendingSave = () => {
  try { localStorage.removeItem(window.__ANNOT_PENDING_SAVE_KEY); } catch (_) {}
};

// Returns {ok: true} on success, {ok: false, reason} on failure. On any
// failure (network, http error, auth expiry, empty serialization) the
// serialized payload is stashed to localStorage so it can be replayed on
// the next init. Callers should NOT assume success based on resolution.
window.annotSaveTile = async () => {
  if (!ANNOT_MODE || !window.__annotState.tileName) return {ok: false, reason: 'no-tile'};
  // Block: state.tileName has advanced but the DOM still belongs to the
  // previous tile (or vice-versa). Saving now would persist mismatched
  // content under the wrong name. The pre-transition save already ran.
  if (window.__annotTileSwitching) {
    console.warn('[annotSave] skipped: tile transition in progress');
    return {ok: false, reason: 'switching'};
  }
  // Capture tile name NOW — before any async work — to prevent race conditions
  // when the user switches tiles while serialization/worker is in progress.
  const snapshotTileName = window.__annotState.tileName;
  const saveStart = performance.now();
  window.setAnnotSaveStatus?.('saving');
  await new Promise((r) => setTimeout(r, 0));

  // DOM serialization (must stay on main thread)
  const serStart = performance.now();
  const serializedSvg = window.serializeFullSvgForSave?.();
  const serMs = performance.now() - serStart;
  if (!serializedSvg) {
    console.warn('[annotSave] empty serialization, nothing to save');
    window.setAnnotSaveStatus?.('error', {reason: 'empty'});
    return {ok: false, reason: 'empty-serialization'};
  }
  console.log(`[annotSave] serialize: ${serMs.toFixed(0)} ms (${(serializedSvg.length / 1024).toFixed(0)} KB)`);

  await new Promise((r) => setTimeout(r, 0));

  // Offload string processing to Web Worker
  const fmtStart = performance.now();
  const svgText = await new Promise((resolve) => {
    const worker = _getSaveWorker();
    worker.onmessage = (evt) => resolve(evt.data);
    worker.postMessage({
      serializedSvg,
      sourceText: typeof window.__currentSvgSourceText === 'string' ? window.__currentSvgSourceText : '',
    });
  });
  const fmtMs = performance.now() - fmtStart;
  console.log(`[annotSave] format (worker): ${fmtMs.toFixed(0)} ms`);

  if (!svgText) {
    console.warn('[annotSave] worker returned empty payload');
    window.setAnnotSaveStatus?.('error', {reason: 'empty'});
    return {ok: false, reason: 'empty-worker'};
  }

  try {
    const tileName = encodeURIComponent(snapshotTileName);
    const saveRes = await fetch(`/annotation/save?tile_name=${tileName}`, {
      method: 'POST',
      headers: {'Content-Type': 'text/plain; charset=utf-8'},
      body: svgText,
    });
    const totalMs = performance.now() - saveStart;
    console.log(`[annotSave] total: ${totalMs.toFixed(0)} ms (fetch: ${(totalMs - serMs - fmtMs).toFixed(0)} ms)`);
    if (saveRes.status === 401) {
      // Stash BEFORE the auth handler shows the login modal — so a reload
      // (manual or via showAnnotLoginModal flow) will replay this save.
      _stashPendingSave(snapshotTileName, svgText, 'auth-401');
      window.setAnnotSaveStatus?.('error', {reason: 'auth'});
      window.handleAnnotAuthError(saveRes);
      return {ok: false, reason: 'auth', status: 401};
    }
    if (saveRes.status === 409) {
      // Server rejected the save because the SVG body's identity attrs
      // (data-source-svg / data-tile-row / data-tile-col) don't match
      // ``snapshotTileName``. This indicates a client-side desync that
      // we can't fix by retrying — replaying the same payload would 409
      // again. Drop any stashed copy so we don't poison future reloads,
      // surface the error, and prompt the user to reload to recover.
      _clearPendingSave();
      let detail = '';
      try {
        const body = await saveRes.json();
        detail = JSON.stringify(body);
        console.error(`[annotSave] 409 identity mismatch for ${snapshotTileName}: ${detail}`);
      } catch (_) {
        console.error(`[annotSave] 409 identity mismatch for ${snapshotTileName} (no body)`);
      }
      window.setAnnotSaveStatus?.('error', {reason: 'mismatch'});
      try {
        alert(
          'Sauvegarde refusée par le serveur : le contenu de la tuile ne ' +
          'correspond pas à son nom (incohérence détectée).\n\nLa page va se ' +
          'recharger pour récupérer un état propre.'
        );
      } catch (_) {}
      try { window.location.reload(); } catch (_) {}
      return {ok: false, reason: 'mismatch', status: 409, detail};
    }
    if (!saveRes.ok) {
      _stashPendingSave(snapshotTileName, svgText, `http-${saveRes.status}`);
      window.setAnnotSaveStatus?.('error', {reason: `${saveRes.status}`});
      return {ok: false, reason: 'http', status: saveRes.status};
    }
    _clearPendingSave();
    window.setAnnotSaveStatus?.('saved', {ts: new Date()});
    return {ok: true};
  } catch (err) {
    console.error('Annot: save failed', err);
    _stashPendingSave(snapshotTileName, svgText, 'network');
    window.setAnnotSaveStatus?.('error', {reason: 'net'});
    return {ok: false, reason: 'network', error: String(err?.message || err)};
  }
};

