// Build SVG content containing only currently-selected primitives (and their class overlays).
// Returns null if nothing is selected or no SVG is loaded.
window.buildSelectionSvgContent = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return null;
  const selected = Array.from(svg.querySelectorAll('[data-selected="true"]'));
  if (!selected.length) return null;
  const selectedUids = new Set(selected.map(el => el.getAttribute('data-uid')).filter(Boolean));
  const clone = svg.cloneNode(true);
  if (svg.__origViewBox) {
    clone.setAttribute('viewBox', svg.__origViewBox);
  }
  const toRemove = [];
  clone.querySelectorAll('*').forEach(el => {
    if (el.hasAttribute('data-selection-overlay-for')) {
      toRemove.push(el);
    } else if (el.hasAttribute('data-class-overlay-for')) {
      if (!selectedUids.has(el.getAttribute('data-class-overlay-for'))) {
        toRemove.push(el);
      }
    } else if (el.hasAttribute('data-uid') && !selectedUids.has(el.getAttribute('data-uid'))) {
      toRemove.push(el);
    }
  });
  toRemove.forEach(el => el.remove());
  clone.querySelectorAll('[data-selected]').forEach(el => el.removeAttribute('data-selected'));
  clone.querySelectorAll('[data-selected-overlay]').forEach(el => el.removeAttribute('data-selected-overlay'));
  clone.querySelectorAll('[data-hidden-by-class]').forEach(el => {
    const orig = el.getAttribute('data-orig-display');
    el.style.display = orig !== null ? orig : '';
    el.removeAttribute('data-hidden-by-class');
    el.removeAttribute('data-orig-display');
  });
  clone.querySelectorAll('[data-class-overlay-for]').forEach(el => {
    el.style.display = '';
  });
  const vb = clone.getAttribute('viewBox');
  if (vb) {
    const parts = vb.split(/\s+/).map(Number);
    if (parts.length === 4) {
      clone.querySelectorAll('clipPath').forEach(cp => {
        if (!cp.children.length) {
          const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          rect.setAttribute('x', parts[0]);
          rect.setAttribute('y', parts[1]);
          rect.setAttribute('width', parts[2]);
          rect.setAttribute('height', parts[3]);
          cp.appendChild(rect);
        }
      });
    }
  }
  const serializer = new XMLSerializer();
  return formatSvgForExport(serializer.serializeToString(clone));
};

