      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({filename, svg: content}),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data?.ok) {
      const msg = data?.error || `HTTP ${res.status}`;
      console.error('Save internal failed:', msg);
      throw new Error(msg);
    }
    window.appendLoadingModalLog?.(`Saved: data/svgs/${data.name}`);
    console.log(`Saved internal SVG: data/svgs/${data.name}`);
  });
};

