window.createHistoryEntry = ({
  el,
  actionType = 'class-assignment',
  className = '',
  next = {},
} = {}) => {
  if (!el) return null;
  const uid = el.getAttribute('data-uid');
  if (!uid) return null;
  const normalizedClassName = String(className || '').trim();
  const classKey = normalizedClassName.toLowerCase();
  const previousSelected = el.getAttribute('data-selected') === 'true';
  return {
    id: `${uid}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    actionType,
    uid,
    primitiveType: (el.tagName || 'primitive').toLowerCase(),
    className: normalizedClassName,
    classColor: CLASS_NAME_COLOR_MAP[classKey] || '#64748b',
    timestamp: Date.now(),
    previous: {
      classId: el.getAttribute('classId') ?? el.getAttribute('classid') ?? null,
      hiddenByClass: el.getAttribute('data-hidden-by-class') === 'true',
      origDisplay: el.getAttribute('data-orig-display'),
      inlineDisplay: el.style.display || '',
      selected: previousSelected,
    },
    next: {
      classId: Object.prototype.hasOwnProperty.call(next, 'classId') ? next.classId : normalizedClassName,
      hiddenByClass: Object.prototype.hasOwnProperty.call(next, 'hiddenByClass') ? next.hiddenByClass : false,
      inlineDisplay: Object.prototype.hasOwnProperty.call(next, 'inlineDisplay') ? next.inlineDisplay : '',
      selected: Object.prototype.hasOwnProperty.call(next, 'selected') ? next.selected : previousSelected,
    },
  };
};

window.createAnnotationHistoryEntry = (el, className) => window.createHistoryEntry({
  el,
  actionType: 'class-assignment',
  className,
  next: {
    classId: String(className || '').trim() || null,
    hiddenByClass: false,
    inlineDisplay: '',
    selected: true,
  },
});

window.createSelectionHistoryEntry = (el, selected) => window.createHistoryEntry({
  el,
  actionType: 'selection',
  next: {
    classId: el.getAttribute('classId') ?? el.getAttribute('classid') ?? null,
    hiddenByClass: el.getAttribute('data-hidden-by-class') === 'true',
    inlineDisplay: el.style.display || '',
    selected: !!selected,
  },
});

window.pushAnnotationHistoryEntry = (entry) => {
  if (!entry) return;
  const state = getAnnotationHistoryState();
  state.items.push(entry);
  scheduleAnnotationHistoryRender();
};

window.pushAnnotationHistoryEntries = (entries) => {
  if (!Array.isArray(entries)) return;
  const valid = entries.filter(Boolean);
  if (!valid.length) return;
  const state = getAnnotationHistoryState();
  if (valid.length === 1) {
    state.items.push(valid[0]);
  } else {
    const first = valid[0];
    state.items.push({
      id: `group-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      isGroup: true,
      entries: valid,
      actionType: first.actionType,
      className: first.className,
      classColor: first.classColor,
      primitiveType: `${valid.length} elements`,
      timestamp: first.timestamp,
    });
  }
  scheduleAnnotationHistoryRender();
};

const restoreHistoryEntryState = (el, snapshot = {}) => {
  if (!el) return;
  if (window.removeClassOverlay) window.removeClassOverlay(el);
  if (window.removeSelectionOverlay) window.removeSelectionOverlay(el);
  el.removeAttribute('data-selected');
  el.removeAttribute('data-hidden-by-class');
  if (el.hasAttribute('classId')) el.removeAttribute('classId');
  if (el.hasAttribute('classid')) el.removeAttribute('classid');

  if (snapshot.classId) {
    el.setAttribute('classId', snapshot.classId);
  }

  if (snapshot.origDisplay !== null && snapshot.origDisplay !== undefined) {
    el.setAttribute('data-orig-display', snapshot.origDisplay);
  } else {
    el.removeAttribute('data-orig-display');
  }

  el.style.display = snapshot.inlineDisplay || '';
  if (snapshot.hiddenByClass) {
    el.setAttribute('data-hidden-by-class', 'true');
    el.style.display = 'none';
  }

  const restoredClassKey = String(snapshot.classId || '').trim().toLowerCase();
  if (snapshot.classId && !snapshot.hiddenByClass && CLASS_NAME_MASK_MAP[restoredClassKey]) {
    const restoredColor = CLASS_NAME_COLOR_MAP[restoredClassKey];
    if (restoredColor && window.addClassOverlay) {
      window.addClassOverlay(el, restoredColor);
    }
  }

  if (snapshot.selected) {
    el.setAttribute('data-selected', 'true');
    if (window.addSelectionOverlay) window.addSelectionOverlay(el);
  }
};

window.undoLastAnnotation = () => {
  const state = getAnnotationHistoryState();
  const entry = state.items.pop();
  if (!entry) {
    window.renderAnnotationHistory?.();
    return;
  }
  const svg = document.querySelector('.svg-clickable svg');
  if (entry.isGroup && Array.isArray(entry.entries)) {
    for (const sub of entry.entries) {
      const selector = `[data-uid="${CSS.escape(String(sub.uid || ''))}"]`;
      const el = svg?.querySelector(selector);
      if (el) restoreHistoryEntryState(el, sub.previous);
    }
    if (entry.actionType === 'class-assignment' && entry.className) {
      const undone = entry.entries.filter((s) => s && s.actionType === 'class-assignment').length;
      if (undone > 0) window.recordAnnotStat?.(entry.className, -undone);
    }
  } else {
    const selector = `[data-uid="${CSS.escape(String(entry.uid || ''))}"]`;
    const el = svg?.querySelector(selector);
    if (el) restoreHistoryEntryState(el, entry.previous);
    if (entry.actionType === 'class-assignment' && entry.className) {
      window.recordAnnotStat?.(entry.className, -1);
    }
  }
  window.renderAnnotationHistory?.();
  window.updateSelectionState?.();
  window.queueAutosave?.({reason: 'undo'});
  window.queueAnnotSaveTile?.();
};

window.setCurrentSvgExportName = (name = '') => {
  const trimmed = typeof name === 'string' ? name.trim() : '';
  const fallback = 'annotated.svg';
  if (!trimmed) {
    window.__currentSvgExportName = fallback;
    return;
  }
  const normalized = trimmed.toLowerCase().endsWith('.svg') ? trimmed : `${trimmed}.svg`;
  window.__currentSvgExportName = normalized;
};

window.serializeCurrentSvg = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return '';
  const serializer = new XMLSerializer();
  return serializer.serializeToString(svg);
};

window.serializeFullSvgForSave = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return '';
  // Temporarily restore hidden elements in the live DOM to avoid
  // an expensive cloneNode(true) on large SVGs.
  const savedViewBox = svg.getAttribute('viewBox');
  if (svg.__origViewBox) svg.setAttribute('viewBox', svg.__origViewBox);

  const hiddenByClass = svg.querySelectorAll('[data-hidden-by-class="true"]');
  const prevDisplay = [];
  hiddenByClass.forEach((el) => {
    prevDisplay.push(el.style.display);
    const orig = el.getAttribute('data-orig-display');
    el.style.display = (orig !== null) ? orig : '';
  });

  const hiddenOverlays = svg.querySelectorAll('[data-class-overlay="true"]');
  const prevOverlayDisplay = [];
  hiddenOverlays.forEach((overlay) => {
    prevOverlayDisplay.push(overlay.style.display);
    overlay.style.display = '';
  });

  // Remove selection overlays (blue highlights) before serializing
  const selectionOverlays = svg.querySelectorAll('[data-selection-overlay="true"]');
  selectionOverlays.forEach(el => el.remove());
  const selectedOverlayMarkers = svg.querySelectorAll('[data-selected-overlay="true"]');
  selectedOverlayMarkers.forEach(el => el.removeAttribute('data-selected-overlay'));

  // Detach access-path overlay layers (analysis results, sanity-check
  // markers) so they never leak into the saved SVG. We re-attach them
  // verbatim afterwards.
  const accessPathLayers = svg.querySelectorAll('g[data-access-path-layer="true"]');
  const detachedAccessLayers = [];
  accessPathLayers.forEach((layer) => {
    detachedAccessLayers.push({parent: layer.parentNode, layer});
    layer.parentNode?.removeChild(layer);
  });

  const serializer = new XMLSerializer();
  const result = serializer.serializeToString(svg);

  // Restore live DOM state — re-add selection overlays for currently selected elements
  selectedOverlayMarkers.forEach(el => window.addSelectionOverlay(el));
  detachedAccessLayers.forEach(({parent, layer}) => parent?.appendChild(layer));
  if (savedViewBox !== null) svg.setAttribute('viewBox', savedViewBox);
  else svg.removeAttribute('viewBox');
  hiddenByClass.forEach((el, i) => { el.style.display = prevDisplay[i]; });
  hiddenOverlays.forEach((overlay, i) => { overlay.style.display = prevOverlayDisplay[i]; });

  return result;
};

const formatSvgForExport = (raw) => {
  if (!raw) return raw;
  return raw
    .replace(/(<\/svg>)/g, '\n$1')
    .replace(/(<(?:path|line|polyline|polygon|rect|circle|ellipse|text|use|g|defs|clipPath|mask|symbol|image|foreignObject)\b)/g, '\n$1')
    .replace(/^\n/, '')
    .replace(/\n[ \t]*\n/g, '\n')
    .replace(/\n{2,}/g, '\n');
};

window.buildAutosaveSvgPayload = () => {
  const serializedSvg = window.serializeFullSvgForSave?.();
  if (!serializedSvg) return '';
  const sourceText = typeof window.__currentSvgSourceText === 'string' ? window.__currentSvgSourceText : '';
  const start = sourceText.search(/<svg[\s>]/i);
  const end = sourceText.toLowerCase().lastIndexOf('</svg>');
  if (start === -1 || end === -1 || end < start) {
    return formatSvgForExport(serializedSvg);
  }
  return formatSvgForExport(`${sourceText.slice(0, start)}${serializedSvg}${sourceText.slice(end + 6)}`);
};

window.queueAutosave = ({reason = 'annotation', immediate = false} = {}) => {
  // In annotation mode, tile save handles persistence — skip autosave to
  // avoid duplicate heavy POST requests that block the server and cause
  // WebSocket heartbeat timeouts ("implicit handshake failed").
  if (typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE) return;
  const state = getAutosaveState();
  state.pendingReason = reason || state.pendingReason || 'annotation';
  if (!state.pendingPromise) {
    state.pendingPromise = new Promise((resolve) => {
      state.pendingResolve = resolve;
    });
  }
  if (state.autosaveTimer) {
    window.clearTimeout(state.autosaveTimer);
    state.autosaveTimer = null;
  }
  const executeReason = state.pendingReason;
  const run = async (runReason) => {
    if (state.restoring) return;
    const lifecycle = getPageLifecycleState();
    await waitForBrowserIdle();
    if (state.restoring || lifecycle.unloading) return;
    const svgText = window.buildAutosaveSvgPayload?.();
    if (!svgText) return;
    state.saving = true;
    try {
      const res = await fetch('/autosave', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
          svg: svgText,
          file_name: window.__currentSvgExportName || 'annotated.svg',
          reason: runReason || 'annotation',
        }),
      });
      const data = await res.json();
      if (!data?.ok) {
        throw new Error(data?.error || 'Autosave failed');
      }
      if (Array.isArray(data?.items)) {
        state.items = data.items;
        window.renderAutosaveList?.();
      } else if (data?.item) {
        state.items = [data.item, ...(state.items || []).filter((item) => item?.id !== data.item.id)];
        window.renderAutosaveList?.();
      }
    } catch (error) {
      if (!lifecycle.unloading) {
        console.error('Autosave failed', error);
      }
    } finally {
      state.saving = false;
    }
  };
  const scheduleDelay = immediate ? 0 : AUTOSAVE_DEBOUNCE_MS;
  state.autosaveTimer = window.setTimeout(() => {
    state.autosaveTimer = null;
    state.pendingReason = '';
    const pendingResolve = state.pendingResolve;
    state.pendingResolve = null;
    const pendingPromise = state.pendingPromise;
    state.pendingPromise = null;
    state.savePromise = state.savePromise.then(
      () => run(executeReason),
      () => run(executeReason),
    ).finally(() => {
      if (typeof pendingResolve === 'function') pendingResolve();
    });
    return pendingPromise;
  }, scheduleDelay);
  return state.pendingPromise;
};

window.flushQueuedAutosave = async () => {
  const state = getAutosaveState();
  if (!state.autosaveTimer) return;
  const pendingReason = state.pendingReason || 'flush';
  window.clearTimeout(state.autosaveTimer);
  state.autosaveTimer = null;
  await window.queueAutosave?.({reason: pendingReason, immediate: true});
};

window.restoreAutosave = async (autosaveId) => {
  if (!autosaveId) return;
  const state = getAutosaveState();
  if (state.restoring) return;
  await window.flushQueuedAutosave?.();
  await state.savePromise;
  state.restoring = true;
  const startedAt = performance.now();
  window.openLoadingModal?.({
    title: 'Restauration autosave',
    status: 'Initialisation',
    step: 'Preparation de la restauration',
  });
  window.appendLoadingModalLog?.(`Autosave id: ${autosaveId}`);
  try {
    window.setLoadingModalStatus?.('Lecture', 'Recuperation autosave depuis le serveur');
    window.appendLoadingModalLog?.('GET /autosave/{id}');
    const res = await fetch(`/autosave/${encodeURIComponent(autosaveId)}`, {method: 'GET', cache: 'no-store'});
    window.appendLoadingModalLog?.(`HTTP status: ${res.status}`);
    const data = await res.json();
    if (!data?.ok || typeof data?.svg !== 'string') {
      throw new Error(data?.error || 'Unable to restore autosave');
    }
    window.appendLoadingModalLog?.('Autosave payload received');
    window.setLoadingModalStatus?.('Application', 'Injection du SVG et reinitialisation UI');
    window.setCurrentSvgExportName(data?.item?.base_name || 'annotated.svg');
    window.applySvgText(data.svg);
    window.setLoadingModalStatus?.('Synchronisation', 'Rafraichissement de la liste autosave');
    await window.refreshAutosaveList?.();
    window.setLoadingModalStatus?.('Termine', 'Autosave restaure');
    window.appendLoadingModalLog?.(`Autosave restored in ${formatPerfMs(performance.now() - startedAt)}`);
    window.setTimeout(() => window.closeLoadingModal?.(), 500);
  } catch (error) {
    window.setLoadingModalStatus?.('Erreur', 'Echec de restauration autosave');
    window.appendLoadingModalLog?.(`Error: ${error instanceof Error ? error.message : String(error)}`, 'error');
    console.error('Autosave restore failed', error);
  } finally {
    state.restoring = false;
  }
};

