// Busy guard: shows loading modal during long operations and prevents concurrent actions.
let __busyGuardActive = false;
const withBusyGuard = async (title, stepLabel, asyncFn) => {
  if (__busyGuardActive) return;
  __busyGuardActive = true;
  window.openLoadingModal?.({title, status: 'En cours', step: stepLabel});
  try {
    await nextAnimationFrame();
    await asyncFn();
    window.setLoadingModalStatus?.('Termine', stepLabel);
    window.setTimeout(() => window.closeLoadingModal?.(), 400);
  } catch (err) {
    window.setLoadingModalStatus?.('Erreur', String(err?.message || err));
    window.appendLoadingModalLog?.(String(err?.message || err), 'error');
  } finally {
    __busyGuardActive = false;
  }
};

window.setLoadingModalStatus = (status, step) => {
  const {status: statusEl, currentStep} = getLoadingModalElements();
  if (statusEl && typeof status === 'string') statusEl.textContent = status;
  if (currentStep && typeof step === 'string') currentStep.textContent = step;
};

window.appendLoadingModalLog = (message, kind = '') => {
  const {log} = getLoadingModalElements();
  if (!log || typeof message !== 'string' || !message.trim()) return;
  if (!Array.isArray(window.__loadingModalLines)) window.__loadingModalLines = [];
  const previous = window.__loadingModalLines[window.__loadingModalLines.length - 1];
  if (previous && previous.message === message && previous.kind === kind) return;
  window.__loadingModalLines.push({message, kind});
  log.innerHTML = window.__loadingModalLines
    .map((line) => `<div class="loading-modal-log-line${line.kind ? ` is-${escapeHtml(line.kind)}` : ''}">${escapeHtml(line.message)}</div>`)
    .join('');
  log.scrollTop = log.scrollHeight;
};

