// Sélection par clic (gestion overlays et évènements)
window.handleSvgClick = (e) => {
  let t = e.target;
  if (!t) return;
  if (e.shiftKey || isCtrlOrCmd(e)) return;
  if (t.getAttribute && t.getAttribute('data-selection-overlay') === 'true') {
    const uid = t.getAttribute('data-selection-overlay-for');
    if (uid) {
      const svg = t.ownerSVGElement;
      const original = svg ? svg.querySelector(`[data-uid="${uid}"]`) : null;
      if (original) t = original;
    }
  }
  if (t.getAttribute && t.getAttribute('data-class-overlay') === 'true') {
    const uid = t.getAttribute('data-class-overlay-for');
    if (uid) {
      const svg = t.ownerSVGElement;
      const original = svg ? svg.querySelector(`[data-uid="${uid}"]`) : null;
      if (original) t = original;
    }
  }
  const tag = (t.tagName || '').toLowerCase();
  const primitives = ['path','line','polyline','polygon','rect','circle','ellipse','text'];
  if (!primitives.includes(tag)) return;
  // Frozen elements (overlap zone context) cannot be selected
  const clickClassId = (t.getAttribute('classId') || t.getAttribute('classid') || '').trim().toLowerCase();
  if (clickClassId === 'frozen') return;
  const svg = t.ownerSVGElement;
  if (svg) {
    if (Number(svg.__panSuppressClickUntil) > performance.now()) {
      return;
    }
    const deselect = (el) => {
      const orig = el.getAttribute('data-orig-stroke-width');
      if (orig !== null) {
        el.setAttribute('stroke-width', orig);
        el.removeAttribute('data-orig-stroke-width');
      }
      const origStroke = el.getAttribute('data-orig-stroke');
      if (origStroke !== null) {
        el.setAttribute('stroke', origStroke);
        el.removeAttribute('data-orig-stroke');
      }
      if (window.removeSelectionOverlay) window.removeSelectionOverlay(el);
      el.removeAttribute('data-selected');
    };
    const select = (el) => {
      if (el.hasAttribute('data-selected')) return;
      const historyEntry = window.createSelectionHistoryEntry?.(el, true) || null;
      const stroke = el.getAttribute('stroke');
      const fill = el.getAttribute('fill');
      const hasStroke = !!stroke && stroke !== 'none';
      const hasFill = !!fill && fill !== 'none';
      if (!hasStroke && !hasFill) return;
      if (!el.hasAttribute('data-orig-stroke')) {
        el.setAttribute('data-orig-stroke', stroke ?? '');
      }
      el.setAttribute('data-selected', 'true');
      if (window.addSelectionOverlay) window.addSelectionOverlay(el);
      window.pushAnnotationHistoryEntry?.(historyEntry);
    };
    if (t.hasAttribute('data-selected')) {
      window.pushAnnotationHistoryEntry?.(window.createSelectionHistoryEntry?.(t, false) || null);
      deselect(t);
      if (window.updateSelectionState) window.updateSelectionState();
      return;
    }
    select(t);
    if (window.updateSelectionState) window.updateSelectionState();
  }
};

// Mode lasso (alternatif au rectangle de sélection)
window.__lassoMode = false;
window.toggleLassoMode = () => {
  window.__lassoMode = !window.__lassoMode;
  const btn = document.getElementById('toggle-lasso-btn');
  if (btn) {
    btn.classList.toggle('is-active', window.__lassoMode);
    btn.setAttribute('aria-pressed', window.__lassoMode ? 'true' : 'false');
    btn.style.background = window.__lassoMode ? '#dbeafe' : '';
    btn.style.borderColor = window.__lassoMode ? '#1d4ed8' : '';
  }
  return window.__lassoMode;
};

// --- Split selected primitives -----------------------------------------
// Decompose each selected primitive (path/polyline/polygon/line) into one
// new primitive per straight-line segment. Style, classId and overlays
// are propagated to every fragment so visual classification is preserved.
const _splitParseFloats = (s) =>
  (s || '').trim().split(/[\s,]+/).filter(Boolean).map(Number);

const _splitDecomposePathD = (d) => {
  // Returns an array of [[x1,y1],[x2,y2]] segments, or null if d contains
  // commands we don't safely split (curves, arcs, etc.).
  const tokens = (d || '').match(/[MmLlHhVvZz][^MmLlHhVvCcSsQqTtAaZz]*/g);
  if (!tokens) return null;
  if (/[CcSsQqTtAa]/.test(d)) return null;
  const segments = [];
  let cur = null;
  let start = null;
  for (const tok of tokens) {
    const cmd = tok[0];
    const args = _splitParseFloats(tok.slice(1));
    const abs = cmd === cmd.toUpperCase();
    if (cmd === 'M' || cmd === 'm') {
      if (args.length < 2) return null;
      let x = args[0], y = args[1];
      if (!abs && cur) { x += cur[0]; y += cur[1]; }
      cur = [x, y];
      start = [x, y];
      // Implicit Lineto for additional pairs after the moveto target
      for (let i = 2; i + 1 < args.length; i += 2) {
        let nx = args[i], ny = args[i + 1];
        if (!abs) { nx += cur[0]; ny += cur[1]; }
        segments.push([cur, [nx, ny]]);
        cur = [nx, ny];
      }
    } else if (cmd === 'L' || cmd === 'l') {
      for (let i = 0; i + 1 < args.length; i += 2) {
        if (!cur) return null;
        let nx = args[i], ny = args[i + 1];
        if (!abs) { nx += cur[0]; ny += cur[1]; }
        segments.push([cur, [nx, ny]]);
        cur = [nx, ny];
      }
    } else if (cmd === 'H' || cmd === 'h') {
      for (const v of args) {
        if (!cur) return null;
        const nx = abs ? v : cur[0] + v;
        segments.push([cur, [nx, cur[1]]]);
        cur = [nx, cur[1]];
      }
    } else if (cmd === 'V' || cmd === 'v') {
      for (const v of args) {
        if (!cur) return null;
        const ny = abs ? v : cur[1] + v;
        segments.push([cur, [cur[0], ny]]);
        cur = [cur[0], ny];
      }
    } else if (cmd === 'Z' || cmd === 'z') {
      if (cur && start && (cur[0] !== start[0] || cur[1] !== start[1])) {
        segments.push([cur, start]);
        cur = start;
      }
    }
  }
  return segments;
};

const _splitDecomposeElement = (el) => {
  const tag = el.tagName.toLowerCase();
  if (tag === 'line') {
    const x1 = parseFloat(el.getAttribute('x1') || '0');
    const y1 = parseFloat(el.getAttribute('y1') || '0');
    const x2 = parseFloat(el.getAttribute('x2') || '0');
    const y2 = parseFloat(el.getAttribute('y2') || '0');
    return [[[x1, y1], [x2, y2]]];
  }
  if (tag === 'polyline' || tag === 'polygon') {
    const pts = _splitParseFloats(el.getAttribute('points') || '');
    if (pts.length < 4) return null;
    const segments = [];
    for (let i = 2; i + 1 < pts.length; i += 2) {
      segments.push([[pts[i - 2], pts[i - 1]], [pts[i], pts[i + 1]]]);
    }
    if (tag === 'polygon' && pts.length >= 4) {
      segments.push([[pts[pts.length - 2], pts[pts.length - 1]], [pts[0], pts[1]]]);
    }
    return segments;
  }
  if (tag === 'path') {
    return _splitDecomposePathD(el.getAttribute('d') || '');
  }
  return null;
};

const _splitFmt = (n) => {
  if (!Number.isFinite(n)) return '0';
  const r = Math.round(n * 100000) / 100000;
  return Number.isInteger(r) ? String(r) : String(r);
};

const _splitNextUidFactory = (svg) => {
  let maxN = 0;
  svg.querySelectorAll('[data-uid]').forEach((el) => {
    const v = (el.getAttribute('data-uid') || '').trim();
    const n = parseInt(v, 10);
    if (Number.isFinite(n) && n > maxN) maxN = n;
  });
  let next = maxN + 1;
  return () => {
    const v = String(next);
    next += 1;
    return v;
  };
};

window.splitSelectedPrimitives = async () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return 0;
  const selected = Array.from(svg.querySelectorAll('[data-selected="true"]'));
  if (!selected.length) return 0;
  const allocUid = _splitNextUidFactory(svg);
  let totalCreated = 0;
  let totalReplaced = 0;
  const skipped = [];

  for (const el of selected) {
    const segments = _splitDecomposeElement(el);
    if (!segments || segments.length < 2) {
      // Nothing to split (already one segment or unsupported geometry)
      if (segments === null) skipped.push(el.tagName.toLowerCase());
      continue;
    }
    const oldUid = el.getAttribute('data-uid');
    if (window.removeClassOverlay) window.removeClassOverlay(el);
    // Belt-and-braces: also remove any leftover overlay still pointing to oldUid
    if (oldUid) {
      svg.querySelectorAll(
        `[data-class-overlay-for="${CSS.escape(oldUid)}"]`,
      ).forEach((n) => n.remove());
    }
    const parent = el.parentNode;
    const anchor = el.nextSibling;
    const newEls = [];
    for (const [a, b] of segments) {
      const seg = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      // Copy attrs but reset identity / selection / overlay markers
      for (const attr of Array.from(el.attributes)) {
        if (
          attr.name === 'd' || attr.name === 'points'
          || attr.name === 'x1' || attr.name === 'y1'
          || attr.name === 'x2' || attr.name === 'y2'
          || attr.name === 'id' || attr.name === 'data-uid'
          || attr.name === 'data-selected' || attr.name === 'data-selected-overlay'
          || attr.name === 'data-class-overlay' || attr.name === 'data-class-overlay-for'
        ) continue;
        seg.setAttribute(attr.name, attr.value);
      }
      seg.setAttribute('d', `M ${_splitFmt(a[0])} ${_splitFmt(a[1])} L ${_splitFmt(b[0])} ${_splitFmt(b[1])}`);
      seg.setAttribute('data-uid', allocUid());
      parent.insertBefore(seg, anchor);
      newEls.push(seg);
    }
    el.remove();
    for (const seg of newEls) {
      window.ensureElementClassOverlay?.(seg);
    }
    totalCreated += newEls.length;
    totalReplaced += 1;
  }

  if (totalReplaced > 0) {
    window.updateSelectionState?.();
    // Save in the "protected" version, mirroring the Save button:
    // - annotation mode: tile-based annotated save
    // - normal mode: overwrite the existing internal SVG (no timestamp)
    const isAnnot = typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE;
    try {
      if (isAnnot) {
        await window.annotManualSaveTile?.();
      } else {
        await window.saveInternalSvgOverwrite?.();
      }
    } catch (err) {
      console.error('[split] save failed', err);
    }
  }
  if (skipped.length) {
    console.warn(
      `[split] ${skipped.length} primitive(s) skipped (curves/arcs not split): ${skipped.join(', ')}`,
    );
  }
  return totalCreated;
};

// Sélection par rectangle (drag) ou lasso selon window.__lassoMode
window.handleSvgSelectionRect = (e) => {
  if (e.shiftKey || isCtrlOrCmd(e)) return;
  const container = e.currentTarget;
  const svg = container.tagName.toLowerCase() === 'svg' ? container : container.querySelector('svg');
  if (!svg) return;
  const t = e.target;
  const tag = (t?.tagName || '').toLowerCase();
  const primitives = ['path','line','polyline','polygon','rect','circle','ellipse','text'];
  // Allow rectangle/lasso selection to start on frozen primitives (they act as background)
  if (primitives.includes(tag)) {
    const tClassId = (t.getAttribute('classId') || t.getAttribute('classid') || '').trim().toLowerCase();
    if (tClassId !== 'frozen') return;
  }
  e.preventDefault();

  const toSvgPoint = (evt) => {
    const pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    const ctm = svg.getScreenCTM();
    if (!ctm) return {x: 0, y: 0};
    const p = pt.matrixTransform(ctm.inverse());
    return {x: p.x, y: p.y};
  };

  const lasso = !!window.__lassoMode;
  svg.__selectionMode = lasso ? 'lasso' : 'rect';

  // Cleanup any lingering visual from the other mode
  const cleanupVisuals = () => {
    if (svg.__selectionRect) {
      svg.__selectionRect.remove();
      svg.__selectionRect = null;
    }
    if (svg.__selectionLasso) {
      svg.__selectionLasso.remove();
      svg.__selectionLasso = null;
    }
    if (svg.__selectionDimLabel) {
      svg.__selectionDimLabel.remove();
      svg.__selectionDimLabel = null;
    }
    svg.querySelectorAll('[data-selection-rect="true"]').forEach((n) => n.remove());
    svg.querySelectorAll('[data-selection-lasso="true"]').forEach((n) => n.remove());
    svg.querySelectorAll('[data-selection-dim="true"]').forEach((n) => n.remove());
  };
  cleanupVisuals();

  const start = toSvgPoint(e);
  svg.__selectionActive = true;
  svg.__selectionStart = start;

  if (lasso) {
    const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    poly.setAttribute('id', '__selection_lasso');
    poly.setAttribute('data-selection-lasso', 'true');
    poly.setAttribute('fill', 'rgba(0,0,255,0.25)');
    poly.setAttribute('stroke', '#0000ff');
    poly.setAttribute('stroke-width', '0.1');
    poly.setAttribute('stroke-dasharray', '0.3 0.2');
    poly.setAttribute('vector-effect', 'non-scaling-stroke');
    poly.setAttribute('style', 'fill:rgba(0,0,255,0.25);stroke:#0000ff;stroke-width:0.1;stroke-dasharray:0.3 0.2;vector-effect:non-scaling-stroke;');
    poly.setAttribute('pointer-events', 'none');
    svg.appendChild(poly);
    svg.__selectionLasso = poly;
    svg.__selectionLassoPoints = [start];
    poly.setAttribute('points', `${start.x},${start.y}`);
    // Cache CTM scale so onMove can threshold in screen pixels (independent of zoom)
    const startCtm = svg.getScreenCTM();
    svg.__selectionLassoScaleX = startCtm ? startCtm.a : 1;
    svg.__selectionLassoScaleY = startCtm ? startCtm.d : 1;
  } else {
    const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    r.setAttribute('id', '__selection');
    r.setAttribute('data-selection-rect', 'true');
    r.setAttribute('fill', 'rgba(0,0,255,0.25)');
    r.setAttribute('stroke', '#0000ff');
    r.setAttribute('stroke-width', '0.1');
    r.setAttribute('stroke-dasharray', '0.3 0.2');
    r.setAttribute('vector-effect', 'non-scaling-stroke');
    r.setAttribute('style', 'fill:rgba(0,0,255,0.25);stroke:#0000ff;stroke-width:0.1;stroke-dasharray:0.3 0.2;vector-effect:non-scaling-stroke;');
    r.setAttribute('pointer-events', 'none');
    r.setAttribute('visibility', 'visible');
    svg.appendChild(r);
    svg.__selectionRect = r;
    r.setAttribute('x', start.x);
    r.setAttribute('y', start.y);
    r.setAttribute('width', 0);
    r.setAttribute('height', 0);
  }

  const finishSelectionFromCandidates = (candidates, predicate, label) => {
    const onUpStartedAt = performance.now();
    const selectionEpoch = (Number(svg.__selectionEpoch) || 0) + 1;
    svg.__selectionEpoch = selectionEpoch;
    if (!candidates.length) {
      cleanupVisuals();
      return;
    }
    withBusyGuard(label, 'Analyse des primitives', async () => {
      const historyEntries = [];
      let insideCount = 0;
      let selectedCount = 0;
      window.appendLoadingModalLog?.(`Candidats a evaluer: ${candidates.length}`);
      const loopStartedAt = performance.now();
      const select = (el) => {
        if (el.hasAttribute('data-selected')) return false;
        const historyEntry = window.createSelectionHistoryEntry?.(el, true) || null;
        const stroke = el.getAttribute('stroke');
        const fill = el.getAttribute('fill');
        const hasStroke = !!stroke && stroke !== 'none';
        const hasFill = !!fill && fill !== 'none';
        if (!hasStroke && !hasFill) return false;
        if (!el.hasAttribute('data-orig-stroke')) {
          el.setAttribute('data-orig-stroke', stroke ?? '');
        }
        el.setAttribute('data-selected', 'true');
        if (window.addSelectionOverlay) window.addSelectionOverlay(el);
        if (historyEntry) historyEntries.push(historyEntry);
        selectedCount += 1;
        return true;
      };
      const completed = await processInAnimationBatches(candidates, (entry) => {
        const el = entry.el;
        if (!el) return;
        if (el.getAttribute('data-hidden-by-class') === 'true' || el.style.display === 'none') return;
        // Frozen elements (overlap zone context) cannot be selected
        const elClassId = (el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
        if (elClassId === 'frozen') return;
        const bbox = entry.bbox || getSelectionLocalBBox(el);
        if (!bbox) return;
        if (predicate(bbox)) {
          insideCount += 1;
          select(el);
        }
      }, {
        batchSize: 50,
        shouldContinue: () => (Number(svg.__selectionEpoch) || 0) === selectionEpoch,
        onProgress: (done, total) => window.setLoadingModalStatus?.('En cours', `Selection: ${done}/${total} (${selectedCount} retenus)`),
      });
      if (!completed) return;
      const loopMs = performance.now() - loopStartedAt;
      cleanupVisuals();
      window.pushAnnotationHistoryEntries?.(historyEntries);
      if (window.updateSelectionState) window.updateSelectionState();
      window.appendLoadingModalLog?.(`${selectedCount} elements selectionnes en ${formatPerfMs(performance.now() - onUpStartedAt)}`);
      perfDebugLog(`${label}.onUp`, {
        scanned_count: candidates.length,
        inside_count: insideCount,
        selected_count: selectedCount,
        history_entries: historyEntries.length,
        loop_ms: roundPerfMs(loopMs),
        total_ms: roundPerfMs(performance.now() - onUpStartedAt),
      });
    });
  };

  if (!svg.__selectionListeners) {
    const onMove = (evt) => {
      if (!svg.__selectionActive) return;
      const cur = toSvgPoint(evt);
      if (svg.__selectionMode === 'lasso') {
        if (!svg.__selectionLasso) return;
        const pts = svg.__selectionLassoPoints || [];
        const last = pts[pts.length - 1];
        // Thinning in screen space (~0.5 pixel) — independent of zoom level
        if (last) {
          const sx = svg.__selectionLassoScaleX || 1;
          const sy = svg.__selectionLassoScaleY || 1;
          const sdx = (cur.x - last.x) * sx;
          const sdy = (cur.y - last.y) * sy;
          if ((sdx * sdx + sdy * sdy) < 0.25) return;
        }
        pts.push(cur);
        svg.__selectionLassoPoints = pts;
        // Incremental O(1) append via SVGPointList instead of rebuilding the
        // full `points` string each time (which was O(n²) over the drag).
        try {
          const svgPt = svg.createSVGPoint();
          svgPt.x = cur.x;
          svgPt.y = cur.y;
          svg.__selectionLasso.points.appendItem(svgPt);
        } catch (_) {
          svg.__selectionLasso.setAttribute(
            'points',
            pts.map((p) => `${p.x},${p.y}`).join(' '),
          );
        }
      } else {
        if (!svg.__selectionRect) return;
        const x = Math.min(svg.__selectionStart.x, cur.x);
        const y = Math.min(svg.__selectionStart.y, cur.y);
        const w = Math.abs(svg.__selectionStart.x - cur.x);
        const h = Math.abs(svg.__selectionStart.y - cur.y);
        svg.__selectionRect.setAttribute('x', x);
        svg.__selectionRect.setAttribute('y', y);
        svg.__selectionRect.setAttribute('width', w);
        svg.__selectionRect.setAttribute('height', h);

        // Show selection dimensions in cm at the top centre of the viewport.
        // SVG units × 10 = centimetres (CM_PER_UNIT = 10).
        const CM_PER_UNIT = 10;
        const wCm = (w * CM_PER_UNIT).toFixed(0);
        const hCm = (h * CM_PER_UNIT).toFixed(0);
        const dimText = `${wCm} × ${hCm} cm`;
        if (!svg.__selectionDimLabel) {
          const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          label.setAttribute('data-selection-dim', 'true');
          label.setAttribute('pointer-events', 'none');
          label.setAttribute('fill', '#0000ff');
          label.setAttribute('text-anchor', 'middle');
          label.setAttribute('dominant-baseline', 'hanging');
          label.setAttribute('font-family', 'sans-serif');
          svg.appendChild(label);
          svg.__selectionDimLabel = label;
        }
        const vb = getSvgViewBox(svg);
        if (vb) {
          const fontSize = vb.height * 0.018;
          svg.__selectionDimLabel.setAttribute('font-size', fontSize);
          svg.__selectionDimLabel.setAttribute('x', vb.x + vb.width / 2);
          svg.__selectionDimLabel.setAttribute('y', vb.y + fontSize * 0.3);
        }
        svg.__selectionDimLabel.textContent = dimText;
      }
    };

    const onUp = (evt) => {
      if (!svg.__selectionActive) return;
      svg.__selectionActive = false;
      const cur = toSvgPoint(evt);
      if (svg.__selectionMode === 'lasso') {
        const pts = (svg.__selectionLassoPoints || []).slice();
        // Append final point if it differs from the last one
        const last = pts[pts.length - 1];
        if (!last || last.x !== cur.x || last.y !== cur.y) pts.push(cur);
        // Need at least 3 points and a meaningful screen area to be a real lasso
        if (pts.length < 3) {
          cleanupVisuals();
          return;
        }
        const polyRect = polygonBoundingRect(pts);
        const ctm = svg.getScreenCTM();
        const screenW = ctm && polyRect ? polyRect.w * ctm.a : (polyRect?.w ?? 0);
        const screenH = ctm && polyRect ? polyRect.h * ctm.d : (polyRect?.h ?? 0);
        const MIN_RECT_PX = 2;
        if (Math.abs(screenW) < MIN_RECT_PX || Math.abs(screenH) < MIN_RECT_PX) {
          cleanupVisuals();
          return;
        }
        const candidates = querySelectionCandidates(svg, polyRect);
        finishSelectionFromCandidates(
          candidates,
          (bbox) => bboxInsidePolygon(bbox, pts),
          'Selection lasso',
        );
      } else {
        const x = Math.min(svg.__selectionStart.x, cur.x);
        const y = Math.min(svg.__selectionStart.y, cur.y);
        const w = Math.abs(svg.__selectionStart.x - cur.x);
        const h = Math.abs(svg.__selectionStart.y - cur.y);
        const rect = {x, y, w, h};
        const MIN_RECT_PX = 2;
        const ctm = svg.getScreenCTM();
        const screenW = ctm ? w * ctm.a : w;
        const screenH = ctm ? h * ctm.d : h;
        if (Math.abs(screenW) < MIN_RECT_PX || Math.abs(screenH) < MIN_RECT_PX) {
          if (svg.__selectionRect) {
            svg.__selectionRect.setAttribute('visibility', 'hidden');
          }
          return;
        }
        const candidates = querySelectionCandidates(svg, rect);
        finishSelectionFromCandidates(
          candidates,
          (bbox) => (
            bbox.left >= rect.x &&
            bbox.top >= rect.y &&
            bbox.right <= (rect.x + rect.w) &&
            bbox.bottom <= (rect.y + rect.h)
          ),
          'Selection rectangle',
        );
      }
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    svg.__selectionListeners = {onMove, onUp};
  }
};

// ── Annotation mode ─────────────────────────────────────────────────────────

window.__annotState = {
  tileName: null,
  tileIndex: -1,
  totalTiles: 0,
};

window.annotLoadCurrentTile = async () => {
  if (typeof ANNOT_MODE === 'undefined' || !ANNOT_MODE) return;
  // Cancel any pending debounced saves to prevent stale saves after tile switch
  if (window.__annotSaveTileTimer) {
    window.clearTimeout(window.__annotSaveTileTimer);
    window.__annotSaveTileTimer = null;
  }
  if (window._annotSaveTimer) {
    window.clearTimeout(window._annotSaveTimer);
    window._annotSaveTimer = null;
  }
  window.openLoadingModal?.({title: 'Chargement de la tuile', status: 'En cours', step: 'Récupération des métadonnées...'});
  // Block any concurrent save while we mutate the DOM. State is updated
  // only AFTER applySvgText so that on any throw between fetch and render,
  // state.tileName stays aligned with the DOM (still showing the previous
  // tile). Heartbeat/logout/manual saves are gated by this flag too.
  window.__annotTileSwitching = true;
  try {
    window.appendLoadingModalLog?.('Requête /annotation/current...');
    const res = await fetch('/annotation/current');
    if (window.handleAnnotAuthError(res)) return;
    if (!res.ok) {
      window.setLoadingModalStatus?.('Erreur', `Serveur: ${res.status}`);
      window.appendLoadingModalLog?.(`Erreur ${res.status}`, 'error');
      window.setTimeout(() => window.closeLoadingModal?.(), 2000);
      return;
    }
    const data = await res.json();
    if (!data?.ok) {
      window.closeLoadingModal?.();
      return;
    }
    if (data.done) {
      window.__annotState.tileName = null;
      window.annotUpdateInfoBar('All tiles are fully annotated.');
      window.setLoadingModalStatus?.('Terminé', 'Toutes les tuiles sont annotées');
      window.setTimeout(() => window.closeLoadingModal?.(), 400);
      return;
    }
    // Capture incoming tile data into locals — DON'T touch __annotState yet.
    const incomingName = data.tile_name;
    const incomingIndex = data.tile_index;
    const incomingTotal = data.total_tiles;
    const incomingSvgUrl = data.svg_url;

    window.setLoadingModalStatus?.('En cours', `Téléchargement SVG: ${incomingName}`);
    window.appendLoadingModalLog?.(`Tuile ${incomingIndex + 1}/${incomingTotal}: ${incomingName}`);
    const svgRes = await fetch(incomingSvgUrl, {cache: 'no-store'});
    const svgText = await svgRes.text();
    window.appendLoadingModalLog?.(`SVG reçu (${(svgText.length / 1024).toFixed(0)} KB)`);
    window.setLoadingModalStatus?.('En cours', 'Rendu SVG...');
    window.applySvgText(svgText);

    // DOM now reflects the new tile — safe to publish into state.
    window.__annotState.tileName = incomingName;
    window.__annotState.tileIndex = incomingIndex;
    window.__annotState.totalTiles = incomingTotal;
    try { localStorage.setItem(window.__annotStorageKey('annot_last_tile'), String(incomingIndex)); } catch (_) {}
    window.setCurrentSvgExportName(incomingName);

    window.annotReapplyClassVisibility();
    window.annotUpdateInfoBar();
    window.setLoadingModalStatus?.('Terminé', incomingName);
    window.appendLoadingModalLog?.('Tuile chargée');
    window.setTimeout(() => window.closeLoadingModal?.(), 400);
  } catch (err) {
    console.error('Annot: failed to load tile', err);
    window.setLoadingModalStatus?.('Erreur', String(err?.message || err));
    window.appendLoadingModalLog?.(String(err?.message || err), 'error');
  } finally {
    window.__annotTileSwitching = false;
  }
};

// Lazy-init save Web Worker (offloads string formatting from main thread)
let _saveWorker = null;
const _getSaveWorker = () => {
  if (!_saveWorker) {
    _saveWorker = new Worker('/assets/save-worker.js');
  }
  return _saveWorker;
};

// Namespace localStorage keys by ANNOT_USER_KEY (basename of
// --annotation-dir, e.g. "user1"). In production each container has
// its own origin so the value is the same across containers; in dev
// running multiple users in the same browser would otherwise share
// state and cause out-of-range tile indexes / poison pending saves.
window.__annotStorageKey = (base) => {
  const k = (typeof ANNOT_USER_KEY === 'string') ? ANNOT_USER_KEY : '';
  return k ? `${base}:${k}` : base;
};

// One-shot migration of pre-namespaced keys. Reads the legacy bare
// key, copies it into the namespaced key, then removes the legacy.
// Idempotent — runs once per page load before any read.
window.__annotMigrateKey = (base) => {
  const target = window.__annotStorageKey(base);
  if (target === base) return;
  try {
    if (localStorage.getItem(target) === null) {
      const legacy = localStorage.getItem(base);
      if (legacy !== null) {
        localStorage.setItem(target, legacy);
        localStorage.removeItem(base);
      }
    }
  } catch (_) {}
};

// localStorage key used to recover an annotation tile save that didn't reach
// the server (auth expiry, network error, page reload). Replayed at the next
// init before any tile loads — see initAppUiAfterAuth.
window.__ANNOT_PENDING_SAVE_KEY = window.__annotStorageKey('annot_pending_save');

// Save button state in the main toolbar — driven by every save path
// (manual, debounced, navigation flush, logout flush).
window.setAnnotSaveStatus = (state, payload = {}) => {
  const btn = document.getElementById('annot-save-btn');
  const label = document.getElementById('annot-save-label');
  if (!btn || !label) return;
  btn.classList.toggle('is-saving', state === 'saving');
  label.classList.toggle('is-saving', state === 'saving');
  label.classList.toggle('is-saved', state === 'saved');
  label.classList.toggle('is-error', state === 'error');
  if (state === 'saving') {
    label.textContent = 'Saving...';
    btn.title = 'Sauvegarde en cours';
  } else if (state === 'saved') {
    const ts = payload.ts instanceof Date ? payload.ts : new Date();
    const hh = String(ts.getHours()).padStart(2, '0');
    const mm = String(ts.getMinutes()).padStart(2, '0');
    const ss = String(ts.getSeconds()).padStart(2, '0');
    label.textContent = `Saved ${hh}:${mm}:${ss}`;
    btn.title = `Dernière sauvegarde à ${hh}:${mm}:${ss}`;
  } else if (state === 'error') {
    label.textContent = `Erreur (${payload.reason || '?'})`;
    btn.title = 'Échec de la sauvegarde — cliquer pour réessayer';
  } else {
    label.textContent = 'Save';
    btn.title = 'Sauvegarder maintenant';
  }
};

const _stashPendingSave = (tileName, svgText, reason) => {
  try {
    localStorage.setItem(window.__ANNOT_PENDING_SAVE_KEY, JSON.stringify({
      tile_name: tileName,
      svg_text: svgText,
      ts: Date.now(),
      reason,
    }));
    console.warn(`[annotSave] stashed for recovery (${reason}): ${tileName}`);
  } catch (e) {
    console.error('[annotSave] failed to stash pending save', e);
  }
};

const _clearPendingSave = () => {
  try { localStorage.removeItem(window.__ANNOT_PENDING_SAVE_KEY); } catch (_) {}
};

// Returns {ok: true} on success, {ok: false, reason} on failure. On any
// failure (network, http error, auth expiry, empty serialization) the
// serialized payload is stashed to localStorage so it can be replayed on
// the next init. Callers should NOT assume success based on resolution.
window.annotSaveTile = async () => {
  if (!ANNOT_MODE || !window.__annotState.tileName) return {ok: false, reason: 'no-tile'};
  // Block: state.tileName has advanced but the DOM still belongs to the
  // previous tile (or vice-versa). Saving now would persist mismatched
  // content under the wrong name. The pre-transition save already ran.
  if (window.__annotTileSwitching) {
    console.warn('[annotSave] skipped: tile transition in progress');
    return {ok: false, reason: 'switching'};
  }
  // Capture tile name NOW — before any async work — to prevent race conditions
  // when the user switches tiles while serialization/worker is in progress.
  const snapshotTileName = window.__annotState.tileName;
  const saveStart = performance.now();
  window.setAnnotSaveStatus?.('saving');
  await new Promise((r) => setTimeout(r, 0));

  // DOM serialization (must stay on main thread)
  const serStart = performance.now();
  const serializedSvg = window.serializeFullSvgForSave?.();
  const serMs = performance.now() - serStart;
  if (!serializedSvg) {
    console.warn('[annotSave] empty serialization, nothing to save');
    window.setAnnotSaveStatus?.('error', {reason: 'empty'});
    return {ok: false, reason: 'empty-serialization'};
  }
  console.log(`[annotSave] serialize: ${serMs.toFixed(0)} ms (${(serializedSvg.length / 1024).toFixed(0)} KB)`);

  await new Promise((r) => setTimeout(r, 0));

  // Offload string processing to Web Worker
  const fmtStart = performance.now();
  const svgText = await new Promise((resolve) => {
    const worker = _getSaveWorker();
    worker.onmessage = (evt) => resolve(evt.data);
    worker.postMessage({
      serializedSvg,
      sourceText: typeof window.__currentSvgSourceText === 'string' ? window.__currentSvgSourceText : '',
    });
  });
  const fmtMs = performance.now() - fmtStart;
  console.log(`[annotSave] format (worker): ${fmtMs.toFixed(0)} ms`);

  if (!svgText) {
    console.warn('[annotSave] worker returned empty payload');
    window.setAnnotSaveStatus?.('error', {reason: 'empty'});
    return {ok: false, reason: 'empty-worker'};
  }

  try {
    const tileName = encodeURIComponent(snapshotTileName);
    const saveRes = await fetch(`/annotation/save?tile_name=${tileName}`, {
      method: 'POST',
      headers: {'Content-Type': 'text/plain; charset=utf-8'},
      body: svgText,
    });
    const totalMs = performance.now() - saveStart;
    console.log(`[annotSave] total: ${totalMs.toFixed(0)} ms (fetch: ${(totalMs - serMs - fmtMs).toFixed(0)} ms)`);
    if (saveRes.status === 401) {
      // Stash BEFORE the auth handler shows the login modal — so a reload
      // (manual or via showAnnotLoginModal flow) will replay this save.
      _stashPendingSave(snapshotTileName, svgText, 'auth-401');
      window.setAnnotSaveStatus?.('error', {reason: 'auth'});
      window.handleAnnotAuthError(saveRes);
      return {ok: false, reason: 'auth', status: 401};
    }
    if (saveRes.status === 409) {
      // Server rejected the save because the SVG body's identity attrs
      // (data-source-svg / data-tile-row / data-tile-col) don't match
      // ``snapshotTileName``. This indicates a client-side desync that
      // we can't fix by retrying — replaying the same payload would 409
      // again. Drop any stashed copy so we don't poison future reloads,
      // surface the error, and prompt the user to reload to recover.
      _clearPendingSave();
      let detail = '';
      try {
        const body = await saveRes.json();
        detail = JSON.stringify(body);
        console.error(`[annotSave] 409 identity mismatch for ${snapshotTileName}: ${detail}`);
      } catch (_) {
        console.error(`[annotSave] 409 identity mismatch for ${snapshotTileName} (no body)`);
      }
      window.setAnnotSaveStatus?.('error', {reason: 'mismatch'});
      try {
        alert(
          'Sauvegarde refusée par le serveur : le contenu de la tuile ne ' +
          'correspond pas à son nom (incohérence détectée).\n\nLa page va se ' +
          'recharger pour récupérer un état propre.'
        );
      } catch (_) {}
      try { window.location.reload(); } catch (_) {}
      return {ok: false, reason: 'mismatch', status: 409, detail};
    }
    if (!saveRes.ok) {
      _stashPendingSave(snapshotTileName, svgText, `http-${saveRes.status}`);
      window.setAnnotSaveStatus?.('error', {reason: `${saveRes.status}`});
      return {ok: false, reason: 'http', status: saveRes.status};
    }
    _clearPendingSave();
    window.setAnnotSaveStatus?.('saved', {ts: new Date()});
    return {ok: true};
  } catch (err) {
    console.error('Annot: save failed', err);
    _stashPendingSave(snapshotTileName, svgText, 'network');
    window.setAnnotSaveStatus?.('error', {reason: 'net'});
    return {ok: false, reason: 'network', error: String(err?.message || err)};
  }
};

// ── Annotation stats: per-day class-assignment action counters ─────────────
// Fire-and-forget delta upload. Failures are logged but do not affect the UI.
window.recordAnnotStat = (className, delta) => {
  if (typeof ANNOT_MODE === 'undefined' || !ANNOT_MODE) return;
  if (!className || !delta) return;
  try {
    fetch('/annotation/stats/increment', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({class_name: String(className), delta: Number(delta)}),
      keepalive: true,
    }).catch((err) => console.warn('Annot stats: increment failed', err));
  } catch (err) {
    console.warn('Annot stats: increment threw', err);
  }
};

const ensureAnnotStatsDialog = () => {
  let backdrop = document.getElementById('annot-stats-backdrop');
  if (backdrop) return backdrop;
  backdrop = document.createElement('div');
  backdrop.id = 'annot-stats-backdrop';
  backdrop.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.45);z-index:9000;display:none;align-items:center;justify-content:center;';
  backdrop.innerHTML = `
    <div role="dialog" aria-modal="true" aria-labelledby="annot-stats-title"
         style="background:#fff;border-radius:8px;box-shadow:0 12px 40px rgba(0,0,0,0.25);max-width:min(96vw,1400px);max-height:85vh;display:flex;flex-direction:column;overflow:hidden;">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;border-bottom:1px solid #e5e7eb;">
        <span id="annot-stats-title" style="font-weight:600;color:#0f172a;">Statistiques d'annotation</span>
        <div style="display:flex;align-items:center;gap:8px;">
          <button id="annot-stats-copy" type="button" title="Copier au presse-papiers (TSV)"
                  style="background:#1d4ed8;color:#fff;border:none;border-radius:4px;padding:6px 12px;cursor:pointer;font-size:13px;">
            Copier
          </button>
          <button id="annot-stats-close" type="button" aria-label="Fermer" style="background:transparent;border:none;font-size:18px;cursor:pointer;color:#475569;padding:4px 10px;">×</button>
        </div>
      </div>
      <div id="annot-stats-body" style="padding:12px 16px;overflow:auto;font-family:system-ui,sans-serif;color:#0f172a;font-size:13px;"></div>
    </div>
  `;
  document.body.appendChild(backdrop);
  backdrop.addEventListener('click', (ev) => {
    if (ev.target === backdrop) backdrop.style.display = 'none';
  });
  backdrop.querySelector('#annot-stats-close').addEventListener('click', () => {
    backdrop.style.display = 'none';
  });
  backdrop.querySelector('#annot-stats-copy').addEventListener('click', async () => {
    const tsv = backdrop.__statsTsv || '';
    const btn = backdrop.querySelector('#annot-stats-copy');
    if (!tsv) return;
    try {
      await navigator.clipboard.writeText(tsv);
      const original = btn.textContent;
      btn.textContent = 'Copié ✓';
      setTimeout(() => { btn.textContent = original; }, 1200);
    } catch (err) {
      console.warn('Annot stats: clipboard write failed', err);
      // Fallback: select-all in a hidden textarea
      const ta = document.createElement('textarea');
      ta.value = tsv;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (_) {}
      ta.remove();
      const original = btn.textContent;
      btn.textContent = 'Copié ✓';
      setTimeout(() => { btn.textContent = original; }, 1200);
    }
  });
  return backdrop;
};

const _annotStatsAllClasses = () => {
  const map = (typeof CLASS_NAME_COLOR_MAP === 'object' && CLASS_NAME_COLOR_MAP) ? CLASS_NAME_COLOR_MAP : {};
  return Object.keys(map).sort();
};

const buildAnnotStatsTsv = (stats, days, classes) => {
  const lines = [];
  lines.push(['Date', ...classes, 'Total'].join('\t'));
  days.forEach((d) => {
    const bucket = stats[d] || {};
    let dayTotal = 0;
    const row = [d];
    classes.forEach((c) => {
      const v = Number(bucket[c] || 0);
      dayTotal += v;
      row.push(String(v));
    });
    row.push(String(dayTotal));
    lines.push(row.join('\t'));
  });
  return lines.join('\n');
};

const renderAnnotStatsTable = (stats) => {
  const days = Object.keys(stats || {}).sort().reverse();
  const knownClasses = _annotStatsAllClasses();
  // Include any class that appears in stats but isn't in the known list
  // (defensive — shouldn't happen unless SVG_CATEGORIES changes).
  const extra = new Set();
  days.forEach((d) => {
    Object.keys(stats[d] || {}).forEach((c) => {
      if (!knownClasses.includes(c)) extra.add(c);
    });
  });
  const classes = [...knownClasses, ...Array.from(extra).sort()];
  if (!days.length) {
    return {
      html: `<p style="color:#475569;margin:0;">Aucune statistique enregistrée pour le moment. (${classes.length} classes connues)</p>`,
      tsv: buildAnnotStatsTsv({}, [], classes),
    };
  }
  const cellPad = 'padding:4px 10px;border-bottom:1px solid #e5e7eb;white-space:nowrap;';
  const headPad = 'padding:6px 10px;border-bottom:2px solid #cbd5e1;background:#f8fafc;text-align:left;font-weight:600;white-space:nowrap;position:sticky;top:0;';
  const numCell = `${cellPad}text-align:right;font-variant-numeric:tabular-nums;`;
  const numHead = `${headPad}text-align:right;`;
  let html = '<table style="border-collapse:collapse;width:max-content;min-width:100%;">';
  html += '<thead><tr>';
  html += `<th style="${headPad}">Date</th>`;
  classes.forEach((c) => { html += `<th style="${numHead}">${c}</th>`; });
  html += `<th style="${numHead}">Total</th>`;
  html += '</tr></thead><tbody>';
  days.forEach((d) => {
    const bucket = stats[d] || {};
    let dayTotal = 0;
    html += `<tr><td style="${cellPad}font-weight:500;">${d}</td>`;
    classes.forEach((c) => {
      const v = Number(bucket[c] || 0);
      dayTotal += v;
      const dim = v === 0 ? 'color:#cbd5e1;' : '';
      html += `<td style="${numCell}${dim}">${v}</td>`;
    });
    html += `<td style="${numCell}font-weight:600;">${dayTotal}</td>`;
    html += '</tr>';
  });
  html += '</tbody></table>';
  return {html, tsv: buildAnnotStatsTsv(stats, days, classes)};
};

window.openAnnotStats = async () => {
  if (typeof ANNOT_MODE === 'undefined' || !ANNOT_MODE) return;
  const backdrop = ensureAnnotStatsDialog();
  const body = backdrop.querySelector('#annot-stats-body');
  body.innerHTML = '<p style="color:#475569;margin:0;">Chargement...</p>';
  backdrop.__statsTsv = '';
  backdrop.style.display = 'flex';
  try {
    const res = await fetch('/annotation/stats');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    const rendered = renderAnnotStatsTable(data?.stats || {});
    body.innerHTML = rendered.html;
    backdrop.__statsTsv = rendered.tsv;
  } catch (err) {
    body.innerHTML = `<p style="color:#b91c1c;margin:0;">Erreur de chargement : ${String(err.message || err)}</p>`;
  }
};

// Manual save: triggered by the toolbar button. Cancels any pending
// debounced auto-save first so we don't end up with two saves in flight.
window.annotManualSaveTile = async () => {
  if (!ANNOT_MODE) return;
  if (window.__annotSaveTileTimer) { window.clearTimeout(window.__annotSaveTileTimer); window.__annotSaveTileTimer = null; }
  if (window._annotSaveTimer) { window.clearTimeout(window._annotSaveTimer); window._annotSaveTimer = null; }
  await window.annotSaveTile();
};

// Debounced tile auto-save — fires after annotation without blocking the UI
window.__annotSaveTileTimer = null;
window.__annotSaveTilePromise = Promise.resolve();

window.queueAnnotSaveTile = () => {
  if (typeof ANNOT_MODE === 'undefined' || !ANNOT_MODE) return;
  if (window.__annotSaveTileTimer) {
    window.clearTimeout(window.__annotSaveTileTimer);
  }
  window.__annotSaveTileTimer = window.setTimeout(() => {
    window.__annotSaveTileTimer = null;
    window.__annotSaveTilePromise = window.__annotSaveTilePromise
      .then(() => window.annotSaveTile())
      .catch((err) => console.error('Annot: debounced save failed', err));
  }, 2000);
};

window.annotCheckCompletion = () => {
  if (!ANNOT_MODE) return false;
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return false;
  const elements = svg.querySelectorAll('path,line,polyline,polygon,rect,circle,ellipse');
  for (const el of elements) {
    if (el.getAttribute('data-class-overlay-for') !== null) continue;
    const classId = (el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
    if (classId === 'frozen' || classId === 'text') continue;
    if (!classId || classId === 'unlabelled') return false;
  }
  return true;
};

window.annotReapplyClassVisibility = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const unchecked = Array.from(document.querySelectorAll('.tool-checkbox[data-class-id]'))
    .filter((cb) => !cb.checked);
  if (!unchecked.length) return;
  const hiddenClasses = new Set(unchecked.map((cb) => (cb.dataset.classId || '').trim().toLowerCase()));
  const overlayIndex = buildClassOverlayIndex(svg);
  svg.querySelectorAll('path,line,polyline,polygon,rect,circle,ellipse,text,use').forEach((el) => {
    // Skip overlays — they are controlled via their primitive's data-uid lookup
    if (el.hasAttribute('data-class-overlay-for')) return;
    const classNode = el.closest('[classId],[classid]');
    if (!classNode) return;
    const classValue = String(classNode.getAttribute('classId') || classNode.getAttribute('classid') || '').trim().toLowerCase();
    if (!classValue || !hiddenClasses.has(classValue)) return;
    if (!el.hasAttribute('data-orig-display')) {
      el.setAttribute('data-orig-display', el.style.display || '');
    }
    el.style.display = 'none';
    el.setAttribute('data-hidden-by-class', 'true');
    const uid = String(el.getAttribute('data-uid') || '').trim();
    if (uid) {
      const overlay = overlayIndex.get(uid);
      if (overlay) overlay.style.display = 'none';
    }
  });
};

window.annotGoToTile = async (index) => {
  if (!ANNOT_MODE) return;
  // Cancel any pending debounced saves to prevent stale saves after tile switch
  if (window.__annotSaveTileTimer) {
    window.clearTimeout(window.__annotSaveTileTimer);
    window.__annotSaveTileTimer = null;
  }
  if (window._annotSaveTimer) {
    window.clearTimeout(window._annotSaveTimer);
    window._annotSaveTimer = null;
  }
  window.openLoadingModal?.({title: 'Changement de tuile', status: 'Sauvegarde', step: 'Sauvegarde de la tuile en cours...'});
  // Save current tile first (state.tileName + DOM still match here)
  window.appendLoadingModalLog?.('Sauvegarde de la tuile courante...');
  await window.annotSaveTile();
  window.appendLoadingModalLog?.('Sauvegarde terminée');
  // Block any concurrent save while we mutate the DOM. State is updated
  // only AFTER applySvgText so that on any throw between fetch and render,
  // state.tileName stays aligned with the DOM (still showing the previous
  // tile). Without this, a save firing after a failed transition could
  // persist the previous tile's content under the new tile's name.
  window.__annotTileSwitching = true;
  try {
    window.setLoadingModalStatus?.('En cours', 'Récupération des métadonnées...');
    window.appendLoadingModalLog?.(`Requête /annotation/tile/${index}...`);
    const res = await fetch(`/annotation/tile/${index}`);
    if (window.handleAnnotAuthError(res)) return;
    if (!res.ok) {
      window.setLoadingModalStatus?.('Erreur', `Serveur: ${res.status}`);
      window.appendLoadingModalLog?.(`Erreur ${res.status} pour la tuile ${index}`, 'error');
      window.setTimeout(() => window.closeLoadingModal?.(), 2000);
      return;
    }
    const data = await res.json();
    if (!data?.ok) {
      // Index out of range (e.g. stale localStorage from another user with
      // more tiles) or tile dir empty — fall back to the resolver-based
      // loader, which picks the next valid tile from the current set.
      console.warn(`[annot] tile/${index} not-ok, falling back to /annotation/current:`, data?.error);
      window.appendLoadingModalLog?.(`Tuile ${index} invalide: ${data?.error || '?'} — fallback`, 'error');
      // Release the switching lock before delegating; annotLoadCurrentTile
      // will take it again itself.
      window.__annotTileSwitching = false;
      return window.annotLoadCurrentTile();
    }
    // Capture incoming tile data into locals — DON'T touch __annotState yet.
    const incomingName = data.tile_name;
    const incomingIndex = data.tile_index;
    const incomingTotal = data.total_tiles;
    const incomingSvgUrl = data.svg_url;

    window.setLoadingModalStatus?.('En cours', `Téléchargement SVG: ${incomingName}`);
    window.appendLoadingModalLog?.(`Tuile ${incomingIndex + 1}/${incomingTotal}: ${incomingName}`);
    const svgRes = await fetch(incomingSvgUrl, {cache: 'no-store'});
    const svgText = await svgRes.text();
    window.appendLoadingModalLog?.(`SVG reçu (${(svgText.length / 1024).toFixed(0)} KB)`);
    window.setLoadingModalStatus?.('En cours', 'Rendu SVG...');
    window.applySvgText(svgText);

    // DOM now reflects the new tile — safe to publish into state.
    window.__annotState.tileName = incomingName;
    window.__annotState.tileIndex = incomingIndex;
    window.__annotState.totalTiles = incomingTotal;
    try { localStorage.setItem(window.__annotStorageKey('annot_last_tile'), String(incomingIndex)); } catch (_) {}
    window.setCurrentSvgExportName(incomingName);

    window.annotReapplyClassVisibility();
    window.annotUpdateInfoBar();
    window.setLoadingModalStatus?.('Terminé', incomingName);
    window.appendLoadingModalLog?.('Tuile chargée');
    window.setTimeout(() => window.closeLoadingModal?.(), 400);
  } catch (err) {
    console.error('Annot: failed to load tile', err);
    window.setLoadingModalStatus?.('Erreur', String(err?.message || err));
    window.appendLoadingModalLog?.(String(err?.message || err), 'error');
  } finally {
    window.__annotTileSwitching = false;
  }
};

window.annotUpdateInfoBar = (message) => {
  let bar = document.getElementById('annotation-info-bar');
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'annotation-info-bar';
    bar.style.cssText = 'position:fixed;top:8px;left:50%;transform:translateX(-50%);z-index:10000;background:#1e293b;color:#f8fafc;padding:6px 18px;border-radius:6px;font:600 14px/1.4 system-ui,sans-serif;white-space:nowrap;display:flex;align-items:center;gap:10px;';
    document.body.appendChild(bar);
  }
  const s = window.__annotState;
  if (message) {
    bar.innerHTML = '';
    bar.style.pointerEvents = 'none';
    bar.textContent = message;
    return;
  }
  if (!s.tileName) return;
  bar.style.pointerEvents = 'auto';
  const hasPrev = s.tileIndex > 0;
  const hasNext = s.tileIndex < s.totalTiles - 1;
  const btnStyle = 'background:none;border:1px solid #64748b;color:#f8fafc;border-radius:4px;padding:2px 8px;cursor:pointer;font:600 13px system-ui,sans-serif;';
  const disabledStyle = 'background:none;border:1px solid #334155;color:#475569;border-radius:4px;padding:2px 8px;cursor:default;font:600 13px system-ui,sans-serif;';
  bar.innerHTML = `<button id="annotation-prev-btn" style="${hasPrev ? btnStyle : disabledStyle}" ${hasPrev ? '' : 'disabled'}>◀</button>`
    + `<span style="pointer-events:none;">(${s.tileIndex + 1}/${s.totalTiles})</span>`
    + `<button id="annotation-next-btn" style="${hasNext ? btnStyle : disabledStyle}" ${hasNext ? '' : 'disabled'}>▶</button>`;
  document.getElementById('annotation-prev-btn')?.addEventListener('click', () => {
    if (hasPrev) window.annotGoToTile(s.tileIndex - 1);
  });
  document.getElementById('annotation-next-btn')?.addEventListener('click', () => {
    if (hasNext) window.annotGoToTile(s.tileIndex + 1);
  });
};

window.annotOnClassAssigned = async () => {
  if (!ANNOT_MODE) return;
  // Debounced save — doesn't block the UI or reset the view
  window._annotSaveQueued = true;
  if (!window._annotSaveTimer) {
    window._annotSaveTimer = window.setTimeout(async () => {
      window._annotSaveTimer = null;
      window._annotSaveQueued = false;
      await window.annotSaveTile();
    }, 2000);
  }
  // Check if tile is complete
  if (window.annotCheckCompletion()) {
    // Flush pending save before moving to next tile
    if (window._annotSaveTimer) {
      window.clearTimeout(window._annotSaveTimer);
      window._annotSaveTimer = null;
    }
    await window.annotSaveTile();
    window.annotUpdateInfoBar('Tile complete! Loading next...');
    await new Promise(r => setTimeout(r, 800));
    await window.annotLoadCurrentTile();
  }
};

// Initialisation globale (palette, vue globale, etc.)
window.handleAnnotAuthError = (res) => {
  if (res.status === 401 && typeof AUTH_REQUIRED !== 'undefined' && AUTH_REQUIRED) {
    window.stopAnnotHeartbeat?.();
    window.closeLoadingModal?.();
    alert('Session expirée.\nVeuillez vous reconnecter.');
    window.showAnnotLoginModal();
    return true;
  }
  return false;
};

window.showAnnotLoginModal = () => {
  if (document.getElementById('annot-login-modal')) return;
  const backdrop = document.createElement('div');
  backdrop.id = 'annot-login-modal';
  backdrop.style.cssText = 'position:fixed;inset:0;z-index:100000;background:rgba(0,0,0,0.85);backdrop-filter:blur(30px);-webkit-backdrop-filter:blur(30px);display:flex;align-items:center;justify-content:center;';
  const box = document.createElement('div');
  box.style.cssText = 'background:#fff;border-radius:8px;padding:32px;min-width:320px;box-shadow:0 4px 24px rgba(0,0,0,0.3);text-align:center;font-family:system-ui,sans-serif;';
  box.innerHTML = `
    <h2 style="margin:0 0 16px;font-size:18px;">${typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE ? 'Annotation' : 'CT AI Check'} — Connexion</h2>
    <input id="annot-login-pw" type="password" placeholder="Mot de passe"
      style="width:100%;padding:8px 12px;font-size:14px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;" />
    <div id="annot-login-error" style="color:#c0392b;margin-top:8px;font-size:13px;min-height:20px;"></div>
    <button id="annot-login-btn" type="button"
      style="margin-top:12px;padding:8px 24px;font-size:14px;background:#2980b9;color:#fff;border:none;border-radius:4px;cursor:pointer;">
      Se connecter
    </button>
  `;
  backdrop.appendChild(box);
  document.body.appendChild(backdrop);
  const pwInput = document.getElementById('annot-login-pw');
  const errDiv = document.getElementById('annot-login-error');
  const btn = document.getElementById('annot-login-btn');
  const doLogin = async () => {
    const pw = pwInput.value;
    if (!pw) { errDiv.textContent = 'Veuillez entrer le mot de passe.'; return; }
    btn.disabled = true;
    btn.textContent = '...';
    try {
      const res = await fetch('/auth/login', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({password: pw}),
      });
      const data = await res.json();
      if (!data.ok) {
        errDiv.textContent = data.error || 'Erreur';
        btn.disabled = false;
        btn.textContent = 'Se connecter';
        return;
      }
      backdrop.remove();
      window._annotAuthenticated = true;
      window.initAppUiAfterAuth();
    } catch (e) {
      errDiv.textContent = String(e?.message || e);
      btn.disabled = false;
      btn.textContent = 'Se connecter';
    }
  };
  btn.addEventListener('click', doLogin);
  pwInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') doLogin(); });
  pwInput.focus();
};

window.startAnnotHeartbeat = () => {
  window.stopAnnotHeartbeat();
  window.__annotHeartbeatId = window.setInterval(async () => {
    try {
      const res = await fetch('/auth/heartbeat', {method: 'POST'});
      if (res.status === 401) {
        window.stopAnnotHeartbeat();
        // Try to save BEFORE showing the login modal. The cookie is now
        // invalid so the fetch will return 401 — annotSaveTile stashes the
        // payload to localStorage so it can be replayed after re-auth.
        if (window.__annotSaveTileTimer) { window.clearTimeout(window.__annotSaveTileTimer); window.__annotSaveTileTimer = null; }
        if (window._annotSaveTimer) { window.clearTimeout(window._annotSaveTimer); window._annotSaveTimer = null; }
        try { await window.annotSaveTile(); } catch (e) { console.error('Heartbeat: save failed', e); }
        window.closeLoadingModal?.();
        alert('Session expirée.\nVeuillez vous reconnecter.');
        window.showAnnotLoginModal();
      }
    } catch (_) { /* network error, retry next tick */ }
  }, 5000);
};

window.stopAnnotHeartbeat = () => {
  if (window.__annotHeartbeatId) {
    window.clearInterval(window.__annotHeartbeatId);
    window.__annotHeartbeatId = null;
  }
};

window.logoutAnnotSession = async () => {
  window.stopAnnotHeartbeat();
  // Cancel any pending debounced saves so they cannot race with our flush.
  if (window.__annotSaveTileTimer) { window.clearTimeout(window.__annotSaveTileTimer); window.__annotSaveTileTimer = null; }
  if (window._annotSaveTimer) { window.clearTimeout(window._annotSaveTimer); window._annotSaveTimer = null; }
  // Flush the current tile to disk BEFORE destroying the session — otherwise
  // the page reload below would wipe any unsaved DOM edits.
  try { await window.annotSaveTile(); } catch (e) { console.error('Logout: save failed', e); }
  try {
    await fetch('/auth/logout', { method: 'POST' });
  } catch (_) { /* ignore */ }
  window.location.reload();
};

// ── Check mode: business validation against test_pmr_basis fixtures ────────
window.__checkState = {
  fixtures: [],
  rules: [],
  current: null,           // {fixture_index, name, business}
  saveTimer: null,
  // PMR computation result for the currently displayed fixture
  pmrIncidentsByRule: {},  // rule_code → [incident, ...]
  pmrStatusByRule: {},     // rule_code → 'ok' | 'ko' (computed)
  activeRuleCode: null,
  activeIncidentIdx: null, // null = all instances, number = single instance
  expandedRules: new Set(), // rule codes whose sub-list is expanded
  // Per-fixture PMR result cache (key: fixture stem)
  pmrCache: {},            // stem → {pmrIncidentsByRule, pmrStatusByRule}
};

window.checkInit = async () => {
  if (typeof CHECK_MODE === 'undefined' || !CHECK_MODE) return;
  try {
    const res = await fetch('/check/fixtures', {cache: 'no-store'});
    const data = await res.json();
    if (!data?.ok) return;
    window.__checkState.fixtures = data.fixtures || [];
    window.__checkState.rules = data.rules || [];
  } catch (err) {
    console.error('Check: failed to load fixtures', err);
    return;
  }
  // Restore last opened fixture (server-side, fallback to localStorage, fallback to 0)
  let lastIdx = null;
  try {
    const res = await fetch('/check/last-fixture', {cache: 'no-store'});
    const data = await res.json();
    if (data?.ok && data.fixture_index !== null && data.fixture_index !== undefined) {
      lastIdx = data.fixture_index;
    }
  } catch (_) {}
  if (lastIdx === null) {
    try { const v = localStorage.getItem('check_last_fixture'); if (v !== null) lastIdx = Number(v); } catch (_) {}
  }
  if (lastIdx === null || isNaN(Number(lastIdx))) lastIdx = 0;
  await window.checkGoToFixture(Number(lastIdx));

  // Keyboard navigation: ArrowUp/ArrowDown moves between rules (and sub-items when expanded)
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
    const listEl = document.getElementById('check-rules-list');
    if (!listEl) return;
    const focused = document.activeElement;
    if (focused && (focused.tagName === 'INPUT' || focused.tagName === 'TEXTAREA')) return;
    e.preventDefault();
    const state = window.__checkState;
    const rules = state.rules || [];
    if (rules.length === 0) return;

    // Build flat navigation list: main items + sub-items for expanded rules
    const navList = [];
    for (const rule of rules) {
      navList.push({ruleCode: rule.code, incidentIdx: null});
      if (state.expandedRules.has(rule.code)) {
        const incidents = state.pmrIncidentsByRule[rule.code] || [];
        for (let i = 0; i < incidents.length; i++) {
          navList.push({ruleCode: rule.code, incidentIdx: i});
        }
      }
    }

    const curPos = navList.findIndex((item) =>
      item.ruleCode === state.activeRuleCode && item.incidentIdx === state.activeIncidentIdx
    );
    let nextPos;
    if (e.key === 'ArrowDown') {
      nextPos = curPos < navList.length - 1 ? curPos + 1 : 0;
    } else {
      nextPos = curPos > 0 ? curPos - 1 : navList.length - 1;
    }
    const next = navList[nextPos];
    window.checkSelectRule(next.ruleCode, next.incidentIdx);

    // Scroll the selected row into view
    const activeRow = listEl.querySelector('.check-rule.is-active, .check-rule-sub.is-active');
    if (activeRow) activeRow.scrollIntoView({block: 'nearest'});
  });
};

window.checkGoToFixture = async (index) => {
  if (typeof CHECK_MODE === 'undefined' || !CHECK_MODE) return;
  // Cancel any pending save before switching, then flush it inline
  if (window.__checkState.saveTimer) {
    window.clearTimeout(window.__checkState.saveTimer);
    window.__checkState.saveTimer = null;
    await window.checkSaveBusiness();
  }
  // Reset prior PMR overlays + per-fixture state when switching fixtures
  window.clearAccessPathOverlays?.('pmr-check');
  window.__checkState.pmrIncidentsByRule = {};
  window.__checkState.pmrStatusByRule = {};
  window.__checkState.activeRuleCode = null;
  window.__checkState.activeIncidentIdx = null;

  window.openLoadingModal?.({title: 'Chargement de la fixture', status: 'En cours', step: 'Récupération des métadonnées...'});
  try {
    const res = await fetch(`/check/fixture/${index}`, {cache: 'no-store'});
    if (window.handleAnnotAuthError && window.handleAnnotAuthError(res)) return;
    const data = await res.json();
    if (!data?.ok) {
      console.error('Check: load fixture failed', data?.error);
      window.setLoadingModalStatus?.('Erreur', data?.error || 'Inconnue');
      window.setTimeout(() => window.closeLoadingModal?.(), 1500);
      return;
    }
    window.__checkState.current = {
      fixture_index: data.fixture_index,
      total_fixtures: data.total_fixtures,
      name: data.name,
      stem: data.stem,
      business: data.business || {},
    };
    try { localStorage.setItem('check_last_fixture', String(data.fixture_index)); } catch (_) {}
    window.setCurrentSvgExportName?.(data.name);

    window.setLoadingModalStatus?.('En cours', `Téléchargement SVG: ${data.name}`);
    window.appendLoadingModalLog?.(`Fixture ${data.fixture_index + 1}/${data.total_fixtures}: ${data.name}`);
    const svgRes = await fetch(data.svg_url, {cache: 'no-store'});
    const svgText = await svgRes.text();
    window.appendLoadingModalLog?.(`SVG reçu (${(svgText.length / 1024).toFixed(0)} KB)`);
    window.setLoadingModalStatus?.('En cours', 'Rendu SVG...');
    window.applySvgText(svgText);

    // Reuse PMR results from (1) server-side disk cache bundled in the
    // fixture payload, then (2) in-session memory cache — no recompute.
    const applyIncidents = (incidents, source) => {
      const byRule = {};
      const statusByRule = {};
      (incidents || []).forEach((inc) => {
        const code = inc.rule_code;
        if (!byRule[code]) byRule[code] = [];
        byRule[code].push(inc);
        const cur = statusByRule[code];
        if (cur !== 'ko') {
          statusByRule[code] = (inc.status === 'ko') ? 'ko' : 'ok';
        }
      });
      window.__checkState.pmrIncidentsByRule = byRule;
      window.__checkState.pmrStatusByRule = statusByRule;
      window.__checkState.pmrCache[data.stem] = {
        pmrIncidentsByRule: byRule,
        pmrStatusByRule: statusByRule,
      };
      window.checkRenderPanel();
      window.appendLoadingModalLog?.(`PMR: résultats restaurés depuis ${source}`);
      window.setLoadingModalStatus?.('Terminé', data.name);
      window.setTimeout(() => window.closeLoadingModal?.(), 400);
    };
    if (Array.isArray(data.pmr)) {
      applyIncidents(data.pmr, 'cache serveur');
      return;
    }
    const cached = window.__checkState.pmrCache[data.stem];
    if (cached) {
      window.__checkState.pmrIncidentsByRule = cached.pmrIncidentsByRule;
      window.__checkState.pmrStatusByRule = cached.pmrStatusByRule;
      window.checkRenderPanel();
      window.appendLoadingModalLog?.('PMR: résultats restaurés depuis le cache mémoire');
      window.setLoadingModalStatus?.('Terminé', data.name);
      window.setTimeout(() => window.closeLoadingModal?.(), 400);
      return;
    }

    // No server cache: PMR results are generated by the unit tests.
    window.appendLoadingModalLog?.('PMR: aucun cache — exécutez les tests unitaires (uv run pytest -n auto tests/test_pmr_basis.py)');
    window.checkRenderPanel();
    window.setLoadingModalStatus?.('Terminé', data.name);
    window.setTimeout(() => window.closeLoadingModal?.(), 600);
  } catch (err) {
    console.error('Check: failed to load fixture', err);
    window.setLoadingModalStatus?.('Erreur', String(err?.message || err));
    window.appendLoadingModalLog?.(String(err?.message || err), 'error');
  }
};


window.checkSelectRule = (ruleCode, incidentIdx) => {
  // incidentIdx: null = all instances, number = single instance
  const idxVal = (incidentIdx !== null && incidentIdx !== undefined) ? incidentIdx : null;
  const state = window.__checkState;
  // Toggle off when clicking the already-active selection
  if (state.activeRuleCode === ruleCode && state.activeIncidentIdx === idxVal) {
    state.activeRuleCode = null;
    state.activeIncidentIdx = null;
    window.clearAccessPathOverlays?.('pmr-check');
    window.checkRenderPanel();
    window.checkUpdateCommentOverlay?.();
    return;
  }
  state.activeRuleCode = ruleCode;
  state.activeIncidentIdx = idxVal;
  window.clearAccessPathOverlays?.('pmr-check');
  const incidents = state.pmrIncidentsByRule[ruleCode] || [];
  if (incidents.length === 0) {
    window.checkRenderPanel();
    return;
  }
  const toShow = idxVal !== null ? [incidents[idxVal]].filter(Boolean) : incidents;
  const merged = {
    circles: toShow.flatMap((i) => i.circles || []),
    paths: toShow.flatMap((i) => i.paths || []),
    fills: toShow.flatMap((i) => i.fills || []),
    labels: toShow.flatMap((i) => i.labels || []),
    images: toShow.flatMap((i) => i.images || []),
    actionId: 'pmr-check',
  };
  window.renderAccessPathCircles?.(merged);
  window.checkRenderPanel();

  // Zoom to incident when a sub-item is selected; leave view unchanged for main items
  if (idxVal !== null && window.zoomToBounds) {
    const svg = document.querySelector('.svg-clickable svg');
    if (svg) {
      const overlays = svg.querySelectorAll('[data-access-path-overlay="true"][data-analysis-action="pmr-check"]');
      let xmin = Infinity, ymin = Infinity, xmax = -Infinity, ymax = -Infinity;
      overlays.forEach((el) => {
        try {
          const bb = el.getBBox();
          if (bb.width === 0 && bb.height === 0) return;
          if (bb.x < xmin) xmin = bb.x;
          if (bb.y < ymin) ymin = bb.y;
          if (bb.x + bb.width > xmax) xmax = bb.x + bb.width;
          if (bb.y + bb.height > ymax) ymax = bb.y + bb.height;
        } catch (_) {}
      });
      if (isFinite(xmin) && isFinite(ymin) && isFinite(xmax) && isFinite(ymax)) {
        window.zoomToBounds(xmin, ymin, xmax, ymax);
      }
    }
  }
};

window.checkRenderPanel = () => {
  const state = window.__checkState;
  const cur = state.current;
  const infoEl = document.getElementById('check-fixture-info');
  const listEl = document.getElementById('check-rules-list');
  if (!cur || !infoEl || !listEl) return;

  const hasPrev = cur.fixture_index > 0;
  const hasNext = cur.fixture_index < cur.total_fixtures - 1;
  infoEl.innerHTML = '';
  const prevBtn = document.createElement('button');
  prevBtn.className = 'check-nav-btn';
  prevBtn.textContent = '◀';
  prevBtn.disabled = !hasPrev;
  prevBtn.addEventListener('click', () => window.checkGoToFixture(cur.fixture_index - 1));
  const nameSpan = document.createElement('span');
  nameSpan.className = 'check-fixture-name';
  nameSpan.title = cur.name;
  nameSpan.textContent = `(${cur.fixture_index + 1}/${cur.total_fixtures}) ${cur.name}`;
  const nextBtn = document.createElement('button');
  nextBtn.className = 'check-nav-btn';
  nextBtn.textContent = '▶';
  nextBtn.disabled = !hasNext;
  nextBtn.addEventListener('click', () => window.checkGoToFixture(cur.fixture_index + 1));
  infoEl.appendChild(prevBtn);
  infoEl.appendChild(nameSpan);
  infoEl.appendChild(nextBtn);

  listEl.innerHTML = '';

  // Extract a display name from an incident.
  // Priority: 1) label with kind ending in "label"/"name"  2) inc.message  3) "Inst. N"
  const getIncidentName = (inc, idx) => {
    for (const lbl of (inc?.labels || [])) {
      const kind = lbl?.kind || '';
      if (kind.endsWith('label') || kind.endsWith('name')) {
        const t = lbl?.text || lbl?.label || '';
        if (t && typeof t === 'string') return t;
      }
    }
    if (inc?.message && typeof inc.message === 'string') {
      // Use text before first ':' if present, else truncate
      const colon = inc.message.indexOf(':');
      const short = colon > 0 ? inc.message.slice(0, colon).trim() : inc.message.slice(0, 40).trim();
      if (short) return short;
    }
    return `Inst. ${idx + 1}`;
  };

  state.rules.forEach((rule) => {
    const incidents = state.pmrIncidentsByRule[rule.code] || [];
    const computed = state.pmrStatusByRule[rule.code] || null;
    const instanceDecisions = (cur.business && cur.business[rule.code]) || {};
    const isExpanded = state.expandedRules.has(rule.code);
    const isActive = state.activeRuleCode === rule.code && state.activeIncidentIdx === null;

    // ── Main rule row (no radios — click shows all instances) ──
    const row = document.createElement('div');
    row.className = 'check-rule';
    if (isActive) row.classList.add('is-active');
    row.dataset.ruleCode = rule.code;

    // Expand/collapse toggle button
    const expandBtn = document.createElement('button');
    expandBtn.type = 'button';
    expandBtn.className = 'check-rule-expand-btn';
    expandBtn.disabled = incidents.length === 0;
    expandBtn.textContent = incidents.length === 0 ? '○' : (isExpanded ? '▼' : '▶');
    expandBtn.title = isExpanded ? 'Replier' : `Déplier — ${incidents.length} instance(s)`;
    expandBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (state.expandedRules.has(rule.code)) state.expandedRules.delete(rule.code);
      else state.expandedRules.add(rule.code);
      window.checkRenderPanel();
    });

    const codeEl = document.createElement('span');
    codeEl.className = 'check-rule-code';
    codeEl.textContent = incidents.length > 0 ? `${rule.code} (${incidents.length})` : rule.code;

    const meta = document.createElement('div');
    meta.className = 'check-rule-meta';
    const codeLine = document.createElement('div');
    codeLine.className = 'check-rule-code-line';
    codeLine.appendChild(expandBtn);
    codeLine.appendChild(codeEl);
    const titleEl = document.createElement('div');
    titleEl.className = 'check-rule-title';
    titleEl.textContent = rule.title;
    meta.appendChild(codeLine);
    meta.appendChild(titleEl);
    if (rule.description) {
      const descEl = document.createElement('div');
      descEl.className = 'check-rule-desc';
      descEl.textContent = rule.description;
      meta.appendChild(descEl);
    }
    meta.addEventListener('click', () => window.checkSelectRule(rule.code, null));

    row.appendChild(meta);
    listEl.appendChild(row);

    // ── Sub-items: one per instance, shown when expanded ──
    if (isExpanded && incidents.length > 0) {
      incidents.forEach((inc, idx) => {
        const incStatus = inc.status || 'ok';
        const bizStatus = instanceDecisions[String(idx)] || 'none';
        const isSubActive = state.activeRuleCode === rule.code && state.activeIncidentIdx === idx;

        const subRow = document.createElement('div');
        subRow.className = 'check-rule check-rule-sub';
        if (bizStatus === 'ok') subRow.classList.add('is-ok');
        else if (bizStatus === 'ko') subRow.classList.add('is-ko');
        if (isSubActive) subRow.classList.add('is-active');
        subRow.dataset.ruleCode = rule.code;
        subRow.dataset.incidentIdx = String(idx);

        // Algo badge for this instance
        const subBadge = document.createElement('span');
        subBadge.className = 'check-rule-computed';
        if (incStatus === 'ok') {
          subBadge.classList.add('is-ok'); subBadge.textContent = '✓';
          subBadge.title = 'Instance conforme';
        } else {
          subBadge.classList.add('is-ko'); subBadge.textContent = '✗';
          subBadge.title = 'Instance non conforme';
        }
        const nameEl = document.createElement('span');
        nameEl.className = 'check-rule-code';
        nameEl.textContent = getIncidentName(inc, idx);

        const subMeta = document.createElement('div');
        subMeta.className = 'check-rule-meta';
        const subLine = document.createElement('div');
        subLine.className = 'check-rule-code-line';
        subLine.appendChild(subBadge);
        subLine.appendChild(nameEl);
        subMeta.appendChild(subLine);
        subRow.addEventListener('click', () => window.checkSelectRule(rule.code, idx));

        // Business radios for this instance
        const radios = document.createElement('div');
        radios.className = 'check-rule-radios';
        ['none', 'ok', 'ko'].forEach((value) => {
          const lbl = document.createElement('label');
          const input = document.createElement('input');
          input.type = 'radio';
          input.name = `check-inst-${rule.code}-${idx}`;
          input.value = value;
          input.checked = (bizStatus === value);
          input.addEventListener('change', () => window.checkOnRuleChange(rule.code, idx, value));
          lbl.addEventListener('click', (e) => e.stopPropagation());
          lbl.appendChild(input);
          lbl.appendChild(document.createTextNode(value === 'none' ? '∅' : value.toUpperCase()));
          radios.appendChild(lbl);
        });

        // Comment button for this instance
        const instComments = ((cur.business && cur.business._comments) || {})[rule.code] || {};
        const instCommentText = instComments[String(idx)] || '';
        const commentBtn = document.createElement('button');
        commentBtn.type = 'button';
        commentBtn.className = 'check-rule-comment-btn';
        if (instCommentText) commentBtn.classList.add('has-comment');
        commentBtn.textContent = '✎';
        commentBtn.title = instCommentText ? `Commentaire : ${instCommentText}` : 'Ajouter un commentaire';
        commentBtn.addEventListener('click', (e) => { e.stopPropagation(); window.checkEditComment(rule.code, idx, commentBtn); });

        subRow.appendChild(subMeta);
        subRow.appendChild(radios);
        subRow.appendChild(commentBtn);
        listEl.appendChild(subRow);
      });
    }
  });
  window.checkUpdateCommentOverlay();
};

window.checkEditComment = (ruleCode, incidentIdx, anchorEl) => {
  const cur = window.__checkState.current;
  if (!cur) return;

  // Remove any existing inline comment editor
  document.getElementById('check-comment-editor')?.remove();

  if (!cur.business._comments || typeof cur.business._comments !== 'object') {
    cur.business._comments = {};
  }
  if (!cur.business._comments[ruleCode] || typeof cur.business._comments[ruleCode] !== 'object') {
    cur.business._comments[ruleCode] = {};
  }
  const idxStr = String(incidentIdx);
  const current = cur.business._comments[ruleCode][idxStr] || '';

  // Build inline editor anchored below the button
  const editor = document.createElement('div');
  editor.id = 'check-comment-editor';
  editor.className = 'check-comment-editor';

  const input = document.createElement('input');
  input.type = 'text';
  input.value = current;
  input.placeholder = 'Commentaire…';
  input.className = 'check-comment-editor-input';

  const saveComment = () => {
    editor.remove();
    const trimmed = input.value.trim();
    if (trimmed) {
      cur.business._comments[ruleCode][idxStr] = trimmed;
    } else {
      delete cur.business._comments[ruleCode][idxStr];
      if (Object.keys(cur.business._comments[ruleCode]).length === 0) {
        delete cur.business._comments[ruleCode];
      }
    }
    if (window.__checkState.saveTimer) window.clearTimeout(window.__checkState.saveTimer);
    window.__checkState.saveTimer = window.setTimeout(() => {
      window.__checkState.saveTimer = null;
      window.checkSaveBusiness();
    }, 600);
    const stateEl = document.getElementById('check-save-state');
    if (stateEl) stateEl.textContent = '...';
    window.checkRenderPanel();
  };

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); saveComment(); }
    if (e.key === 'Escape') { editor.remove(); }
    e.stopPropagation();
  });
  input.addEventListener('blur', () => saveComment());
  input.addEventListener('click', (e) => e.stopPropagation());

  editor.appendChild(input);

  // Position below the anchor button
  if (anchorEl) {
    anchorEl.parentElement.appendChild(editor);
  } else {
    document.body.appendChild(editor);
  }
  input.focus();
  input.select();
};

window.checkUpdateCommentOverlay = () => {
  const state = window.__checkState;
  const cur = state && state.current;
  const svgContainer = document.querySelector('.svg-clickable');
  if (!svgContainer) return;
  let overlay = document.getElementById('check-comment-overlay');
  const activeCode = state && state.activeRuleCode;
  const activeIdx = state && state.activeIncidentIdx;
  const ruleComments = ((cur && cur.business && cur.business._comments) || {})[activeCode] || {};
  const text = (activeCode !== null && activeIdx !== null) ? (ruleComments[String(activeIdx)] || '') : '';
  if (!text) {
    if (overlay) overlay.remove();
    return;
  }
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'check-comment-overlay';
    overlay.className = 'check-comment-overlay';
    svgContainer.appendChild(overlay);
  }
  overlay.innerHTML = '';
  const codeEl = document.createElement('div');
  codeEl.className = 'check-comment-overlay-code';
  codeEl.textContent = 'commentaire :';
  const textEl = document.createElement('div');
  textEl.className = 'check-comment-overlay-text';
  textEl.textContent = text;
  overlay.appendChild(codeEl);
  overlay.appendChild(textEl);
};

window.checkOnRuleChange = (ruleCode, incidentIdx, status) => {
  const cur = window.__checkState.current;
  if (!cur) return;
  if (!cur.business[ruleCode] || typeof cur.business[ruleCode] !== 'object') {
    cur.business[ruleCode] = {};
  }
  cur.business[ruleCode][String(incidentIdx)] = status;
  // Update sub-row visual state
  const subRow = document.querySelector(
    `.check-rule-sub[data-rule-code="${CSS.escape(ruleCode)}"][data-incident-idx="${incidentIdx}"]`
  );
  if (subRow) {
    subRow.classList.remove('is-ok', 'is-ko');
    if (status === 'ok') subRow.classList.add('is-ok');
    else if (status === 'ko') subRow.classList.add('is-ko');
  }
  // Debounced save
  if (window.__checkState.saveTimer) window.clearTimeout(window.__checkState.saveTimer);
  window.__checkState.saveTimer = window.setTimeout(() => {
    window.__checkState.saveTimer = null;
    window.checkSaveBusiness();
  }, 600);
  const stateEl = document.getElementById('check-save-state');
  if (stateEl) stateEl.textContent = '...';
};

window.checkSaveBusiness = async () => {
  const cur = window.__checkState.current;
  if (!cur) return;
  const stateEl = document.getElementById('check-save-state');
  try {
    const res = await fetch(`/check/fixture/${cur.fixture_index}/business`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({business: cur.business}),
    });
    const data = await res.json();
    if (stateEl) stateEl.textContent = data?.ok ? 'sauvegardé' : 'erreur';
  } catch (err) {
    console.error('Check: save failed', err);
    if (stateEl) stateEl.textContent = 'erreur';
  }
};

// ── Performance (F1) modal ─────────────────────────────────────────────────

window._ensureCheckModal = () => {
  let modal = document.getElementById('check-perf-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'check-perf-modal';
    modal.className = 'check-perf-modal';
    modal.addEventListener('click', (e) => {
      if (e.target === modal) modal.remove();
    });
    document.body.appendChild(modal);
  }
  return modal;
};

// Flush any pending debounced business save before reading F1 stats.
window._flushPendingCheckSave = async () => {
  if (window.__checkState.saveTimer) {
    window.clearTimeout(window.__checkState.saveTimer);
    window.__checkState.saveTimer = null;
    await window.checkSaveBusiness();
  }
};

window.openCheckRules = async () => {
  if (typeof CHECK_MODE === 'undefined' || !CHECK_MODE) return;
  await window._flushPendingCheckSave();
  const modal = window._ensureCheckModal();
  window._renderPerfLoading(modal, 'Chargement…');
  try {
    const res = await fetch('/check/rules');
    const data = await res.json();
    window.renderCheckRules(modal, data);
  } catch (err) {
    window._renderPerfError(modal, err);
    console.error('Rules load failed', err);
  }
};


window._renderPerfError = (modal, err) => {
  modal.innerHTML = '';
  const panel = document.createElement('div');
  panel.className = 'check-perf-panel';
  const body = document.createElement('div');
  body.className = 'check-perf-body check-perf-empty';
  const title = document.createElement('div');
  title.style.fontWeight = '600';
  title.style.color = '#b91c1c';
  title.textContent = 'Erreur de calcul';
  const detail = document.createElement('div');
  detail.style.marginTop = '8px';
  detail.style.fontSize = '12px';
  detail.style.color = '#475569';
  detail.style.whiteSpace = 'pre-wrap';
  detail.textContent = String(err?.message || err || 'inconnue');
  const close = document.createElement('button');
  close.className = 'check-perf-btn';
  close.style.marginTop = '14px';
  close.textContent = 'Fermer';
  close.addEventListener('click', () => modal.remove());
  body.appendChild(title);
  body.appendChild(detail);
  body.appendChild(close);
  panel.appendChild(body);
  modal.appendChild(panel);
};

window._renderPerfLoading = (modal, message) => {
  modal.innerHTML = '';
  const panel = document.createElement('div');
  panel.className = 'check-perf-panel';
  const body = document.createElement('div');
  body.className = 'check-perf-body check-perf-empty';
  const spinner = document.createElement('div');
  spinner.className = 'check-perf-spinner';
  const label = document.createElement('div');
  label.style.marginTop = '10px';
  label.textContent = message || 'Chargement…';
  body.appendChild(spinner);
  body.appendChild(label);
  panel.appendChild(body);
  modal.appendChild(panel);
};



// ── Rules panel (per-rule F1 stats) ────────────────────────────────────────
window.renderCheckRules = (modal, data) => {
  if (!modal) return;
  const rules = Array.isArray(data?.rules) ? data.rules : [];
  const fixturesCount = data?.fixtures_count || 0;
  const computedAt = data?.computed_at || null;
  const panel = document.createElement('div');
  panel.className = 'check-perf-panel';

  const header = document.createElement('div');
  header.className = 'check-perf-header';
  const title = document.createElement('div');
  title.className = 'check-perf-title';
  const titleText = document.createElement('span');
  titleText.textContent = 'performance par règle';
  title.appendChild(titleText);
  const svgCount = document.createElement('span');
  svgCount.className = 'check-perf-svg-count';
  svgCount.textContent = `${fixturesCount} SVG`;
  title.appendChild(svgCount);
  if (computedAt) {
    const stamp = document.createElement('span');
    stamp.className = 'check-perf-svg-count';
    try {
      const d = new Date(computedAt);
      stamp.textContent = d.toLocaleString();
    } catch (_) {
      stamp.textContent = computedAt;
    }
    title.appendChild(stamp);
  }
  const actions = document.createElement('div');
  actions.className = 'check-perf-actions';
  const closeBtn = document.createElement('button');
  closeBtn.className = 'check-perf-btn';
  closeBtn.textContent = 'Fermer';
  closeBtn.addEventListener('click', () => modal.remove());
  actions.appendChild(closeBtn);
  header.appendChild(title);
  header.appendChild(actions);
  panel.appendChild(header);

  const body = document.createElement('div');
  body.className = 'check-perf-body check-rules-body';

  if (rules.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'check-perf-empty';
    empty.textContent = 'Aucune règle disponible.';
    body.appendChild(empty);
  } else {
    const headerRow = document.createElement('div');
    headerRow.className = 'check-rules-row is-header';
    ['Code', 'Règle', 'Catégorie', 'Total', 'Exemples', 'TP', 'TN', 'FP', 'FN'].forEach((label, idx) => {
      const cell = document.createElement('div');
      cell.textContent = label;
      if (idx >= 3) cell.className = 'check-perf-num';
      if (idx === 3) cell.title = 'Nombre total d\'incidents (sans filtre métier)';
      if (idx === 4) cell.title = 'Incidents avec annotation métier ok/ko';
      headerRow.appendChild(cell);
    });
    body.appendChild(headerRow);

    const makeCountCell = (value, {fnAlert, missing} = {}) => {
      const cell = document.createElement('div');
      cell.className = 'check-perf-num';
      if (value === null || value === undefined) {
        cell.textContent = '—';
        cell.classList.add('is-na');
      } else {
        cell.textContent = String(value);
        if (fnAlert && value > 0) cell.classList.add('check-perf-fn-alert');
        if (missing) cell.classList.add('check-perf-missing');
      }
      return cell;
    };

    rules.forEach((r) => {
      const row = document.createElement('div');
      row.className = 'check-rules-row';

      const codeCell = document.createElement('div');
      codeCell.className = 'check-perf-short';
      codeCell.textContent = r.code;

      const titleCell = document.createElement('div');
      titleCell.className = 'check-rules-title-cell';
      const tTitle = document.createElement('div');
      tTitle.className = 'check-rules-rule-title';
      tTitle.textContent = r.title || r.code;
      titleCell.appendChild(tTitle);
      if (r.description) {
        const desc = document.createElement('div');
        desc.className = 'check-rules-rule-desc';
        desc.textContent = r.description;
        titleCell.appendChild(desc);
      }

      const catCell = document.createElement('div');
      catCell.className = 'check-rules-cat';
      catCell.textContent = r.category || '—';

      const totalCell = document.createElement('div');
      totalCell.className = 'check-perf-num';
      totalCell.textContent = String(r.total || 0);
      totalCell.title = 'Incidents totaux (sans filtre métier)';

      const countCell = document.createElement('div');
      countCell.className = 'check-perf-num';
      countCell.textContent = String(r.count || 0);
      countCell.title = 'Incidents avec annotation métier ok/ko';

      const tp = r.tp || 0, tn = r.tn || 0, fp = r.fp || 0, fn = r.fn || 0;

      row.appendChild(codeCell);
      row.appendChild(titleCell);
      row.appendChild(catCell);
      row.appendChild(totalCell);
      row.appendChild(countCell);
      row.appendChild(makeCountCell(tp, {missing: tp === 0}));
      row.appendChild(makeCountCell(tn, {missing: tn === 0}));
      row.appendChild(makeCountCell(fp, {missing: fp > 0}));
      row.appendChild(makeCountCell(fn, {fnAlert: true}));
      body.appendChild(row);
    });
  }
  panel.appendChild(body);

  modal.innerHTML = '';
  modal.appendChild(panel);
};

window.initAppUiAfterAuth = async () => {
  // Verify auth server-side to prevent console bypass
  if (typeof AUTH_REQUIRED !== 'undefined' && AUTH_REQUIRED && !window._annotAuthenticated) {
    try {
      const res = await fetch('/auth/check');
      const data = await res.json();
      if (!data.authenticated) return;
    } catch (_) { return; }
    window._annotAuthenticated = true;
  }
  // Remove blur and restore interaction after successful auth
  [
    document.getElementById('floating-toolbar-container'),
    document.getElementById('floating-class-toolbar'),
    document.getElementById('floating-annotation-toolbar'),

    document.querySelector('.svg-clickable'),
  ].forEach(el => {
    if (!el) return;
    el.style.removeProperty('filter');
    el.style.removeProperty('pointer-events');
    el.style.removeProperty('user-select');
  });
  window.initFloatingPalette?.();
  window.initFloatingAnnotationToolbar?.();
  window.initFloatingAutosaveToolbar?.();
  window.initFloatingPmrToolbar?.();
  window.initZoomPan?.();
  window.setToolbarState?.(!!document.querySelector('.svg-clickable svg'));
  window.updateSelectionState?.();
  window.renderAnnotationHistory?.();
  window.refreshAutosaveList?.();
  if (typeof AUTH_REQUIRED !== 'undefined' && AUTH_REQUIRED) {
    window.startAnnotHeartbeat();
  }
  if (typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE) {
    // One-shot migration of pre-namespaced localStorage keys. Without
    // this, an upgrade-in-place would lose annotators' last-tile
    // pointer and any pending recovery save the first time they reload.
    window.__annotMigrateKey?.('annot_last_tile');
    window.__annotMigrateKey?.('annot_pending_save');

    // Recovery: replay any tile save that didn't reach the server before
    // the previous reload (auth expiry, network error, manual reload).
    // This must run BEFORE loading any tile, otherwise applySvgText would
    // overwrite the recovered DOM with the server's stale copy.
    try {
      const pending = localStorage.getItem(window.__ANNOT_PENDING_SAVE_KEY);
      if (pending) {
        const {tile_name, svg_text, ts, reason} = JSON.parse(pending);
        if (tile_name && svg_text) {
          console.warn(`[annot] Recovering pending save (${reason}, ${Math.round((Date.now() - ts) / 1000)}s ago): ${tile_name}`);
          const res = await fetch(`/annotation/save?tile_name=${encodeURIComponent(tile_name)}`, {
            method: 'POST',
            headers: {'Content-Type': 'text/plain; charset=utf-8'},
            body: svg_text,
          });
          if (res.ok) {
            localStorage.removeItem(window.__ANNOT_PENDING_SAVE_KEY);
            console.log('[annot] Recovery save OK');
          } else if (res.status === 409) {
            // Poison payload: SVG identity doesn't match the target tile.
            // Replaying it on every reload would 409 forever and prevent
            // the user from making progress, so drop it and log loudly.
            let detail = '';
            try { detail = JSON.stringify(await res.json()); } catch (_) {}
            console.error(`[annot] Recovery save REJECTED 409 (mismatch) for ${tile_name} — discarding poison payload: ${detail}`);
            localStorage.removeItem(window.__ANNOT_PENDING_SAVE_KEY);
          } else {
            console.error('[annot] Recovery save HTTP error', res.status);
          }
        }
      }
    } catch (e) { console.error('[annot] Recovery save failed', e); }

    // Restore last tile from server-side persistence, fallback to localStorage
    let lastTile = null;
    try {
      const res = await fetch('/annotation/last-tile', {cache: 'no-store'});
      const data = await res.json();
      if (data?.ok && data.tile_index !== null && data.tile_index !== undefined) {
        lastTile = data.tile_index;
      }
    } catch (_) {}
    if (lastTile === null) {
      try { const v = localStorage.getItem(window.__annotStorageKey('annot_last_tile')); if (v !== null) lastTile = Number(v); } catch (_) {}
    }
    if (lastTile !== null && !isNaN(Number(lastTile))) {
      window.annotGoToTile(Number(lastTile));
    } else {
      window.annotLoadCurrentTile();
    }
  }
  if (typeof CHECK_MODE !== 'undefined' && CHECK_MODE) {
    window.checkInit();
  }
};

window.initAppUi = async () => {
  const authRequired = typeof AUTH_REQUIRED !== 'undefined' && AUTH_REQUIRED;
  if (authRequired) {
    // Apply heavy blur + disable interaction on all UI content until authenticated
    const _authBlurTargets = [
      document.getElementById('floating-toolbar-container'),
      document.getElementById('floating-class-toolbar'),
      document.getElementById('floating-annotation-toolbar'),

      document.querySelector('.svg-clickable'),
    ];
    _authBlurTargets.forEach(el => {
      if (!el) return;
      el.style.setProperty('filter', 'blur(20px)');
      el.style.setProperty('pointer-events', 'none');
      el.style.setProperty('user-select', 'none');
    });
    try {
      const res = await fetch('/auth/check');
      const data = await res.json();
      if (data.authenticated) {
        window._annotAuthenticated = true;
        window.initAppUiAfterAuth();
        return;
      }
    } catch (_) { /* needs login */ }
    window.showAnnotLoginModal();
    return;
  }
  window.initAppUiAfterAuth();
};

