# Single-user session: one user at a time, in both annotation and normal mode
_annot_session: dict[str, Any] = {}  # {token, created_at, last_heartbeat}
_annot_session_lock = threading.Lock()

ANNOT_HEARTBEAT_TIMEOUT = 30  # seconds — session expires if no heartbeat for this long
ANNOT_SESSION_MAX_AGE = 24 * 60 * 60  # 24 hours absolute max session duration



def _session_alive() -> bool:
    """Return True if the single-user session has a recent heartbeat and hasn't exceeded max age."""
    last = _annot_session.get("last_heartbeat")
    if not last:
        return False
    now = datetime.now(timezone.utc)
    if (now - last).total_seconds() >= ANNOT_HEARTBEAT_TIMEOUT:
        return False
    created_str = _annot_session.get("created_at")
    if created_str:
        try:
            created = datetime.fromisoformat(created_str)
            if (now - created).total_seconds() >= ANNOT_SESSION_MAX_AGE:
                return False
        except (ValueError, TypeError):
            pass
    return True


def _is_token_valid(token: str) -> bool:
    """Check if a session token matches the active session and is not expired."""
    if not token or token != _annot_session.get("token"):
        return False
    return _session_alive()


