def _require_annot_auth(request: Request):
    """FastAPI dependency: reject if password auth is enabled and token is invalid."""
    if not ANNOT_PASSWORD:
        return
    token = request.cookies.get("annot_token", "")
    with _annot_session_lock:
        if not _is_token_valid(token):
            raise HTTPException(status_code=401, detail="Not authenticated.")


_login_attempts: list[float] = []  # timestamps of failed login attempts
_LOGIN_MAX_ATTEMPTS = 5
_LOGIN_WINDOW_SECONDS = 60

@app.post("/auth/login")
def auth_login(payload: dict = Body(...)) -> JSONResponse:
    """Validate password and create a session."""
    if not ANNOT_PASSWORD:
        return JSONResponse({"ok": True, "message": "No authentication required."})
    # Rate limiting: max 5 failed attempts per 60 seconds
    now = time.monotonic()
    with _annot_session_lock:
        _login_attempts[:] = [t for t in _login_attempts if now - t < _LOGIN_WINDOW_SECONDS]
        if len(_login_attempts) >= _LOGIN_MAX_ATTEMPTS:
            return JSONResponse(
                {"ok": False, "error": "Trop de tentatives. Réessayez dans une minute."},
                status_code=429,
            )
    password = (payload.get("password") or "") if isinstance(payload, dict) else ""
    if not hmac.compare_digest(password, ANNOT_PASSWORD):
        with _annot_session_lock:
            _login_attempts.append(now)
        return JSONResponse({"ok": False, "error": "Mot de passe incorrect."}, status_code=403)
    with _annot_session_lock:
        # Single-user: reject if another session is active
        if _annot_session.get("token") and _session_alive():
            return JSONResponse(
                {"ok": False, "error": "Une session est déjà active dans un autre onglet. Fermez-le d'abord."},
                status_code=409,
            )
        now_utc = datetime.now(timezone.utc)
        token = uuid.uuid4().hex
        _annot_session.clear()
        _annot_session["token"] = token
        _annot_session["created_at"] = now_utc.isoformat()
        _annot_session["last_heartbeat"] = now_utc
    response = JSONResponse({"ok": True})
    response.set_cookie("annot_token", token, httponly=True, samesite="lax", secure=not _IS_LOCALHOST)
    return response


@app.get("/auth/check")
def auth_check(request: Request) -> dict:
    """Check if the current session is still valid."""
    if not ANNOT_PASSWORD:
        return {"ok": True, "authenticated": True}
    token = request.cookies.get("annot_token", "")
    with _annot_session_lock:
        if _is_token_valid(token):
            return {"ok": True, "authenticated": True}
    return {"ok": True, "authenticated": False}


@app.post("/auth/heartbeat")
def auth_heartbeat(request: Request) -> dict:
    """Keep the session alive."""
    if not ANNOT_PASSWORD:
        return {"ok": True}
    token = request.cookies.get("annot_token", "")
    with _annot_session_lock:
        if not _is_token_valid(token):
            raise HTTPException(status_code=401, detail="Not authenticated.")
        _annot_session["last_heartbeat"] = datetime.now(timezone.utc)
    return {"ok": True}


@app.post("/auth/logout")
def auth_logout(request: Request) -> JSONResponse:
    """Invalidate the current session."""
    if not ANNOT_PASSWORD:
        return JSONResponse({"ok": True})
    token = request.cookies.get("annot_token", "")
    with _annot_session_lock:
        if token and token == _annot_session.get("token"):
            _annot_session.clear()
    response = JSONResponse({"ok": True})
    response.delete_cookie("annot_token")
    return response


# Protected static file serving — replaces public add_static_files for sensitive dirs
import mimetypes

_PROTECTED_DIR_MAP = {
    "data": Path("data"),
    "cache": CACHE_DIR,
    "autosave-files": AUTOSAVE_BASE_DIR,
    "annotation-tiles": ANNOT_TILES_DIR,
}

@app.get("/data/{file_path:path}", dependencies=[Depends(_require_annot_auth)])
@app.get("/cache/{file_path:path}", dependencies=[Depends(_require_annot_auth)])
@app.get("/autosave-files/{file_path:path}", dependencies=[Depends(_require_annot_auth)])
@app.get("/annotation-tiles/{file_path:path}", dependencies=[Depends(_require_annot_auth)])
def _serve_protected_static(request: Request, file_path: str):
    """Serve files from protected directories with auth check."""
    prefix = request.url.path.split("/")[1]
    base_dir = _PROTECTED_DIR_MAP.get(prefix)
    if not base_dir:
        raise HTTPException(status_code=404, detail="Not found")
    resolved = (base_dir / file_path).resolve()
    if not str(resolved).startswith(str(base_dir.resolve())):
        raise HTTPException(status_code=403, detail="Forbidden")
    if not resolved.is_file():
        raise HTTPException(status_code=404, detail="Not found")
    content_type = mimetypes.guess_type(str(resolved))[0] or "application/octet-stream"
    return StarletteResponse(content=resolved.read_bytes(), media_type=content_type)


