# Ouverture .svg ou .pdf (SPECS.md : ouverture fichiers)
def _decode_svg_bytes(data: bytes) -> str:
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return data.decode("utf-8", errors="replace")


def _read_svg_file(svg_path: Path) -> str:
    return _decode_svg_bytes(svg_path.read_bytes())


_pdf_open_jobs: dict[str, dict[str, Any]] = {}
_pdf_open_jobs_lock = threading.Lock()
_pdf_upload_sessions: dict[str, dict[str, Any]] = {}
_pdf_upload_sessions_lock = threading.Lock()
_SHA1_PREFIX_RE = re.compile(r"^(?P<sha1>[0-9a-f]{40})_(?P<name>.+)$")
AUTOSAVE_DIR = AUTOSAVE_BASE_DIR
if not (ANNOT_MODE or CHECK_MODE):
    AUTOSAVE_DIR.mkdir(parents=True, exist_ok=True)
_AUTOSAVE_FILE_RE = re.compile(r"^(?P<timestamp>\d{8}T\d{6}\d{3}Z)__(?P<basename>.+)\.svg$")
_AUTOSAVE_SHA1_DISPLAY_LENGTH = 6


def _strip_cache_sha1_prefix(name: str) -> str:
    match = _SHA1_PREFIX_RE.match(name)
    if not match:
        return name
    return match.group("name")


def _sanitize_autosave_basename(name: str) -> str:
    raw = Path(str(name or "").strip() or "annotated.svg").name
    stem = Path(raw).stem or "annotated"
    slug = re.sub(r"[^A-Za-z0-9._-]+", "-", stem).strip("._-")
    return slug or "annotated"


def _build_autosave_filename(base_name: str, timestamp: datetime | None = None) -> str:
    current = timestamp or datetime.now(timezone.utc)
    stamp = current.strftime("%Y%m%dT%H%M%S%f")[:18] + "Z"
    return f"{stamp}__{_sanitize_autosave_basename(base_name)}.svg"


def _build_autosave_display_name(base_name: str) -> str:
    match = _SHA1_PREFIX_RE.match(base_name)
    if not match:
        return base_name
    return match.group("sha1")[:_AUTOSAVE_SHA1_DISPLAY_LENGTH]


def _serialize_autosave_item(path: Path) -> dict[str, Any] | None:
    match = _AUTOSAVE_FILE_RE.match(path.name)
    if not match:
        return None
    timestamp_raw = match.group("timestamp")
    try:
        created_at = datetime.strptime(timestamp_raw, "%Y%m%dT%H%M%S%fZ").replace(tzinfo=timezone.utc)
    except ValueError:
        return None
    return {
        "id": path.name,
        "file_name": path.name,
        "base_name": match.group("basename"),
        "display_name": _build_autosave_display_name(match.group("basename")),
        "created_at": created_at.isoformat(),
        "created_at_epoch_ms": int(created_at.timestamp() * 1000),
        "svg_url": f"/autosave-files/{path.name}",
    }


def _list_autosave_items(limit: int = 50) -> list[dict[str, Any]]:
    items: list[tuple[float, dict[str, Any]]] = []
    for path in AUTOSAVE_DIR.glob("*.svg"):
        item = _serialize_autosave_item(path)
        if not item:
            continue
        items.append((path.stat().st_mtime, item))
    items.sort(key=lambda entry: entry[0], reverse=True)
    return [item for _, item in items[:limit]]


def _first_generated_svg_path(
    pdf_path: Path,
    page_number: int = 1,
    selected_scale: str | int | None = None,
) -> Path:
    return pdf_path.parent / f"{get_svg_cache_base_name(pdf_path, page_number, scale=selected_scale)}_p{page_number}.svg"


def _legacy_generated_svg_path(pdf_path: Path, page_number: int = 1) -> Path:
    return pdf_path.parent / f"{get_pdf_cache_base_name(pdf_path)}_p{page_number}.svg"


def _resolve_generated_svg_path(
    pdf_path: Path,
    page_number: int = 1,
    selected_scale: str | int | None = None,
) -> Path | None:
    expected_path = _first_generated_svg_path(pdf_path, page_number, selected_scale=selected_scale)
    if expected_path.exists():
        return expected_path

    legacy_path = _legacy_generated_svg_path(pdf_path, page_number)
    if legacy_path.exists():
        return legacy_path

    original_stem = Path(_strip_cache_sha1_prefix(pdf_path.stem)).stem or "document"
    pattern = str(pdf_path.parent / f"*_{original_stem}_p{page_number}.svg")
    candidates = [Path(path) for path in glob(pattern)]
    if candidates:
        return max(candidates, key=lambda path: path.stat().st_mtime)

    return None


def _infer_pdf_job_status(message: str) -> tuple[str, str]:
    normalized = (message or "").strip()
    lowered = normalized.lower()
    if lowered.startswith("file:"):
        return "Preparation", normalized
    if "reading pdf metadata" in lowered:
        return "Analysis", normalized
    if "page " in lowered and "cm x" in lowered:
        return "Analysis", normalized
    if "scales found" in lowered or "using scale" in lowered:
        return "Analysis", normalized
    if "selected scale" in lowered or "selected page" in lowered:
        return "Configuration", normalized
    if "export pdf -> svg" in lowered:
        return "Conversion", normalized
    if "prepare svg tree" in lowered:
        return "Conversion", normalized
    if "export svg with inkscape" in lowered:
        return "Conversion", normalized
    if "flatten and normalize svg" in lowered:
        return "Conversion", normalized
    if "restore text classification" in lowered:
        return "Conversion", normalized
    if "wrote svg:" in lowered:
        return "Generation", normalized
    if "pdf conversion finished" in lowered:
        return "Done", normalized
    if lowered.startswith("error:"):
        return "Error", normalized
    return "Processing", normalized


def _append_pdf_job_log(job_id: str, message: str) -> None:
    status, step = _infer_pdf_job_status(message)
    with _pdf_open_jobs_lock:
        job = _pdf_open_jobs.get(job_id)
        if not job:
            return
        job["logs"].append(message)
        job["status"] = status
        job["step"] = step


def _run_pdf_open_job(
    job_id: str,
    pdf_path: Path,
    pdf_dir: Path,
    selected_scale: str,
    page_number: int | None,
    analysis: dict[str, Any] | None,
) -> None:
    try:
        ok = process_pdf_file(
            str(pdf_path),
            str(pdf_dir),
            selected_scale=selected_scale,
            page_number=page_number,
            analysis=analysis,
            log_analysis=False,
            text_color_name="text",
            remove_images=True,
            log_callback=lambda message: _append_pdf_job_log(job_id, message),
        )
        if not ok:
            with _pdf_open_jobs_lock:
                job = _pdf_open_jobs.get(job_id)
                if job:
                    job["done"] = True
                    job["ok"] = False
                    job["error"] = "PDF conversion failed."
                    job["status"] = "Error"
                    job["step"] = "PDF conversion failed"
            return

        source_svg = _resolve_generated_svg_path(pdf_path, page_number or 1, selected_scale=selected_scale)
        if source_svg is None:
            with _pdf_open_jobs_lock:
                job = _pdf_open_jobs.get(job_id)
                if job:
                    job["done"] = True
                    job["ok"] = False
                    job["error"] = f"No SVG output generated for page {page_number or 1}."
                    job["status"] = "Error"
                    job["step"] = "No SVG output generated"
            return

        _append_pdf_job_log(job_id, f"Final SVG prepared: {source_svg.name}")
        _append_pdf_job_log(job_id, "SVG ready for browser display")
        with _pdf_open_jobs_lock:
            job = _pdf_open_jobs.get(job_id)
            if job:
                job["done"] = True
                job["ok"] = True
                job["svg_url"] = f"/cache/{source_svg.name}"
                job["svg_path"] = str(source_svg)
                job["status"] = "Done"
                job["step"] = "PDF displayed"
    except Exception as exc:
        _append_pdf_job_log(job_id, f"Error: {exc}")
        with _pdf_open_jobs_lock:
            job = _pdf_open_jobs.get(job_id)
            if job:
                job["done"] = True
                job["ok"] = False
                job["error"] = str(exc)
                job["status"] = "Error"
                job["step"] = str(exc)


@app.post("/open-file", dependencies=[Depends(_require_annot_auth)])
def open_file(file: UploadFile = File(...)) -> dict:
    filename = file.filename or ""
    lower = filename.lower()
    data = file.file.read()
    logs: list[str] = [f"Received file: {Path(filename).name or 'upload'}"]
    if lower.endswith(".svg"):
        safe_name = Path(filename).name or "upload.svg"
        safe_base = Path(safe_name).stem or "upload"
        pdf_dir = CACHE_DIR
        pdf_dir.mkdir(parents=True, exist_ok=True)
        svg_path = pdf_dir / f"{uuid.uuid4().hex}_{safe_base}.svg"
        svg_path.write_bytes(data)
        logs.append("Reading SVG file")
        logs.append("Sending SVG to the web interface")
        return {
            "ok": True,
            "svg": _decode_svg_bytes(data),
            "svg_url": f"/cache/{svg_path.name}",
            "logs": logs,
            "source_type": "svg",
        }

    if not lower.endswith(".pdf"):
        return {"ok": False, "error": "Unsupported file type."}

    # Pour les PDF, on génère un SVG persistant à côté du fichier source et
    # on réutilise ensuite le même code de lecture que pour un .svg chargé directement.
    safe_name = Path(filename).name
    pdf_dir = CACHE_DIR
    pdf_dir.mkdir(parents=True, exist_ok=True)

    pdf_path = cache_pdf_bytes(safe_name, data, pdf_dir)
    logs.append(f"Cached PDF: {pdf_path.name}")

    ok = process_pdf_file(
        str(pdf_path),
        str(pdf_dir),
        text_color_name="text",
        remove_images=True,
        log_callback=logs.append,
    )
    if not ok:
        return {"ok": False, "error": "PDF conversion failed.", "logs": logs, "source_type": "pdf"}

    source_svg = _resolve_generated_svg_path(pdf_path)
    if source_svg is None:
        return {"ok": False, "error": "No SVG output generated for page 1.", "logs": logs, "source_type": "pdf"}

    logs.append(f"Final SVG prepared: {source_svg.name}")
    logs.append("SVG ready for browser display")
    return {
        "ok": True,
        "svg_url": f"/cache/{source_svg.name}",
        "svg_path": str(source_svg),
        "logs": logs,
        "source_type": "pdf",
    }


@app.post("/open-file/pdf/start", dependencies=[Depends(_require_annot_auth)])
def open_pdf_start(
    upload_id: str = Form(...),
    scale: str = Form(...),
    page_number: int = Form(1),
) -> dict:
    with _pdf_upload_sessions_lock:
        upload_session = _pdf_upload_sessions.get(upload_id)
    if not upload_session:
        return {"ok": False, "error": "Unknown upload session."}

    pdf_path = Path(upload_session["pdf_path"])
    safe_name = upload_session["safe_name"]
    page_count = int(upload_session.get("page_count") or 0)
    if page_number < 1 or (page_count and page_number > page_count):
        return {"ok": False, "error": f"Invalid page number: {page_number}"}
    normalized_scale = normalize_scale(scale)
    if not normalized_scale:
        return {"ok": False, "error": f"Invalid scale: {scale}"}
    job_id = uuid.uuid4().hex
    initial_logs = [
        f"Selected page: {page_number}",
        f"Selected scale: {normalized_scale}",
    ]
    with _pdf_open_jobs_lock:
        _pdf_open_jobs[job_id] = {
            "done": False,
            "ok": None,
            "error": None,
            "logs": initial_logs[:],
            "status": "Queued",
            "step": "Preparing PDF conversion",
            "svg_url": None,
            "svg_path": None,
        }

    analysis = {
        "page_count": upload_session.get("page_count"),
        "page_sizes": upload_session.get("page_sizes") or [],
        "scales": upload_session.get("scales") or [],
    }
    thread = threading.Thread(
        target=_run_pdf_open_job,
        args=(job_id, pdf_path, pdf_path.parent, normalized_scale, page_number, analysis),
        daemon=True,
    )
    thread.start()

    return {
        "ok": True,
        "job_id": job_id,
        "logs": initial_logs,
        "next_offset": len(initial_logs),
        "status": "Queued",
        "step": "Preparing PDF conversion",
        "source_type": "pdf",
    }


@app.post("/open-file/pdf/analyze", dependencies=[Depends(_require_annot_auth)])
def open_pdf_analyze(file: UploadFile = File(...)) -> dict:
    filename = file.filename or ""
    lower = filename.lower()
    if not lower.endswith(".pdf"):
        return {"ok": False, "error": "Unsupported file type."}

    data = file.file.read()
    safe_name = Path(filename).name or "upload.pdf"
    upload_id = uuid.uuid4().hex
    pdf_dir = CACHE_DIR
    pdf_dir.mkdir(parents=True, exist_ok=True)
    pdf_path = cache_pdf_bytes(safe_name, data, pdf_dir)

    logs = [
        f"Received PDF file: {safe_name}",
        f"Cached PDF: {pdf_path.name}",
        "Reading PDF metadata and extracting text",
    ]
    try:
        analysis = analyze_pdf_file(str(pdf_path))
    except Exception as exc:
        logs.append(f"Error: {exc}")
        return {"ok": False, "error": str(exc), "logs": logs}

    page_sizes = analysis["page_sizes"]
    for page_info in page_sizes:
        logs.append(
            f"  Page {page_info['page_number']}: {page_info['width_cm']:.2f} cm x {page_info['height_cm']:.2f} cm"
        )
    scales = analysis["scales"]
    logs.append(f"  Scales found: {', '.join(scales)}" if scales else "  Scales found: none")

    with _pdf_upload_sessions_lock:
        _pdf_upload_sessions[upload_id] = {
            "pdf_path": str(pdf_path),
            "safe_name": safe_name,
            "page_count": analysis["page_count"],
            "page_sizes": page_sizes,
            "scales": scales,
        }

    return {
        "ok": True,
        "upload_id": upload_id,
        "logs": logs,
        "page_count": analysis["page_count"],
        "page_sizes": page_sizes,
