    svgs_dir = Path("data") / "svgs"
    if not svgs_dir.is_dir():
        return {"ok": True, "items": []}
    items = []
    for path in sorted(svgs_dir.iterdir(), key=lambda p: p.name.lower()):
        if path.is_file() and path.suffix.lower() == ".svg":
            try:
                size = path.stat().st_size
            except OSError:
                size = 0
            items.append({
                "name": path.name,
                "url": f"/data/svgs/{path.name}",
                "size": size,
            })
