@app.post("/internal-svgs/save", dependencies=[Depends(_require_annot_auth)])
def save_internal_svg(payload: dict = Body(...)) -> dict:
    """Save an SVG payload into data/svgs/<filename>.

    The filename is sanitized (basename only) and must end with .svg.
    """
    if not isinstance(payload, dict):
        return {"ok": False, "error": "Invalid payload."}
    filename_raw = payload.get("filename")
    svg_text = payload.get("svg")
    if not isinstance(filename_raw, str) or not filename_raw.strip():
        return {"ok": False, "error": "Missing filename."}
    if not isinstance(svg_text, str) or not svg_text.strip():
        return {"ok": False, "error": "Missing svg content."}

    safe_name = Path(filename_raw).name
    if not safe_name or safe_name in {".", ".."}:
        return {"ok": False, "error": "Invalid filename."}
    if not safe_name.lower().endswith(".svg"):
        safe_name = f"{safe_name}.svg"

    svgs_dir = Path("data") / "svgs"
    svgs_dir.mkdir(parents=True, exist_ok=True)
    target = (svgs_dir / safe_name).resolve()
    if not str(target).startswith(str(svgs_dir.resolve())):
        return {"ok": False, "error": "Forbidden path."}

    target.write_text(svg_text, encoding="utf-8")
    return {
        "ok": True,
        "name": safe_name,
        "url": f"/data/svgs/{safe_name}",
        "size": target.stat().st_size,
    }


