@app.post("/autosave", dependencies=[Depends(_require_annot_auth)])
async def create_autosave(payload: dict = Body(...)) -> dict:
    svg_text = payload.get("svg") if isinstance(payload, dict) else None
    file_name = payload.get("file_name") if isinstance(payload, dict) else None
    if not isinstance(svg_text, str) or not svg_text.strip():
        return {"ok": False, "error": "Missing svg payload."}

    def _persist_autosave() -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
        autosave_name = _build_autosave_filename(str(file_name or "annotated.svg"))
        autosave_path = AUTOSAVE_DIR / autosave_name
        autosave_path.write_text(svg_text, encoding="utf-8")
        item = _serialize_autosave_item(autosave_path)
        return item, _list_autosave_items()

    item, items = await asyncio.to_thread(_persist_autosave)
    if item is None:
        return {"ok": False, "error": "Autosave metadata generation failed."}
    return {
        "ok": True,
        "item": item,
        "items": items,
    }


