    item = _serialize_autosave_item(target)
    if item is None:
        raise HTTPException(status_code=404, detail="Unknown autosave.")
    return {
        "ok": True,
        "item": item,
        "svg": _read_svg_file(target),
    }


# ── Annotation mode tile management ──────────────────────────────────────────

def _annot_all_tiles() -> list[Path]:
    """Return all tile SVG paths in annotation/tiles/, sorted by index prefix."""
    if not ANNOT_TILES_DIR.exists():
        return []
    return sorted(ANNOT_TILES_DIR.glob("*_tile_r*c*.svg"))


# ---- Tile stats cache (persisted to annotation/tiles/_stats_cache.json) ----
# In-memory dict keyed by tile filename → (mtime, stats_dict)
_tile_stats_cache: dict[str, tuple[float, dict]] = {}
_STATS_CACHE_PATH = ANNOT_TILES_DIR / "_stats_cache.json"
_CURRENT_TILE_PATH = ANNOT_TILES_DIR / "_current_tile.txt"


def _read_current_tile_index() -> int | None:
    """Read persisted current tile index from disk."""
    try:
        return int(_CURRENT_TILE_PATH.read_text(encoding="utf-8").strip())
    except Exception:
        return None


def _write_current_tile_index(index: int) -> None:
    """Persist current tile index to disk."""
    try:
        _CURRENT_TILE_PATH.write_text(str(index), encoding="utf-8")
    except Exception:
        pass


def _load_stats_cache() -> None:
    """Load the stats cache from disk into memory."""
    global _tile_stats_cache
    if _STATS_CACHE_PATH.exists():
        try:
            import json
            data = json.loads(_STATS_CACHE_PATH.read_text(encoding="utf-8"))
            _tile_stats_cache = {k: (v[0], v[1]) for k, v in data.items()}
        except Exception:
            _tile_stats_cache = {}


def _save_stats_cache() -> None:
    """Persist the current stats cache to disk."""
    try:
        import json
        _STATS_CACHE_PATH.write_text(
            json.dumps(_tile_stats_cache, ensure_ascii=False),
            encoding="utf-8",
        )
    except Exception:
        pass


# Load cache on startup
_load_stats_cache()


def _annot_tile_full_stats(svg_path: Path) -> dict:
    """Parse a tile once and return total, annotated, has_unlabelled, is_empty.

    Results are cached by file mtime — re-parsed only when the file changes.
    Cache is persisted to disk so it survives server restarts.
    """
    import xml.etree.ElementTree as _ET

    key = svg_path.name
    try:
        mtime = svg_path.stat().st_mtime
    except OSError:
        mtime = 0.0

    cached = _tile_stats_cache.get(key)
    if cached is not None and cached[0] == mtime:
        return cached[1]

    tree = _ET.parse(svg_path)
    root = tree.getroot()
    total = 0
    annotated = 0
    has_unlabelled = False
    is_empty = True
    for el in root.iter():
        tag = el.tag
        if tag.startswith("{"):
            tag = tag.split("}", 1)[1]
        if tag not in DRAWABLE_TAGS:
            continue
        is_empty = False
        if el.get("data-class-overlay-for") is not None:
            continue
        class_id = (el.get("classId") or el.get("classid") or "").strip().lower()
        if class_id in ("frozen", "text", "texture"):
            continue
        total += 1
        if class_id and class_id != "unlabelled":
            annotated += 1
        else:
            has_unlabelled = True

    result = {
        "total": total,
        "annotated": annotated,
        "has_unlabelled": has_unlabelled,
        "is_empty": is_empty,
    }
    _tile_stats_cache[key] = (mtime, result)
    _save_stats_cache()
    return result


def _annot_tile_has_unlabelled(svg_path: Path) -> bool:
    """Check if an SVG tile still has unlabelled primitives (excluding frozen/text/texture)."""
    return _annot_tile_full_stats(svg_path)["has_unlabelled"]


def _annot_tile_is_empty(svg_path: Path) -> bool:
    """Check if tile has 0 drawable primitives."""
    return _annot_tile_full_stats(svg_path)["is_empty"]




def _annot_tile_url(tile_path: Path) -> str:
    """Build the serving URL for a tile in annotation/tiles/.

    Includes the file mtime as a cache-buster so reverse proxies
    (e.g. Cloudflare) serve the latest version after a save.
    """
    try:
        mtime = int(tile_path.stat().st_mtime)
    except OSError:
        mtime = 0
    return f"/annotation-tiles/{tile_path.name}?v={mtime}"


def _annot_resolve_current_tile() -> dict | None:
    """Find the current tile to annotate.

    Priority:
    1. Last in-progress tile (has unlabelled primitives)
    2. Next unannotated tile (skip empty tiles)

    All tiles are served directly from annotation/tiles/.
    """
    all_tiles = _annot_all_tiles()
    if not all_tiles:
        return None

    # Find last in-progress tile (has unlabelled primitives)
    for tile_path in all_tiles:
        if _annot_tile_has_unlabelled(tile_path):
            idx = all_tiles.index(tile_path)
            return {
                "tile_path": str(tile_path),
                "tile_name": tile_path.name,
                "tile_index": idx,
                "total_tiles": len(all_tiles),
                "svg_url": _annot_tile_url(tile_path),
                "source": "tiles",
            }

    # Find first tile that hasn't been fully annotated yet
    for idx, tile_path in enumerate(all_tiles):
        if not _annot_tile_has_unlabelled(tile_path):
            continue  # Already fully annotated
        if _annot_tile_is_empty(tile_path):
            continue  # Skip empty tiles
        return {
            "tile_path": str(tile_path),
            "tile_name": tile_path.name,
            "tile_index": idx,
            "total_tiles": len(all_tiles),
            "svg_url": _annot_tile_url(tile_path),
            "source": "tiles",
        }

    return None  # All tiles are fully annotated


@app.get("/annotation/last-tile", dependencies=[Depends(_require_annot_auth)])
def annot_last_tile() -> dict:
    """Return the last persisted tile index (server-side)."""
    idx = _read_current_tile_index()
    if idx is not None:
        all_tiles = _annot_all_tiles()
        if 0 <= idx < len(all_tiles):
            return {"ok": True, "tile_index": idx}
    return {"ok": True, "tile_index": None}


@app.get("/annotation/current", dependencies=[Depends(_require_annot_auth)])
def annot_current_tile() -> dict:
    tile = _annot_resolve_current_tile()
    if tile is None:
        return {"ok": True, "done": True, "message": "All tiles are fully annotated."}
    return {"ok": True, "done": False, **tile}


@app.get("/annotation/tile/{tile_index}", dependencies=[Depends(_require_annot_auth)])
def annot_tile_by_index(tile_index: int) -> dict:
    """Load a specific tile by index."""
    all_tiles = _annot_all_tiles()
    if not all_tiles:
        return {"ok": False, "error": "No tiles available."}
    if tile_index < 0 or tile_index >= len(all_tiles):
        return {"ok": False, "error": f"Tile index {tile_index} out of range (0-{len(all_tiles) - 1})."}
    _write_current_tile_index(tile_index)
    tile_path = all_tiles[tile_index]
    return {
        "ok": True,
        "done": False,
        "tile_path": str(tile_path),
        "tile_name": tile_path.name,
        "tile_index": tile_index,
        "total_tiles": len(all_tiles),
        "svg_url": _annot_tile_url(tile_path),
        "source": "tiles",
    }


# Tile filename grammar: ``<index>_<source-stem>_tile_r<row>c<col>.svg``.
# Same pattern as ``merge_annot_plan_work.py`` — kept here too so the save
# endpoint can validate the body's identity attrs against the target file.
_ANNOT_TILE_NAME_RE = re.compile(
    r"^(?P<index>\d+)_(?P<stem>.+)_tile_r(?P<row>\d+)c(?P<col>\d+)\.svg$"
)
_ANNOT_BODY_SOURCE_RE = re.compile(r'data-source-svg="([^"]+)"')
_ANNOT_BODY_ROW_RE = re.compile(r'data-tile-row="(\d+)"')
_ANNOT_BODY_COL_RE = re.compile(r'data-tile-col="(\d+)"')


def _validate_tile_identity(tile_name: str, svg_text: str) -> tuple[bool, dict]:
    """Cross-check the SVG body's identity attrs against ``tile_name``.

    Tiles produced by ``add_annot_plan_work.py`` carry ``data-source-svg``,
    ``data-tile-row`` and ``data-tile-col`` on the SVG root. Comparing those
    to the row/col/stem encoded in the filename catches the case where a
    client-side race writes one tile's DOM under another tile's name.

    Returns ``(True, {})`` on match, ``(False, info)`` otherwise. ``info``
    contains expected/got fields so the client can log the mismatch.
    """
    m = _ANNOT_TILE_NAME_RE.match(tile_name)
    if not m:
        return False, {"error": "invalid_tile_name", "tile_name": tile_name}

    # The identity attrs live on the <svg> root, well within the first 8 KB.
    head = svg_text[:8192]
    src = _ANNOT_BODY_SOURCE_RE.search(head)
    row = _ANNOT_BODY_ROW_RE.search(head)
    col = _ANNOT_BODY_COL_RE.search(head)
    if not (src and row and col):
        return False, {"error": "missing_identity_attrs"}

    expected = {"source": m.group("stem"), "row": m.group("row"), "col": m.group("col")}
    got = {"source": src.group(1), "row": row.group(1), "col": col.group(1)}
    if got != expected:
        return False, {
            "error": "tile_identity_mismatch",
            "expected": expected,
            "got": got,
        }
    return True, {}


@app.post("/annotation/save", dependencies=[Depends(_require_annot_auth)])
async def annot_save_tile(request: Request, tile_name: str = Query(...)) -> JSONResponse:
    """Save current tile annotation back to annotation/tiles/.

    Accepts the SVG as a plain-text body (no JSON wrapping) to avoid
    blocking the browser main thread with JSON.stringify on large payloads.

    Rejects with 409 if the body's identity attrs don't match ``tile_name``
    so a client-side race can never persist tile A's DOM under tile B's name.
    """
    svg_text = (await request.body()).decode("utf-8", errors="replace")
    if not svg_text.strip():
        return JSONResponse({"ok": False, "error": "Missing svg payload."}, status_code=400)
    if not tile_name:
        return JSONResponse({"ok": False, "error": "Missing tile_name."}, status_code=400)

    safe_name = Path(tile_name).name
    if not safe_name.endswith(".svg"):
        safe_name += ".svg"

    ok, info = _validate_tile_identity(safe_name, svg_text)
    if not ok:
        print(f"[annot-save] REJECTED 409 ({safe_name}): {info}", flush=True)
        return JSONResponse({"ok": False, **info}, status_code=409)

    def _persist() -> None:
        ANNOT_TILES_DIR.mkdir(parents=True, exist_ok=True)
        out_path = ANNOT_TILES_DIR / safe_name
        out_path.write_text(svg_text, encoding="utf-8")

    await asyncio.to_thread(_persist)
    return JSONResponse({"ok": True, "saved": safe_name})


# ── Annotation stats: per-day class-assignment action counters ──────────────

_ANNOT_STATS_PATH = ANNOT_DIR / "annot_stats.json"
_annot_stats_lock = threading.Lock()


def _annot_stats_today_key() -> str:
    return datetime.now().date().isoformat()


def _annot_stats_load() -> dict:
    if not _ANNOT_STATS_PATH.exists():
        return {}
    try:
        data = json.loads(_ANNOT_STATS_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def _annot_stats_write(data: dict) -> None:
    ANNOT_DIR.mkdir(parents=True, exist_ok=True)
    tmp = _ANNOT_STATS_PATH.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(data, indent=2, sort_keys=True), encoding="utf-8")
    tmp.replace(_ANNOT_STATS_PATH)


@app.post("/annotation/stats/increment", dependencies=[Depends(_require_annot_auth)])
def annot_stats_increment(payload: dict = Body(...)) -> dict:
    """Increment today's counter for a class by `delta` (can be negative)."""
    class_name = str(payload.get("class_name") or "").strip()
    try:
        delta = int(payload.get("delta") or 0)
    except (TypeError, ValueError):
        delta = 0
    if not class_name or delta == 0:
        return {"ok": False, "error": "class_name and non-zero delta required"}

    day = _annot_stats_today_key()
    with _annot_stats_lock:
        data = _annot_stats_load()
        bucket = data.setdefault(day, {})
        new_value = int(bucket.get(class_name, 0)) + delta
        if new_value <= 0:
            bucket.pop(class_name, None)
        else:
            bucket[class_name] = new_value
        if not bucket:
            data.pop(day, None)
        _annot_stats_write(data)
    return {"ok": True, "day": day, "class_name": class_name, "delta": delta}


@app.get("/annotation/stats", dependencies=[Depends(_require_annot_auth)])
def annot_stats_get() -> dict:
    """Return all daily stats as `{ "YYYY-MM-DD": {class_name: count, ...}, ... }`."""
    with _annot_stats_lock:
        data = _annot_stats_load()
    return {"ok": True, "stats": data}


# ── Check mode: business validation against test_pmr_basis fixtures ─────────

CHECK_REF_DIR = Path("data/tests")
_CHECK_LAST_FIXTURE_PATH = CHECK_REF_DIR / "_current_check_fixture.txt"
_CHECK_VALID_STATUSES = {"none", "ok", "ko"}


def _check_load_fixtures() -> list[Path]:
    """Return the SVG fixtures listed in tests/test_pmr_basis.py.

    The list is the source of truth for both the unit test and the check
    panel — we read it from the test module rather than duplicating the
    paths here. We first try a normal import (works in dev where pytest
    is installed); if that fails (e.g. minimal runtime images that skip
    dev deps), we fall back to parsing the source with ast so the UI
    stays populated without shipping pytest in production.
    """
    import importlib.util

    test_path = Path("tests/test_pmr_basis.py")
    if not test_path.is_file():
        return []
    spec = importlib.util.spec_from_file_location("_test_pmr_basis_for_check", test_path)
    if spec is not None and spec.loader is not None:
        module = importlib.util.module_from_spec(spec)
        try:
            spec.loader.exec_module(module)
            fixtures = getattr(module, "SVG_FIXTURES", None)
            if fixtures:
                return [Path(p) for p in fixtures]
        except Exception:
            pass

    # AST fallback: resolve `SVG_DIR = Path("...")` and the list elements
    # `SVG_DIR / "filename.svg"` without executing module-level imports.
    import ast

    try:
        tree = ast.parse(test_path.read_text(encoding="utf-8"))
    except Exception:
        return []
    svg_dir: Path | None = None
    fixture_list: list[Path] = []
    for node in tree.body:
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if not isinstance(target, ast.Name):
                continue
            if target.id == "SVG_DIR":
                val = node.value
                if (isinstance(val, ast.Call) and isinstance(val.func, ast.Name)
                        and val.func.id == "Path" and val.args
                        and isinstance(val.args[0], ast.Constant)
                        and isinstance(val.args[0].value, str)):
                    svg_dir = Path(val.args[0].value)
            elif target.id == "SVG_FIXTURES" and isinstance(node.value, ast.List):
                for elt in node.value.elts:
                    if (isinstance(elt, ast.BinOp) and isinstance(elt.op, ast.Div)
                            and isinstance(elt.left, ast.Name) and elt.left.id == "SVG_DIR"
                            and isinstance(elt.right, ast.Constant)
                            and isinstance(elt.right.value, str)
                            and svg_dir is not None):
                        fixture_list.append(svg_dir / elt.right.value)
    return fixture_list


def _check_business_path(svg_path: Path) -> Path:
    """Return the business JSON path for a given SVG fixture."""
    return CHECK_REF_DIR / f"{svg_path.stem}_business.json"


def _pmr_cache_load(svg_path: Path) -> dict | None:
    """Load PMR incidents from the cache written by the unit tests."""
    path = CHECK_REF_DIR / f"{svg_path.stem}_pmr_cache.json"
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else None
    except Exception:
        return None


_CHECK_COMMENTS_KEY = "_comments"


def _check_default_business() -> dict:
    """Return a fresh empty business state (no decisions yet)."""
    return {_CHECK_COMMENTS_KEY: {}}


def _check_load_business(svg_path: Path) -> dict:
    """Load instance-level business state for a fixture.

    New format: {rule_code: {"0": "ok"|"ko"|"none", ...}, "_comments": {rule_code: {"0": text, ...}}}.
    Old format (plain string per rule) is ignored/invalidated.
    """
    business: dict = {_CHECK_COMMENTS_KEY: {}}
    json_path = _check_business_path(svg_path)
    if not json_path.is_file():
        return business
    try:
        saved = json.loads(json_path.read_text(encoding="utf-8"))
    except Exception:
        return business
    if not isinstance(saved, dict):
        return business
    valid_codes = {rule["code"] for rule in PMR_RULES}
    for key, val in saved.items():
        if key == _CHECK_COMMENTS_KEY:
            if isinstance(val, dict):
                loaded: dict = {}
                for k, v in val.items():
                    if not isinstance(k, str):
                        continue
                    if isinstance(v, dict):
                        # New format: {rule_code: {idx_str: text}}
                        inner = {ik: iv for ik, iv in v.items()
                                 if isinstance(ik, str) and isinstance(iv, str) and iv.strip()}
                        if inner:
                            loaded[k] = inner
                    elif isinstance(v, str) and v.strip():
                        # Old format: {rule_code: text} — keep as-is for display
                        loaded[k] = v
                business[_CHECK_COMMENTS_KEY] = loaded
        elif key in valid_codes and isinstance(val, dict):
            # New per-instance format: {idx_str: status}
            business[key] = {
                idx: status for idx, status in val.items()
                if isinstance(idx, str) and status in _CHECK_VALID_STATUSES
            }
        # Old format (plain string value) → silently ignored
    return business


def _check_save_business(svg_path: Path, business: dict) -> None:
    """Persist instance-level business state."""
    valid_codes = {rule["code"] for rule in PMR_RULES}
    cleaned: dict = {}
    for key, val in business.items():
        if key == _CHECK_COMMENTS_KEY:
            if isinstance(val, dict):
                comments: dict = {}
                for k, v in val.items():
                    if not isinstance(k, str):
                        continue
                    if isinstance(v, dict):
                        # New format: {rule_code: {idx_str: text}}
                        inner = {ik: iv.strip() for ik, iv in v.items()
                                 if isinstance(ik, str) and isinstance(iv, str) and iv.strip()}
                        if inner:
                            comments[k] = inner
                    elif isinstance(v, str) and v.strip():
                        comments[k] = v.strip()
                if comments:
                    cleaned[_CHECK_COMMENTS_KEY] = comments
        elif key in valid_codes and isinstance(val, dict):
            instance_decisions = {
                idx: status for idx, status in val.items()
                if isinstance(idx, str) and status in _CHECK_VALID_STATUSES
            }
            if instance_decisions:
                cleaned[key] = instance_decisions
    CHECK_REF_DIR.mkdir(parents=True, exist_ok=True)
    json_path = _check_business_path(svg_path)
    json_path.write_text(
