# ── Check mode: performance (F1) per rule ────────────────────────────────────


def _f1_from_counts(tp: int, fp: int, fn: int, tn: int) -> float | None:
    """Compute F1. Degenerate case: all-negative fixture that passes → 1.0."""
    denom = 2 * tp + fp + fn
    if denom > 0:
        return 2 * tp / denom
    if tn > 0:
        return 1.0
    return None





@app.get("/check/rules", dependencies=[Depends(_require_annot_auth)])
def check_rules_stats() -> dict:
    """Per-rule F1 stats read from test-generated PMR cache files."""
    import datetime as _dt
    fixtures = _check_load_fixtures()
    valid_codes = {rule["code"] for rule in PMR_RULES}
    rule_tp: dict[str, int] = {}
    rule_fp: dict[str, int] = {}
    rule_fn: dict[str, int] = {}
    rule_tn: dict[str, int] = {}
    rule_total: dict[str, int] = {}  # all incidents regardless of business
    svgs_with_cache = 0
    for svg_path in fixtures:
        cache = _pmr_cache_load(svg_path)
        if cache is None:
            continue
        svgs_with_cache += 1
        business = _check_load_business(svg_path)
        # Group incidents by rule code.
        incidents_by_rule: dict[str, list[dict]] = {}
        for inc in cache.get("incidents", []):
            code = inc.get("rule_code")
            if code not in valid_codes:
                continue
            incidents_by_rule.setdefault(code, []).append(inc)
        # Total incidents per rule (no business filter).
        for code, incs in incidents_by_rule.items():
            rule_total[code] = rule_total.get(code, 0) + len(incs)
        # Count at incident level using per-instance business decisions.
        for code in valid_codes:
            instance_decisions = business.get(code)
            if not isinstance(instance_decisions, dict) or not instance_decisions:
                continue
            incidents = incidents_by_rule.get(code)
            if not incidents:
                continue
            for idx, inc in enumerate(incidents):
                biz = instance_decisions.get(str(idx), "none")
                if biz not in {"ok", "ko"}:
                    continue
                inc_status = inc.get("status", "ok")
                if biz == "ko" and inc_status == "ko":
                    rule_tp[code] = rule_tp.get(code, 0) + 1
                elif biz == "ok" and inc_status == "ko":
                    rule_fp[code] = rule_fp.get(code, 0) + 1
                elif biz == "ko" and inc_status == "ok":
                    rule_fn[code] = rule_fn.get(code, 0) + 1
                else:
                    rule_tn[code] = rule_tn.get(code, 0) + 1
    rules: list[dict] = []
    for rule in PMR_RULES:
        code = rule["code"]
        tp = rule_tp.get(code, 0)
        fp = rule_fp.get(code, 0)
        fn = rule_fn.get(code, 0)
        tn = rule_tn.get(code, 0)
        rules.append({
            "code": code,
            "title": rule["title"],
            "description": rule.get("description", ""),
            "category": rule.get("category", ""),
            "tp": tp, "fp": fp, "fn": fn, "tn": tn,
            "count": tp + fp + fn + tn,
            "total": rule_total.get(code, 0),
            "f1": _f1_from_counts(tp, fp, fn, tn),
        })
    return {
        "ok": True,
        "fixtures_count": len(fixtures),
        "svgs_with_cache": svgs_with_cache,
        "computed_at": _dt.datetime.now(_dt.timezone.utc).isoformat(timespec="seconds"),
        "rules": rules,
    }








