VLM_PYTHON = os.getenv(
    "VLM_PYTHON", "/home/greg/miniconda3/envs/internvl/bin/python"
)
VLM_REPO_DIR = Path(__file__).resolve().parents[2] / "vlm"
VLM_RUN_DIR = Path(os.getenv(
    "VLM_RUN_DIR",
    str(VLM_REPO_DIR / "outputs" / "internvl35_4B" / "annot_layer" / "aws_annot_layered_30k"),
))
VLM_CHECKPOINT = os.getenv("VLM_CHECKPOINT", "completed-plan")
VLM_MERGED_MODEL_DIR = os.getenv("VLM_MERGED_MODEL_DIR", "") or None


def _run_vlm_inference(svg_text: str) -> dict:
    import subprocess

    if not VLM_RUN_DIR.exists():
        return {"ok": False, "error": f"VLM run dir not found: {VLM_RUN_DIR}"}

    work_root = (CACHE_DIR / "vlm_inference").resolve()
    work_root.mkdir(parents=True, exist_ok=True)
    job_id = uuid.uuid4().hex
    job_dir = work_root / job_id
    job_dir.mkdir(parents=True, exist_ok=True)

    input_svg = job_dir / "input.svg"
    output_svg = job_dir / "output.svg"
    tile_dir = job_dir / "tiles"
    input_svg.write_text(svg_text, encoding="utf-8")

    merged_model_dir = VLM_MERGED_MODEL_DIR or str(
        VLM_RUN_DIR / VLM_CHECKPOINT / "merged_model"
    )
    cmd = [
        VLM_PYTHON,
        str(VLM_REPO_DIR / "inference_svg_plan_vllm.py"),
        str(VLM_RUN_DIR),
        "--svg", str(input_svg),
        "--output", str(output_svg),
        "--checkpoint", VLM_CHECKPOINT,
        "--merged-model-dir", merged_model_dir,
        "--work-dir", str(tile_dir),
    ]

    log_path = job_dir / "run.log"
    try:
        with log_path.open("w", encoding="utf-8") as log_fh:
            proc = subprocess.run(
                cmd, cwd=str(VLM_REPO_DIR),
                stdout=log_fh, stderr=subprocess.STDOUT,
                timeout=30 * 60,
            )
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "Inference timed out (30 min)."}
    except FileNotFoundError as exc:
        return {"ok": False, "error": f"Python interpreter not found: {exc}"}

    if proc.returncode != 0:
        tail = ""
        try:
            tail = log_path.read_text(encoding="utf-8", errors="replace")[-2000:]
        except Exception:
            pass
        return {
            "ok": False,
            "error": f"Inference exited with code {proc.returncode}.\n{tail}",
        }

    if not output_svg.exists():
        return {"ok": False, "error": "Annotated SVG not produced."}

    return {"ok": True, "svg": output_svg.read_text(encoding="utf-8")}


