def _make_row(cat):
    name = cat.get("name", "").strip()
    cid = name.lower()
    color = cat.get("color_hex") or "#000000"
    label, key_text = format_tool_label(cat)
    key_upper = (cat.get("keyboard") or "").strip().upper()
    visibility_title = f"Toggle {name or 'tool'} visibility"
    if key_upper:
        visibility_title += f" (Shift+{key_upper})"
    return (
        f'<div class="tool-color-row">'
        f'<input class="tool-checkbox" type="checkbox" title="{visibility_title}" checked data-class-id="{cid}" onchange="window.toggleCategoryVisibility(this)" />'
        f'<button class="tool-color tool-disabled" style="background:{color};" onclick="window.setSelectedStroke(\'{color}\')" title="{name or "tool"}" data-class-id="{cid}" data-requires-selection="true" disabled></button>'
        f'<span class="tool-label">{label}</span>'
        f'<span class="tool-key">{key_text}</span>'
        f'</div>'
    )

def _make_row_for_walls(cat, key_label: str):
    """Same shape as ``_make_row`` but with an explicit keyboard label.

    Wall1/2/3 carry an empty ``keyboard`` field in SVG_CATEGORIES so they
    don't pollute KEY_COLOR_MAP outside OBJECTS_MODE — we inject the label
    here only when the Walls toolbar is rendered. ``key_label`` may
    contain ``&``/``"`` so we HTML-escape it before embedding.
    """
    import html as _html
    name = cat.get("name", "").strip()
    cid = name.lower()
    color = cat.get("color_hex") or "#000000"
    label = (cat.get("description") or name).strip()
    safe_key = _html.escape(key_label or "", quote=True)
    visibility_title = f"Toggle {name or 'tool'} visibility"
    if key_label:
        # Use the unescaped char in the title via attribute escape so it
        # renders correctly in the tooltip.
        visibility_title += f" ({safe_key})"
    key_text = f"({safe_key})" if key_label else ""
    return (
        f'<div class="tool-color-row">'
        f'<input class="tool-checkbox" type="checkbox" title="{visibility_title}" checked data-class-id="{cid}" onchange="window.toggleCategoryVisibility(this)" />'
        f'<button class="tool-color tool-disabled" style="background:{color};" onclick="window.setSelectedStroke(\'{color}\')" title="{name or "tool"}" data-class-id="{cid}" data-requires-selection="true" disabled></button>'
        f'<span class="tool-label">{label}</span>'
        f'<span class="tool-key">{key_text}</span>'
        f'</div>'
    )


