if OBJECTS_MODE:
    _walls_specs = [("wall1", "&"), ("wall2", "é"), ("wall3", '"')]
    _cat_by_name_all = {c["name"].strip().lower(): c for c in SVG_CATEGORIES}
    _walls_rows_parts = []
    for wname, wkey in _walls_specs:
        wcat = _cat_by_name_all.get(wname)
        if wcat:
            _walls_rows_parts.append(_make_row_for_walls(wcat, wkey))
    _walls_rows = "\n".join(_walls_rows_parts)


_palette_parts = []
_active_toolbar_groups = _TOOLBAR_GROUPS_OBJECTS if OBJECTS_MODE else _TOOLBAR_GROUPS
for gi, group in enumerate(_active_toolbar_groups):
    if gi > 0:
