window.refreshAutosaveList = async () => {
  try {
    const res = await fetch('/autosave', {method: 'GET', cache: 'no-store'});
    const data = await res.json();
    if (!data?.ok || !Array.isArray(data?.items)) {
      throw new Error(data?.error || 'Unable to list autosaves');
    }
    getAutosaveState().items = data.items;
    window.renderAutosaveList?.();
  } catch (error) {
    console.error('Autosave list refresh failed', error);
