window.renderAnnotationHistory = () => {
  const list = document.getElementById('annotation-history-list');
  const undoButton = document.getElementById('annotation-history-undo');
  const state = getAnnotationHistoryState();
  const items = Array.isArray(state.items) ? state.items : [];
  if (undoButton instanceof HTMLButtonElement) {
    undoButton.disabled = items.length === 0;
  }
  if (!list) return;
  if (!items.length) {
    list.innerHTML = '<div class="annotation-history-empty">Aucune annotation</div>';
    return;
  }
  list.innerHTML = items
    .slice()
    .reverse()
    .map((item) => {
      const actionMeta = getHistoryActionMeta(item);
      const color = escapeHtml(actionMeta.color);
      const className = escapeHtml(actionMeta.label);
      const primitiveType = escapeHtml(item.primitiveType || 'primitive');
      const timestamp = escapeHtml(formatAnnotationTime(item.timestamp));
      return `
        <div class="annotation-history-item" data-annotation-entry-id="${escapeHtml(item.id)}">
          <div class="annotation-history-item-main">
            <span class="annotation-history-primitive">${primitiveType}</span>
            <span class="annotation-history-class" style="--annotation-class-color:${color};">${className}</span>
          </div>
          <div class="annotation-history-time">${timestamp}</div>
        </div>
      `;
    })
    .join('');
