// Save the full SVG to the server (data/svgs/<base>_<timestamp>.svg).
window.saveInternalSvg = async () => {
  const content = window.buildCurrentSvgContent();
  if (!content) return;
  const rawName = (window.__currentSvgExportName || 'annotated.svg').split(/[\\/]/).pop() || 'annotated.svg';
  const base = rawName.replace(/\.svg$/i, '');
  const ts = (() => {
    const d = new Date();
    const pad = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
  })();
  const filename = `${base}_${ts}.svg`;
  await withBusyGuard('Sauvegarde interne', filename, async () => {
    window.appendLoadingModalLog?.(`POST /internal-svgs/save (${formatApproxBytes(content.length)})`);
    const res = await fetch('/internal-svgs/save', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({filename, svg: content}),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data?.ok) {
      const msg = data?.error || `HTTP ${res.status}`;
      console.error('Save internal failed:', msg);
      throw new Error(msg);
    }
    window.appendLoadingModalLog?.(`Saved: data/svgs/${data.name}`);
    console.log(`Saved internal SVG: data/svgs/${data.name}`);
  });
};

