window.resetZoom = () => {};

const getSvgViewBox = (svg) => {
  const raw = (svg?.getAttribute('viewBox') || '').trim();
  return parseViewBoxRaw(raw);
};

const parseViewBoxRaw = (raw) => {
  const text = String(raw || '').trim();
  if (!text) return null;
  const parts = text.split(/\s+/).map(Number);
  if (parts.length === 4 && parts.every((value) => Number.isFinite(value))) {
    return {raw: text, x: parts[0], y: parts[1], width: parts[2], height: parts[3]};
  }
  return null;
};

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));


window.openLoadingModal = ({title = 'Chargement en cours', status = 'Initialisation', step = 'Preparation...'} = {}) => {
  const {backdrop, status: statusEl, currentStep, log} = getLoadingModalElements();
  backdrop.classList.add('is-open');
  const titleEl = backdrop.querySelector('#loading-modal-title');
  if (titleEl) titleEl.textContent = title;
  if (statusEl) statusEl.textContent = status;
  if (currentStep) currentStep.textContent = step;
  if (log) log.innerHTML = '';
  window.__loadingModalLines = [];
};

// Busy guard: shows loading modal during long operations and prevents concurrent actions.
let __busyGuardActive = false;
const withBusyGuard = async (title, stepLabel, asyncFn) => {
  if (__busyGuardActive) return;
  __busyGuardActive = true;
  window.openLoadingModal?.({title, status: 'En cours', step: stepLabel});
  try {
    await nextAnimationFrame();
    await asyncFn();
    window.setLoadingModalStatus?.('Termine', stepLabel);
    window.setTimeout(() => window.closeLoadingModal?.(), 400);
  } catch (err) {
    window.setLoadingModalStatus?.('Erreur', String(err?.message || err));
    window.appendLoadingModalLog?.(String(err?.message || err), 'error');
  } finally {
    __busyGuardActive = false;
  }
};

window.setLoadingModalStatus = (status, step) => {
  const {status: statusEl, currentStep} = getLoadingModalElements();
  if (statusEl && typeof status === 'string') statusEl.textContent = status;
  if (currentStep && typeof step === 'string') currentStep.textContent = step;
};

window.appendLoadingModalLog = (message, kind = '') => {
  const {log} = getLoadingModalElements();
  if (!log || typeof message !== 'string' || !message.trim()) return;
  if (!Array.isArray(window.__loadingModalLines)) window.__loadingModalLines = [];
  const previous = window.__loadingModalLines[window.__loadingModalLines.length - 1];
  if (previous && previous.message === message && previous.kind === kind) return;
  window.__loadingModalLines.push({message, kind});
  log.innerHTML = window.__loadingModalLines
    .map((line) => `<div class="loading-modal-log-line${line.kind ? ` is-${escapeHtml(line.kind)}` : ''}">${escapeHtml(line.message)}</div>`)
    .join('');
  log.scrollTop = log.scrollHeight;
};

window.closeLoadingModal = () => {
  const {backdrop} = getLoadingModalElements();
  backdrop.classList.remove('is-open');
};

const ensurePdfConfigModal = () => {
  let backdrop = document.getElementById('pdf-config-modal-backdrop');
  if (backdrop) return backdrop;

  backdrop = document.createElement('div');
  backdrop.id = 'pdf-config-modal-backdrop';
  backdrop.className = 'pdf-config-modal-backdrop';
  backdrop.innerHTML = `
    <div class="pdf-config-modal" role="dialog" aria-modal="true" aria-labelledby="pdf-config-modal-title">
      <div class="pdf-config-modal-header">
        <div id="pdf-config-modal-title" class="pdf-config-modal-title">Configuration du PDF</div>
      </div>
      <div class="pdf-config-modal-body">
        <div id="pdf-config-modal-message" class="pdf-config-modal-message"></div>
        <label id="pdf-config-modal-label" class="pdf-config-modal-label" for="pdf-config-modal-input"></label>
        <input id="pdf-config-modal-input" class="pdf-config-modal-input" />
        <div class="pdf-config-modal-actions">
          <button id="pdf-config-modal-cancel" type="button" class="pdf-config-modal-button is-secondary">Annuler</button>
          <button id="pdf-config-modal-confirm" type="button" class="pdf-config-modal-button">Confirmer</button>
