window.openPdfConfigModal = ({
  title = 'Configuration du PDF',
  message = '',
  label = '',
  inputType = 'text',
  value = '',
  min = '',
  max = '',
  step = '',
  placeholder = '',
  options = [],
  confirmLabel = 'Confirmer',
} = {}) => new Promise((resolve) => {
  const backdrop = ensurePdfConfigModal();
  const titleEl = backdrop.querySelector('#pdf-config-modal-title');
  const messageEl = backdrop.querySelector('#pdf-config-modal-message');
  const labelEl = backdrop.querySelector('#pdf-config-modal-label');
  const currentInput = backdrop.querySelector('#pdf-config-modal-input');
  const confirmButton = backdrop.querySelector('#pdf-config-modal-confirm');
  const cancelButton = backdrop.querySelector('#pdf-config-modal-cancel');

  const nextInput = inputType === 'select'
    ? document.createElement('select')
    : document.createElement('input');
  nextInput.id = 'pdf-config-modal-input';
  nextInput.className = 'pdf-config-modal-input';
  if (inputType === 'select') {
    options.forEach((option) => {
      const opt = document.createElement('option');
      opt.value = option.value;
      opt.textContent = option.label;
      if (String(option.value) === String(value)) opt.selected = true;
      nextInput.appendChild(opt);
    });
  } else {
    nextInput.type = inputType;
    if (value !== undefined && value !== null) nextInput.value = String(value);
    if (min !== '') nextInput.min = String(min);
    if (max !== '') nextInput.max = String(max);
    if (step !== '') nextInput.step = String(step);
    if (placeholder) nextInput.placeholder = placeholder;
  }
  currentInput.replaceWith(nextInput);

  if (titleEl) titleEl.textContent = title;
  if (messageEl) messageEl.textContent = message;
  if (labelEl) labelEl.textContent = label;
  if (confirmButton) confirmButton.textContent = confirmLabel;

  let done = false;
  const close = (result) => {
    if (done) return;
    done = true;
    backdrop.classList.remove('is-open');
    confirmButton?.removeEventListener('click', handleConfirm);
    cancelButton?.removeEventListener('click', handleCancel);
    nextInput.removeEventListener('keydown', handleKeydown);
    resolve(result);
  };
  const handleCancel = () => close(null);
  const handleConfirm = () => close(nextInput.value);
  const handleKeydown = (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      handleConfirm();
    } else if (event.key === 'Escape') {
      event.preventDefault();
      handleCancel();
    }
  };

  confirmButton?.addEventListener('click', handleConfirm);
  cancelButton?.addEventListener('click', handleCancel);
  nextInput.addEventListener('keydown', handleKeydown);
  backdrop.classList.add('is-open');
  window.setTimeout(() => nextInput.focus(), 0);
});

window.selectPdfPage = async (analysis) => {
  if (!analysis?.requires_page_confirmation) return 1;
  const pageValue = await window.openPdfConfigModal({
    title: 'Choisir la page',
    message: `Ce PDF contient ${analysis.page_count} pages. Indiquez la page a convertir.`,
    label: 'Numero de page',
    inputType: 'number',
    value: 1,
    min: 1,
    max: analysis.page_count,
    step: 1,
    confirmLabel: 'Valider la page',
  });
  if (pageValue === null) return null;
  const parsed = Number.parseInt(String(pageValue), 10);
  if (!Number.isInteger(parsed) || parsed < 1 || parsed > analysis.page_count) {
    throw new Error(`Invalid page number: ${pageValue}`);
  }
  return parsed;
};

window.selectPdfScale = async (analysis) => {
  if (!analysis?.requires_scale_confirmation) return analysis?.default_scale || '1/25';
  const scales = Array.isArray(analysis?.scales) ? analysis.scales : [];
  if (scales.length > 0) {
    const selected = await window.openPdfConfigModal({
      title: 'Confirmer l\'echelle',
      message: 'Plusieurs echelles ont ete detectees. Choisissez celle a utiliser pour la conversion.',
      label: 'Echelle',
      inputType: 'select',
      value: analysis?.default_scale || scales[0],
      options: scales.map((scale) => ({value: scale, label: scale.replace('/', ':')})),
      confirmLabel: 'Valider l\'echelle',
    });
    return selected === null ? null : selected;
  }
  const manualScale = await window.openPdfConfigModal({
    title: 'Confirmer l\'echelle',
    message: `Aucune echelle unique n'a ete detectee. Confirmer l'echelle "${(analysis?.default_scale || '1/25').replace('/', ':')}".`,
    label: 'Echelle',
    inputType: 'text',
    value: analysis?.default_scale || '1/25',
    placeholder: '1:50',
    confirmLabel: 'Valider l\'echelle',
  });
  return manualScale === null ? null : manualScale;
};

// Affichage des primitives sélectionnées (surcouche bleue)
window.addSelectionOverlay = (el) => {
  if (!el || !el.ownerSVGElement) return;
  if (el.hasAttribute('data-selected-overlay')) return;
  const overlay = el.cloneNode(true);
  overlay.removeAttribute('id');
  overlay.removeAttribute('data-selected');
  overlay.removeAttribute('data-instance-id');
  overlay.setAttribute('data-selection-overlay', 'true');
  const uid = el.getAttribute('data-uid');
  if (uid) overlay.setAttribute('data-selection-overlay-for', uid);
  const fill = el.getAttribute('fill');
  const stroke = el.getAttribute('stroke');
  const hasFill = !!fill && fill !== 'none';
  const hasStroke = !!stroke && stroke !== 'none';
  const sw = el.getAttribute('stroke-width');
  if (hasStroke) {
    overlay.setAttribute('stroke', '#0000ff');
    if (sw !== null) {
      overlay.setAttribute('stroke-width', sw);
    } else {
      overlay.removeAttribute('stroke-width');
    }
  } else {
    overlay.setAttribute('stroke', 'none');
    overlay.removeAttribute('stroke-width');
  }
  if (hasFill) {
    overlay.setAttribute('fill', '#0000ff');
  } else {
    overlay.setAttribute('fill', 'none');
  }
  overlay.setAttribute('fill-opacity', '0.8');
  overlay.setAttribute('stroke-opacity', '0.8');
  overlay.setAttribute('pointer-events', 'none');
  el.insertAdjacentElement('afterend', overlay);
  el.setAttribute('data-selected-overlay', 'true');
  // Hide the class overlay so the blue selection overlay is visible
  const classOverlay = getClassOverlay(el);
  if (classOverlay) classOverlay.style.display = 'none';
};

window.removeSelectionOverlay = (el) => {
  if (!el || !el.ownerSVGElement) return;
  const uid = el.getAttribute('data-uid');
  if (uid) {
    const overlay = el.ownerSVGElement.querySelector(`[data-selection-overlay-for="${uid}"]`);
    if (overlay) overlay.remove();
  } else {
    const next = el.nextElementSibling;
    if (next && next.getAttribute('data-selection-overlay') === 'true') {
      next.remove();
    }
  }
  el.removeAttribute('data-selected-overlay');
  // Restore class overlay visibility now that selection overlay is gone
  const classOverlay = getClassOverlay(el);
  if (classOverlay && el.getAttribute('data-hidden-by-class') !== 'true') {
    classOverlay.style.display = '';
  }
};

const getClassOverlay = (el) => {
  if (!el || !el.ownerSVGElement) return null;
  const uid = el.getAttribute('data-uid');
  if (!uid) return null;
  return el.ownerSVGElement.querySelector(`[data-class-overlay-for="${uid}"]`);
};

const _isWhiteFillNoStroke = (el) => {
  const stroke = (el.getAttribute('stroke') || '').trim().toLowerCase();
  if (stroke && stroke !== 'none') return false;
  const fill = (el.getAttribute('fill') || '').trim().toLowerCase();
  if (!fill || fill === 'none') return false;
  let r, g, b;
  if (fill.startsWith('#')) {
    let h = fill.slice(1);
    if (h.length === 3) h = h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
    if (h.length === 6) { r = parseInt(h.slice(0,2),16); g = parseInt(h.slice(2,4),16); b = parseInt(h.slice(4,6),16); }
    else return false;
  } else {
    const m = fill.match(/^rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)$/);
    if (m) { r = +m[1]; g = +m[2]; b = +m[3]; }
    else {
      const mp = fill.match(/^rgb\(\s*([\d.]+)%\s*,\s*([\d.]+)%\s*,\s*([\d.]+)%\s*\)$/);
      if (!mp) return false;
      r = Math.round(+mp[1]*255/100); g = Math.round(+mp[2]*255/100); b = Math.round(+mp[3]*255/100);
    }
  }
  return r > 252 && g > 252 && b > 252;
};

// Affichage par masque de couleur de la classe affectée
window.addClassOverlay = (el, color) => {
  if (!el || !el.ownerSVGElement || !color) return;
  const uid = el.getAttribute('data-uid');
  if (!uid) return;
  const existing = getClassOverlay(el);
  if (existing) existing.remove();
  const overlay = el.cloneNode(true);
  overlay.removeAttribute('id');
  overlay.removeAttribute('data-uid');
  overlay.removeAttribute('data-selected');
  overlay.removeAttribute('data-selected-overlay');
  overlay.removeAttribute('data-instance-id');
  overlay.setAttribute('data-class-overlay', 'true');
  overlay.setAttribute('data-class-overlay-for', uid);
  const origStroke = el.getAttribute('stroke');
  const origFill = el.getAttribute('fill');
  const hasStroke = !!origStroke && origStroke !== 'none';
  const hasFill = !!origFill && origFill !== 'none';
  if (hasStroke) {
    overlay.setAttribute('stroke', color);
  } else {
    overlay.setAttribute('stroke', 'none');
  }
  if (hasFill) {
    overlay.setAttribute('fill', color);
  } else {
    overlay.setAttribute('fill', 'none');
  }
  overlay.setAttribute('stroke-opacity', '0.8');
  overlay.setAttribute('fill-opacity', '0.8');
  overlay.setAttribute('pointer-events', 'none');
  el.insertAdjacentElement('afterend', overlay);
  overlay.style.display = el.getAttribute('data-hidden-by-class') === 'true' ? 'none' : '';
};

window.removeClassOverlay = (el) => {
  const overlay = getClassOverlay(el);
  if (overlay) overlay.remove();
};

window.ensureElementClassOverlay = (el) => {
  if (!el) return;
  const classKey = String(el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
  // Never create overlays on frozen white-fill-only primitives
  if (classKey === 'frozen' && _isWhiteFillNoStroke(el)) {
    window.removeClassOverlay?.(el);
    return;
  }
  const color = CLASS_NAME_COLOR_MAP[classKey];
  const shouldShowOverlay = !!classKey && !!CLASS_NAME_MASK_MAP[classKey] && !!color;
  if (!shouldShowOverlay) {
    window.removeClassOverlay?.(el);
    return;
  }
  let overlay = getClassOverlay(el);
  if (!overlay) {
    window.addClassOverlay?.(el, color);
    overlay = getClassOverlay(el);
  }
  if (overlay) {
    overlay.style.display = el.getAttribute('data-hidden-by-class') === 'true' ? 'none' : '';
  }
};

// ===================================================================
// Objects mode — instance ID grouping (Ctrl+I).
//
// In OBJECTS_MODE, primitives can be grouped into instances: pressing
// Ctrl+I (or clicking the ID toolbar button) on a selection sets a
// SHA-1-derived `data-instance-id` on each primitive of the selection
// and draws a coloured bounding box around the group. Re-labelling the
// group as `unlabelled` removes the instance ID and the bbox.
// ===================================================================

const _sha1Hex = async (text) => {
  const buf = new TextEncoder().encode(text);
  const hash = await crypto.subtle.digest('SHA-1', buf);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
};

const _instanceColor = (instanceId) => {
  let h = 0;
  for (let i = 0; i < instanceId.length; i++) {
    h = (h * 31 + instanceId.charCodeAt(i)) >>> 0;
  }
  const hue = h % 360;
  return `hsl(${hue} 80% 45%)`;
};

// Average stroke-width across the SVG's drawable primitives, cached on
// the SVG element. Used as a fixed visual margin around instance bboxes:
// it sits in the same unit as the primitives, so the frame breathes by
// roughly one line thickness regardless of viewBox scale.
const _instanceBboxMargin = (svg) => {
  if (typeof svg.__instanceBboxMargin === 'number') return svg.__instanceBboxMargin;
  const drawables = svg.querySelectorAll(
    'path,line,polyline,polygon,rect,circle,ellipse,text',
  );
  let total = 0;
  let count = 0;
  for (const el of drawables) {
    if (el.hasAttribute('data-class-overlay-for')) continue;
    if (el.hasAttribute('data-instance-bbox-for')) continue;
    const sw = parseFloat(el.getAttribute('stroke-width') || '');
    if (!isFinite(sw) || sw <= 0) continue;
    total += sw;
    count += 1;
  }
  const margin = count > 0 ? total / count : 0;
  svg.__instanceBboxMargin = margin;
  return margin;
};

// Colour used for an instance bbox before it is labelled with a wall
// class. Matches the unlabelled overlay colour from svg_categories so
// the frame reads as "neutral / not yet a wall".
const _BBOX_UNLABELLED_COLOR =
  (typeof CLASS_NAME_COLOR_MAP !== 'undefined' && CLASS_NAME_COLOR_MAP['unlabelled'])
    || '#404040';

const _bboxColorForClass = (className) => {
  const cls = String(className || '').trim().toLowerCase();
  if (!cls || cls === 'unlabelled') return _BBOX_UNLABELLED_COLOR;
  return (typeof CLASS_NAME_COLOR_MAP !== 'undefined' && CLASS_NAME_COLOR_MAP[cls])
    || _BBOX_UNLABELLED_COLOR;
};

window.renderInstanceBbox = (instanceId) => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg || !instanceId) return;
  // Snapshot prior classId PER SIDE (matched by the side index encoded
  // in data-uid="bbox_<instanceId>_<idx>") so a bbox with mixed wall
  // labels — e.g. top=wall1, left=wall2, others=unlabelled — is fully
  // preserved across geometry refreshes (refreshInstanceBboxes drops
  // and rebuilds every bbox on tile reload and after primitive moves).
  // Earlier we collapsed all sides to the first non-unlabelled classId
  // we found, which silently propagated wall1 to the whole frame after
  // any save/reload — see bug report.
  const olds = svg.querySelectorAll(
    `[data-instance-bbox-for="${CSS.escape(instanceId)}"]`,
  );
  const priorClassIds = ['', '', '', ''];
  olds.forEach((o) => {
    const uid = o.getAttribute('data-uid') || '';
    const m = /_(\d+)$/.exec(uid);
    if (!m) return;
    const idx = parseInt(m[1], 10);
    if (!Number.isFinite(idx) || idx < 0 || idx >= 4) return;
    const cid = (o.getAttribute('classId') || o.getAttribute('classid') || '')
      .trim().toLowerCase();
    priorClassIds[idx] = cid;
  });
  olds.forEach((el) => el.remove());
  const members = Array.from(svg.querySelectorAll(
    `[data-instance-id="${CSS.escape(instanceId)}"]`,
  )).filter((el) => !el.hasAttribute('data-instance-bbox-for'));
  if (!members.length) return;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const el of members) {
    let bb;
    try { bb = el.getBBox(); } catch (_) { continue; }
    if (!bb || !isFinite(bb.x) || !isFinite(bb.y)) continue;
    if (bb.width === 0 && bb.height === 0) continue;
    if (bb.x < minX) minX = bb.x;
    if (bb.y < minY) minY = bb.y;
    if (bb.x + bb.width > maxX) maxX = bb.x + bb.width;
    if (bb.y + bb.height > maxY) maxY = bb.y + bb.height;
  }
  if (!isFinite(minX)) return;
  // Margin and stroke-width are scaled ×4 relative to the previous
  // single-rect layout so the frame is clearly readable around the
  // grouped primitives even on dense object plates.
  const pad = _instanceBboxMargin(svg) * 4;
  const x0 = minX - pad;
  const y0 = minY - pad;
  const x1 = maxX + pad;
  const y1 = maxY + pad;
  // Four independent lines (not a closed rect) — keeps each side a
  // first-class primitive, matching the rest of the SVG vocabulary and
  // letting wall1/wall2/wall3 land on individual sides for orientation.
  const sides = [
    {x1: x0, y1: y0, x2: x1, y2: y0},  // top   (idx 0)
    {x1: x1, y1: y0, x2: x1, y2: y1},  // right (idx 1)
    {x1: x1, y1: y1, x2: x0, y2: y1},  // bottom(idx 2)
    {x1: x0, y1: y1, x2: x0, y2: y0},  // left  (idx 3)
  ];
  sides.forEach((s, idx) => {
    const sideClassId = priorClassIds[idx] || 'unlabelled';
    const sideColor = _bboxColorForClass(sideClassId);
    const ln = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    ln.setAttribute('x1', String(s.x1));
    ln.setAttribute('y1', String(s.y1));
    ln.setAttribute('x2', String(s.x2));
    ln.setAttribute('y2', String(s.y2));
    ln.setAttribute('stroke', sideColor);
    // Was 2 px before — quadrupled to 8 px (non-scaling-stroke ⇒ pixels).
    ln.setAttribute('stroke-width', '8');
    ln.setAttribute('stroke-linecap', 'round');
    ln.setAttribute('vector-effect', 'non-scaling-stroke');
    // pointer-events="auto" so a rectangle selection can pick the line up;
    // pointer-events="none" would hide it from hit-testing on click flows
    // (we still rely on the primitives test in handleSvgSelectionRect for
    // the rectangle-start guard, which only checks event.target tag).
    ln.setAttribute('pointer-events', 'none');
    ln.setAttribute('data-instance-bbox', 'true');
    ln.setAttribute('data-instance-bbox-for', instanceId);
    // Stable per-side data-uid — also encodes the side index so the
    // per-side classId snapshot above can match before/after correctly
    // even after attribute order changes through XMLSerializer round-trips.
    ln.setAttribute('data-uid', `bbox_${instanceId}_${idx}`);
    ln.setAttribute('classId', sideClassId);
    svg.appendChild(ln);
  });
};

window.removeInstanceBbox = (instanceId) => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg || !instanceId) return;
  svg.querySelectorAll(
    `[data-instance-bbox-for="${CSS.escape(instanceId)}"]`,
  ).forEach((el) => el.remove());
};

// Recompute every instance bbox from the live `data-instance-id` set,
// dropping bboxes whose group has been emptied. Called after tile load
// and after any class re-labelling that could have removed members.
window.refreshInstanceBboxes = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const liveIds = new Set();
  svg.querySelectorAll('[data-instance-id]').forEach((el) => {
    if (el.hasAttribute('data-instance-bbox-for')) return;
    const id = el.getAttribute('data-instance-id');
    if (id) liveIds.add(id);
  });
  svg.querySelectorAll('[data-instance-bbox-for]').forEach((el) => {
    const id = el.getAttribute('data-instance-bbox-for');
    if (!id || !liveIds.has(id)) el.remove();
  });
  liveIds.forEach((id) => window.renderInstanceBbox(id));
};

window.assignInstanceId = async () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const selected = Array.from(svg.querySelectorAll('[data-selected="true"]'))
    .filter((el) => !el.hasAttribute('data-instance-bbox-for'));
  if (!selected.length) return;
  const uids = selected
    .map((el) => el.getAttribute('data-uid'))
    .filter(Boolean);
  if (!uids.length) return;
  const sortedUids = [...uids].sort();
  const fullSha = await _sha1Hex(sortedUids.join('|'));
  const instanceId = fullSha.slice(0, 12);
  // Drop any prior instance affiliations on these primitives so the
  // bboxes of those old instances get recomputed too.
  const orphanedIds = new Set();
  selected.forEach((el) => {
    if (!el.getAttribute('data-uid')) return;
    const prev = el.getAttribute('data-instance-id');
    if (prev && prev !== instanceId) orphanedIds.add(prev);
    el.setAttribute('data-instance-id', instanceId);
  });
  window.renderInstanceBbox(instanceId);
  orphanedIds.forEach((id) => window.renderInstanceBbox(id));
  // Drop any bbox whose entire group just got reassigned.
  window.refreshInstanceBboxes();
  window.queueAnnotSaveTile?.();
};

// Affectation des classes (classId) : normalisation
window.normalizeClassIdCase = (svg) => {
  if (!svg) return;
  const nodes = svg.querySelectorAll('[classid]');
  nodes.forEach((el) => {
    if (!el.hasAttribute('classId')) {
      const value = el.getAttribute('classid');
      if (value !== null) el.setAttribute('classId', value);
    }
    el.removeAttribute('classid');
  });
};

window.setToolbarState = (hasSvg) => {
  const required = document.querySelectorAll('[data-requires-svg="true"]');
  required.forEach((btn) => {
    if (!(btn instanceof HTMLButtonElement)) return;
    btn.disabled = !hasSvg;
    btn.classList.toggle('tool-disabled', !hasSvg);
  });
};

window.updateSelectionState = () => {
  const svg = document.querySelector('.svg-clickable svg');
  const hasSelected = !!svg && svg.querySelector('[data-selected="true"]');
  const required = document.querySelectorAll('[data-requires-selection="true"]');
  required.forEach((btn) => {
    if (!(btn instanceof HTMLButtonElement)) return;
    btn.disabled = !hasSelected;
    btn.classList.toggle('tool-disabled', !hasSelected);
  });
};

const DOOR_CLASS_IDS = new Set(['inside door', 'outside door', 'cabinet door']);

const resolveElementClassId = (el, svgRoot) => {
  let node = el;
  while (node && node !== svgRoot) {
    const classId = (node.getAttribute?.('classId') || node.getAttribute?.('classid') || '').trim().toLowerCase();
    if (classId) return classId;
    node = node.parentElement;
  }
  return '';
};

const isLinearSvgPathData = (d) => {
  if (!d || typeof d !== 'string') return false;
  const commands = d.match(/[a-zA-Z]/g) || [];
  if (!commands.length) return false;
  return commands.every((cmd) => 'mMlLhHvVzZ'.includes(cmd));
};

const parseSimpleLinearPathPoints = (d) => {
  if (!isLinearSvgPathData(d)) return [];
  const tokens = String(d).match(/[a-zA-Z]|[-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?/g) || [];
  const points = [];
  let i = 0;
  let cmd = '';
  let x = 0;
  let y = 0;
  let subpathStartX = 0;
  let subpathStartY = 0;

  const pushPoint = (nextX, nextY) => {
    x = nextX;
    y = nextY;
    points.push({x, y});
  };

  while (i < tokens.length) {
    const token = tokens[i];
    if (/^[a-zA-Z]$/.test(token)) {
      cmd = token;
      i += 1;
    }
    if (!cmd) break;

    if (cmd === 'Z' || cmd === 'z') {
      pushPoint(subpathStartX, subpathStartY);
      continue;
    }

    if (cmd === 'M' || cmd === 'm') {
      if (i + 1 >= tokens.length) break;
      const dx = Number(tokens[i]);
      const dy = Number(tokens[i + 1]);
      i += 2;
      const nextX = cmd === 'm' ? x + dx : dx;
      const nextY = cmd === 'm' ? y + dy : dy;
      pushPoint(nextX, nextY);
      subpathStartX = x;
      subpathStartY = y;
      cmd = cmd === 'm' ? 'l' : 'L';
      continue;
    }

    if (cmd === 'L' || cmd === 'l') {
      if (i + 1 >= tokens.length) break;
      const dx = Number(tokens[i]);
      const dy = Number(tokens[i + 1]);
      i += 2;
      pushPoint(cmd === 'l' ? x + dx : dx, cmd === 'l' ? y + dy : dy);
      continue;
    }

    if (cmd === 'H' || cmd === 'h') {
      if (i >= tokens.length) break;
      const dx = Number(tokens[i]);
      i += 1;
      pushPoint(cmd === 'h' ? x + dx : dx, y);
      continue;
    }

    if (cmd === 'V' || cmd === 'v') {
      if (i >= tokens.length) break;
      const dy = Number(tokens[i]);
      i += 1;
      pushPoint(x, cmd === 'v' ? y + dy : dy);
      continue;
    }

    break;
  }

  return points;
};

const pathIsClosed = (points) => {
  if (!Array.isArray(points) || points.length < 3) return false;
  const first = points[0];
  const last = points[points.length - 1];
  return Math.hypot(last.x - first.x, last.y - first.y) <= 1e-9;
};

const computePolylineTurnMetrics = (points) => {
  let totalTurn = 0;
  let maxTurn = 0;
  for (let i = 0; i + 2 < points.length; i += 1) {
    const a = points[i];
    const b = points[i + 1];
    const c = points[i + 2];
    const v1x = b.x - a.x;
    const v1y = b.y - a.y;
    const v2x = c.x - b.x;
    const v2y = c.y - b.y;
    const len1 = Math.hypot(v1x, v1y);
    const len2 = Math.hypot(v2x, v2y);
    if (len1 <= 1e-9 || len2 <= 1e-9) continue;
    const cosTheta = Math.max(-1, Math.min(1, ((v1x * v2x) + (v1y * v2y)) / (len1 * len2)));
    const angle = Math.acos(cosTheta) * 180 / Math.PI;
    totalTurn += angle;
    maxTurn = Math.max(maxTurn, angle);
  }
  return {totalTurn, maxTurn};
};

const computeMaxPointToChordDistance = (points) => {
  if (!Array.isArray(points) || points.length < 3) return 0;
  const start = points[0];
  const end = points[points.length - 1];
  const chordDx = end.x - start.x;
  const chordDy = end.y - start.y;
  const chordLen = Math.hypot(chordDx, chordDy);
  if (chordLen <= 1e-9) return 0;
  let maxDistance = 0;
  for (let i = 1; i < points.length - 1; i += 1) {
    const p = points[i];
    const areaTwice = Math.abs(((p.x - start.x) * chordDy) - ((p.y - start.y) * chordDx));
    maxDistance = Math.max(maxDistance, areaTwice / chordLen);
  }
  return maxDistance;
};

const isArcLikeLinearPathData = (d) => {
  const points = parseSimpleLinearPathPoints(d);
  if (points.length < 2) return false;
  if (pathIsClosed(points)) return false;
  if (points.length < 3) return false;

  const start = points[0];
  const end = points[points.length - 1];
  const chord = Math.hypot(end.x - start.x, end.y - start.y);
  if (chord <= 1e-9) return false;

  const {totalTurn, maxTurn} = computePolylineTurnMetrics(points);
  const maxOffset = computeMaxPointToChordDistance(points);
  if (totalTurn >= 6 && maxTurn >= 4 && maxOffset >= Math.max(0.01, chord * 0.005)) return true;
  return totalTurn >= 0.5 && maxOffset >= Math.max(0.0015, chord * 0.001);
};

const SELECTION_PRIMITIVE_SELECTOR = 'path,line,polyline,polygon,rect,circle,ellipse,text';
const SELECTION_SPATIAL_INDEX_TARGET_CELLS = 72;
const SELECTION_SPATIAL_INDEX_MAX_CELL_SPAN = 12;

const pointInPolygon = (point, vertices) => {
  if (!vertices || vertices.length < 3) return false;
  let inside = false;
  for (let i = 0, j = vertices.length - 1; i < vertices.length; j = i++) {
    const xi = vertices[i].x, yi = vertices[i].y;
    const xj = vertices[j].x, yj = vertices[j].y;
    const denom = (yj - yi) || 1e-12;
    const intersect = ((yi > point.y) !== (yj > point.y))
      && (point.x < (xj - xi) * (point.y - yi) / denom + xi);
    if (intersect) inside = !inside;
  }
  return inside;
};

const bboxInsidePolygon = (bbox, vertices) => {
  if (!bbox || !vertices || vertices.length < 3) return false;
  const corners = [
    {x: bbox.left, y: bbox.top},
    {x: bbox.right, y: bbox.top},
    {x: bbox.right, y: bbox.bottom},
    {x: bbox.left, y: bbox.bottom},
  ];
  for (let i = 0; i < 4; i += 1) {
    if (!pointInPolygon(corners[i], vertices)) return false;
  }
  return true;
};

const polygonBoundingRect = (vertices) => {
  if (!vertices || !vertices.length) return null;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const p of vertices) {
    if (p.x < minX) minX = p.x;
    if (p.y < minY) minY = p.y;
    if (p.x > maxX) maxX = p.x;
    if (p.y > maxY) maxY = p.y;
  }
  return {x: minX, y: minY, w: maxX - minX, h: maxY - minY};
};

const getSelectionLocalBBox = (el) => {
  if (!el || typeof el.getBBox !== 'function') return null;
  if (el.hasAttribute('data-selection-overlay')) return null;
  if (el.hasAttribute('data-class-overlay')) return null;
  if (el.hasAttribute('data-selection-rect')) return null;
  if (el.hasAttribute('data-access-path-overlay')) return null;
  try {
    const bbox = el.getBBox();
    if (!Number.isFinite(bbox.x) || !Number.isFinite(bbox.y) || !Number.isFinite(bbox.width) || !Number.isFinite(bbox.height)) {
      return null;
    }
    return {
      left: bbox.x,
      top: bbox.y,
      right: bbox.x + bbox.width,
      bottom: bbox.y + bbox.height,
    };
  } catch (_) {
    return null;
  }
};

const buildSelectionSpatialIndex = (svg) => {
  const index = {
    minX: 0,
    minY: 0,
    maxX: 0,
    maxY: 0,
    cellSize: 1,
    buckets: new Map(),
    entries: new Map(),
    overflowEntries: [],
  };
  if (!svg) return index;
  const primitives = Array.from(svg.querySelectorAll(SELECTION_PRIMITIVE_SELECTOR));
  svg.__selectionPrimitiveList = primitives;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  const rawEntries = [];
  primitives.forEach((el) => {
    const bbox = getSelectionLocalBBox(el);
    if (!bbox) return;
    const uid = String(el.getAttribute('data-uid') || '').trim() || `${rawEntries.length + 1}`;
    rawEntries.push({uid, el, bbox});
    minX = Math.min(minX, bbox.left);
    minY = Math.min(minY, bbox.top);
    maxX = Math.max(maxX, bbox.right);
    maxY = Math.max(maxY, bbox.bottom);
  });
  if (!rawEntries.length || !Number.isFinite(minX) || !Number.isFinite(minY) || !Number.isFinite(maxX) || !Number.isFinite(maxY)) {
    return index;
  }
  const width = Math.max(maxX - minX, 1);
  const height = Math.max(maxY - minY, 1);
  const longerSide = Math.max(width, height);
  const cellSize = Math.max(longerSide / SELECTION_SPATIAL_INDEX_TARGET_CELLS, 1e-6);
  index.minX = minX;
  index.minY = minY;
  index.maxX = maxX;
  index.maxY = maxY;
  index.cellSize = cellSize;
  rawEntries.forEach((entry) => {
    const ix0 = Math.floor((entry.bbox.left - minX) / cellSize);
    const iy0 = Math.floor((entry.bbox.top - minY) / cellSize);
    const ix1 = Math.floor((entry.bbox.right - minX) / cellSize);
    const iy1 = Math.floor((entry.bbox.bottom - minY) / cellSize);
    if ((ix1 - ix0) > SELECTION_SPATIAL_INDEX_MAX_CELL_SPAN || (iy1 - iy0) > SELECTION_SPATIAL_INDEX_MAX_CELL_SPAN) {
      index.overflowEntries.push(entry);
      return;
    }
    index.entries.set(entry.uid, entry);
    for (let ix = ix0; ix <= ix1; ix += 1) {
      for (let iy = iy0; iy <= iy1; iy += 1) {
        const key = `${ix},${iy}`;
        if (!index.buckets.has(key)) index.buckets.set(key, []);
        index.buckets.get(key).push(entry.uid);
      }
    }
  });
  return index;
};

const ensureSelectionSpatialIndex = (svg) => {
  if (!svg) return null;
  if (svg.__selectionSpatialIndex) return svg.__selectionSpatialIndex;
  svg.__selectionSpatialIndex = buildSelectionSpatialIndex(svg);
  return svg.__selectionSpatialIndex;
};

const invalidateSelectionSpatialIndex = (svg) => {
  if (!svg) return;
  svg.__selectionSpatialIndex = null;
  svg.__selectionPrimitiveList = null;
};

const querySelectionCandidates = (svg, rect) => {
  const index = ensureSelectionSpatialIndex(svg);
  if (!index || !index.buckets || index.buckets.size === 0) {
    return Array.from(svg?.querySelectorAll(SELECTION_PRIMITIVE_SELECTOR) || []);
  }
  const minX = index.minX;
  const minY = index.minY;
  const cellSize = index.cellSize;
  const ix0 = Math.floor((rect.x - minX) / cellSize);
  const iy0 = Math.floor((rect.y - minY) / cellSize);
  const ix1 = Math.floor((rect.x + rect.w - minX) / cellSize);
  const iy1 = Math.floor((rect.y + rect.h - minY) / cellSize);
  const seen = new Set();
  const candidates = [];
  for (let ix = ix0; ix <= ix1; ix += 1) {
    for (let iy = iy0; iy <= iy1; iy += 1) {
      const key = `${ix},${iy}`;
      const bucket = index.buckets.get(key);
      if (!bucket) continue;
      bucket.forEach((uid) => {
        if (seen.has(uid)) return;
        const entry = index.entries.get(uid);
        if (!entry || !entry.el) return;
        seen.add(uid);
        candidates.push(entry);
      });
    }
  }
  (index.overflowEntries || []).forEach((entry) => {
    if (!entry?.uid || seen.has(entry.uid)) return;
    seen.add(entry.uid);
    candidates.push(entry);
  });
  return candidates;
};

// Application du SVG dans la vue principale
window.applySvgText = (text) => {
  if (typeof text !== 'string') return;
  const totalStartedAt = performance.now();
  const container = document.querySelector('.svg-clickable');
  if (!container) return;
  window.__currentSvgSourceText = text;
  window.resetAnnotationHistoryState?.();
  let stepStartedAt = performance.now();
  container.innerHTML = text;
  logSvgPerfStep('SVG DOM injection', stepStartedAt);
  const svg = container.querySelector('svg');
  if (svg) {
    svg.__selectionSpatialIndex = null;
    svg.__selectionPrimitiveList = null;
    svg.__instanceBboxMargin = undefined;
    svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    if (window.normalizeClassIdCase) {
      stepStartedAt = performance.now();
      window.normalizeClassIdCase(svg);
      logSvgPerfStep('SVG classId normalization', stepStartedAt);
    }
    // Clean up baked hidden-by-class state from saved SVGs
    stepStartedAt = performance.now();
    svg.querySelectorAll('[data-hidden-by-class]').forEach((el) => {
      const orig = el.getAttribute('data-orig-display');
      if (orig !== null) {
        el.style.display = orig;
        el.removeAttribute('data-orig-display');
      } else {
        el.style.display = '';
      }
      el.removeAttribute('data-hidden-by-class');
    });
    logSvgPerfStep('SVG hidden-by-class cleanup', stepStartedAt);
  }
  if (window.clearAccessPathOverlays) {
    stepStartedAt = performance.now();
    window.clearAccessPathOverlays();
    logSvgPerfStep('SVG overlay cleanup', stepStartedAt);
  }
  if (window.resetVisibilityCheckboxes && !(typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE)) {
    stepStartedAt = performance.now();
    window.resetVisibilityCheckboxes();
    logSvgPerfStep('SVG visibility reset', stepStartedAt);
  }
  if (window.clearSelection) {
    stepStartedAt = performance.now();
    window.clearSelection();
    logSvgPerfStep('SVG selection reset', stepStartedAt);
  }
  if (window.assignSvgUids) {
    stepStartedAt = performance.now();
    window.assignSvgUids();
    logSvgPerfStep('SVG uid assignment', stepStartedAt);
  }
  if (window.initZoomPan) {
    stepStartedAt = performance.now();
    window.initZoomPan();
    logSvgPerfStep('SVG zoom/pan initialization', stepStartedAt);
  }
  if (window.resetPmrToolbar) window.resetPmrToolbar();
  if (window.setToolbarState) window.setToolbarState(true);
  if (window.updateSelectionState) window.updateSelectionState();
  // In objects mode, recompute instance bboxes against the freshly
  // injected DOM so saved bboxes are redrawn at the right size.
  if (typeof OBJECTS_MODE !== 'undefined' && OBJECTS_MODE && window.refreshInstanceBboxes) {
    window.refreshInstanceBboxes();
  }
  logSvgPerfStep('SVG total display pipeline', totalStartedAt);
  // Fire-and-forget annotation sanity check — surfaces obvious
  // mis-classifications (window+sliding door close, orphan
  // shower/windows door, primitives inside kitchen-devices polygon).
  // Defer one tick so DOM injection finishes first, then runAnalysisAction
  // can serialise the live SVG for the backend.
  if (window.runSanityCheck) {
    setTimeout(() => window.runSanityCheck(), 0);
  }
};

