// Ouverture .svg ou .pdf
window.loadSvgFromFile = async (file) => {
  const formData = new FormData();
  formData.append('file', file, file.name);
  try {
    const res = await fetch('/open-file', {method: 'POST', body: formData});
    const data = await res.json();
    if (Array.isArray(data?.logs)) {
      data.logs.forEach((line) => window.appendLoadingModalLog?.(line, data?.ok ? '' : 'error'));
    }
    if (!data?.ok || typeof data?.svg !== 'string') {
      throw new Error(data?.error || 'Unable to open SVG');
    }
    window.setCurrentSvgExportName(file?.name || 'annotated.svg');
    window.setLoadingModalStatus?.('Display', 'Injecting SVG into JavaScript');
    window.appendLoadingModalLog?.('Display phase: SVG -> JavaScript');
    window.applySvgText(data.svg);
    window.appendLoadingModalLog?.('SVG display completed');
    window.setLoadingModalStatus?.('Done', 'File ready');
    window.setTimeout(() => window.closeLoadingModal?.(), 500);
  } catch (error) {
    window.appendLoadingModalLog?.(`Error: ${error instanceof Error ? error.message : String(error)}`, 'error');
    window.setLoadingModalStatus?.('Error', 'Unable to open SVG');
  }
};

window.loadSvgFromUrl = async (url) => {
  window.setLoadingModalStatus?.('Fetching', 'Reading generated SVG');
  window.appendLoadingModalLog?.(`Fetching SVG: ${url}`);
  const res = await fetch(url, {method: 'GET', cache: 'no-store'});
  if (!res.ok) {
    throw new Error(`SVG fetch failed: ${res.status}`);
  }
  const text = await res.text();
  const fileName = (() => {
    try {
      const parsed = new URL(url, window.location.href);
      const lastSegment = parsed.pathname.split('/').filter(Boolean).pop() || '';
      return lastSegment || 'annotated.svg';
    } catch (_) {
      return url.split('/').filter(Boolean).pop() || 'annotated.svg';
    }
  })();
  window.setCurrentSvgExportName(fileName);
  window.setLoadingModalStatus?.('Display', 'Injecting SVG into JavaScript');
  window.appendLoadingModalLog?.('Display phase: SVG -> JavaScript');
  window.applySvgText(text);
  window.appendLoadingModalLog?.('SVG display completed');
};

window.waitForPdfOpenJob = async (jobId, initialOffset = 0) => {
  let offset = initialOffset;
  while (true) {
    const res = await fetch(`/open-file/jobs/${encodeURIComponent(jobId)}?offset=${offset}`, {
      method: 'GET',
      cache: 'no-store',
    });
    if (!res.ok) {
      throw new Error(`PDF job fetch failed: ${res.status}`);
    }
    const data = await res.json();
    if (Array.isArray(data?.logs)) {
      data.logs.forEach((line) => window.appendLoadingModalLog?.(line, data?.ok === false ? 'error' : ''));
    }
    if (typeof data?.next_offset === 'number') {
      offset = data.next_offset;
    }
    window.setLoadingModalStatus?.(data?.status || 'Processing', data?.step || 'PDF conversion in progress');
    if (data?.done) {
      return data;
    }
    await new Promise((resolve) => window.setTimeout(resolve, 250));
  }
};

window.loadPdfFromFile = async (file) => {
  const formData = new FormData();
  formData.append('file', file, file.name);
  if (window.setToolbarState) window.setToolbarState(false);
  window.openLoadingModal?.({
    title: 'Opening PDF',
    status: 'Analysis',
    step: 'Reading PDF',
  });
  try {
    const analyzeRes = await fetch('/open-file/pdf/analyze', {method: 'POST', body: formData});
    const analysis = await analyzeRes.json();
    if (Array.isArray(analysis?.logs)) {
      analysis.logs.forEach((line) => window.appendLoadingModalLog?.(line, analysis?.ok ? '' : 'error'));
    }
    if (!analysis?.ok || !analysis?.upload_id) {
      window.setLoadingModalStatus?.('Error', 'PDF analysis failed');
      window.appendLoadingModalLog?.(`Error: ${analysis?.error || 'unknown error'}`, 'error');
      console.error('PDF analyze failed', analysis?.error || 'unknown error');
      return;
    }

    window.setLoadingModalStatus?.('Configuration', 'Choosing conversion options');
    const pageNumber = await window.selectPdfPage(analysis);
    if (pageNumber === null) {
      window.setLoadingModalStatus?.('Canceled', 'PDF opening canceled');
      window.appendLoadingModalLog?.('PDF opening canceled');
      window.setTimeout(() => window.closeLoadingModal?.(), 500);
      return;
    }

    const scale = await window.selectPdfScale(analysis);
    if (scale === null) {
      window.setLoadingModalStatus?.('Canceled', 'PDF opening canceled');
      window.appendLoadingModalLog?.('PDF opening canceled');
      window.setTimeout(() => window.closeLoadingModal?.(), 500);
      return;
    }

    const startData = new FormData();
    startData.append('upload_id', analysis.upload_id);
    startData.append('page_number', String(pageNumber));
    startData.append('scale', scale);

    const startRes = await fetch('/open-file/pdf/start', {method: 'POST', body: startData});
    const data = await startRes.json();
    if (Array.isArray(data?.logs)) {
      data.logs.forEach((line) => window.appendLoadingModalLog?.(line, data?.ok ? '' : 'error'));
    }
    if (!data?.ok || !data?.job_id) {
      window.setLoadingModalStatus?.('Error', 'PDF conversion failed');
      window.appendLoadingModalLog?.(`Error: ${data?.error || 'unknown error'}`, 'error');
      console.error('PDF load failed', data?.error || 'unknown error');
      return;
    }

    const finalData = await window.waitForPdfOpenJob(data.job_id, data?.next_offset || 0);
    if (finalData?.ok && finalData?.svg_url) {
      await window.loadSvgFromUrl(finalData.svg_url);
      window.setLoadingModalStatus?.('Done', 'PDF displayed');
      window.setTimeout(() => window.closeLoadingModal?.(), 700);
    } else {
      window.setLoadingModalStatus?.('Error', 'PDF conversion failed');
      window.appendLoadingModalLog?.(`Error: ${finalData?.error || 'unknown error'}`, 'error');
      console.error('PDF load failed', finalData?.error || 'unknown error');
    }
  } catch (err) {
    window.setLoadingModalStatus?.('Error', 'PDF conversion failed');
    window.appendLoadingModalLog?.(`Error: ${err instanceof Error ? err.message : String(err)}`, 'error');
    console.error('PDF load failed', err);
  } finally {
    window.setToolbarState?.(!!document.querySelector('.svg-clickable svg'));
  }
};

window.handleFileInput = (evt) => {
  const file = evt?.target?.files?.[0];
  if (!file) return;
  const name = (file.name || '').toLowerCase();
  if (name.endsWith('.svg')) {
    window.openLoadingModal?.({
      title: 'Ouverture du SVG',
      status: 'Lecture',
      step: 'Chargement du fichier SVG',
    });
    window.appendLoadingModalLog?.(`Received SVG file: ${file.name}`);
    window.loadSvgFromFile(file);
  } else if (name.endsWith('.pdf')) {
    window.loadPdfFromFile(file);
  }
  evt.target.value = '';
};

