// Sélection par clic (gestion overlays et évènements)
window.handleSvgClick = (e) => {
  let t = e.target;
  if (!t) return;
  if (e.shiftKey || isCtrlOrCmd(e)) return;
  if (t.getAttribute && t.getAttribute('data-selection-overlay') === 'true') {
    const uid = t.getAttribute('data-selection-overlay-for');
    if (uid) {
      const svg = t.ownerSVGElement;
      const original = svg ? svg.querySelector(`[data-uid="${uid}"]`) : null;
      if (original) t = original;
    }
  }
  if (t.getAttribute && t.getAttribute('data-class-overlay') === 'true') {
    const uid = t.getAttribute('data-class-overlay-for');
    if (uid) {
      const svg = t.ownerSVGElement;
      const original = svg ? svg.querySelector(`[data-uid="${uid}"]`) : null;
      if (original) t = original;
    }
  }
  const tag = (t.tagName || '').toLowerCase();
  const primitives = ['path','line','polyline','polygon','rect','circle','ellipse','text'];
  if (!primitives.includes(tag)) return;
  // Frozen elements (overlap zone context) cannot be selected
  const clickClassId = (t.getAttribute('classId') || t.getAttribute('classid') || '').trim().toLowerCase();
  if (clickClassId === 'frozen') return;
  const svg = t.ownerSVGElement;
  if (svg) {
    if (Number(svg.__panSuppressClickUntil) > performance.now()) {
      return;
    }
    const deselect = (el) => {
      const orig = el.getAttribute('data-orig-stroke-width');
      if (orig !== null) {
        el.setAttribute('stroke-width', orig);
        el.removeAttribute('data-orig-stroke-width');
      }
      const origStroke = el.getAttribute('data-orig-stroke');
      if (origStroke !== null) {
        el.setAttribute('stroke', origStroke);
        el.removeAttribute('data-orig-stroke');
      }
      if (window.removeSelectionOverlay) window.removeSelectionOverlay(el);
      el.removeAttribute('data-selected');
    };
    const select = (el) => {
      if (el.hasAttribute('data-selected')) return;
      const historyEntry = window.createSelectionHistoryEntry?.(el, true) || null;
      const stroke = el.getAttribute('stroke');
      const fill = el.getAttribute('fill');
      const hasStroke = !!stroke && stroke !== 'none';
      const hasFill = !!fill && fill !== 'none';
      if (!hasStroke && !hasFill) return;
      if (!el.hasAttribute('data-orig-stroke')) {
        el.setAttribute('data-orig-stroke', stroke ?? '');
      }
      el.setAttribute('data-selected', 'true');
      if (window.addSelectionOverlay) window.addSelectionOverlay(el);
      window.pushAnnotationHistoryEntry?.(historyEntry);
    };
    if (t.hasAttribute('data-selected')) {
      window.pushAnnotationHistoryEntry?.(window.createSelectionHistoryEntry?.(t, false) || null);
      deselect(t);
      if (window.updateSelectionState) window.updateSelectionState();
      return;
    }
    select(t);
    if (window.updateSelectionState) window.updateSelectionState();
  }
};

