// Vue principale (canvas SVG)
// - sélection par clic et rectangle
// - affichage des primitives sélectionnées
// - affectation des classes (classId)
// - affichage par masque de couleur de la classe affectée
// - zoom/pan et export .svg

// Cartographie clavier -> couleur -> classId (injectée par app.py)
// const KEY_COLOR_MAP
// const CLASS_COLOR_MAP
// const CLASS_NAME_COLOR_MAP
// const CLASS_NAME_MASK_MAP

// Sur macOS, ⌘ remplace Ctrl pour les raccourcis (zoom, pan, sélection multiple).
const IS_MAC = typeof navigator !== 'undefined' && (
  (navigator.userAgentData && navigator.userAgentData.platform === 'macOS') ||
  /Mac|iPhone|iPad|iPod/i.test(navigator.platform || '') ||
  /Mac OS X/i.test(navigator.userAgent || '')
);
const isCtrlOrCmd = (e) => IS_MAC ? !!e.metaKey : !!e.ctrlKey;
const PAN_MOD_KEY = IS_MAC ? 'Meta' : 'Control';

// Wall classes are reserved for bbox sides — never apply to primitives,
// even if accidentally part of the rectangle selection.
const _WALL_CLASSES = new Set(['wall1', 'wall2', 'wall3']);

window.setSelectedStroke = (color, clearAfter = true) => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const key = (color || '').toLowerCase();
  const className = CLASS_COLOR_MAP[key] || CLASS_COLOR_MAP[color] || '';
  if (!className) return;
  const isWallClass = _WALL_CLASSES.has(className.toLowerCase());
  const selected = Array.from(svg.querySelectorAll('[data-selected="true"]'));
  if (!selected.length) return;
  withBusyGuard('Affectation de classe', `${className} (${selected.length} elements)`, async () => {
    const startedAt = performance.now();
    const selectedCount = selected.length;
    const historyEntries = [];
    let hiddenByClassCount = 0;
    window.appendLoadingModalLog?.(`Classe: ${className}`);
    window.appendLoadingModalLog?.(`Elements selectionnes: ${selectedCount}`);
    await processInAnimationBatches(selected, (el) => {
      // Frozen elements (overlap context) cannot be reclassified
      const curClass = (el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
      if (curClass === 'frozen') return;
      const isBboxLine = el.getAttribute('data-instance-bbox') === 'true';
      // Mode objets : les classes Wall1/2/3 ne s'appliquent QU'aux côtés
      // de bbox d'instance. Symétriquement, les classes "primitives"
      // (door/bed/sofa/…) ne s'appliquent jamais aux côtés de bbox —
      // sinon un rectangle qui englobe la bbox réécrirait sa couleur.
      if (typeof OBJECTS_MODE !== 'undefined' && OBJECTS_MODE) {
        if (isWallClass && !isBboxLine) return;
        if (!isWallClass && isBboxLine) return;
      }
      historyEntries.push(window.createAnnotationHistoryEntry?.(el, className) || null);
      if (window.removeClassOverlay) window.removeClassOverlay(el);
      if (el.hasAttribute('classId')) el.removeAttribute('classId');
      if (el.hasAttribute('classid')) el.removeAttribute('classid');
      el.setAttribute('classId', className);
      window.ensureElementClassOverlay?.(el);
    }, {
      onProgress: (done, total) => window.setLoadingModalStatus?.('En cours', `Affectation: ${done}/${total}`),
    });
    // Edition visibilité des classes
    const classKey = (className || '').trim().toLowerCase();
    const checkbox = document.querySelector(`.tool-checkbox[data-class-id="${CSS.escape(classKey)}"]`);
    if (checkbox && !checkbox.checked) {
      window.appendLoadingModalLog?.(`Classe ${className} masquee, application de la visibilite`);
      await processInAnimationBatches(selected, (el) => {
        const classValue = String(el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
        if (classValue && CLASS_NAME_MASK_MAP[classValue]) {
          window.ensureElementClassOverlay?.(el);
        }
        if (window.removeSelectionOverlay) window.removeSelectionOverlay(el);
        if (!el.hasAttribute('data-orig-display')) {
          el.setAttribute('data-orig-display', el.style.display || '');
        }
        el.style.display = 'none';
        el.setAttribute('data-hidden-by-class', 'true');
        hiddenByClassCount += 1;
        const uid = String(el.getAttribute('data-uid') || '').trim();
        if (uid) {
          const overlay = el.ownerSVGElement?.querySelector(`[data-class-overlay-for="${CSS.escape(uid)}"]`);
          if (overlay) overlay.style.display = 'none';
        }
      }, {
        onProgress: (done, total) => window.setLoadingModalStatus?.('En cours', `Masquage: ${done}/${total}`),
      });
    }
    window.pushAnnotationHistoryEntries?.(historyEntries);
    // Objects mode: route the class assignment to its proper effect.
    //   - Wall1/2/3 label a bbox: just refresh its stroke (no overlay,
    //     no instance-id mutation — the underlying primitives keep their
    //     existing instance affiliation).
    //   - Unlabelled re-labels primitives: ungroups them by dropping
    //     data-instance-id; affected bboxes are refreshed/removed.
    //   - Any other class on primitives: deterministic instance-id
    //     grouping (SHA-1 over the selected uids) via assignInstanceId.
    if (typeof OBJECTS_MODE !== 'undefined' && OBJECTS_MODE) {
      if (isWallClass) {
        // Bbox visuals: replace stroke directly so we get the exact wall
        // colour without the 0.8-opacity overlay tint. Drop any class
        // overlay that ensureElementClassOverlay may have just added.
        const wallColor = CLASS_NAME_COLOR_MAP[className.toLowerCase()];
        selected.forEach((el) => {
          if (el.getAttribute('data-instance-bbox') !== 'true') return;
          window.removeClassOverlay?.(el);
          if (wallColor) el.setAttribute('stroke', wallColor);
        });
      } else if (className.toLowerCase() === 'unlabelled') {
        const touchedInstanceIds = new Set();
        selected.forEach((el) => {
          if (el.getAttribute('data-instance-bbox') === 'true') return;
          const id = el.getAttribute('data-instance-id');
          if (id) {
            touchedInstanceIds.add(id);
            el.removeAttribute('data-instance-id');
          }
        });
        if (touchedInstanceIds.size > 0) {
          touchedInstanceIds.forEach((id) => window.renderInstanceBbox?.(id));
          window.refreshInstanceBboxes?.();
        }
      } else {
        await window.assignInstanceId?.();
      }
    }
    if (hiddenByClassCount > 0) invalidateSelectionSpatialIndex(svg);
    if (clearAfter && window.clearSelection) window.clearSelection({recordHistory: false});
    if (selectedCount) {
      window.queueAutosave?.({reason: 'class-assignment'});
      window.annotOnClassAssigned?.();
    }
    const reclassifiedCount = historyEntries.filter(Boolean).length;
    if (reclassifiedCount > 0) {
      window.recordAnnotStat?.(className, reclassifiedCount);
    }
    const totalMs = roundPerfMs(performance.now() - startedAt);
    window.appendLoadingModalLog?.(`Termine en ${formatPerfMs(performance.now() - startedAt)}`);
    perfDebugLog('setSelectedStroke', {
      class_name: className,
      selected_count: selectedCount,
      history_entries: historyEntries.filter(Boolean).length,
      hidden_by_class_count: hiddenByClassCount,
      clear_after: !!clearAfter,
      total_ms: totalMs,
    });
  });
};

