const _annotStatsAllClasses = () => {
  const map = (typeof CLASS_NAME_COLOR_MAP === 'object' && CLASS_NAME_COLOR_MAP) ? CLASS_NAME_COLOR_MAP : {};
  return Object.keys(map).sort();
};

const buildAnnotStatsTsv = (stats, days, classes) => {
  const lines = [];
  lines.push(['Date', ...classes, 'Total'].join('\t'));
  days.forEach((d) => {
    const bucket = stats[d] || {};
    let dayTotal = 0;
    const row = [d];
    classes.forEach((c) => {
      const v = Number(bucket[c] || 0);
      dayTotal += v;
      row.push(String(v));
    });
    row.push(String(dayTotal));
    lines.push(row.join('\t'));
  });
  return lines.join('\n');
};

const renderAnnotStatsTable = (stats) => {
  const days = Object.keys(stats || {}).sort().reverse();
  const knownClasses = _annotStatsAllClasses();
  // Include any class that appears in stats but isn't in the known list
  // (defensive — shouldn't happen unless SVG_CATEGORIES changes).
  const extra = new Set();
  days.forEach((d) => {
    Object.keys(stats[d] || {}).forEach((c) => {
      if (!knownClasses.includes(c)) extra.add(c);
    });
  });
  const classes = [...knownClasses, ...Array.from(extra).sort()];
  if (!days.length) {
    return {
      html: `<p style="color:#475569;margin:0;">Aucune statistique enregistrée pour le moment. (${classes.length} classes connues)</p>`,
      tsv: buildAnnotStatsTsv({}, [], classes),
    };
  }
  const cellPad = 'padding:4px 10px;border-bottom:1px solid #e5e7eb;white-space:nowrap;';
  const headPad = 'padding:6px 10px;border-bottom:2px solid #cbd5e1;background:#f8fafc;text-align:left;font-weight:600;white-space:nowrap;position:sticky;top:0;';
  const numCell = `${cellPad}text-align:right;font-variant-numeric:tabular-nums;`;
  const numHead = `${headPad}text-align:right;`;
  let html = '<table style="border-collapse:collapse;width:max-content;min-width:100%;">';
  html += '<thead><tr>';
  html += `<th style="${headPad}">Date</th>`;
  classes.forEach((c) => { html += `<th style="${numHead}">${c}</th>`; });
  html += `<th style="${numHead}">Total</th>`;
  html += '</tr></thead><tbody>';
  days.forEach((d) => {
    const bucket = stats[d] || {};
    let dayTotal = 0;
    html += `<tr><td style="${cellPad}font-weight:500;">${d}</td>`;
    classes.forEach((c) => {
      const v = Number(bucket[c] || 0);
      dayTotal += v;
      const dim = v === 0 ? 'color:#cbd5e1;' : '';
      html += `<td style="${numCell}${dim}">${v}</td>`;
    });
    html += `<td style="${numCell}font-weight:600;">${dayTotal}</td>`;
    html += '</tr>';
  });
  html += '</tbody></table>';
  return {html, tsv: buildAnnotStatsTsv(stats, days, classes)};
};

window.openAnnotStats = async () => {
  if (typeof ANNOT_MODE === 'undefined' || !ANNOT_MODE) return;
  const backdrop = ensureAnnotStatsDialog();
