// Manual save: triggered by the toolbar button. Cancels any pending
// debounced auto-save first so we don't end up with two saves in flight.
window.annotManualSaveTile = async () => {
  if (!ANNOT_MODE) return;
  if (window.__annotSaveTileTimer) { window.clearTimeout(window.__annotSaveTileTimer); window.__annotSaveTileTimer = null; }
  if (window._annotSaveTimer) { window.clearTimeout(window._annotSaveTimer); window._annotSaveTimer = null; }
  await window.annotSaveTile();
};

// Debounced tile auto-save — fires after annotation without blocking the UI
window.__annotSaveTileTimer = null;
window.__annotSaveTilePromise = Promise.resolve();

window.queueAnnotSaveTile = () => {
  if (typeof ANNOT_MODE === 'undefined' || !ANNOT_MODE) return;
  if (window.__annotSaveTileTimer) {
    window.clearTimeout(window.__annotSaveTileTimer);
  }
  window.__annotSaveTileTimer = window.setTimeout(() => {
