// Dialogue de chargement d'un SVG interne (data/svgs/ côté serveur)
const ensureInternalFilesModal = () => {
  let backdrop = document.getElementById('internal-files-modal-backdrop');
  if (backdrop) return backdrop;

  backdrop = document.createElement('div');
  backdrop.id = 'internal-files-modal-backdrop';
  backdrop.className = 'internal-files-modal-backdrop';
  backdrop.innerHTML = `
    <div class="internal-files-modal" role="dialog" aria-modal="true" aria-labelledby="internal-files-modal-title">
      <div class="internal-files-modal-header">
        <div id="internal-files-modal-title" class="internal-files-modal-title">SVG internes</div>
        <div class="internal-files-modal-subtitle">data/svgs/ (côté serveur)</div>
      </div>
      <input id="internal-files-modal-search" class="internal-files-modal-search" type="search" placeholder="Filtrer..." />
      <div id="internal-files-modal-list" class="internal-files-modal-list"></div>
      <div class="internal-files-modal-actions">
        <button id="internal-files-modal-cancel" type="button" class="pdf-config-modal-button is-secondary">Fermer</button>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  backdrop.addEventListener('click', (event) => {
    if (event.target === backdrop) backdrop.classList.remove('is-open');
  });
  backdrop.querySelector('#internal-files-modal-cancel')?.addEventListener('click', () => {
    backdrop.classList.remove('is-open');
  });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && backdrop.classList.contains('is-open')) {
      backdrop.classList.remove('is-open');
    }
  });
  return backdrop;
};

const formatInternalFileSize = (bytes) => {
  const n = Number(bytes) || 0;
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(2)} MB`;
};

const renderInternalFilesList = (items, query) => {
  const listEl = document.getElementById('internal-files-modal-list');
  if (!listEl) return;
  const q = (query || '').trim().toLowerCase();
  const filtered = q
    ? items.filter((item) => (item.name || '').toLowerCase().includes(q))
    : items;
  if (!filtered.length) {
    listEl.innerHTML = '<div class="internal-files-modal-empty">Aucun fichier trouvé.</div>';
    return;
  }
  listEl.innerHTML = filtered.map((item) => {
    const name = String(item.name || '');
    const size = formatInternalFileSize(item.size);
    const safeName = name.replace(/"/g, '&quot;');
    return `<div class="internal-files-modal-item" data-url="${safeName}" title="${safeName}">
      <span class="internal-files-modal-item-name"></span>
      <span class="internal-files-modal-item-size">${size}</span>
    </div>`;
  }).join('');
  // Set names via textContent to avoid HTML injection from filenames
  const itemEls = listEl.querySelectorAll('.internal-files-modal-item');
  filtered.forEach((item, i) => {
    const el = itemEls[i];
    if (!el) return;
    const nameEl = el.querySelector('.internal-files-modal-item-name');
    if (nameEl) nameEl.textContent = item.name || '';
    el.addEventListener('click', () => {
      document.getElementById('internal-files-modal-backdrop')?.classList.remove('is-open');
      window.loadInternalSvg?.(item.url, item.name);
    });
  });
};

window.openInternalDialog = async () => {
  const backdrop = ensureInternalFilesModal();
  const listEl = backdrop.querySelector('#internal-files-modal-list');
  const searchEl = backdrop.querySelector('#internal-files-modal-search');
  if (listEl) listEl.innerHTML = '<div class="internal-files-modal-empty">Chargement...</div>';
  if (searchEl) searchEl.value = '';
  backdrop.classList.add('is-open');
  let items = [];
  try {
    const res = await fetch('/internal-svgs', {method: 'GET', cache: 'no-store'});
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    items = Array.isArray(data?.items) ? data.items : [];
  } catch (err) {
    if (listEl) listEl.innerHTML = `<div class="internal-files-modal-empty">Erreur: ${err instanceof Error ? err.message : String(err)}</div>`;
    return;
  }
  renderInternalFilesList(items, '');
  if (searchEl) {
    searchEl.oninput = () => renderInternalFilesList(items, searchEl.value);
    searchEl.focus();
  }
};

window.loadInternalSvg = async (url, name) => {
  if (!url) return;
  window.openLoadingModal?.({
    title: 'Ouverture du SVG interne',
    status: 'Lecture',
    step: 'Chargement depuis le serveur',
  });
  window.appendLoadingModalLog?.(`Internal SVG: ${name || url}`);
  try {
    await window.loadSvgFromUrl(url);
    window.setLoadingModalStatus?.('Done', 'File ready');
    window.setTimeout(() => window.closeLoadingModal?.(), 500);
  } catch (err) {
    window.appendLoadingModalLog?.(`Error: ${err instanceof Error ? err.message : String(err)}`, 'error');
    window.setLoadingModalStatus?.('Error', 'Unable to open SVG');
  } finally {
    window.setToolbarState?.(!!document.querySelector('.svg-clickable svg'));
  }
};

const ensureLoadingModal = () => {
  let backdrop = document.getElementById('loading-modal-backdrop');
  if (backdrop) return backdrop;

  backdrop = document.createElement('div');
  backdrop.id = 'loading-modal-backdrop';
  backdrop.className = 'loading-modal-backdrop';
  backdrop.innerHTML = `
    <div class="loading-modal" role="dialog" aria-modal="true" aria-live="polite" aria-labelledby="loading-modal-title">
      <div class="loading-modal-header">
        <div id="loading-modal-title" class="loading-modal-title">Chargement en cours</div>
        <div id="loading-modal-status" class="loading-modal-status">Initialisation</div>
      </div>
      <div class="loading-modal-body">
        <div class="loading-modal-current">
          <span class="loading-modal-spinner" aria-hidden="true"></span>
          <span id="loading-modal-current-step">Preparation...</span>
        </div>
        <pre id="loading-modal-log" class="loading-modal-log"></pre>
      </div>
    </div>
  `;
  document.body.appendChild(backdrop);
  return backdrop;
};

const getLoadingModalElements = () => {
  const backdrop = ensureLoadingModal();
  return {
    backdrop,
    status: backdrop.querySelector('#loading-modal-status'),
    currentStep: backdrop.querySelector('#loading-modal-current-step'),
    log: backdrop.querySelector('#loading-modal-log'),
  };
};

const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#39;');

const formatPerfMs = (value) => `${Math.round(Number(value) || 0)} ms`;

const formatApproxBytes = (value) => {
  const bytes = Number(value) || 0;
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
};

const logSvgPerfStep = (label, startedAt) => {
  const elapsed = performance.now() - startedAt;
  const message = `${label}: ${formatPerfMs(elapsed)}`;
  window.appendLoadingModalLog?.(message);
  console.info(message);
  return elapsed;
};

const PERF_DEBUG_STATE = {
  initialized: false,
  enabled: false,
};

const roundPerfMs = (value) => Math.round((Number(value) || 0) * 10) / 10;

const isPerfDebugEnabled = () => {
  if (window.__perf_debug === true) return true;
  try {
    if (window.localStorage?.getItem('ct_perf_debug') === '1') return true;
  } catch (_) {
    // ignore storage access errors
  }
  try {
    const params = new URLSearchParams(window.location.search || '');
    if (params.get('perf_debug') === '1') return true;
  } catch (_) {
    // ignore URL parsing errors
  }
  return false;
};

const shouldPerfDebug = () => {
  if (!PERF_DEBUG_STATE.initialized) {
    PERF_DEBUG_STATE.enabled = isPerfDebugEnabled();
    PERF_DEBUG_STATE.initialized = true;
    if (PERF_DEBUG_STATE.enabled) {
      console.info('[perf] debug instrumentation enabled');
    }
  }
  return PERF_DEBUG_STATE.enabled;
};

const perfDebugLog = (label, payload = {}) => {
  if (!shouldPerfDebug()) return;
  console.info(`[perf] ${label}`, payload);
};


const getAnnotationHistoryState = () => {
  if (!window.__annotationHistoryState) {
    window.__annotationHistoryState = {
      items: [],
    };
  }
  return window.__annotationHistoryState;
};

const getAutosaveState = () => {
  if (!window.__autosaveState) {
    window.__autosaveState = {
      items: [],
      saving: false,
      restoring: false,
      savePromise: Promise.resolve(),
      autosaveTimer: null,
      pendingReason: '',
      pendingPromise: null,
      pendingResolve: null,
    };
  }
  return window.__autosaveState;
};

const AUTOSAVE_DEBOUNCE_MS = 1800;
const AUTOSAVE_IDLE_TIMEOUT_MS = 1200;
const VISIBILITY_BATCH_SIZE = 50;

const nextAnimationFrame = () => new Promise((resolve) => {
  window.requestAnimationFrame(() => resolve());
});

const processInAnimationBatches = async (items, fn, {
  batchSize = VISIBILITY_BATCH_SIZE,
  shouldContinue = null,
  onProgress = null,
} = {}) => {
  const total = items.length;
  for (let i = 0; i < total; i += batchSize) {
    if (typeof shouldContinue === 'function' && !shouldContinue()) return false;
    const sliceEnd = Math.min(i + batchSize, total);
    for (let j = i; j < sliceEnd; j += 1) {
      fn(items[j], j);
    }
    if (typeof onProgress === 'function') onProgress(sliceEnd, total);
    if (sliceEnd < total) {
      await nextAnimationFrame();
    }
  }
  return true;
};

const waitForBrowserIdle = () => new Promise((resolve) => {
  if (typeof window.requestIdleCallback === 'function') {
    window.requestIdleCallback(() => resolve(), {timeout: AUTOSAVE_IDLE_TIMEOUT_MS});
    return;
  }
  window.setTimeout(resolve, 50);
});

const getPageLifecycleState = () => {
  if (!window.__pageLifecycleState) {
    window.__pageLifecycleState = {unloading: false};
    window.addEventListener('beforeunload', () => {
      window.__pageLifecycleState.unloading = true;
    });
    window.addEventListener('pagehide', () => {
      window.__pageLifecycleState.unloading = true;
    });
  }
  return window.__pageLifecycleState;
};

const getClassVisibilityState = () => {
  if (!window.__classVisibilityState) {
    window.__classVisibilityState = {epoch: 0};
  }
  return window.__classVisibilityState;
};

const formatAnnotationTime = (timestamp) => {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return '--:--:--';
  return new Intl.DateTimeFormat('fr-FR', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  }).format(date);
};

const formatAutosaveDateTime = (timestamp) => {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return '--';
  return new Intl.DateTimeFormat('fr-FR', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  }).format(date);
};

const toDisplayClassName = (value) => String(value || '')
  .trim()
  .replace(/\s+/g, ' ');

const getHistoryActionMeta = (item) => {
  const actionType = String(item?.actionType || 'class-assignment');
  if (actionType === 'selection') {
    const isSelected = item?.next?.selected !== false;
    return {
      color: isSelected ? '#2563eb' : '#64748b',
      label: isSelected ? 'Selection' : 'Deselection',
    };
  }
  return {
    color: item?.classColor || '#64748b',
    label: toDisplayClassName(item?.className) || 'Sans classe',
  };
};

window.renderAutosaveList = () => {
  const list = document.getElementById('autosave-list');
  if (!list) return;
  const state = getAutosaveState();
  const items = Array.isArray(state.items) ? state.items : [];
  if (!items.length) {
    list.innerHTML = '<div class="autosave-empty">Aucune sauvegarde</div>';
    return;
  }
  list.innerHTML = items
    .map((item) => `
      <button
        class="autosave-item"
        type="button"
        data-autosave-id="${escapeHtml(item?.id || '')}"
        title="Restaurer ${escapeHtml(item?.base_name || 'annotated')}"
      >
        <div class="autosave-item-main">
          <span class="autosave-time">${escapeHtml(formatAutosaveDateTime(item?.created_at_epoch_ms || item?.created_at))}</span>
          <span class="autosave-file">${escapeHtml(item?.display_name || item?.base_name || 'annotated')}</span>
        </div>
      </button>
    `)
    .join('');
  list.querySelectorAll('.autosave-item').forEach((button) => {
    button.addEventListener('mousedown', (e) => e.stopPropagation());
    button.addEventListener('click', async () => {
      const autosaveId = button.getAttribute('data-autosave-id') || '';
      if (!autosaveId) return;
      await window.restoreAutosave?.(autosaveId);
    });
  });
};

window.refreshAutosaveList = async () => {
  try {
    const res = await fetch('/autosave', {method: 'GET', cache: 'no-store'});
    const data = await res.json();
    if (!data?.ok || !Array.isArray(data?.items)) {
      throw new Error(data?.error || 'Unable to list autosaves');
    }
    getAutosaveState().items = data.items;
    window.renderAutosaveList?.();
  } catch (error) {
    console.error('Autosave list refresh failed', error);
  }
};

window.renderAnnotationHistory = () => {
  const list = document.getElementById('annotation-history-list');
  const undoButton = document.getElementById('annotation-history-undo');
  const state = getAnnotationHistoryState();
  const items = Array.isArray(state.items) ? state.items : [];
  if (undoButton instanceof HTMLButtonElement) {
    undoButton.disabled = items.length === 0;
  }
  if (!list) return;
  if (!items.length) {
    list.innerHTML = '<div class="annotation-history-empty">Aucune annotation</div>';
    return;
  }
  list.innerHTML = items
    .slice()
    .reverse()
    .map((item) => {
      const actionMeta = getHistoryActionMeta(item);
      const color = escapeHtml(actionMeta.color);
      const className = escapeHtml(actionMeta.label);
      const primitiveType = escapeHtml(item.primitiveType || 'primitive');
      const timestamp = escapeHtml(formatAnnotationTime(item.timestamp));
      return `
        <div class="annotation-history-item" data-annotation-entry-id="${escapeHtml(item.id)}">
          <div class="annotation-history-item-main">
            <span class="annotation-history-primitive">${primitiveType}</span>
            <span class="annotation-history-class" style="--annotation-class-color:${color};">${className}</span>
          </div>
          <div class="annotation-history-time">${timestamp}</div>
        </div>
      `;
    })
    .join('');
};

window.resetAnnotationHistoryState = () => {
  const state = getAnnotationHistoryState();
  state.items = [];
  window.renderAnnotationHistory?.();
};

const scheduleAnnotationHistoryRender = () => {
  const state = getAnnotationHistoryState();
  if (state.renderScheduled) return;
  state.renderScheduled = true;
  window.requestAnimationFrame(() => {
    state.renderScheduled = false;
    window.renderAnnotationHistory?.();
  });
};

window.createHistoryEntry = ({
  el,
  actionType = 'class-assignment',
  className = '',
  next = {},
} = {}) => {
  if (!el) return null;
  const uid = el.getAttribute('data-uid');
  if (!uid) return null;
  const normalizedClassName = String(className || '').trim();
  const classKey = normalizedClassName.toLowerCase();
  const previousSelected = el.getAttribute('data-selected') === 'true';
  return {
    id: `${uid}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    actionType,
    uid,
    primitiveType: (el.tagName || 'primitive').toLowerCase(),
    className: normalizedClassName,
    classColor: CLASS_NAME_COLOR_MAP[classKey] || '#64748b',
    timestamp: Date.now(),
    previous: {
      classId: el.getAttribute('classId') ?? el.getAttribute('classid') ?? null,
      hiddenByClass: el.getAttribute('data-hidden-by-class') === 'true',
      origDisplay: el.getAttribute('data-orig-display'),
      inlineDisplay: el.style.display || '',
      selected: previousSelected,
    },
    next: {
      classId: Object.prototype.hasOwnProperty.call(next, 'classId') ? next.classId : normalizedClassName,
      hiddenByClass: Object.prototype.hasOwnProperty.call(next, 'hiddenByClass') ? next.hiddenByClass : false,
      inlineDisplay: Object.prototype.hasOwnProperty.call(next, 'inlineDisplay') ? next.inlineDisplay : '',
      selected: Object.prototype.hasOwnProperty.call(next, 'selected') ? next.selected : previousSelected,
    },
  };
};

window.createAnnotationHistoryEntry = (el, className) => window.createHistoryEntry({
  el,
  actionType: 'class-assignment',
  className,
  next: {
    classId: String(className || '').trim() || null,
    hiddenByClass: false,
    inlineDisplay: '',
    selected: true,
  },
});

window.createSelectionHistoryEntry = (el, selected) => window.createHistoryEntry({
  el,
  actionType: 'selection',
  next: {
    classId: el.getAttribute('classId') ?? el.getAttribute('classid') ?? null,
    hiddenByClass: el.getAttribute('data-hidden-by-class') === 'true',
    inlineDisplay: el.style.display || '',
    selected: !!selected,
  },
});

window.pushAnnotationHistoryEntry = (entry) => {
  if (!entry) return;
  const state = getAnnotationHistoryState();
  state.items.push(entry);
  scheduleAnnotationHistoryRender();
};

window.pushAnnotationHistoryEntries = (entries) => {
  if (!Array.isArray(entries)) return;
  const valid = entries.filter(Boolean);
  if (!valid.length) return;
  const state = getAnnotationHistoryState();
  if (valid.length === 1) {
    state.items.push(valid[0]);
  } else {
    const first = valid[0];
    state.items.push({
      id: `group-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      isGroup: true,
      entries: valid,
      actionType: first.actionType,
      className: first.className,
      classColor: first.classColor,
      primitiveType: `${valid.length} elements`,
      timestamp: first.timestamp,
    });
  }
  scheduleAnnotationHistoryRender();
};

const restoreHistoryEntryState = (el, snapshot = {}) => {
  if (!el) return;
  if (window.removeClassOverlay) window.removeClassOverlay(el);
  if (window.removeSelectionOverlay) window.removeSelectionOverlay(el);
  el.removeAttribute('data-selected');
  el.removeAttribute('data-hidden-by-class');
  if (el.hasAttribute('classId')) el.removeAttribute('classId');
  if (el.hasAttribute('classid')) el.removeAttribute('classid');

  if (snapshot.classId) {
    el.setAttribute('classId', snapshot.classId);
  }

  if (snapshot.origDisplay !== null && snapshot.origDisplay !== undefined) {
    el.setAttribute('data-orig-display', snapshot.origDisplay);
  } else {
    el.removeAttribute('data-orig-display');
  }

  el.style.display = snapshot.inlineDisplay || '';
  if (snapshot.hiddenByClass) {
    el.setAttribute('data-hidden-by-class', 'true');
    el.style.display = 'none';
  }

  const restoredClassKey = String(snapshot.classId || '').trim().toLowerCase();
  if (snapshot.classId && !snapshot.hiddenByClass && CLASS_NAME_MASK_MAP[restoredClassKey]) {
    const restoredColor = CLASS_NAME_COLOR_MAP[restoredClassKey];
    if (restoredColor && window.addClassOverlay) {
      window.addClassOverlay(el, restoredColor);
    }
  }

  if (snapshot.selected) {
    el.setAttribute('data-selected', 'true');
    if (window.addSelectionOverlay) window.addSelectionOverlay(el);
  }
};

window.undoLastAnnotation = () => {
  const state = getAnnotationHistoryState();
  const entry = state.items.pop();
  if (!entry) {
    window.renderAnnotationHistory?.();
    return;
  }
  const svg = document.querySelector('.svg-clickable svg');
  if (entry.isGroup && Array.isArray(entry.entries)) {
    for (const sub of entry.entries) {
      const selector = `[data-uid="${CSS.escape(String(sub.uid || ''))}"]`;
      const el = svg?.querySelector(selector);
      if (el) restoreHistoryEntryState(el, sub.previous);
    }
    if (entry.actionType === 'class-assignment' && entry.className) {
      const undone = entry.entries.filter((s) => s && s.actionType === 'class-assignment').length;
      if (undone > 0) window.recordAnnotStat?.(entry.className, -undone);
    }
  } else {
    const selector = `[data-uid="${CSS.escape(String(entry.uid || ''))}"]`;
    const el = svg?.querySelector(selector);
    if (el) restoreHistoryEntryState(el, entry.previous);
    if (entry.actionType === 'class-assignment' && entry.className) {
      window.recordAnnotStat?.(entry.className, -1);
    }
  }
  window.renderAnnotationHistory?.();
  window.updateSelectionState?.();
  window.queueAutosave?.({reason: 'undo'});
  window.queueAnnotSaveTile?.();
};

window.setCurrentSvgExportName = (name = '') => {
  const trimmed = typeof name === 'string' ? name.trim() : '';
  const fallback = 'annotated.svg';
  if (!trimmed) {
    window.__currentSvgExportName = fallback;
    return;
  }
  const normalized = trimmed.toLowerCase().endsWith('.svg') ? trimmed : `${trimmed}.svg`;
  window.__currentSvgExportName = normalized;
};

window.serializeCurrentSvg = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return '';
  const serializer = new XMLSerializer();
  return serializer.serializeToString(svg);
};

window.serializeFullSvgForSave = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return '';
  // Temporarily restore hidden elements in the live DOM to avoid
  // an expensive cloneNode(true) on large SVGs.
  const savedViewBox = svg.getAttribute('viewBox');
  if (svg.__origViewBox) svg.setAttribute('viewBox', svg.__origViewBox);

  const hiddenByClass = svg.querySelectorAll('[data-hidden-by-class="true"]');
  const prevDisplay = [];
  hiddenByClass.forEach((el) => {
    prevDisplay.push(el.style.display);
    const orig = el.getAttribute('data-orig-display');
    el.style.display = (orig !== null) ? orig : '';
  });

  const hiddenOverlays = svg.querySelectorAll('[data-class-overlay="true"]');
  const prevOverlayDisplay = [];
  hiddenOverlays.forEach((overlay) => {
    prevOverlayDisplay.push(overlay.style.display);
    overlay.style.display = '';
  });

  // Remove selection overlays (blue highlights) before serializing
  const selectionOverlays = svg.querySelectorAll('[data-selection-overlay="true"]');
  selectionOverlays.forEach(el => el.remove());
  const selectedOverlayMarkers = svg.querySelectorAll('[data-selected-overlay="true"]');
  selectedOverlayMarkers.forEach(el => el.removeAttribute('data-selected-overlay'));

  // Detach access-path overlay layers (analysis results, sanity-check
  // markers) so they never leak into the saved SVG. We re-attach them
  // verbatim afterwards.
  const accessPathLayers = svg.querySelectorAll('g[data-access-path-layer="true"]');
  const detachedAccessLayers = [];
  accessPathLayers.forEach((layer) => {
    detachedAccessLayers.push({parent: layer.parentNode, layer});
    layer.parentNode?.removeChild(layer);
  });

  const serializer = new XMLSerializer();
  const result = serializer.serializeToString(svg);

  // Restore live DOM state — re-add selection overlays for currently selected elements
  selectedOverlayMarkers.forEach(el => window.addSelectionOverlay(el));
  detachedAccessLayers.forEach(({parent, layer}) => parent?.appendChild(layer));
  if (savedViewBox !== null) svg.setAttribute('viewBox', savedViewBox);
  else svg.removeAttribute('viewBox');
  hiddenByClass.forEach((el, i) => { el.style.display = prevDisplay[i]; });
  hiddenOverlays.forEach((overlay, i) => { overlay.style.display = prevOverlayDisplay[i]; });

  return result;
};

const formatSvgForExport = (raw) => {
  if (!raw) return raw;
  return raw
    .replace(/(<\/svg>)/g, '\n$1')
    .replace(/(<(?:path|line|polyline|polygon|rect|circle|ellipse|text|use|g|defs|clipPath|mask|symbol|image|foreignObject)\b)/g, '\n$1')
    .replace(/^\n/, '')
    .replace(/\n[ \t]*\n/g, '\n')
    .replace(/\n{2,}/g, '\n');
};

window.buildAutosaveSvgPayload = () => {
  const serializedSvg = window.serializeFullSvgForSave?.();
  if (!serializedSvg) return '';
  const sourceText = typeof window.__currentSvgSourceText === 'string' ? window.__currentSvgSourceText : '';
  const start = sourceText.search(/<svg[\s>]/i);
  const end = sourceText.toLowerCase().lastIndexOf('</svg>');
  if (start === -1 || end === -1 || end < start) {
    return formatSvgForExport(serializedSvg);
  }
  return formatSvgForExport(`${sourceText.slice(0, start)}${serializedSvg}${sourceText.slice(end + 6)}`);
};

window.queueAutosave = ({reason = 'annotation', immediate = false} = {}) => {
  // In annotation mode, tile save handles persistence — skip autosave to
  // avoid duplicate heavy POST requests that block the server and cause
  // WebSocket heartbeat timeouts ("implicit handshake failed").
  if (typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE) return;
  const state = getAutosaveState();
  state.pendingReason = reason || state.pendingReason || 'annotation';
  if (!state.pendingPromise) {
    state.pendingPromise = new Promise((resolve) => {
      state.pendingResolve = resolve;
    });
  }
  if (state.autosaveTimer) {
    window.clearTimeout(state.autosaveTimer);
    state.autosaveTimer = null;
  }
  const executeReason = state.pendingReason;
  const run = async (runReason) => {
    if (state.restoring) return;
    const lifecycle = getPageLifecycleState();
    await waitForBrowserIdle();
    if (state.restoring || lifecycle.unloading) return;
    const svgText = window.buildAutosaveSvgPayload?.();
    if (!svgText) return;
    state.saving = true;
    try {
      const res = await fetch('/autosave', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
          svg: svgText,
          file_name: window.__currentSvgExportName || 'annotated.svg',
          reason: runReason || 'annotation',
        }),
      });
      const data = await res.json();
      if (!data?.ok) {
        throw new Error(data?.error || 'Autosave failed');
      }
      if (Array.isArray(data?.items)) {
        state.items = data.items;
        window.renderAutosaveList?.();
      } else if (data?.item) {
        state.items = [data.item, ...(state.items || []).filter((item) => item?.id !== data.item.id)];
        window.renderAutosaveList?.();
      }
    } catch (error) {
      if (!lifecycle.unloading) {
        console.error('Autosave failed', error);
      }
    } finally {
      state.saving = false;
    }
  };
  const scheduleDelay = immediate ? 0 : AUTOSAVE_DEBOUNCE_MS;
  state.autosaveTimer = window.setTimeout(() => {
    state.autosaveTimer = null;
    state.pendingReason = '';
    const pendingResolve = state.pendingResolve;
    state.pendingResolve = null;
    const pendingPromise = state.pendingPromise;
    state.pendingPromise = null;
    state.savePromise = state.savePromise.then(
      () => run(executeReason),
      () => run(executeReason),
    ).finally(() => {
      if (typeof pendingResolve === 'function') pendingResolve();
    });
    return pendingPromise;
  }, scheduleDelay);
  return state.pendingPromise;
};

window.flushQueuedAutosave = async () => {
  const state = getAutosaveState();
  if (!state.autosaveTimer) return;
  const pendingReason = state.pendingReason || 'flush';
  window.clearTimeout(state.autosaveTimer);
  state.autosaveTimer = null;
  await window.queueAutosave?.({reason: pendingReason, immediate: true});
};

window.restoreAutosave = async (autosaveId) => {
  if (!autosaveId) return;
  const state = getAutosaveState();
  if (state.restoring) return;
  await window.flushQueuedAutosave?.();
  await state.savePromise;
  state.restoring = true;
  const startedAt = performance.now();
  window.openLoadingModal?.({
    title: 'Restauration autosave',
    status: 'Initialisation',
    step: 'Preparation de la restauration',
  });
  window.appendLoadingModalLog?.(`Autosave id: ${autosaveId}`);
  try {
    window.setLoadingModalStatus?.('Lecture', 'Recuperation autosave depuis le serveur');
    window.appendLoadingModalLog?.('GET /autosave/{id}');
    const res = await fetch(`/autosave/${encodeURIComponent(autosaveId)}`, {method: 'GET', cache: 'no-store'});
    window.appendLoadingModalLog?.(`HTTP status: ${res.status}`);
    const data = await res.json();
    if (!data?.ok || typeof data?.svg !== 'string') {
      throw new Error(data?.error || 'Unable to restore autosave');
    }
    window.appendLoadingModalLog?.('Autosave payload received');
    window.setLoadingModalStatus?.('Application', 'Injection du SVG et reinitialisation UI');
    window.setCurrentSvgExportName(data?.item?.base_name || 'annotated.svg');
    window.applySvgText(data.svg);
    window.setLoadingModalStatus?.('Synchronisation', 'Rafraichissement de la liste autosave');
    await window.refreshAutosaveList?.();
    window.setLoadingModalStatus?.('Termine', 'Autosave restaure');
    window.appendLoadingModalLog?.(`Autosave restored in ${formatPerfMs(performance.now() - startedAt)}`);
    window.setTimeout(() => window.closeLoadingModal?.(), 500);
  } catch (error) {
    window.setLoadingModalStatus?.('Erreur', 'Echec de restauration autosave');
    window.appendLoadingModalLog?.(`Error: ${error instanceof Error ? error.message : String(error)}`, 'error');
    console.error('Autosave restore failed', error);
  } finally {
    state.restoring = false;
  }
};

// Build the full annotated SVG content for export/save. Returns null if no SVG is loaded.
window.buildCurrentSvgContent = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return null;
  return window.buildAutosaveSvgPayload?.()
