window.startAnnotHeartbeat = () => {
  window.stopAnnotHeartbeat();
  window.__annotHeartbeatId = window.setInterval(async () => {
    try {
      const res = await fetch('/auth/heartbeat', {method: 'POST'});
      if (res.status === 401) {
        window.stopAnnotHeartbeat();
        // Try to save BEFORE showing the login modal. The cookie is now
        // invalid so the fetch will return 401 — annotSaveTile stashes the
        // payload to localStorage so it can be replayed after re-auth.
        if (window.__annotSaveTileTimer) { window.clearTimeout(window.__annotSaveTileTimer); window.__annotSaveTileTimer = null; }
        if (window._annotSaveTimer) { window.clearTimeout(window._annotSaveTimer); window._annotSaveTimer = null; }
        try { await window.annotSaveTile(); } catch (e) { console.error('Heartbeat: save failed', e); }
        window.closeLoadingModal?.();
        alert('Session expirée.\nVeuillez vous reconnecter.');
        window.showAnnotLoginModal();
      }
    } catch (_) { /* network error, retry next tick */ }
  }, 5000);
};

window.stopAnnotHeartbeat = () => {
  if (window.__annotHeartbeatId) {
    window.clearInterval(window.__annotHeartbeatId);
    window.__annotHeartbeatId = null;
  }
};

window.logoutAnnotSession = async () => {
  window.stopAnnotHeartbeat();
  // Cancel any pending debounced saves so they cannot race with our flush.
  if (window.__annotSaveTileTimer) { window.clearTimeout(window.__annotSaveTileTimer); window.__annotSaveTileTimer = null; }
  if (window._annotSaveTimer) { window.clearTimeout(window._annotSaveTimer); window._annotSaveTimer = null; }
  // Flush the current tile to disk BEFORE destroying the session — otherwise
  // the page reload below would wipe any unsaved DOM edits.
  try { await window.annotSaveTile(); } catch (e) { console.error('Logout: save failed', e); }
  try {
    await fetch('/auth/logout', { method: 'POST' });
  } catch (_) { /* ignore */ }
  window.location.reload();
};

// ── Check mode: business validation against test_pmr_basis fixtures ────────
window.__checkState = {
  fixtures: [],
  rules: [],
  current: null,           // {fixture_index, name, business}
  saveTimer: null,
  // PMR computation result for the currently displayed fixture
  pmrIncidentsByRule: {},  // rule_code → [incident, ...]
  pmrStatusByRule: {},     // rule_code → 'ok' | 'ko' (computed)
  activeRuleCode: null,
  activeIncidentIdx: null, // null = all instances, number = single instance
  expandedRules: new Set(), // rule codes whose sub-list is expanded
  // Per-fixture PMR result cache (key: fixture stem)
  pmrCache: {},            // stem → {pmrIncidentsByRule, pmrStatusByRule}
};

window.checkInit = async () => {
  if (typeof CHECK_MODE === 'undefined' || !CHECK_MODE) return;
  try {
    const res = await fetch('/check/fixtures', {cache: 'no-store'});
    const data = await res.json();
    if (!data?.ok) return;
    window.__checkState.fixtures = data.fixtures || [];
    window.__checkState.rules = data.rules || [];
  } catch (err) {
    console.error('Check: failed to load fixtures', err);
    return;
  }
  // Restore last opened fixture (server-side, fallback to localStorage, fallback to 0)
  let lastIdx = null;
  try {
    const res = await fetch('/check/last-fixture', {cache: 'no-store'});
    const data = await res.json();
    if (data?.ok && data.fixture_index !== null && data.fixture_index !== undefined) {
      lastIdx = data.fixture_index;
    }
  } catch (_) {}
  if (lastIdx === null) {
    try { const v = localStorage.getItem('check_last_fixture'); if (v !== null) lastIdx = Number(v); } catch (_) {}
  }
  if (lastIdx === null || isNaN(Number(lastIdx))) lastIdx = 0;
  await window.checkGoToFixture(Number(lastIdx));

  // Keyboard navigation: ArrowUp/ArrowDown moves between rules (and sub-items when expanded)
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
    const listEl = document.getElementById('check-rules-list');
    if (!listEl) return;
    const focused = document.activeElement;
    if (focused && (focused.tagName === 'INPUT' || focused.tagName === 'TEXTAREA')) return;
    e.preventDefault();
    const state = window.__checkState;
    const rules = state.rules || [];
    if (rules.length === 0) return;

    // Build flat navigation list: main items + sub-items for expanded rules
    const navList = [];
    for (const rule of rules) {
      navList.push({ruleCode: rule.code, incidentIdx: null});
      if (state.expandedRules.has(rule.code)) {
        const incidents = state.pmrIncidentsByRule[rule.code] || [];
        for (let i = 0; i < incidents.length; i++) {
          navList.push({ruleCode: rule.code, incidentIdx: i});
        }
      }
    }

    const curPos = navList.findIndex((item) =>
      item.ruleCode === state.activeRuleCode && item.incidentIdx === state.activeIncidentIdx
    );
    let nextPos;
    if (e.key === 'ArrowDown') {
      nextPos = curPos < navList.length - 1 ? curPos + 1 : 0;
    } else {
      nextPos = curPos > 0 ? curPos - 1 : navList.length - 1;
    }
    const next = navList[nextPos];
    window.checkSelectRule(next.ruleCode, next.incidentIdx);

    // Scroll the selected row into view
    const activeRow = listEl.querySelector('.check-rule.is-active, .check-rule-sub.is-active');
    if (activeRow) activeRow.scrollIntoView({block: 'nearest'});
  });
};

window.checkGoToFixture = async (index) => {
  if (typeof CHECK_MODE === 'undefined' || !CHECK_MODE) return;
  // Cancel any pending save before switching, then flush it inline
  if (window.__checkState.saveTimer) {
    window.clearTimeout(window.__checkState.saveTimer);
    window.__checkState.saveTimer = null;
    await window.checkSaveBusiness();
  }
  // Reset prior PMR overlays + per-fixture state when switching fixtures
  window.clearAccessPathOverlays?.('pmr-check');
  window.__checkState.pmrIncidentsByRule = {};
  window.__checkState.pmrStatusByRule = {};
  window.__checkState.activeRuleCode = null;
  window.__checkState.activeIncidentIdx = null;

  window.openLoadingModal?.({title: 'Chargement de la fixture', status: 'En cours', step: 'Récupération des métadonnées...'});
  try {
    const res = await fetch(`/check/fixture/${index}`, {cache: 'no-store'});
    if (window.handleAnnotAuthError && window.handleAnnotAuthError(res)) return;
    const data = await res.json();
    if (!data?.ok) {
      console.error('Check: load fixture failed', data?.error);
      window.setLoadingModalStatus?.('Erreur', data?.error || 'Inconnue');
      window.setTimeout(() => window.closeLoadingModal?.(), 1500);
      return;
    }
    window.__checkState.current = {
      fixture_index: data.fixture_index,
      total_fixtures: data.total_fixtures,
      name: data.name,
      stem: data.stem,
      business: data.business || {},
    };
    try { localStorage.setItem('check_last_fixture', String(data.fixture_index)); } catch (_) {}
    window.setCurrentSvgExportName?.(data.name);

    window.setLoadingModalStatus?.('En cours', `Téléchargement SVG: ${data.name}`);
    window.appendLoadingModalLog?.(`Fixture ${data.fixture_index + 1}/${data.total_fixtures}: ${data.name}`);
    const svgRes = await fetch(data.svg_url, {cache: 'no-store'});
    const svgText = await svgRes.text();
    window.appendLoadingModalLog?.(`SVG reçu (${(svgText.length / 1024).toFixed(0)} KB)`);
    window.setLoadingModalStatus?.('En cours', 'Rendu SVG...');
    window.applySvgText(svgText);

    // Reuse PMR results from (1) server-side disk cache bundled in the
    // fixture payload, then (2) in-session memory cache — no recompute.
    const applyIncidents = (incidents, source) => {
      const byRule = {};
      const statusByRule = {};
      (incidents || []).forEach((inc) => {
        const code = inc.rule_code;
        if (!byRule[code]) byRule[code] = [];
        byRule[code].push(inc);
        const cur = statusByRule[code];
        if (cur !== 'ko') {
          statusByRule[code] = (inc.status === 'ko') ? 'ko' : 'ok';
        }
      });
      window.__checkState.pmrIncidentsByRule = byRule;
      window.__checkState.pmrStatusByRule = statusByRule;
      window.__checkState.pmrCache[data.stem] = {
        pmrIncidentsByRule: byRule,
        pmrStatusByRule: statusByRule,
      };
      window.checkRenderPanel();
      window.appendLoadingModalLog?.(`PMR: résultats restaurés depuis ${source}`);
      window.setLoadingModalStatus?.('Terminé', data.name);
      window.setTimeout(() => window.closeLoadingModal?.(), 400);
    };
    if (Array.isArray(data.pmr)) {
      applyIncidents(data.pmr, 'cache serveur');
      return;
    }
    const cached = window.__checkState.pmrCache[data.stem];
    if (cached) {
      window.__checkState.pmrIncidentsByRule = cached.pmrIncidentsByRule;
      window.__checkState.pmrStatusByRule = cached.pmrStatusByRule;
      window.checkRenderPanel();
      window.appendLoadingModalLog?.('PMR: résultats restaurés depuis le cache mémoire');
      window.setLoadingModalStatus?.('Terminé', data.name);
      window.setTimeout(() => window.closeLoadingModal?.(), 400);
      return;
    }

    // No server cache: PMR results are generated by the unit tests.
    window.appendLoadingModalLog?.('PMR: aucun cache — exécutez les tests unitaires (uv run pytest -n auto tests/test_pmr_basis.py)');
    window.checkRenderPanel();
    window.setLoadingModalStatus?.('Terminé', data.name);
    window.setTimeout(() => window.closeLoadingModal?.(), 600);
  } catch (err) {
    console.error('Check: failed to load fixture', err);
    window.setLoadingModalStatus?.('Erreur', String(err?.message || err));
    window.appendLoadingModalLog?.(String(err?.message || err), 'error');
  }
};


window.checkSelectRule = (ruleCode, incidentIdx) => {
  // incidentIdx: null = all instances, number = single instance
  const idxVal = (incidentIdx !== null && incidentIdx !== undefined) ? incidentIdx : null;
  const state = window.__checkState;
  // Toggle off when clicking the already-active selection
  if (state.activeRuleCode === ruleCode && state.activeIncidentIdx === idxVal) {
    state.activeRuleCode = null;
    state.activeIncidentIdx = null;
    window.clearAccessPathOverlays?.('pmr-check');
    window.checkRenderPanel();
    window.checkUpdateCommentOverlay?.();
    return;
  }
  state.activeRuleCode = ruleCode;
  state.activeIncidentIdx = idxVal;
  window.clearAccessPathOverlays?.('pmr-check');
  const incidents = state.pmrIncidentsByRule[ruleCode] || [];
  if (incidents.length === 0) {
    window.checkRenderPanel();
    return;
  }
  const toShow = idxVal !== null ? [incidents[idxVal]].filter(Boolean) : incidents;
  const merged = {
    circles: toShow.flatMap((i) => i.circles || []),
    paths: toShow.flatMap((i) => i.paths || []),
    fills: toShow.flatMap((i) => i.fills || []),
    labels: toShow.flatMap((i) => i.labels || []),
    images: toShow.flatMap((i) => i.images || []),
    actionId: 'pmr-check',
  };
  window.renderAccessPathCircles?.(merged);
  window.checkRenderPanel();

  // Zoom to incident when a sub-item is selected; leave view unchanged for main items
  if (idxVal !== null && window.zoomToBounds) {
    const svg = document.querySelector('.svg-clickable svg');
    if (svg) {
      const overlays = svg.querySelectorAll('[data-access-path-overlay="true"][data-analysis-action="pmr-check"]');
      let xmin = Infinity, ymin = Infinity, xmax = -Infinity, ymax = -Infinity;
      overlays.forEach((el) => {
        try {
          const bb = el.getBBox();
          if (bb.width === 0 && bb.height === 0) return;
          if (bb.x < xmin) xmin = bb.x;
          if (bb.y < ymin) ymin = bb.y;
          if (bb.x + bb.width > xmax) xmax = bb.x + bb.width;
          if (bb.y + bb.height > ymax) ymax = bb.y + bb.height;
        } catch (_) {}
      });
      if (isFinite(xmin) && isFinite(ymin) && isFinite(xmax) && isFinite(ymax)) {
        window.zoomToBounds(xmin, ymin, xmax, ymax);
      }
    }
  }
};

window.checkRenderPanel = () => {
  const state = window.__checkState;
  const cur = state.current;
  const infoEl = document.getElementById('check-fixture-info');
  const listEl = document.getElementById('check-rules-list');
  if (!cur || !infoEl || !listEl) return;

  const hasPrev = cur.fixture_index > 0;
  const hasNext = cur.fixture_index < cur.total_fixtures - 1;
  infoEl.innerHTML = '';
  const prevBtn = document.createElement('button');
  prevBtn.className = 'check-nav-btn';
  prevBtn.textContent = '◀';
  prevBtn.disabled = !hasPrev;
  prevBtn.addEventListener('click', () => window.checkGoToFixture(cur.fixture_index - 1));
  const nameSpan = document.createElement('span');
  nameSpan.className = 'check-fixture-name';
  nameSpan.title = cur.name;
  nameSpan.textContent = `(${cur.fixture_index + 1}/${cur.total_fixtures}) ${cur.name}`;
  const nextBtn = document.createElement('button');
  nextBtn.className = 'check-nav-btn';
  nextBtn.textContent = '▶';
  nextBtn.disabled = !hasNext;
  nextBtn.addEventListener('click', () => window.checkGoToFixture(cur.fixture_index + 1));
  infoEl.appendChild(prevBtn);
  infoEl.appendChild(nameSpan);
  infoEl.appendChild(nextBtn);

  listEl.innerHTML = '';

  // Extract a display name from an incident.
  // Priority: 1) label with kind ending in "label"/"name"  2) inc.message  3) "Inst. N"
  const getIncidentName = (inc, idx) => {
    for (const lbl of (inc?.labels || [])) {
      const kind = lbl?.kind || '';
      if (kind.endsWith('label') || kind.endsWith('name')) {
        const t = lbl?.text || lbl?.label || '';
        if (t && typeof t === 'string') return t;
      }
    }
    if (inc?.message && typeof inc.message === 'string') {
      // Use text before first ':' if present, else truncate
      const colon = inc.message.indexOf(':');
      const short = colon > 0 ? inc.message.slice(0, colon).trim() : inc.message.slice(0, 40).trim();
      if (short) return short;
    }
    return `Inst. ${idx + 1}`;
  };

  state.rules.forEach((rule) => {
    const incidents = state.pmrIncidentsByRule[rule.code] || [];
    const computed = state.pmrStatusByRule[rule.code] || null;
    const instanceDecisions = (cur.business && cur.business[rule.code]) || {};
    const isExpanded = state.expandedRules.has(rule.code);
    const isActive = state.activeRuleCode === rule.code && state.activeIncidentIdx === null;

    // ── Main rule row (no radios — click shows all instances) ──
    const row = document.createElement('div');
    row.className = 'check-rule';
    if (isActive) row.classList.add('is-active');
    row.dataset.ruleCode = rule.code;

    // Expand/collapse toggle button
    const expandBtn = document.createElement('button');
    expandBtn.type = 'button';
    expandBtn.className = 'check-rule-expand-btn';
    expandBtn.disabled = incidents.length === 0;
    expandBtn.textContent = incidents.length === 0 ? '○' : (isExpanded ? '▼' : '▶');
    expandBtn.title = isExpanded ? 'Replier' : `Déplier — ${incidents.length} instance(s)`;
    expandBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (state.expandedRules.has(rule.code)) state.expandedRules.delete(rule.code);
      else state.expandedRules.add(rule.code);
      window.checkRenderPanel();
    });

    const codeEl = document.createElement('span');
    codeEl.className = 'check-rule-code';
    codeEl.textContent = incidents.length > 0 ? `${rule.code} (${incidents.length})` : rule.code;

    const meta = document.createElement('div');
    meta.className = 'check-rule-meta';
    const codeLine = document.createElement('div');
    codeLine.className = 'check-rule-code-line';
    codeLine.appendChild(expandBtn);
    codeLine.appendChild(codeEl);
    const titleEl = document.createElement('div');
    titleEl.className = 'check-rule-title';
    titleEl.textContent = rule.title;
    meta.appendChild(codeLine);
    meta.appendChild(titleEl);
    if (rule.description) {
      const descEl = document.createElement('div');
      descEl.className = 'check-rule-desc';
      descEl.textContent = rule.description;
      meta.appendChild(descEl);
    }
    meta.addEventListener('click', () => window.checkSelectRule(rule.code, null));

    row.appendChild(meta);
    listEl.appendChild(row);

    // ── Sub-items: one per instance, shown when expanded ──
    if (isExpanded && incidents.length > 0) {
      incidents.forEach((inc, idx) => {
        const incStatus = inc.status || 'ok';
        const bizStatus = instanceDecisions[String(idx)] || 'none';
        const isSubActive = state.activeRuleCode === rule.code && state.activeIncidentIdx === idx;

        const subRow = document.createElement('div');
        subRow.className = 'check-rule check-rule-sub';
        if (bizStatus === 'ok') subRow.classList.add('is-ok');
        else if (bizStatus === 'ko') subRow.classList.add('is-ko');
        if (isSubActive) subRow.classList.add('is-active');
        subRow.dataset.ruleCode = rule.code;
        subRow.dataset.incidentIdx = String(idx);

        // Algo badge for this instance
        const subBadge = document.createElement('span');
        subBadge.className = 'check-rule-computed';
        if (incStatus === 'ok') {
          subBadge.classList.add('is-ok'); subBadge.textContent = '✓';
          subBadge.title = 'Instance conforme';
        } else {
          subBadge.classList.add('is-ko'); subBadge.textContent = '✗';
          subBadge.title = 'Instance non conforme';
        }
        const nameEl = document.createElement('span');
        nameEl.className = 'check-rule-code';
        nameEl.textContent = getIncidentName(inc, idx);

        const subMeta = document.createElement('div');
        subMeta.className = 'check-rule-meta';
        const subLine = document.createElement('div');
        subLine.className = 'check-rule-code-line';
        subLine.appendChild(subBadge);
        subLine.appendChild(nameEl);
        subMeta.appendChild(subLine);
        subRow.addEventListener('click', () => window.checkSelectRule(rule.code, idx));

        // Business radios for this instance
        const radios = document.createElement('div');
        radios.className = 'check-rule-radios';
        ['none', 'ok', 'ko'].forEach((value) => {
          const lbl = document.createElement('label');
          const input = document.createElement('input');
          input.type = 'radio';
          input.name = `check-inst-${rule.code}-${idx}`;
          input.value = value;
          input.checked = (bizStatus === value);
          input.addEventListener('change', () => window.checkOnRuleChange(rule.code, idx, value));
          lbl.addEventListener('click', (e) => e.stopPropagation());
          lbl.appendChild(input);
          lbl.appendChild(document.createTextNode(value === 'none' ? '∅' : value.toUpperCase()));
          radios.appendChild(lbl);
        });

        // Comment button for this instance
        const instComments = ((cur.business && cur.business._comments) || {})[rule.code] || {};
        const instCommentText = instComments[String(idx)] || '';
        const commentBtn = document.createElement('button');
        commentBtn.type = 'button';
        commentBtn.className = 'check-rule-comment-btn';
        if (instCommentText) commentBtn.classList.add('has-comment');
        commentBtn.textContent = '✎';
        commentBtn.title = instCommentText ? `Commentaire : ${instCommentText}` : 'Ajouter un commentaire';
        commentBtn.addEventListener('click', (e) => { e.stopPropagation(); window.checkEditComment(rule.code, idx, commentBtn); });

        subRow.appendChild(subMeta);
        subRow.appendChild(radios);
        subRow.appendChild(commentBtn);
        listEl.appendChild(subRow);
      });
    }
  });
  window.checkUpdateCommentOverlay();
};

window.checkEditComment = (ruleCode, incidentIdx, anchorEl) => {
  const cur = window.__checkState.current;
  if (!cur) return;

  // Remove any existing inline comment editor
  document.getElementById('check-comment-editor')?.remove();

  if (!cur.business._comments || typeof cur.business._comments !== 'object') {
    cur.business._comments = {};
  }
  if (!cur.business._comments[ruleCode] || typeof cur.business._comments[ruleCode] !== 'object') {
    cur.business._comments[ruleCode] = {};
  }
  const idxStr = String(incidentIdx);
  const current = cur.business._comments[ruleCode][idxStr] || '';

  // Build inline editor anchored below the button
  const editor = document.createElement('div');
  editor.id = 'check-comment-editor';
  editor.className = 'check-comment-editor';

  const input = document.createElement('input');
  input.type = 'text';
  input.value = current;
  input.placeholder = 'Commentaire…';
  input.className = 'check-comment-editor-input';

  const saveComment = () => {
    editor.remove();
    const trimmed = input.value.trim();
    if (trimmed) {
      cur.business._comments[ruleCode][idxStr] = trimmed;
    } else {
      delete cur.business._comments[ruleCode][idxStr];
      if (Object.keys(cur.business._comments[ruleCode]).length === 0) {
        delete cur.business._comments[ruleCode];
      }
    }
    if (window.__checkState.saveTimer) window.clearTimeout(window.__checkState.saveTimer);
    window.__checkState.saveTimer = window.setTimeout(() => {
      window.__checkState.saveTimer = null;
      window.checkSaveBusiness();
    }, 600);
    const stateEl = document.getElementById('check-save-state');
    if (stateEl) stateEl.textContent = '...';
    window.checkRenderPanel();
  };

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); saveComment(); }
    if (e.key === 'Escape') { editor.remove(); }
    e.stopPropagation();
  });
  input.addEventListener('blur', () => saveComment());
  input.addEventListener('click', (e) => e.stopPropagation());

  editor.appendChild(input);

  // Position below the anchor button
  if (anchorEl) {
    anchorEl.parentElement.appendChild(editor);
  } else {
    document.body.appendChild(editor);
  }
  input.focus();
  input.select();
};

window.checkUpdateCommentOverlay = () => {
  const state = window.__checkState;
  const cur = state && state.current;
  const svgContainer = document.querySelector('.svg-clickable');
  if (!svgContainer) return;
  let overlay = document.getElementById('check-comment-overlay');
  const activeCode = state && state.activeRuleCode;
  const activeIdx = state && state.activeIncidentIdx;
  const ruleComments = ((cur && cur.business && cur.business._comments) || {})[activeCode] || {};
  const text = (activeCode !== null && activeIdx !== null) ? (ruleComments[String(activeIdx)] || '') : '';
  if (!text) {
    if (overlay) overlay.remove();
    return;
  }
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'check-comment-overlay';
    overlay.className = 'check-comment-overlay';
    svgContainer.appendChild(overlay);
  }
  overlay.innerHTML = '';
  const codeEl = document.createElement('div');
  codeEl.className = 'check-comment-overlay-code';
  codeEl.textContent = 'commentaire :';
  const textEl = document.createElement('div');
  textEl.className = 'check-comment-overlay-text';
  textEl.textContent = text;
  overlay.appendChild(codeEl);
  overlay.appendChild(textEl);
};

window.checkOnRuleChange = (ruleCode, incidentIdx, status) => {
  const cur = window.__checkState.current;
  if (!cur) return;
  if (!cur.business[ruleCode] || typeof cur.business[ruleCode] !== 'object') {
    cur.business[ruleCode] = {};
  }
  cur.business[ruleCode][String(incidentIdx)] = status;
  // Update sub-row visual state
  const subRow = document.querySelector(
    `.check-rule-sub[data-rule-code="${CSS.escape(ruleCode)}"][data-incident-idx="${incidentIdx}"]`
  );
  if (subRow) {
    subRow.classList.remove('is-ok', 'is-ko');
    if (status === 'ok') subRow.classList.add('is-ok');
    else if (status === 'ko') subRow.classList.add('is-ko');
  }
  // Debounced save
  if (window.__checkState.saveTimer) window.clearTimeout(window.__checkState.saveTimer);
  window.__checkState.saveTimer = window.setTimeout(() => {
    window.__checkState.saveTimer = null;
    window.checkSaveBusiness();
  }, 600);
  const stateEl = document.getElementById('check-save-state');
  if (stateEl) stateEl.textContent = '...';
};

window.checkSaveBusiness = async () => {
  const cur = window.__checkState.current;
  if (!cur) return;
  const stateEl = document.getElementById('check-save-state');
  try {
    const res = await fetch(`/check/fixture/${cur.fixture_index}/business`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({business: cur.business}),
    });
    const data = await res.json();
    if (stateEl) stateEl.textContent = data?.ok ? 'sauvegardé' : 'erreur';
  } catch (err) {
    console.error('Check: save failed', err);
    if (stateEl) stateEl.textContent = 'erreur';
  }
};

// ── Performance (F1) modal ─────────────────────────────────────────────────

window._ensureCheckModal = () => {
  let modal = document.getElementById('check-perf-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'check-perf-modal';
    modal.className = 'check-perf-modal';
    modal.addEventListener('click', (e) => {
      if (e.target === modal) modal.remove();
    });
    document.body.appendChild(modal);
  }
  return modal;
};

// Flush any pending debounced business save before reading F1 stats.
window._flushPendingCheckSave = async () => {
  if (window.__checkState.saveTimer) {
    window.clearTimeout(window.__checkState.saveTimer);
    window.__checkState.saveTimer = null;
    await window.checkSaveBusiness();
  }
};

window.openCheckRules = async () => {
  if (typeof CHECK_MODE === 'undefined' || !CHECK_MODE) return;
  await window._flushPendingCheckSave();
  const modal = window._ensureCheckModal();
  window._renderPerfLoading(modal, 'Chargement…');
  try {
    const res = await fetch('/check/rules');
    const data = await res.json();
    window.renderCheckRules(modal, data);
  } catch (err) {
    window._renderPerfError(modal, err);
    console.error('Rules load failed', err);
  }
};


window._renderPerfError = (modal, err) => {
  modal.innerHTML = '';
  const panel = document.createElement('div');
  panel.className = 'check-perf-panel';
  const body = document.createElement('div');
  body.className = 'check-perf-body check-perf-empty';
  const title = document.createElement('div');
  title.style.fontWeight = '600';
  title.style.color = '#b91c1c';
  title.textContent = 'Erreur de calcul';
  const detail = document.createElement('div');
  detail.style.marginTop = '8px';
  detail.style.fontSize = '12px';
  detail.style.color = '#475569';
  detail.style.whiteSpace = 'pre-wrap';
  detail.textContent = String(err?.message || err || 'inconnue');
  const close = document.createElement('button');
  close.className = 'check-perf-btn';
  close.style.marginTop = '14px';
  close.textContent = 'Fermer';
  close.addEventListener('click', () => modal.remove());
  body.appendChild(title);
  body.appendChild(detail);
  body.appendChild(close);
  panel.appendChild(body);
  modal.appendChild(panel);
};

window._renderPerfLoading = (modal, message) => {
  modal.innerHTML = '';
  const panel = document.createElement('div');
  panel.className = 'check-perf-panel';
  const body = document.createElement('div');
  body.className = 'check-perf-body check-perf-empty';
  const spinner = document.createElement('div');
  spinner.className = 'check-perf-spinner';
  const label = document.createElement('div');
  label.style.marginTop = '10px';
  label.textContent = message || 'Chargement…';
  body.appendChild(spinner);
  body.appendChild(label);
  panel.appendChild(body);
  modal.appendChild(panel);
};



// ── Rules panel (per-rule F1 stats) ────────────────────────────────────────
window.renderCheckRules = (modal, data) => {
  if (!modal) return;
  const rules = Array.isArray(data?.rules) ? data.rules : [];
  const fixturesCount = data?.fixtures_count || 0;
  const computedAt = data?.computed_at || null;
  const panel = document.createElement('div');
  panel.className = 'check-perf-panel';

  const header = document.createElement('div');
  header.className = 'check-perf-header';
  const title = document.createElement('div');
  title.className = 'check-perf-title';
  const titleText = document.createElement('span');
  titleText.textContent = 'performance par règle';
  title.appendChild(titleText);
  const svgCount = document.createElement('span');
  svgCount.className = 'check-perf-svg-count';
  svgCount.textContent = `${fixturesCount} SVG`;
  title.appendChild(svgCount);
  if (computedAt) {
    const stamp = document.createElement('span');
    stamp.className = 'check-perf-svg-count';
    try {
      const d = new Date(computedAt);
      stamp.textContent = d.toLocaleString();
    } catch (_) {
      stamp.textContent = computedAt;
    }
    title.appendChild(stamp);
  }
  const actions = document.createElement('div');
  actions.className = 'check-perf-actions';
  const closeBtn = document.createElement('button');
  closeBtn.className = 'check-perf-btn';
  closeBtn.textContent = 'Fermer';
  closeBtn.addEventListener('click', () => modal.remove());
  actions.appendChild(closeBtn);
  header.appendChild(title);
  header.appendChild(actions);
  panel.appendChild(header);

  const body = document.createElement('div');
  body.className = 'check-perf-body check-rules-body';

  if (rules.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'check-perf-empty';
    empty.textContent = 'Aucune règle disponible.';
    body.appendChild(empty);
  } else {
    const headerRow = document.createElement('div');
    headerRow.className = 'check-rules-row is-header';
    ['Code', 'Règle', 'Catégorie', 'Total', 'Exemples', 'TP', 'TN', 'FP', 'FN'].forEach((label, idx) => {
      const cell = document.createElement('div');
      cell.textContent = label;
      if (idx >= 3) cell.className = 'check-perf-num';
      if (idx === 3) cell.title = 'Nombre total d\'incidents (sans filtre métier)';
      if (idx === 4) cell.title = 'Incidents avec annotation métier ok/ko';
      headerRow.appendChild(cell);
    });
    body.appendChild(headerRow);

    const makeCountCell = (value, {fnAlert, missing} = {}) => {
      const cell = document.createElement('div');
      cell.className = 'check-perf-num';
      if (value === null || value === undefined) {
        cell.textContent = '—';
        cell.classList.add('is-na');
      } else {
        cell.textContent = String(value);
        if (fnAlert && value > 0) cell.classList.add('check-perf-fn-alert');
        if (missing) cell.classList.add('check-perf-missing');
      }
      return cell;
    };

    rules.forEach((r) => {
      const row = document.createElement('div');
      row.className = 'check-rules-row';

      const codeCell = document.createElement('div');
      codeCell.className = 'check-perf-short';
      codeCell.textContent = r.code;

      const titleCell = document.createElement('div');
      titleCell.className = 'check-rules-title-cell';
      const tTitle = document.createElement('div');
      tTitle.className = 'check-rules-rule-title';
      tTitle.textContent = r.title || r.code;
      titleCell.appendChild(tTitle);
      if (r.description) {
        const desc = document.createElement('div');
        desc.className = 'check-rules-rule-desc';
        desc.textContent = r.description;
        titleCell.appendChild(desc);
      }

      const catCell = document.createElement('div');
      catCell.className = 'check-rules-cat';
      catCell.textContent = r.category || '—';

      const totalCell = document.createElement('div');
      totalCell.className = 'check-perf-num';
      totalCell.textContent = String(r.total || 0);
      totalCell.title = 'Incidents totaux (sans filtre métier)';

      const countCell = document.createElement('div');
      countCell.className = 'check-perf-num';
      countCell.textContent = String(r.count || 0);
      countCell.title = 'Incidents avec annotation métier ok/ko';

      const tp = r.tp || 0, tn = r.tn || 0, fp = r.fp || 0, fn = r.fn || 0;

      row.appendChild(codeCell);
      row.appendChild(titleCell);
      row.appendChild(catCell);
      row.appendChild(totalCell);
      row.appendChild(countCell);
      row.appendChild(makeCountCell(tp, {missing: tp === 0}));
      row.appendChild(makeCountCell(tn, {missing: tn === 0}));
      row.appendChild(makeCountCell(fp, {missing: fp > 0}));
      row.appendChild(makeCountCell(fn, {fnAlert: true}));
      body.appendChild(row);
    });
  }
  panel.appendChild(body);

  modal.innerHTML = '';
  modal.appendChild(panel);
};

window.initAppUiAfterAuth = async () => {
  // Verify auth server-side to prevent console bypass
  if (typeof AUTH_REQUIRED !== 'undefined' && AUTH_REQUIRED && !window._annotAuthenticated) {
    try {
      const res = await fetch('/auth/check');
      const data = await res.json();
      if (!data.authenticated) return;
    } catch (_) { return; }
    window._annotAuthenticated = true;
  }
  // Remove blur and restore interaction after successful auth
  [
    document.getElementById('floating-toolbar-container'),
    document.getElementById('floating-class-toolbar'),
    document.getElementById('floating-annotation-toolbar'),

    document.querySelector('.svg-clickable'),
  ].forEach(el => {
    if (!el) return;
    el.style.removeProperty('filter');
    el.style.removeProperty('pointer-events');
    el.style.removeProperty('user-select');
  });
  window.initFloatingPalette?.();
  window.initFloatingAnnotationToolbar?.();
  window.initFloatingAutosaveToolbar?.();
  window.initFloatingPmrToolbar?.();
  window.initZoomPan?.();
  window.setToolbarState?.(!!document.querySelector('.svg-clickable svg'));
  window.updateSelectionState?.();
  window.renderAnnotationHistory?.();
  window.refreshAutosaveList?.();
  if (typeof AUTH_REQUIRED !== 'undefined' && AUTH_REQUIRED) {
    window.startAnnotHeartbeat();
  }
  if (typeof ANNOT_MODE !== 'undefined' && ANNOT_MODE) {
    // One-shot migration of pre-namespaced localStorage keys. Without
    // this, an upgrade-in-place would lose annotators' last-tile
    // pointer and any pending recovery save the first time they reload.
    window.__annotMigrateKey?.('annot_last_tile');
    window.__annotMigrateKey?.('annot_pending_save');

    // Recovery: replay any tile save that didn't reach the server before
    // the previous reload (auth expiry, network error, manual reload).
    // This must run BEFORE loading any tile, otherwise applySvgText would
    // overwrite the recovered DOM with the server's stale copy.
    try {
      const pending = localStorage.getItem(window.__ANNOT_PENDING_SAVE_KEY);
      if (pending) {
        const {tile_name, svg_text, ts, reason} = JSON.parse(pending);
        if (tile_name && svg_text) {
          console.warn(`[annot] Recovering pending save (${reason}, ${Math.round((Date.now() - ts) / 1000)}s ago): ${tile_name}`);
          const res = await fetch(`/annotation/save?tile_name=${encodeURIComponent(tile_name)}`, {
            method: 'POST',
            headers: {'Content-Type': 'text/plain; charset=utf-8'},
            body: svg_text,
          });
          if (res.ok) {
            localStorage.removeItem(window.__ANNOT_PENDING_SAVE_KEY);
            console.log('[annot] Recovery save OK');
          } else if (res.status === 409) {
            // Poison payload: SVG identity doesn't match the target tile.
            // Replaying it on every reload would 409 forever and prevent
            // the user from making progress, so drop it and log loudly.
            let detail = '';
            try { detail = JSON.stringify(await res.json()); } catch (_) {}
            console.error(`[annot] Recovery save REJECTED 409 (mismatch) for ${tile_name} — discarding poison payload: ${detail}`);
            localStorage.removeItem(window.__ANNOT_PENDING_SAVE_KEY);
          } else {
            console.error('[annot] Recovery save HTTP error', res.status);
          }
        }
      }
    } catch (e) { console.error('[annot] Recovery save failed', e); }

    // Restore last tile from server-side persistence, fallback to localStorage
    let lastTile = null;
    try {
      const res = await fetch('/annotation/last-tile', {cache: 'no-store'});
      const data = await res.json();
      if (data?.ok && data.tile_index !== null && data.tile_index !== undefined) {
        lastTile = data.tile_index;
      }
    } catch (_) {}
    if (lastTile === null) {
      try { const v = localStorage.getItem(window.__annotStorageKey('annot_last_tile')); if (v !== null) lastTile = Number(v); } catch (_) {}
    }
    if (lastTile !== null && !isNaN(Number(lastTile))) {
      window.annotGoToTile(Number(lastTile));
    } else {
      window.annotLoadCurrentTile();
    }
  }
  if (typeof CHECK_MODE !== 'undefined' && CHECK_MODE) {
    window.checkInit();
  }
};

window.initAppUi = async () => {
  const authRequired = typeof AUTH_REQUIRED !== 'undefined' && AUTH_REQUIRED;
  if (authRequired) {
    // Apply heavy blur + disable interaction on all UI content until authenticated
    const _authBlurTargets = [
      document.getElementById('floating-toolbar-container'),
      document.getElementById('floating-class-toolbar'),
      document.getElementById('floating-annotation-toolbar'),

      document.querySelector('.svg-clickable'),
    ];
    _authBlurTargets.forEach(el => {
      if (!el) return;
      el.style.setProperty('filter', 'blur(20px)');
      el.style.setProperty('pointer-events', 'none');
      el.style.setProperty('user-select', 'none');
    });
    try {
      const res = await fetch('/auth/check');
      const data = await res.json();
      if (data.authenticated) {
        window._annotAuthenticated = true;
        window.initAppUiAfterAuth();
        return;
      }
    } catch (_) { /* needs login */ }
    window.showAnnotLoginModal();
    return;
  }
  window.initAppUiAfterAuth();
};

