window.runPmrCheck = async () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg || _pmrState.running) return;

  _pmrState.running = true;
  _pmrState.incidents = [];
  _pmrState.activeIndex = -1;

  // Show progress
  const progress = document.getElementById('pmr-progress');
  const progressText = document.getElementById('pmr-progress-text');
  const summary = document.getElementById('pmr-summary');
  const list = document.getElementById('pmr-incident-list');
  if (progress) progress.style.display = '';
  if (progressText) progressText.textContent = 'Analyse en cours...';
  if (summary) summary.style.display = 'none';
  if (list) list.innerHTML = '';

  // Clear any existing PMR overlays
  window.clearAccessPathOverlays?.('pmr-check');

  const serializer = new XMLSerializer();
  const svgText = serializer.serializeToString(svg);

  try {
    const res = await fetch('/pmr-check', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({svg: svgText}),
    });
    const data = await res.json();

    if (data?.ok) {
      _pmrState.rules = data.rules || [];
      _pmrState.incidents = data.incidents || [];
      window.renderPmrIncidents();
    } else {
      if (list) list.innerHTML = '<div class="pmr-empty">Erreur: ' + (data?.error || 'inconnue') + '</div>';
    }
  } catch (err) {
    console.error('PMR check failed', err);
    if (list) list.innerHTML = '<div class="pmr-empty">Erreur réseau</div>';
  } finally {
    _pmrState.running = false;
    if (progress) progress.style.display = 'none';
  }
};

window.renderPmrIncidents = () => {
  const list = document.getElementById('pmr-incident-list');
  const summary = document.getElementById('pmr-summary');
  if (!list) return;

  const incidents = _pmrState.incidents;

  // Summary
  if (summary) {
    summary.style.display = '';
    const koCount = incidents.filter(i => i.status !== 'ok').length;
    const okCount = incidents.filter(i => i.status === 'ok').length;
    if (koCount === 0) {
      summary.className = 'pmr-summary pmr-all-ok';
      summary.textContent = `${okCount} règle(s) conforme(s) ✓`;
    } else {
      summary.className = 'pmr-summary pmr-has-issues';
      summary.textContent = `${koCount} non-conformité(s), ${okCount} conforme(s)`;
    }
  }

  // Incident list
  list.innerHTML = '';
  if (incidents.length === 0) {
    return;
  }

  incidents.forEach((incident, idx) => {
    const item = document.createElement('div');
    item.className = 'pmr-incident' + (idx === _pmrState.activeIndex ? ' pmr-active' : '');
    item.addEventListener('click', () => window.selectPmrIncident(idx));

    const isOk = incident.status === 'ok';
    const status = document.createElement('div');
    status.className = 'pmr-incident-status ' + (isOk ? 'pmr-pass' : 'pmr-fail');
    status.textContent = isOk ? '\u2713' : '\u2717';

    const text = document.createElement('div');
    text.className = 'pmr-incident-text';

    const msg = document.createElement('div');
    msg.className = 'pmr-incident-message';
    msg.textContent = incident.message;

    const ruleCode = document.createElement('div');
    ruleCode.className = 'pmr-incident-rule';
    ruleCode.textContent = incident.rule_code + ' - ' + incident.rule_title;

    const ruleData = (_pmrState.rules || []).find((r) => r.code === incident.rule_code);
    const ruleDesc = document.createElement('div');
    ruleDesc.className = 'pmr-incident-desc';
    ruleDesc.textContent = ruleData?.description || '';

    text.appendChild(msg);
    text.appendChild(ruleCode);
    text.appendChild(ruleDesc);
    item.appendChild(status);
    item.appendChild(text);
    list.appendChild(item);
  });
};

window.selectPmrIncident = (idx) => {
  const incidents = _pmrState.incidents;
  if (idx < 0 || idx >= incidents.length) return;

  // Toggle: clicking same incident again deselects
  if (_pmrState.activeIndex === idx) {
    _pmrState.activeIndex = -1;
    window.clearAccessPathOverlays?.('pmr-check');
    window.renderPmrIncidents();
    return;
  }

  _pmrState.activeIndex = idx;
  const incident = incidents[idx];

  // Render this incident's overlays
  window.renderAccessPathCircles?.({
    circles: incident.circles || [],
    paths: incident.paths || [],
    fills: incident.fills || [],
    labels: incident.labels || [],
    images: incident.images || [],
    actionId: 'pmr-check',
  });

  window.renderPmrIncidents();
};

window.initZoomPan = () => {
  const mainSvg = document.querySelector('.svg-clickable svg');
  if (!mainSvg) return;
  mainSvg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  const currentViewBox = getSvgViewBox(mainSvg);
  if (!currentViewBox) return;
  if (!mainSvg.__origViewBox) {
    mainSvg.__origViewBox = currentViewBox.raw;
  }
  const origViewBox = parseViewBoxRaw(mainSvg.__origViewBox) || currentViewBox;
  const {x: vx, y: vy, width: vw, height: vh} = origViewBox;
  const marginRatio = 0.25;
  const mx = vw * marginRatio;
  const my = vh * marginRatio;
  const bx = vx - mx;
  const by = vy - my;
  const bw = vw + 2 * mx;
  const bh = vh + 2 * my;
  mainSvg.setAttribute('viewBox', `${bx} ${by} ${bw} ${bh}`);

  const targetAspect = 16 / 10;
  const minRatio = 0.01;
  const maxRatio = 1.0;
  const fitAspect = (maxW, maxH) => {
    if (maxW / maxH > targetAspect) {
      const h = maxH;
      return {w: h * targetAspect, h};
    }
    const w = maxW;
    return {w, h: w / targetAspect};
  };
  let winW = bw;
  let winH = bh;
  let zoomRatio = 1;
  let viewX = bx;
  let viewY = by;

  const updateMainView = () => {
    mainSvg.setAttribute('viewBox', `${viewX} ${viewY} ${winW} ${winH}`);
  };

  const resetZoom = () => {
    zoomRatio = 1;
    winW = bw;
    winH = bh;
    viewX = bx;
    viewY = by;
    updateMainView();
  };
  window.resetZoom = resetZoom;

  window.zoomToPoint = (cx, cy, targetRatio = 0.15) => {
    const fittedSize = fitAspect(bw * targetRatio, bh * targetRatio);
    zoomRatio = targetRatio;
    winW = fittedSize.w;
    winH = fittedSize.h;
    viewX = Math.max(bx, Math.min(bx + bw - winW, cx - winW / 2));
    viewY = Math.max(by, Math.min(by + bh - winH, cy - winH / 2));
    updateMainView();
  };

  window.zoomToBounds = (xmin, ymin, xmax, ymax, padding = 0.15) => {
    const pw = Math.max(1e-9, xmax - xmin);
    const ph = Math.max(1e-9, ymax - ymin);
    const wantW = pw * (1 + 2 * padding);
    const wantH = ph * (1 + 2 * padding);
    const B = targetAspect;
    const needWinW = Math.max(wantW, wantH * B);
    const needWinH = needWinW / B;
    let ratio = Math.max(needWinW / bw, needWinH / bh);
    ratio = Math.min(maxRatio, Math.max(minRatio, ratio));
    const fittedSize = fitAspect(bw * ratio, bh * ratio);
    zoomRatio = ratio;
    winW = fittedSize.w;
    winH = fittedSize.h;
    const cx = (xmin + xmax) / 2;
    const cy = (ymin + ymax) / 2;
    viewX = Math.max(bx, Math.min(bx + bw - winW, cx - winW / 2));
    viewY = Math.max(by, Math.min(by + bh - winH, cy - winH / 2));
    updateMainView();
  };

  const setWindowSize = (ratio, anchor = null) => {
    zoomRatio = Math.min(maxRatio, Math.max(minRatio, ratio));
    const fittedSize = fitAspect(bw * zoomRatio, bh * zoomRatio);
    const oldW = winW;
    const oldH = winH;
    winW = fittedSize.w;
    winH = fittedSize.h;
    if (Number.isFinite(anchor?.x) && Number.isFinite(anchor?.y)) {
      const relX = oldW > 1e-9 ? (anchor.x - viewX) / oldW : 0.5;
      const relY = oldH > 1e-9 ? (anchor.y - viewY) / oldH : 0.5;
      viewX = anchor.x - (relX * winW);
      viewY = anchor.y - (relY * winH);
    } else {
      const centerX = viewX + (oldW / 2);
      const centerY = viewY + (oldH / 2);
      viewX = centerX - (winW / 2);
      viewY = centerY - (winH / 2);
    }
    viewX = Math.max(bx, Math.min(bx + bw - winW, viewX));
    viewY = Math.max(by, Math.min(by + bh - winH, viewY));
    updateMainView();
  };

  const toMainSvgPoint = (evt) => {
    const pt = mainSvg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    const ctm = mainSvg.getScreenCTM();
    if (!ctm) return {x: vx, y: vy};
    const p = pt.matrixTransform(ctm.inverse());
    return {x: p.x, y: p.y};
  };

  // Ctrl/Cmd+Wheel zoom on main SVG
  const onMainWheel = (e) => {
    if (!isCtrlOrCmd(e)) return;
    e.preventDefault();
    const factor = e.deltaY > 0 ? 1.08 : 1 / 1.08;
    setWindowSize(zoomRatio * factor, toMainSvgPoint(e));
  };
  if (mainSvg.__ctrlWheelZoomHandler) {
    mainSvg.removeEventListener('wheel', mainSvg.__ctrlWheelZoomHandler);
  }
  mainSvg.__ctrlWheelZoomHandler = onMainWheel;
  mainSvg.addEventListener('wheel', onMainWheel, {passive: false});

  // Ctrl/Cmd+Drag / Shift+Drag pan on main SVG
  if (window.__mainShiftPanCleanup) {
    window.__mainShiftPanCleanup();
    window.__mainShiftPanCleanup = null;
  }
  const shiftPanState = {
    shiftDown: false,
    ctrlDown: false,
    dragging: false,
    clientStartX: 0,
    clientStartY: 0,
    startViewX: 0,
    startViewY: 0,
    pxToSvgX: 1,
    pxToSvgY: 1,
  };
  const isPanModifierActive = () => shiftPanState.shiftDown || shiftPanState.ctrlDown;
  const updateMainPanCursor = () => {
    if (shiftPanState.dragging) {
      mainSvg.style.cursor = 'grabbing';
      return;
    }
    if (isPanModifierActive()) {
      mainSvg.style.cursor = 'grab';
      return;
    }
    mainSvg.style.cursor = '';
  };
  const onShiftKeyDown = (evt) => {
    if (evt.key === 'Shift') shiftPanState.shiftDown = true;
    else if (evt.key === PAN_MOD_KEY) shiftPanState.ctrlDown = true;
    else return;
    updateMainPanCursor();
  };
  const onShiftKeyUp = (evt) => {
    if (evt.key === 'Shift') shiftPanState.shiftDown = false;
    else if (evt.key === PAN_MOD_KEY) shiftPanState.ctrlDown = false;
    else return;
    updateMainPanCursor();
  };
  const onWindowBlur = () => {
    shiftPanState.shiftDown = false;
    shiftPanState.ctrlDown = false;
    if (shiftPanState.dragging) {
      shiftPanState.dragging = false;
      window.removeEventListener('mousemove', onMainPanMove);
      window.removeEventListener('mouseup', onMainPanUp);
    }
    updateMainPanCursor();
  };
  const onMainPanMove = (evt) => {
    if (!shiftPanState.dragging) return;
    const dxPx = evt.clientX - shiftPanState.clientStartX;
    const dyPx = evt.clientY - shiftPanState.clientStartY;
    viewX = shiftPanState.startViewX - dxPx * shiftPanState.pxToSvgX;
    viewY = shiftPanState.startViewY - dyPx * shiftPanState.pxToSvgY;
    viewX = Math.max(bx, Math.min(bx + bw - winW, viewX));
    viewY = Math.max(by, Math.min(by + bh - winH, viewY));
    updateMainView();
  };
  const onMainPanUp = () => {
    if (!shiftPanState.dragging) return;
    shiftPanState.dragging = false;
    mainSvg.__panSuppressClickUntil = performance.now() + 250;
    window.removeEventListener('mousemove', onMainPanMove);
    window.removeEventListener('mouseup', onMainPanUp);
    updateMainPanCursor();
  };
  const onMainPanDown = (evt) => {
    if (!evt.shiftKey && !isCtrlOrCmd(evt)) return;
    evt.preventDefault();
    evt.stopPropagation();
    shiftPanState.dragging = true;
    if (evt.shiftKey) shiftPanState.shiftDown = true;
    if (isCtrlOrCmd(evt)) shiftPanState.ctrlDown = true;
    shiftPanState.clientStartX = evt.clientX;
    shiftPanState.clientStartY = evt.clientY;
    shiftPanState.startViewX = viewX;
    shiftPanState.startViewY = viewY;
    const svgRect = mainSvg.getBoundingClientRect();
    shiftPanState.pxToSvgX = svgRect.width > 0 ? winW / svgRect.width : 1;
    shiftPanState.pxToSvgY = svgRect.height > 0 ? winH / svgRect.height : 1;
    window.addEventListener('mousemove', onMainPanMove);
    window.addEventListener('mouseup', onMainPanUp);
    updateMainPanCursor();
  };
  mainSvg.addEventListener('mousedown', onMainPanDown);
  window.addEventListener('keydown', onShiftKeyDown);
  window.addEventListener('keyup', onShiftKeyUp);
  window.addEventListener('blur', onWindowBlur);
  window.__mainShiftPanCleanup = () => {
    window.removeEventListener('keydown', onShiftKeyDown);
    window.removeEventListener('keyup', onShiftKeyUp);
    window.removeEventListener('blur', onWindowBlur);
    window.removeEventListener('mousemove', onMainPanMove);
    window.removeEventListener('mouseup', onMainPanUp);
    mainSvg.removeEventListener('mousedown', onMainPanDown);
    mainSvg.style.cursor = '';
  };
};

// Affectation des classes (classId) : identifiant stable pour synchroniser la vue globale
window.assignSvgUids = () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const elements = svg.querySelectorAll('path,line,polyline,polygon,rect,circle,ellipse,text');
  // Collect already-used UIDs to avoid duplicates after save/reload cycles
  const usedUids = new Set();
  elements.forEach((el) => {
    if (el.getAttribute('data-class-overlay') === 'true') return;
    const existing = (el.getAttribute('data-uid') || '').trim();
    if (existing) usedUids.add(existing);
  });
  let nextUid = 1;
  elements.forEach((el) => {
    if (el.getAttribute('data-class-overlay') === 'true') return;
    if (!el.getAttribute('data-uid')) {
      while (usedUids.has(String(nextUid))) nextUid++;
      el.setAttribute('data-uid', String(nextUid));
      usedUids.add(String(nextUid));
      nextUid++;
    }
  });
  // Link baked-in overlays (from tile generation) to their now-assigned data-uid
  svg.querySelectorAll('[data-class-overlay="true"]').forEach((overlay) => {
    const forUid = (overlay.getAttribute('data-class-overlay-for') || '').trim();
    if (forUid) return; // already linked
    const prev = overlay.previousElementSibling;
    if (prev && prev.getAttribute('data-uid')) {
      overlay.setAttribute('data-class-overlay-for', prev.getAttribute('data-uid'));
    }
  });
};

// Edition visibilité des classes (checkbox)
window.updateGlobalCategoryVisibilityCheckbox = () => {
  const globalCheckbox = document.getElementById('tool-checkbox-all-classes');
  if (!(globalCheckbox instanceof HTMLInputElement)) return;
  const checkboxes = Array.from(document.querySelectorAll('.tool-checkbox[data-class-id]'));
  if (!checkboxes.length) {
    globalCheckbox.checked = true;
    globalCheckbox.indeterminate = false;
    return;
  }
  const checkedCount = checkboxes.filter((checkbox) => checkbox.checked).length;
  globalCheckbox.checked = checkedCount === checkboxes.length;
  globalCheckbox.indeterminate = checkedCount > 0 && checkedCount < checkboxes.length;
};

const buildClassOverlayIndex = (svg) => {
  const index = new Map();
  if (!svg) return index;
  svg.querySelectorAll('[data-class-overlay-for]').forEach((overlay) => {
    const uid = String(overlay.getAttribute('data-class-overlay-for') || '').trim();
    if (uid) index.set(uid, overlay);
  });
  return index;
};

const PRIMITIVE_SELECTOR = 'path,line,polyline,polygon,rect,circle,ellipse,text,use';

const collectPrimitiveTargetsForClass = (svg, classId) => {
  const targets = new Set();
  if (!svg || !classId) return targets;
  const classNodes = svg.querySelectorAll('[classId],[classid]');
  classNodes.forEach((node) => {
    // Skip overlays — they are controlled via their primitive's data-uid lookup
    if (node.hasAttribute('data-class-overlay-for')) return;
    const value = String(node.getAttribute('classId') || node.getAttribute('classid') || '').trim().toLowerCase();
    if (value !== classId) return;
    const tag = (node.tagName || '').toLowerCase();
    if (tag && ['path', 'line', 'polyline', 'polygon', 'rect', 'circle', 'ellipse', 'text', 'use'].includes(tag)) {
      targets.add(node);
    }
    node.querySelectorAll(PRIMITIVE_SELECTOR).forEach((el) => targets.add(el));
  });
  return targets;
};

window.toggleCategoryVisibility = async (checkbox) => {
  const classId = (checkbox?.dataset?.classId || '').trim().toLowerCase();
  if (!classId) return;
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const visible = !!checkbox.checked;
  await withBusyGuard('Visibilite', `${visible ? 'Afficher' : 'Masquer'} ${classId}`, async () => {
    const startedAt = performance.now();
    const visibilityState = getClassVisibilityState();
    const epoch = visibilityState.epoch + 1;
    visibilityState.epoch = epoch;
    const targets = collectPrimitiveTargetsForClass(svg, classId);
    const overlayIndex = buildClassOverlayIndex(svg);
    let changedCount = 0;
    const targetList = Array.from(targets);
    window.appendLoadingModalLog?.(`Classe: ${classId}`);
    window.appendLoadingModalLog?.(`Elements concernes: ${targetList.length}`);
    const completed = await processInAnimationBatches(targetList, (el) => {
      if (!visible) {
        if (el.getAttribute('data-hidden-by-class') !== 'true') {
          if (!el.hasAttribute('data-orig-display')) {
            el.setAttribute('data-orig-display', el.style.display || '');
          }
          el.style.display = 'none';
          el.setAttribute('data-hidden-by-class', 'true');
          changedCount += 1;
        }
        const uid = String(el.getAttribute('data-uid') || '').trim();
        if (uid) {
          const overlay = overlayIndex.get(uid);
          if (overlay) overlay.style.display = 'none';
        }
      } else if (el.getAttribute('data-hidden-by-class') === 'true') {
        const orig = el.getAttribute('data-orig-display');
        if (orig !== null) {
          el.style.display = orig;
          el.removeAttribute('data-orig-display');
        } else {
          el.style.display = '';
        }
        el.removeAttribute('data-hidden-by-class');
        changedCount += 1;
        const uid = String(el.getAttribute('data-uid') || '').trim();
        if (uid) {
          const overlay = overlayIndex.get(uid);
          if (overlay) {
            overlay.style.display = '';
          } else {
            const classValue = String(el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
            if (classValue && CLASS_NAME_MASK_MAP[classValue]) {
              window.ensureElementClassOverlay?.(el);
            }
          }
        }
      }
    }, {
      shouldContinue: () => visibilityState.epoch === epoch,
    });
    if (!completed) return;
    invalidateSelectionSpatialIndex(svg);
    window.updateGlobalCategoryVisibilityCheckbox?.();
    const totalMs = roundPerfMs(performance.now() - startedAt);
    window.appendLoadingModalLog?.(`${changedCount} elements modifies en ${formatPerfMs(performance.now() - startedAt)}`);
    perfDebugLog('toggleCategoryVisibility', {
      class_id: classId,
      visible,
      scanned_count: targets.size,
      matched_count: targets.size,
      changed_count: changedCount,
      total_ms: totalMs,
    });
  });
};

window.toggleAllCategoryVisibility = async (checkbox) => {
  const visible = !!checkbox?.checked;
  await withBusyGuard('Visibilite', `${visible ? 'Afficher' : 'Masquer'} toutes les classes`, async () => {
    const startedAt = performance.now();
    const visibilityState = getClassVisibilityState();
    const epoch = visibilityState.epoch + 1;
    visibilityState.epoch = epoch;
    const checkboxes = Array.from(document.querySelectorAll('.tool-checkbox[data-class-id]'));
    checkboxes.forEach((item) => {
      item.checked = visible;
    });

    const svg = document.querySelector('.svg-clickable svg');
    let scannedCount = 0;
    let matchedCount = 0;
    let changedCount = 0;
    if (svg) {
      const overlayIndex = buildClassOverlayIndex(svg);
      if (!visible) {
        const elements = svg.querySelectorAll('path,line,polyline,polygon,rect,circle,ellipse,text,use');
        scannedCount = elements.length;
        window.appendLoadingModalLog?.(`Elements a parcourir: ${scannedCount}`);
        const elementList = Array.from(elements);
        const completed = await processInAnimationBatches(elementList, (el) => {
          // Skip overlays — they are controlled via their primitive's data-uid lookup
          if (el.hasAttribute('data-class-overlay-for')) return;
          const classNode = el.closest('[classId],[classid]');
          if (!classNode) return;
          const classValue = String(classNode.getAttribute('classId') || classNode.getAttribute('classid') || '').trim().toLowerCase();
          if (!classValue) return;
          matchedCount += 1;
          if (el.getAttribute('data-hidden-by-class') !== 'true') {
            if (!el.hasAttribute('data-orig-display')) {
              el.setAttribute('data-orig-display', el.style.display || '');
            }
            el.style.display = 'none';
            el.setAttribute('data-hidden-by-class', 'true');
            changedCount += 1;
          }
          const uid = String(el.getAttribute('data-uid') || '').trim();
          if (uid) {
            const overlay = overlayIndex.get(uid);
            if (overlay) overlay.style.display = 'none';
          }
        }, {
          shouldContinue: () => visibilityState.epoch === epoch,
        });
        if (!completed) return;
      } else {
        const elements = svg.querySelectorAll('[data-hidden-by-class="true"]');
        scannedCount = elements.length;
        window.appendLoadingModalLog?.(`Elements masques a restaurer: ${scannedCount}`);
        const elementList = Array.from(elements);
        const completed = await processInAnimationBatches(elementList, (el) => {
          matchedCount += 1;
          const orig = el.getAttribute('data-orig-display');
          if (orig !== null) {
            el.style.display = orig;
            el.removeAttribute('data-orig-display');
          } else {
            el.style.display = '';
          }
          el.removeAttribute('data-hidden-by-class');
          changedCount += 1;

          const uid = String(el.getAttribute('data-uid') || '').trim();
          if (uid) {
            const overlay = overlayIndex.get(uid);
            if (overlay) {
              overlay.style.display = '';
            } else {
              const classValue = String(el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
              if (classValue && CLASS_NAME_MASK_MAP[classValue]) {
                window.ensureElementClassOverlay?.(el);
              }
            }
          }
        }, {
          shouldContinue: () => visibilityState.epoch === epoch,
        });
        if (!completed) return;
      }
    }

    if (svg) invalidateSelectionSpatialIndex(svg);
    window.updateGlobalCategoryVisibilityCheckbox?.();
    if (checkbox instanceof HTMLInputElement) {
      checkbox.indeterminate = false;
    }
    const totalMs = roundPerfMs(performance.now() - startedAt);
    window.appendLoadingModalLog?.(`${changedCount} elements modifies en ${formatPerfMs(performance.now() - startedAt)}`);
    perfDebugLog('toggleAllCategoryVisibility', {
      target_visible: visible,
      classes_count: checkboxes.length,
      scanned_count: scannedCount,
      matched_count: matchedCount,
      changed_count: changedCount,
      total_ms: totalMs,
    });
  });
};

window.resetVisibilityCheckboxes = async () => {
  await withBusyGuard('Visibilite', 'Reinitialiser toutes les classes', async () => {
    const startedAt = performance.now();
    const checkboxes = document.querySelectorAll('.tool-checkbox[data-class-id]');
    checkboxes.forEach((checkbox) => {
      checkbox.checked = true;
    });
    window.updateGlobalCategoryVisibilityCheckbox?.();
    const svg = document.querySelector('.svg-clickable svg');
    if (!svg) return;
    const elements = svg.querySelectorAll('[data-hidden-by-class="true"]');
    const overlayIndex = buildClassOverlayIndex(svg);
    let restoredCount = 0;
    window.appendLoadingModalLog?.(`Elements masques a restaurer: ${elements.length}`);
    const elementList = Array.from(elements);
    await processInAnimationBatches(elementList, (el) => {
      const orig = el.getAttribute('data-orig-display');
      if (orig !== null) {
        el.style.display = orig;
        el.removeAttribute('data-orig-display');
      } else {
        el.style.display = '';
      }
      el.removeAttribute('data-hidden-by-class');
      restoredCount += 1;

      const uid = String(el.getAttribute('data-uid') || '').trim();
      if (uid) {
        const overlay = overlayIndex.get(uid);
        if (overlay) {
          overlay.style.display = '';
        } else {
          const classValue = String(el.getAttribute('classId') || el.getAttribute('classid') || '').trim().toLowerCase();
          if (classValue && CLASS_NAME_MASK_MAP[classValue]) {
            window.ensureElementClassOverlay?.(el);
          }
        }
      }
    });
    if (restoredCount > 0) invalidateSelectionSpatialIndex(svg);
    window.appendLoadingModalLog?.(`${restoredCount} elements restaures en ${formatPerfMs(performance.now() - startedAt)}`);
    perfDebugLog('resetVisibilityCheckboxes', {
      classes_count: checkboxes.length,
      scanned_count: elements.length,
      restored_count: restoredCount,
      total_ms: roundPerfMs(performance.now() - startedAt),
    });
  });
};

const getAnalysisOverlayState = () => {
  if (!window.__analysisOverlayState) {
    window.__analysisOverlayState = {activeActionId: ''};
  }
  return window.__analysisOverlayState;
};

window.clearAccessPathOverlays = (actionId = '') => {
  const targetAction = typeof actionId === 'string' ? actionId.trim() : '';
  const svgs = [document.querySelector('.svg-clickable svg')].filter(Boolean);
  svgs.forEach((svg) => {
    const selector = targetAction
      ? `[data-access-path-overlay="true"][data-analysis-action="${CSS.escape(targetAction)}"]`
      : '[data-access-path-overlay="true"]';
    svg.querySelectorAll(selector).forEach((node) => node.remove());
    // Restore elements hidden by analysis
    svg.querySelectorAll('[data-hidden-by-analysis="true"]').forEach((el) => {
      el.removeAttribute('data-hidden-by-analysis');
      el.style.display = '';
    });
  });
  const state = getAnalysisOverlayState();
  if (!targetAction || state.activeActionId === targetAction) {
    state.activeActionId = '';
  }
};

const ensureAccessPathLayer = (svg) => {
  if (!svg) return null;
  let layer = svg.querySelector('g[data-access-path-layer="true"]');
  if (!layer) {
    layer = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    layer.setAttribute('data-access-path-layer', 'true');
    layer.setAttribute('pointer-events', 'none');
    svg.appendChild(layer);
  }
  return layer;
};

window.renderAccessPathCircles = ({circles = [], paths = [], fills = [], labels = [], images = [], actionId = '', hide_class_ids = [], hide_uids = []} = {}) => {
  const svgs = [document.querySelector('.svg-clickable svg')].filter(Boolean);
  if (!svgs.length) return;

  const state = getAnalysisOverlayState();
  const targetAction = (typeof actionId === 'string' && actionId.trim()) ? actionId.trim() : 'analysis';
  if (state.activeActionId && state.activeActionId !== targetAction) {
    window.clearAccessPathOverlays?.(state.activeActionId);
  }
  window.clearAccessPathOverlays?.(targetAction);
  state.activeActionId = targetAction;

  const defaults = {
    circleStroke: '#00b300',
    circleFill: 'none',
    circleStrokeWidth: 0.25,
    pathStroke: '#00b300',
    pathStrokeWidth: 0.25,
    fillColor: '#60a5fa',
    fillStroke: '#1d4ed8',
    fillStrokeWidth: 0.15,
  };

  svgs.forEach((svg) => {
    const layer = ensureAccessPathLayer(svg);
    if (!layer) return;

    fills.forEach((item) => {
      const d = typeof item?.d === 'string' ? item.d.trim() : '';
      if (!d) return;
      const el = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      el.setAttribute('d', d);
      el.setAttribute('fill', item?.fill || defaults.fillColor);
      el.setAttribute('stroke', item?.stroke || defaults.fillStroke);
      el.setAttribute('stroke-width', String(item?.stroke_width ?? defaults.fillStrokeWidth));
      el.setAttribute('vector-effect', 'non-scaling-stroke');
      const fillOpacity = String(item?.opacity ?? 0.3);
      el.setAttribute('opacity', fillOpacity);
      el.setAttribute('fill-opacity', fillOpacity);
      if (item?.fill_rule) el.setAttribute('fill-rule', String(item.fill_rule));
      el.setAttribute('data-access-path-overlay', 'true');
      el.setAttribute('data-analysis-action', targetAction);
      if (item?.kind) el.setAttribute('data-access-path-kind', String(item.kind));
      layer.appendChild(el);
    });

    paths.forEach((item) => {
      const pts = Array.isArray(item?.points) ? item.points : [];
      if (pts.length < 2) return;
      const pointsAttr = pts.map((p) => `${p.x},${p.y}`).join(' ');
      const el = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
      el.setAttribute('points', pointsAttr);
      el.setAttribute('fill', 'none');
      el.setAttribute('stroke', item?.stroke || defaults.pathStroke);
      el.setAttribute('stroke-width', String(item?.stroke_width ?? defaults.pathStrokeWidth));
      if (!item?.no_vector_effect) el.setAttribute('vector-effect', 'non-scaling-stroke');
      if (item?.dash) el.setAttribute('stroke-dasharray', String(item.dash));
      el.setAttribute('opacity', String(item?.opacity ?? 1));
      el.setAttribute('data-access-path-overlay', 'true');
      el.setAttribute('data-analysis-action', targetAction);
      if (item?.kind) el.setAttribute('data-access-path-kind', String(item.kind));
      layer.appendChild(el);
    });

    circles.forEach((item) => {
      const cx = item?.cx;
      const cy = item?.cy;
      const r = item?.r;
      if (typeof cx !== 'number' || typeof cy !== 'number' || typeof r !== 'number') return;
      const el = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      el.setAttribute('cx', String(cx));
      el.setAttribute('cy', String(cy));
      el.setAttribute('r', String(r));
      el.setAttribute('stroke', item?.stroke || defaults.circleStroke);
      el.setAttribute('stroke-width', String(item?.stroke_width ?? defaults.circleStrokeWidth));
      el.setAttribute('fill', item?.fill ?? defaults.circleFill);
      el.setAttribute('vector-effect', 'non-scaling-stroke');
      if (item?.dash) el.setAttribute('stroke-dasharray', String(item.dash));
      el.setAttribute('opacity', String(item?.opacity ?? 1));
      el.setAttribute('data-access-path-overlay', 'true');
      el.setAttribute('data-analysis-action', targetAction);
      if (item?.kind) el.setAttribute('data-access-path-kind', String(item.kind));
      layer.appendChild(el);
    });

    labels.forEach((item) => {
      const x = item?.x;
      const y = item?.y;
      const textValue = String(item?.text || '').trim();
      if (typeof x !== 'number' || typeof y !== 'number' || !textValue) return;
      const el = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      el.setAttribute('x', String(x));
      el.setAttribute('y', String(y));
      el.setAttribute('fill', item?.fill || '#111827');
      el.setAttribute('stroke', item?.stroke || '#ffffff');
      el.setAttribute('stroke-width', String(item?.stroke_width ?? 0.08));
      el.setAttribute('paint-order', 'stroke');
      el.setAttribute('font-size', String(item?.font_size ?? 0.45));
      el.setAttribute('font-weight', String(item?.font_weight || 700));
      el.setAttribute('vector-effect', 'non-scaling-stroke');
      el.setAttribute('data-access-path-overlay', 'true');
      el.setAttribute('data-analysis-action', targetAction);
      if (item?.kind) el.setAttribute('data-access-path-kind', String(item.kind));
      el.textContent = textValue;
      layer.appendChild(el);
    });

    images.forEach((item) => {
      const href = typeof item?.href === 'string' ? item.href.trim() : '';
      if (!href) return;
      const el = document.createElementNS('http://www.w3.org/2000/svg', 'image');
      el.setAttribute('href', href);
      el.setAttribute('x', String(item?.x ?? 0));
      el.setAttribute('y', String(item?.y ?? 0));
      el.setAttribute('width', String(item?.width ?? 1));
      el.setAttribute('height', String(item?.height ?? 1));
      el.setAttribute('opacity', String(item?.opacity ?? 1));
      el.setAttribute('preserveAspectRatio', 'xMidYMid meet');
      if (item?.rotate != null) {
        const cx = item?.rotate_cx ?? (item.x + item.width / 2);
        const cy = item?.rotate_cy ?? (item.y + item.height / 2);
        el.setAttribute('transform', `rotate(${item.rotate} ${cx} ${cy})`);
      }
      el.setAttribute('data-access-path-overlay', 'true');
      el.setAttribute('data-analysis-action', targetAction);
      if (item?.kind) el.setAttribute('data-access-path-kind', String(item.kind));
      layer.appendChild(el);
    });

    // Hide original primitives matching hide_class_ids
    if (Array.isArray(hide_class_ids) && hide_class_ids.length > 0) {
      const hideSet = new Set(hide_class_ids);
      svg.querySelectorAll('[classId]').forEach((el) => {
        if (el.hasAttribute('data-access-path-overlay')) return;
        const classId = (el.getAttribute('classId') || '').trim();
        if (hideSet.has(classId)) {
          el.setAttribute('data-hidden-by-analysis', 'true');
          el.style.display = 'none';
        }
      });
      // Also hide class overlays for those classes
      svg.querySelectorAll('[data-class-overlay-for]').forEach((el) => {
        const forUid = (el.getAttribute('data-class-overlay-for') || '').trim();
        if (!forUid) return;
        const target = svg.querySelector(`[data-uid="${CSS.escape(forUid)}"]`);
        if (target && hideSet.has((target.getAttribute('classId') || '').trim())) {
          el.setAttribute('data-hidden-by-analysis', 'true');
          el.style.display = 'none';
        }
      });
    }

    // Hide specific primitives by data-uid
    if (Array.isArray(hide_uids) && hide_uids.length > 0) {
      const uidSet = new Set(hide_uids);
      svg.querySelectorAll('[data-uid]').forEach((el) => {
        if (el.hasAttribute('data-access-path-overlay')) return;
        const uid = (el.getAttribute('data-uid') || '').trim();
        if (uidSet.has(uid)) {
          el.setAttribute('data-hidden-by-analysis', 'true');
          el.style.display = 'none';
        }
      });
      // Also hide overlays for those UIDs
      svg.querySelectorAll('[data-class-overlay-for]').forEach((el) => {
        const forUid = (el.getAttribute('data-class-overlay-for') || '').trim();
        if (forUid && uidSet.has(forUid)) {
          el.setAttribute('data-hidden-by-analysis', 'true');
          el.style.display = 'none';
        }
      });
    }
  });
};

window.runAnalysisAction = async ({endpoint, actionId, errorLabel}) => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const label = errorLabel || 'Analyse';
  const startedAt = performance.now();
  window.openLoadingModal?.({
    title: `${label} en cours`,
    status: 'En cours',
    step: 'Sérialisation du SVG...',
  });
  try {
    const serializer = new XMLSerializer();
    const svgText = serializer.serializeToString(svg);
    window.appendLoadingModalLog?.(`SVG envoyé (${(svgText.length / 1024).toFixed(0)} KB)`);
    window.setLoadingModalStatus?.('Calcul', `Appel ${endpoint}...`);
    const res = await fetch(endpoint, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({svg: svgText}),
    });
    window.setLoadingModalStatus?.('Réception', 'Lecture de la réponse...');
    const data = await res.json();
    if (data?.ok) {
      window.setLoadingModalStatus?.('Affichage', 'Rendu des overlays...');
      await nextAnimationFrame();
      window.renderAccessPathCircles?.({
        circles: data?.circles || [],
        paths: data?.paths || [],
        fills: data?.fills || [],
        labels: data?.labels || [],
        images: data?.images || [],
        actionId,
        hide_class_ids: data?.hide_class_ids || [],
        hide_uids: data?.hide_uids || [],
      });
      window.appendLoadingModalLog?.(`Terminé en ${formatPerfMs(performance.now() - startedAt)}`);
      window.setLoadingModalStatus?.('Terminé', `${label} appliquée`);
      window.setTimeout(() => window.closeLoadingModal?.(), 400);
    } else {
      const msg = data?.error || 'unknown error';
      window.setLoadingModalStatus?.('Erreur', `${label}: ${msg}`);
      window.appendLoadingModalLog?.(String(msg), 'error');
      console.error(`${errorLabel} failed`, msg);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    window.setLoadingModalStatus?.('Erreur', `${label}: ${msg}`);
    window.appendLoadingModalLog?.(msg, 'error');
    console.error(`${errorLabel} failed`, err);
  }
};

window.runVlmInference = async () => {
  const svg = document.querySelector('.svg-clickable svg');
  if (!svg) return;
  const serializer = new XMLSerializer();
  const svgText = serializer.serializeToString(svg);
  window.openLoadingModal?.({
    title: 'Inference VLM',
    status: 'En cours',
    step: 'Analyse du SVG par le modele...',
  });
  window.appendLoadingModalLog?.(`SVG envoye (${(svgText.length / 1024).toFixed(0)} KB)`);
  window.appendLoadingModalLog?.('Cela peut prendre plusieurs minutes (tiling + vLLM).');
  try {
    const res = await fetch('/vlm-inference', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({svg: svgText}),
    });
    const data = await res.json();
    if (!data?.ok || typeof data?.svg !== 'string') {
      throw new Error(data?.error || 'Inference failed');
    }
    window.setLoadingModalStatus?.('Affichage', 'Chargement du SVG annote');
    window.appendLoadingModalLog?.(`SVG annote recu (${(data.svg.length / 1024).toFixed(0)} KB)`);
    window.applySvgText(data.svg);
    window.setLoadingModalStatus?.('Termine', 'Inference terminee');
    window.setTimeout(() => window.closeLoadingModal?.(), 500);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    window.setLoadingModalStatus?.('Erreur', 'Echec de l\'inference');
    window.appendLoadingModalLog?.(`Error: ${msg}`, 'error');
    console.error('VLM inference failed', err);
  }
};

