318→      background-image: linear-gradient(#555, #555);
319→    }
320→    body.svg-theme-dark .tool-separator { background: #555; }
321→    body.svg-theme-dark .tool-color { border-color: #777; }
322→    body.svg-theme-dark .tool-label { color: #d0d0d0; }
323→    body.svg-theme-dark .tool-key { color: #a0a0a0; }
324→    body.svg-theme-dark .palette-global-row { border-bottom-color: #555; }
325→  </style>
326→</head>
327→<body>
328→  <script>
329→    // Apply persisted theme synchronously, before the body content paints,
330→    // to avoid a flash of unstyled background on reload. Default = dark.
331→    (function () {
332→      try {
333→        var saved = localStorage.getItem('svgViewer.theme');
334→        if (saved === null || saved === 'dark') {
335→          document.body.classList.add('svg-theme-dark');
336→        }
337→      } catch (_) { document.body.classList.add('svg-theme-dark'); }
338→    })();
339→  </script>
340→  <div id="container">
341→    <div id="wrapper">${svgContent}</div>
342→  </div>
343→
344→  <aside id="class-toolbar" class="floating-class-toolbar">
345→    <div id="class-toolbar-title" class="palette-title">
346→      <span class="palette-title-label">Classes</span>
347→      <button id="class-toolbar-theme" class="palette-title-btn" type="button" title="Basculer thème sombre / clair">☀</button>
348→      <button id="class-toolbar-toggle" class="palette-title-btn" type="button" title="Collapse / expand">–</button>
349→    </div>
350→    <div id="class-toolbar-body" class="palette-body">
351→      <div class="palette-global-row">
352→        <input id="tool-checkbox-all-classes" class="tool-checkbox" type="checkbox" checked title="Toggle all classes" />
353→        <span class="tool-label">All classes</span>
354→        <span class="tool-key"></span>
355→      </div>
356→      ${toolbarRows}
357→    </div>
358→  </aside>
359→
360→  <script>
361→    // ── Pan / zoom ────────────────────────────────────────────────────
362→    // Drag = pan, wheel / two-finger trackpad scroll = zoom. No modifier
363→    // key required on any platform. On Mac, pinch-to-zoom on a trackpad
364→    // is reported as a wheel event with ctrlKey synthesised by the OS,
365→    // so the same handler covers both gestures naturally.
366→    let scale = 1, panX = 0, panY = 0;
367→    let isPanning = false, startX = 0, startY = 0;
368→    const container = document.getElementById('container');
369→    const wrapper = document.getElementById('wrapper');
370→    let svgEl = wrapper.querySelector('svg');
371→
372→    function updateTransform() {
373→      wrapper.style.transform = 'translate(' + panX + 'px,' + panY + 'px) scale(' + scale + ')';
374→    }
375→
376→    function fitToContent() {
377→      if (!svgEl) return;
378→      // Resolve the SVG's user-space dimensions. Prefer viewBox; fall
379→      // back to width/height attributes; bail out if neither is usable.
380→      let userW = 0, userH = 0, vbX = 0, vbY = 0;
381→      const vb = svgEl.viewBox && svgEl.viewBox.baseVal;
382→      if (vb && vb.width > 0 && vb.height > 0) {
383→        userW = vb.width; userH = vb.height; vbX = vb.x; vbY = vb.y;
384→      } else {
385→        userW = +(svgEl.getAttribute('width') || 0);
386→        userH = +(svgEl.getAttribute('height') || 0);
387→      }
388→      if (!userW || !userH) return;
389→      // Force the SVG to render at its user-space size so the wrapper's
390→      // scale factor maps 1 user unit → 1 CSS pixel. Without this, SVGs
391→      // that only declare a viewBox render at the browser default
392→      // (300×150) and primitives appear tiny in the corner.
393→      svgEl.setAttribute('width', String(userW));
394→      svgEl.setAttribute('height', String(userH));
395→      // Measure the bbox of actual primitives — ignore empty viewBox
396→      // padding so the content fills the window.
397→      let bbox = null;
398→      try { bbox = svgEl.getBBox(); } catch { bbox = null; }
399→      if (!bbox || !bbox.width || !bbox.height) {
400→        bbox = { x: vbX, y: vbY, width: userW, height: userH };
401→      }
402→      // Fit with a 5% margin, preserving aspect ratio.
403→      const margin = 0.92;
404→      scale = Math.min(
405→        container.clientWidth / bbox.width,
406→        container.clientHeight / bbox.height
407→      ) * margin;
408→      // Center the content bbox in the container, accounting for the
409→      // SVG's viewBox origin so non-zero vbX/vbY don't shift things.
410→      const cx = (bbox.x - vbX) + bbox.width / 2;
411→      const cy = (bbox.y - vbY) + bbox.height / 2;
412→      panX = container.clientWidth / 2 - cx * scale;
413→      panY = container.clientHeight / 2 - cy * scale;
414→      updateTransform();
415→    }
416→
417→    window.addEventListener('load', fitToContent);
418→
419→    container.addEventListener('wheel', (e) => {
420→      // Always zoom on wheel — works for mouse wheel, two-finger scroll,
421→      // and trackpad pinch (which the OS reports with ctrlKey set).
422→      e.preventDefault();
423→      const rect = container.getBoundingClientRect();
424→      const mx = e.clientX - rect.left, my = e.clientY - rect.top;
425→      // Pinch gestures send larger deltaY values than wheel ticks; damp
426→      // them so a pinch doesn't jump several zoom steps per frame.
427→      const intensity = e.ctrlKey ? 0.01 : 0.1;
428→      const f = Math.exp(-Math.sign(e.deltaY) * Math.min(Math.abs(e.deltaY) * intensity, 0.4));
429→      panX = mx - (mx - panX) * f;
430→      panY = my - (my - panY) * f;
431→      scale *= f;
432→      updateTransform();
433→    }, { passive: false });
434→
435→    function isInToolbar(target) {
436→      const tb = document.getElementById('class-toolbar');
437→      return !!(tb && tb.contains(target));
438→    }
439→
440→    container.addEventListener('mousedown', (e) => {
441→      if (e.button !== 0) return;
442→      if (isInToolbar(e.target)) return;
443→      isPanning = true;
444→      startX = e.clientX - panX;
445→      startY = e.clientY - panY;
446→      container.classList.add('grabbing');
447→      e.preventDefault();
448→    });
449→
450→    window.addEventListener('mousemove', (e) => {
451→      if (!isPanning) return;
452→      panX = e.clientX - startX;
453→      panY = e.clientY - startY;
454→      updateTransform();
455→    });
456→
457→    window.addEventListener('mouseup', () => {
458→      isPanning = false;
459→      container.classList.remove('grabbing');
460→    });
461→
462→    window.addEventListener('blur', () => {
463→      isPanning = false;
464→      container.classList.remove('grabbing');
465→    });
466→
467→    // ── Class visibility ──────────────────────────────────────────────
468→    const PRIMITIVE_TAGS = ['path','line','polyline','polygon','rect','circle','ellipse','text','use'];
469→
470→    function getClassIdLc(el) {
471→      const v = el.getAttribute('classId') || el.getAttribute('classid') || '';
472→      return String(v).trim().toLowerCase();
473→    }
474→
475→    function buildOverlayIndex() {
476→      const idx = new Map();
477→      if (!svgEl) return idx;
478→      svgEl.querySelectorAll('[data-class-overlay-for]').forEach((ov) => {
479→        const uid = String(ov.getAttribute('data-class-overlay-for') || '').trim();
480→        if (uid) idx.set(uid, ov);
481→      });
482→      return idx;
483→    }
484→
485→    function collectTargetsForClass(classIdLc) {
486→      const targets = new Set();
487→      if (!svgEl || !classIdLc) return targets;
488→      const nodes = svgEl.querySelectorAll('[classId],[classid]');
489→      nodes.forEach((node) => {
490→        if (node.hasAttribute('data-class-overlay-for')) return;
491→        if (getClassIdLc(node) !== classIdLc) return;
492→        const tag = (node.tagName || '').toLowerCase();
493→        if (PRIMITIVE_TAGS.includes(tag)) targets.add(node);
494→        node.querySelectorAll(PRIMITIVE_TAGS.join(',')).forEach((child) => targets.add(child));
495→      });
496→      return targets;
497→    }
498→
499→    function applyVisibility(classIdLc, visible) {
500→      const targets = collectTargetsForClass(classIdLc);
501→      const overlayIdx = buildOverlayIndex();
502→      targets.forEach((el) => {
503→        if (!visible) {
504→          if (el.getAttribute('data-hidden-by-class') !== 'true') {
505→            el.setAttribute('data-orig-display', el.style.display || '');
506→            el.style.display = 'none';
507→            el.setAttribute('data-hidden-by-class', 'true');
508→          }
509→          const uid = String(el.getAttribute('data-uid') || '').trim();
510→          if (uid) {
511→            const ov = overlayIdx.get(uid);
512→            if (ov) ov.style.display = 'none';
513→          }
514→        } else if (el.getAttribute('data-hidden-by-class') === 'true') {
515→          const orig = el.getAttribute('data-orig-display');
516→          el.style.display = orig !== null ? orig : '';
517→          el.removeAttribute('data-orig-display');
518→          el.removeAttribute('data-hidden-by-class');
519→          const uid = String(el.getAttribute('data-uid') || '').trim();
520→          if (uid) {
521→            const ov = overlayIdx.get(uid);
522→            if (ov) ov.style.display = '';
523→          }
524→        }
525→      });
526→    }
527→
528→    function updateGlobalCheckbox() {
529→      const global = document.getElementById('tool-checkbox-all-classes');
530→      const list = Array.from(document.querySelectorAll('.tool-checkbox[data-class-id]'));
531→      if (!list.length) { global.checked = true; global.indeterminate = false; return; }
532→      const checked = list.filter((cb) => cb.checked).length;
533→      global.checked = checked === list.length;
534→      global.indeterminate = checked > 0 && checked < list.length;
535→    }
536→
537→    document.querySelectorAll('.tool-checkbox[data-class-id]').forEach((cb) => {
538→      cb.addEventListener('change', () => {
539→        const classId = String(cb.dataset.classId || '').trim().toLowerCase();
540→        if (!classId) return;
541→        applyVisibility(classId, !!cb.checked);
542→        updateGlobalCheckbox();
543→      });
544→    });
545→
546→    const globalCb = document.getElementById('tool-checkbox-all-classes');
547→    globalCb.addEventListener('change', () => {
548→      const visible = !!globalCb.checked;
549→      document.querySelectorAll('.tool-checkbox[data-class-id]').forEach((cb) => {
550→        if (cb.checked !== visible) {
551→          cb.checked = visible;
552→          const classId = String(cb.dataset.classId || '').trim().toLowerCase();
553→          if (classId) applyVisibility(classId, visible);
554→        }
555→      });
556→      globalCb.indeterminate = false;
557→    });
558→
559→    // Collapse / expand toolbar.
560→    const collapseBtn = document.getElementById('class-toolbar-toggle');
561→    const toolbar = document.getElementById('class-toolbar');
562→    collapseBtn.addEventListener('click', () => {
563→      toolbar.classList.toggle('collapsed');
564→      collapseBtn.textContent = toolbar.classList.contains('collapsed') ? '+' : '–';
565→    });
566→
567→    // Theme toggle button.
568→    const themeBtn = document.getElementById('class-toolbar-theme');
569→    const refreshThemeBtn = () => {
570→      const dark = document.body.classList.contains('svg-theme-dark');
571→      themeBtn.textContent = dark ? '☀' : '☾';
572→      themeBtn.title = dark ? 'Passer en mode clair' : 'Passer en mode sombre';
573→    };
574→    themeBtn.addEventListener('click', () => {
575→      const wasDark = document.body.classList.contains('svg-theme-dark');
576→      document.body.classList.toggle('svg-theme-dark', !wasDark);
577→      try { localStorage.setItem('svgViewer.theme', wasDark ? 'light' : 'dark'); } catch (_) {}
578→      refreshThemeBtn();
579→    });
580→    refreshThemeBtn();
581→
582→    // Draggable title bar.
583→    function makeDraggable(toolbarEl, titleEl) {
584→      let dragging = false, dx = 0, dy = 0;
585→      titleEl.addEventListener('mousedown', (e) => {
586→        if (e.target instanceof HTMLButtonElement) return;
587→        dragging = true;
588→        const rect = toolbarEl.getBoundingClientRect();
589→        dx = e.clientX - rect.left;
590→        dy = e.clientY - rect.top;
591→        e.preventDefault();
592→        e.stopPropagation();
593→      });
594→      window.addEventListener('mousemove', (e) => {
595→        if (!dragging) return;
596→        const x = Math.max(0, Math.min(window.innerWidth - 40, e.clientX - dx));
597→        const y = Math.max(0, Math.min(window.innerHeight - 40, e.clientY - dy));
598→        toolbarEl.style.left = x + 'px';
599→        toolbarEl.style.top = y + 'px';
600→        toolbarEl.style.right = 'auto';
601→      });
602→      window.addEventListener('mouseup', () => { dragging = false; });
603→    }
604→    makeDraggable(toolbar, document.getElementById('class-toolbar-title'));
605→
606→    // ── Live reload on file change ────────────────────────────────────
607→    // Extension host watches the file and posts {type:'reload', svg}
608→    // whenever it changes on disk. Replace the SVG markup in place,
609→    // preserve current pan/zoom, and re-apply per-class visibility from
610→    // the toolbar checkbox state.
611→    function reapplyVisibility() {
612→      document.querySelectorAll('.tool-checkbox[data-class-id]').forEach((cb) => {
613→        const classId = String(cb.dataset.classId || '').trim().toLowerCase();
614→        if (classId) applyVisibility(classId, !!cb.checked);
615→      });
616→    }
617→
618→    window.addEventListener('message', (event) => {
619→      const msg = event.data;
620→      if (!msg || msg.type !== 'reload' || typeof msg.svg !== 'string') return;
621→      // Strip any leading XML declaration / DOCTYPE — innerHTML rejects them.
622→      const html = msg.svg.replace(/^\\s*<\\?xml[^>]*\\?>\\s*/, '').replace(/^\\s*<!DOCTYPE[^>]*>\\s*/i, '');
623→      wrapper.innerHTML = html;
624→      svgEl = wrapper.querySelector('svg');
625→      // Pan/zoom transform stays as-is; user keeps their viewpoint.
626→      reapplyVisibility();
627→    });
628→  </script>
629→</body>
630→</html>`;
631→}
632→
633→export function deactivate() {}
