import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';

export function activate(context: vscode.ExtensionContext) {
  context.subscriptions.push(
    vscode.window.registerCustomEditorProvider(
      'svgViewer.svgPreview',
      new SvgEditorProvider(context),
      {
        supportsMultipleEditorsPerDocument: true,
        // Keep webview DOM + JS state alive on tab switch so pan/zoom and
        // the currently-displayed SVG persist instead of being rebuilt
        // (which resets the view and can briefly flash the previous SVG).
        webviewOptions: { retainContextWhenHidden: true },
      }
    )
  );

  context.subscriptions.push(
    vscode.commands.registerCommand('svgViewer.openPreview', (uri: vscode.Uri) => {
      vscode.commands.executeCommand(
        'vscode.openWith',
        uri,
        'svgViewer.svgPreview'
      );
    })
  );
}

class SvgEditorProvider implements vscode.CustomReadonlyEditorProvider {
  constructor(private readonly _context: vscode.ExtensionContext) {}

  openCustomDocument(uri: vscode.Uri): vscode.CustomDocument {
    return { uri, dispose: () => {} };
  }

  resolveCustomEditor(
    document: vscode.CustomDocument,
    webviewPanel: vscode.WebviewPanel
  ): void {
    webviewPanel.webview.options = { enableScripts: true };
    const svgContent = fs.readFileSync(document.uri.fsPath, 'utf8');
    const fileName = path.basename(document.uri.fsPath);
    webviewPanel.webview.html = getWebviewContent(svgContent, fileName);

    // Watch the file on disk and push fresh SVG content to the webview on
    // every change. The webview replaces the SVG markup in place while
    // preserving pan/zoom and the current class-visibility selection.
    const watcher = vscode.workspace.createFileSystemWatcher(
      new vscode.RelativePattern(
        vscode.Uri.file(path.dirname(document.uri.fsPath)),
        path.basename(document.uri.fsPath)
      )
    );
    const reload = () => {
      try {
        const svg = fs.readFileSync(document.uri.fsPath, 'utf8');
        webviewPanel.webview.postMessage({ type: 'reload', svg });
      } catch {
        // File may be momentarily missing during atomic rename — ignore.
      }
    };
    watcher.onDidChange(reload);
    watcher.onDidCreate(reload);
    webviewPanel.onDidDispose(() => watcher.dispose());
  }
}

// ── Class toolbar data ─────────────────────────────────────────────────
// Mirror of src/app/app.py _TOOLBAR_GROUPS combined with SVG_CATEGORIES
// (toolbar=1 entries only). Keep in sync manually with src/svg_categories.py.
type ClassEntry = { name: string; color: string; key: string };
type Separator = { separator: true };
type ToolbarItem = ClassEntry | Separator;

const TOOLBAR_ITEMS: ToolbarItem[] = [
