    }
    .palette-title-label { flex: 1; }
    .palette-title-btn {
      background: #fff;
      border: 1px solid #bbb;
      border-radius: 3px;
      font-size: 10px;
      padding: 0 5px;
      cursor: pointer;
      line-height: 14px;
    }
    .palette-title-btn:hover { background: #f0f0f0; }
    .palette-body {
      padding: 4px 6px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      column-gap: 8px;
      row-gap: 1px;
      background-image: linear-gradient(#d1d1d1, #d1d1d1);
      background-size: 1px 100%;
      background-position: center top;
      background-repeat: no-repeat;
      overflow-y: auto;
      max-height: calc(100vh - 50px);
    }
    .palette-body > .tool-color-row:first-child { grid-column: 1 / -1; }
    .tool-color-row {
      display: grid;
      grid-template-columns: 12px 12px 1fr auto;
      align-items: center;
      gap: 4px;
      width: 100%;
    }
    .tool-separator {
      grid-column: 1 / -1;
      width: 100%;
      height: 1px;
      background: #d1d1d1;
      margin: 1px 0;
    }
    .tool-checkbox {
      width: 12px; height: 12px; margin: 0; cursor: pointer; outline: none;
    }
    .tool-color {
      width: 12px; height: 12px;
      display: inline-block;
      border: 1px solid #888;
