    body.svg-theme-dark #wrapper svg [classid="others"][stroke]:not([stroke="none"]),
    body.svg-theme-dark #wrapper svg [classId="others"][stroke]:not([stroke="none"]) { stroke: #ffffff; }
    body.svg-theme-dark #wrapper svg [classid="others"]:not([fill="none"]),
    body.svg-theme-dark #wrapper svg [classId="others"]:not([fill="none"]) { fill: #ffffff; }
    body.svg-theme-dark #wrapper svg [classid="texture"][stroke]:not([stroke="none"]),
    body.svg-theme-dark #wrapper svg [classId="texture"][stroke]:not([stroke="none"]) { stroke: #7f7f7f; }
    body.svg-theme-dark #wrapper svg [classid="texture"]:not([fill="none"]),
    body.svg-theme-dark #wrapper svg [classId="texture"]:not([fill="none"]) { fill: #7f7f7f; }
    body.svg-theme-dark #wrapper svg [classid="unlabelled"][stroke]:not([stroke="none"]),
    body.svg-theme-dark #wrapper svg [classId="unlabelled"][stroke]:not([stroke="none"]) { stroke: #bfbfbf; }
    body.svg-theme-dark #wrapper svg [classid="unlabelled"]:not([fill="none"]),
    body.svg-theme-dark #wrapper svg [classId="unlabelled"]:not([fill="none"]) { fill: #bfbfbf; }
    /* Toolbar swatches — small fixed set; filter is fine here. */
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="text"],
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="others"],
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="texture"],
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="unlabelled"] {
