function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  } as Record<string, string>)[c]);
}

function renderToolbarRows(): string {
  return TOOLBAR_ITEMS.map((item) => {
    if ('separator' in item) {
      return '<div class="tool-separator"></div>';
    }
    const cid = item.name.toLowerCase();
    const label = escapeHtml(item.name);
    const keyText = item.key ? escapeHtml(item.key) : '';
    return (
      `<div class="tool-color-row">` +
        `<input class="tool-checkbox" type="checkbox" checked ` +
          `data-class-id="${escapeHtml(cid)}" ` +
          `title="Toggle ${label} visibility" />` +
        `<span class="tool-color" style="background:${item.color};" data-class-id="${escapeHtml(cid)}" title="${label}"></span>` +
        `<span class="tool-label">${label}</span>` +
        `<span class="tool-key">${keyText}</span>` +
      `</div>`
    );
  }).join('\n');
}

function getWebviewContent(svgContent: string, fileName: string): string {
  const toolbarRows = renderToolbarRows();
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>${escapeHtml(fileName)}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { background: #ffffff; height: 100vh; overflow: hidden; }
    #container {
      width: 100%; height: 100%;
