      cursor: grab;
      overflow: hidden;
      touch-action: none;
    }
    #container.grabbing { cursor: grabbing; }
    #wrapper { position: absolute; transform-origin: 0 0; }
    #wrapper svg { display: block; max-width: none; }

    /* ── Floating class toolbar (compact) ── */
    .floating-class-toolbar {
      position: fixed;
      top: 8px;
      right: 8px;
      z-index: 1000;
      width: 230px;
      max-height: calc(100vh - 16px);
      background: #fafafa;
      color: #222;
      border: 1px solid #c7c7c7;
      border-radius: 4px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.18);
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      display: flex;
      flex-direction: column;
    }
    .palette-title {
      padding: 3px 6px;
      font-weight: 600;
      font-size: 10px;
      background: #eaeaea;
      border-bottom: 1px solid #d6d6d6;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
      cursor: move;
      user-select: none;
    }
    .palette-title-label { flex: 1; }
    .palette-title-btn {
      background: #fff;
      border: 1px solid #bbb;
      border-radius: 3px;
      font-size: 10px;
      padding: 0 5px;
      cursor: pointer;
      line-height: 14px;
    }
    .palette-title-btn:hover { background: #f0f0f0; }
    .palette-body {
      padding: 4px 6px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      column-gap: 8px;
      row-gap: 1px;
      background-image: linear-gradient(#d1d1d1, #d1d1d1);
      background-size: 1px 100%;
      background-position: center top;
      background-repeat: no-repeat;
      overflow-y: auto;
      max-height: calc(100vh - 50px);
    }
    .palette-body > .tool-color-row:first-child { grid-column: 1 / -1; }
    .tool-color-row {
      display: grid;
      grid-template-columns: 12px 12px 1fr auto;
      align-items: center;
      gap: 4px;
      width: 100%;
    }
    .tool-separator {
      grid-column: 1 / -1;
      width: 100%;
      height: 1px;
      background: #d1d1d1;
      margin: 1px 0;
    }
    .tool-checkbox {
      width: 12px; height: 12px; margin: 0; cursor: pointer; outline: none;
    }
    .tool-color {
      width: 12px; height: 12px;
      display: inline-block;
      border: 1px solid #888;
      border-radius: 2px;
    }
    .tool-label { font-size: 10px; color: #222; line-height: 1.1; }
    .tool-key {
      font-size: 9px;
      color: #555;
      line-height: 1.1;
      justify-self: end;
      text-align: right;
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    }
    .palette-global-row {
      grid-column: 1 / -1;
      display: grid;
      grid-template-columns: 12px 1fr auto;
      align-items: center;
      gap: 4px;
      padding-bottom: 1px;
      border-bottom: 1px solid #d1d1d1;
      margin-bottom: 1px;
    }
    .palette-global-row .tool-label { font-weight: 600; }
    .floating-class-toolbar.collapsed .palette-body { display: none; }

    /* ── Dark mode (toggleable via title-bar button; default = dark) ── */
    body.svg-theme-dark { background: #2a2a2a; color: #e0e0e0; }
    /* Stroke override is gated on [stroke] being explicitly set to a non-"none"
       value — otherwise CSS would activate stroke on filled glyphs that have
       no stroke attribute and the default stroke-width=1 produces fat blobs. */
    body.svg-theme-dark #wrapper svg [classid="text"][stroke]:not([stroke="none"]),
    body.svg-theme-dark #wrapper svg [classId="text"][stroke]:not([stroke="none"]) { stroke: #dfdfdf; }
    body.svg-theme-dark #wrapper svg [classid="text"]:not([fill="none"]),
    body.svg-theme-dark #wrapper svg [classId="text"]:not([fill="none"]) { fill: #dfdfdf; }
    body.svg-theme-dark #wrapper svg [classid="others"][stroke]:not([stroke="none"]),
    body.svg-theme-dark #wrapper svg [classId="others"][stroke]:not([stroke="none"]) { stroke: #ffffff; }
    body.svg-theme-dark #wrapper svg [classid="others"]:not([fill="none"]),
    body.svg-theme-dark #wrapper svg [classId="others"]:not([fill="none"]) { fill: #ffffff; }
    body.svg-theme-dark #wrapper svg [classid="texture"][stroke]:not([stroke="none"]),
    body.svg-theme-dark #wrapper svg [classId="texture"][stroke]:not([stroke="none"]) { stroke: #7f7f7f; }
    body.svg-theme-dark #wrapper svg [classid="texture"]:not([fill="none"]),
    body.svg-theme-dark #wrapper svg [classId="texture"]:not([fill="none"]) { fill: #7f7f7f; }
    body.svg-theme-dark #wrapper svg [classid="unlabelled"][stroke]:not([stroke="none"]),
    body.svg-theme-dark #wrapper svg [classId="unlabelled"][stroke]:not([stroke="none"]) { stroke: #bfbfbf; }
    body.svg-theme-dark #wrapper svg [classid="unlabelled"]:not([fill="none"]),
    body.svg-theme-dark #wrapper svg [classId="unlabelled"]:not([fill="none"]) { fill: #bfbfbf; }
    /* Toolbar swatches — small fixed set; filter is fine here. */
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="text"],
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="others"],
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="texture"],
    body.svg-theme-dark .floating-class-toolbar .tool-color[data-class-id="unlabelled"] {
      filter: invert(1);
    }
    body.svg-theme-dark .floating-class-toolbar {
      background: #3a3a3a;
      color: #e0e0e0;
      border-color: #555;
    }
    body.svg-theme-dark .palette-title {
      background: #2e2e2e;
      border-bottom-color: #555;
      color: #e8e8e8;
    }
    body.svg-theme-dark .palette-title-btn {
      background: #4a4a4a;
      border-color: #666;
      color: #e0e0e0;
    }
    body.svg-theme-dark .palette-title-btn:hover { background: #525252; }
    body.svg-theme-dark .palette-body {
      background-image: linear-gradient(#555, #555);
    }
    body.svg-theme-dark .tool-separator { background: #555; }
    body.svg-theme-dark .tool-color { border-color: #777; }
    body.svg-theme-dark .tool-label { color: #d0d0d0; }
    body.svg-theme-dark .tool-key { color: #a0a0a0; }
    body.svg-theme-dark .palette-global-row { border-bottom-color: #555; }

    /* ── Measure tool ── */
    #measure-rect {
      position: fixed;
      border: 2px dashed rgba(0,120,255,0.7);
      background: rgba(0,120,255,0.08);
      pointer-events: none;
      z-index: 900;
      display: none;
    }
    #measure-info {
      position: fixed;
      top: 8px;
      left: 8px;
      z-index: 1001;
      background: rgba(0,0,0,0.75);
      color: #fff;
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
      font-size: 12px;
      padding: 4px 8px;
      border-radius: 4px;
      display: none;
      white-space: nowrap;
    }
  </style>
</head>
<body>
  <script>
    // Apply persisted theme synchronously, before the body content paints,
    // to avoid a flash of unstyled background on reload. Default = dark.
    (function () {
      try {
        var saved = localStorage.getItem('svgViewer.theme');
        if (saved === null || saved === 'dark') {
          document.body.classList.add('svg-theme-dark');
        }
      } catch (_) { document.body.classList.add('svg-theme-dark'); }
    })();
  </script>
  <div id="container">
    <div id="wrapper">${svgContent}</div>
  </div>

  <div id="measure-rect"></div>
  <div id="measure-info"></div>

  <aside id="class-toolbar" class="floating-class-toolbar">
    <div id="class-toolbar-title" class="palette-title">
      <span class="palette-title-label">Classes</span>
      <button id="class-toolbar-theme" class="palette-title-btn" type="button" title="Basculer thème sombre / clair">☀</button>
      <button id="class-toolbar-toggle" class="palette-title-btn" type="button" title="Collapse / expand">–</button>
    </div>
    <div id="class-toolbar-body" class="palette-body">
      <div class="palette-global-row">
        <input id="tool-checkbox-all-classes" class="tool-checkbox" type="checkbox" checked title="Toggle all classes" />
        <span class="tool-label">All classes</span>
        <span class="tool-key"></span>
      </div>
      ${toolbarRows}
    </div>
  </aside>

  <script>
    // ── Pan / zoom ────────────────────────────────────────────────────
    // Drag = pan, wheel / two-finger trackpad scroll = zoom. No modifier
    // key required on any platform. On Mac, pinch-to-zoom on a trackpad
    // is reported as a wheel event with ctrlKey synthesised by the OS,
    // so the same handler covers both gestures naturally.
    let scale = 1, panX = 0, panY = 0;
    let isPanning = false, startX = 0, startY = 0;
    const container = document.getElementById('container');
    const wrapper = document.getElementById('wrapper');
    let svgEl = wrapper.querySelector('svg');

    function updateTransform() {
      wrapper.style.transform = 'translate(' + panX + 'px,' + panY + 'px) scale(' + scale + ')';
    }

    function fitToContent() {
      if (!svgEl) return;
      // Resolve the SVG's user-space dimensions. Prefer viewBox; fall
      // back to width/height attributes; bail out if neither is usable.
      let userW = 0, userH = 0, vbX = 0, vbY = 0;
      const vb = svgEl.viewBox && svgEl.viewBox.baseVal;
      if (vb && vb.width > 0 && vb.height > 0) {
        userW = vb.width; userH = vb.height; vbX = vb.x; vbY = vb.y;
      } else {
        userW = +(svgEl.getAttribute('width') || 0);
        userH = +(svgEl.getAttribute('height') || 0);
      }
      if (!userW || !userH) return;
      // Force the SVG to render at its user-space size so the wrapper's
      // scale factor maps 1 user unit → 1 CSS pixel. Without this, SVGs
      // that only declare a viewBox render at the browser default
      // (300×150) and primitives appear tiny in the corner.
      svgEl.setAttribute('width', String(userW));
      svgEl.setAttribute('height', String(userH));
      // Measure the bbox of actual primitives — ignore empty viewBox
      // padding so the content fills the window.
      let bbox = null;
      try { bbox = svgEl.getBBox(); } catch { bbox = null; }
      if (!bbox || !bbox.width || !bbox.height) {
        bbox = { x: vbX, y: vbY, width: userW, height: userH };
      }
      // Fit with a 5% margin, preserving aspect ratio.
      const margin = 0.92;
      scale = Math.min(
        container.clientWidth / bbox.width,
        container.clientHeight / bbox.height
      ) * margin;
      // Center the content bbox in the container, accounting for the
      // SVG's viewBox origin so non-zero vbX/vbY don't shift things.
      const cx = (bbox.x - vbX) + bbox.width / 2;
      const cy = (bbox.y - vbY) + bbox.height / 2;
      panX = container.clientWidth / 2 - cx * scale;
      panY = container.clientHeight / 2 - cy * scale;
      updateTransform();
    }

    window.addEventListener('load', fitToContent);

    container.addEventListener('wheel', (e) => {
      // Always zoom on wheel — works for mouse wheel, two-finger scroll,
      // and trackpad pinch (which the OS reports with ctrlKey set).
      e.preventDefault();
      const rect = container.getBoundingClientRect();
      const mx = e.clientX - rect.left, my = e.clientY - rect.top;
      // Pinch gestures send larger deltaY values than wheel ticks; damp
      // them so a pinch doesn't jump several zoom steps per frame.
      const intensity = e.ctrlKey ? 0.01 : 0.1;
      const f = Math.exp(-Math.sign(e.deltaY) * Math.min(Math.abs(e.deltaY) * intensity, 0.4));
      panX = mx - (mx - panX) * f;
      panY = my - (my - panY) * f;
      scale *= f;
      updateTransform();
    }, { passive: false });

    function isInToolbar(target) {
      const tb = document.getElementById('class-toolbar');
      return !!(tb && tb.contains(target));
    }

    container.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return;
      if (isInToolbar(e.target)) return;
      isPanning = true;
      startX = e.clientX - panX;
      startY = e.clientY - panY;
      container.classList.add('grabbing');
      e.preventDefault();
    });

    window.addEventListener('mousemove', (e) => {
      if (!isPanning) return;
      panX = e.clientX - startX;
      panY = e.clientY - startY;
      updateTransform();
    });

    window.addEventListener('mouseup', () => {
      isPanning = false;
      container.classList.remove('grabbing');
    });

    window.addEventListener('blur', () => {
      isPanning = false;
      container.classList.remove('grabbing');
    });

    // ── Class visibility ──────────────────────────────────────────────
    const PRIMITIVE_TAGS = ['path','line','polyline','polygon','rect','circle','ellipse','text','use'];

    function getClassIdLc(el) {
      const v = el.getAttribute('classId') || el.getAttribute('classid') || '';
      return String(v).trim().toLowerCase();
    }

    function buildOverlayIndex() {
      const idx = new Map();
      if (!svgEl) return idx;
      svgEl.querySelectorAll('[data-class-overlay-for]').forEach((ov) => {
        const uid = String(ov.getAttribute('data-class-overlay-for') || '').trim();
        if (uid) idx.set(uid, ov);
      });
      return idx;
    }

    function collectTargetsForClass(classIdLc) {
      const targets = new Set();
      if (!svgEl || !classIdLc) return targets;
      const nodes = svgEl.querySelectorAll('[classId],[classid]');
      nodes.forEach((node) => {
        if (node.hasAttribute('data-class-overlay-for')) return;
        if (getClassIdLc(node) !== classIdLc) return;
        const tag = (node.tagName || '').toLowerCase();
        if (PRIMITIVE_TAGS.includes(tag)) targets.add(node);
        node.querySelectorAll(PRIMITIVE_TAGS.join(',')).forEach((child) => targets.add(child));
      });
      return targets;
    }

    function applyVisibility(classIdLc, visible) {
      const targets = collectTargetsForClass(classIdLc);
      const overlayIdx = buildOverlayIndex();
      targets.forEach((el) => {
        if (!visible) {
          if (el.getAttribute('data-hidden-by-class') !== 'true') {
            el.setAttribute('data-orig-display', el.style.display || '');
            el.style.display = 'none';
            el.setAttribute('data-hidden-by-class', 'true');
          }
          const uid = String(el.getAttribute('data-uid') || '').trim();
          if (uid) {
            const ov = overlayIdx.get(uid);
            if (ov) ov.style.display = 'none';
          }
        } else if (el.getAttribute('data-hidden-by-class') === 'true') {
          const orig = el.getAttribute('data-orig-display');
          el.style.display = orig !== null ? orig : '';
          el.removeAttribute('data-orig-display');
          el.removeAttribute('data-hidden-by-class');
          const uid = String(el.getAttribute('data-uid') || '').trim();
          if (uid) {
            const ov = overlayIdx.get(uid);
            if (ov) ov.style.display = '';
          }
        }
      });
    }

    function updateGlobalCheckbox() {
      const global = document.getElementById('tool-checkbox-all-classes');
      const list = Array.from(document.querySelectorAll('.tool-checkbox[data-class-id]'));
      if (!list.length) { global.checked = true; global.indeterminate = false; return; }
      const checked = list.filter((cb) => cb.checked).length;
      global.checked = checked === list.length;
      global.indeterminate = checked > 0 && checked < list.length;
    }

    document.querySelectorAll('.tool-checkbox[data-class-id]').forEach((cb) => {
      cb.addEventListener('change', () => {
        const classId = String(cb.dataset.classId || '').trim().toLowerCase();
        if (!classId) return;
        applyVisibility(classId, !!cb.checked);
        updateGlobalCheckbox();
      });
    });

    const globalCb = document.getElementById('tool-checkbox-all-classes');
    globalCb.addEventListener('change', () => {
      const visible = !!globalCb.checked;
      document.querySelectorAll('.tool-checkbox[data-class-id]').forEach((cb) => {
        if (cb.checked !== visible) {
          cb.checked = visible;
          const classId = String(cb.dataset.classId || '').trim().toLowerCase();
          if (classId) applyVisibility(classId, visible);
        }
      });
      globalCb.indeterminate = false;
    });

    // Collapse / expand toolbar.
    const collapseBtn = document.getElementById('class-toolbar-toggle');
    const toolbar = document.getElementById('class-toolbar');
    collapseBtn.addEventListener('click', () => {
      toolbar.classList.toggle('collapsed');
      collapseBtn.textContent = toolbar.classList.contains('collapsed') ? '+' : '–';
    });

    // Theme toggle button.
    const themeBtn = document.getElementById('class-toolbar-theme');
    const refreshThemeBtn = () => {
      const dark = document.body.classList.contains('svg-theme-dark');
      themeBtn.textContent = dark ? '☀' : '☾';
      themeBtn.title = dark ? 'Passer en mode clair' : 'Passer en mode sombre';
    };
    themeBtn.addEventListener('click', () => {
      const wasDark = document.body.classList.contains('svg-theme-dark');
      document.body.classList.toggle('svg-theme-dark', !wasDark);
      try { localStorage.setItem('svgViewer.theme', wasDark ? 'light' : 'dark'); } catch (_) {}
      refreshThemeBtn();
    });
    refreshThemeBtn();

    // Draggable title bar.
    function makeDraggable(toolbarEl, titleEl) {
      let dragging = false, dx = 0, dy = 0;
      titleEl.addEventListener('mousedown', (e) => {
        if (e.target instanceof HTMLButtonElement) return;
        dragging = true;
        const rect = toolbarEl.getBoundingClientRect();
        dx = e.clientX - rect.left;
        dy = e.clientY - rect.top;
        e.preventDefault();
        e.stopPropagation();
      });
      window.addEventListener('mousemove', (e) => {
        if (!dragging) return;
        const x = Math.max(0, Math.min(window.innerWidth - 40, e.clientX - dx));
        const y = Math.max(0, Math.min(window.innerHeight - 40, e.clientY - dy));
        toolbarEl.style.left = x + 'px';
        toolbarEl.style.top = y + 'px';
        toolbarEl.style.right = 'auto';
      });
      window.addEventListener('mouseup', () => { dragging = false; });
    }
    makeDraggable(toolbar, document.getElementById('class-toolbar-title'));

    // ── Measure tool (Ctrl/Cmd + drag) ──────────────────────────────
    // Hold Ctrl (or Cmd on Mac), click and drag to draw a measurement
    // rectangle.  The dimensions in cm (SVG units × 10) are shown in a
    // small floating label at the top-left.  On mouse-up the rectangle
    // disappears and no selection is made.
    const measureRect = document.getElementById('measure-rect');
    const measureInfo = document.getElementById('measure-info');
    let measuring = false, msx = 0, msy = 0;

    container.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return;
      if (!(e.ctrlKey || e.metaKey)) return;
      if (isInToolbar(e.target)) return;
      e.preventDefault();
      e.stopPropagation();
      measuring = true;
      msx = e.clientX;
      msy = e.clientY;
      measureRect.style.left = msx + 'px';
      measureRect.style.top = msy + 'px';
      measureRect.style.width = '0px';
      measureRect.style.height = '0px';
      measureRect.style.display = 'block';
      measureInfo.style.display = 'block';
      measureInfo.textContent = '0 cm × 0 cm';
    }, true);  // capture phase — runs before the pan handler

    window.addEventListener('mousemove', (e) => {
      if (!measuring) return;
      const x = Math.min(msx, e.clientX);
      const y = Math.min(msy, e.clientY);
      const w = Math.abs(e.clientX - msx);
      const h = Math.abs(e.clientY - msy);
      measureRect.style.left = x + 'px';
      measureRect.style.top = y + 'px';
      measureRect.style.width = w + 'px';
      measureRect.style.height = h + 'px';
      // Convert screen pixels to SVG units via the current zoom scale,
      // then to cm (1 SVG unit = 10 cm).
      const CM_PER_UNIT = 10;
      const wCm = (w / scale * CM_PER_UNIT).toFixed(0);
      const hCm = (h / scale * CM_PER_UNIT).toFixed(0);
      measureInfo.textContent = wCm + ' cm × ' + hCm + ' cm';
    });

    window.addEventListener('mouseup', (e) => {
      if (!measuring) return;
      measuring = false;
      measureRect.style.display = 'none';
      // Keep the info visible for 1.5s after release, then fade out.
      setTimeout(() => {
        if (!measuring) measureInfo.style.display = 'none';
      }, 1500);
    });

    // ── Live reload on file change ────────────────────────────────────
    // Extension host watches the file and posts {type:'reload', svg}
    // whenever it changes on disk. Replace the SVG markup in place,
    // preserve current pan/zoom, and re-apply per-class visibility from
    // the toolbar checkbox state.
    function reapplyVisibility() {
      document.querySelectorAll('.tool-checkbox[data-class-id]').forEach((cb) => {
        const classId = String(cb.dataset.classId || '').trim().toLowerCase();
        if (classId) applyVisibility(classId, !!cb.checked);
      });
    }

    window.addEventListener('message', (event) => {
      const msg = event.data;
      if (!msg || msg.type !== 'reload' || typeof msg.svg !== 'string') return;
      // Strip any leading XML declaration / DOCTYPE — innerHTML rejects them.
      const html = msg.svg.replace(/^\\s*<\\?xml[^>]*\\?>\\s*/, '').replace(/^\\s*<!DOCTYPE[^>]*>\\s*/i, '');
      wrapper.innerHTML = html;
      svgEl = wrapper.querySelector('svg');
      // Pan/zoom transform stays as-is; user keeps their viewpoint.
      reapplyVisibility();
    });
  </script>
</body>
</html>`;
