#!/bin/bash

set -e

IMAGE_NAME=${IMAGE_NAME:-ctai_app}

echo "=== Building ${IMAGE_NAME}:dev ==="
docker build -t ${IMAGE_NAME}:dev -f Dockerfile .

#!/bin/bash

set -euo pipefail

if [ -f .env ]; then
  set -a
  source .env
  set +a
fi

# Single image used by all three containers; mode is selected at run time
# via env vars (ANNOTATION=true / CHECK=true) and the right host paths.
IMAGE_NAME=${IMAGE_NAME:-ctai_app}
PASSWORD=${PASSWORD:-}
APP_PORT=${APP_PORT:-8080}

# --- Annotation containers (user1..user4) ---
USER1_CONTAINER=${USER1_CONTAINER:-ctai_app_user1}
USER1_HOST_PORT=${USER1_HOST_PORT:-8080}
USER1_ANNOT_DIR=${USER1_ANNOT_DIR:-$(pwd)/data/annot/plan/user1}

USER2_CONTAINER=${USER2_CONTAINER:-ctai_app_user2}
USER2_HOST_PORT=${USER2_HOST_PORT:-8082}
USER2_ANNOT_DIR=${USER2_ANNOT_DIR:-$(pwd)/data/annot/plan/user2}

USER3_CONTAINER=${USER3_CONTAINER:-ctai_app_user3}
USER3_HOST_PORT=${USER3_HOST_PORT:-8083}
USER3_ANNOT_DIR=${USER3_ANNOT_DIR:-$(pwd)/data/annot/plan/user3}

USER4_CONTAINER=${USER4_CONTAINER:-ctai_app_user4}
USER4_HOST_PORT=${USER4_HOST_PORT:-8084}
USER4_ANNOT_DIR=${USER4_ANNOT_DIR:-$(pwd)/data/annot/plan/user4}

# --- Check container ---
# No annotation mount: check mode reads only test data.
# - tests/ holds the fixture list (tests/test_pmr_basis.py) consumed at runtime.
# - .git is needed by _perf_git_log / _perf_git_head for the F1-per-commit table.
# - data/tests holds _performance.json and the per-fixture business JSONs
#   (read/write, the image copy is shadowed by the host copy).
# - data/svgs holds the fixture SVGs (read-only).
CHECK_CONTAINER=${CHECK_CONTAINER:-ctai_app_check}
CHECK_HOST_PORT=${CHECK_HOST_PORT:-8081}
TESTS_DIR=${TESTS_DIR:-$(pwd)/tests}
GIT_DIR=${GIT_DIR:-$(pwd)/.git}
CHECK_REF_DIR=${CHECK_REF_DIR:-$(pwd)/data/tests}
SVGS_DIR=${SVGS_DIR:-$(pwd)/data/svgs}

# --- Launch annotation containers ---
for i in 1 2 3 4; do
  eval "CONTAINER=\${USER${i}_CONTAINER}"
  eval "HOST_PORT=\${USER${i}_HOST_PORT}"
  eval "ANNOT_DIR=\${USER${i}_ANNOT_DIR}"

  echo "=== Running ${CONTAINER} (annotation, user${i}) on :${HOST_PORT} ==="
  docker run -d \
    --name "${CONTAINER}" \
    -e PORT="${APP_PORT}" \
    -e ANNOTATION=true \
    -e PASSWORD="${PASSWORD}" \
    -p "${HOST_PORT}:${APP_PORT}" \
    -v "${ANNOT_DIR}:/app/annotation" \
    ${IMAGE_NAME}:dev
done

echo "=== Running ${CHECK_CONTAINER} (check) on :${CHECK_HOST_PORT} ==="
docker run -d \
  --name "${CHECK_CONTAINER}" \
  -e PORT="${APP_PORT}" \
  -e CHECK=true \
  -e PASSWORD="${PASSWORD}" \
  -p "${CHECK_HOST_PORT}:${APP_PORT}" \
  -v "${TESTS_DIR}:/app/tests:ro" \
  -v "${GIT_DIR}:/app/.git:ro" \
  -v "${CHECK_REF_DIR}:/app/data/tests" \
  -v "${SVGS_DIR}:/app/data/svgs:ro" \
  ${IMAGE_NAME}:dev

