#!/bin/bash

set -euo pipefail

if [ -f .env ]; then
  set -a
  source .env
  set +a
fi

# Single image used by all three containers; mode is selected at run time
# via env vars (ANNOTATION=true / CHECK=true) and the right host paths.
IMAGE_NAME=${IMAGE_NAME:-ctai_app}
PASSWORD=${PASSWORD:-}
APP_PORT=${APP_PORT:-8080}

# --- Annotation containers (user1..user6) ---
USER1_CONTAINER=${USER1_CONTAINER:-ctai_app_user1}
USER1_HOST_PORT=${USER1_HOST_PORT:-8080}
USER1_ANNOT_DIR=${USER1_ANNOT_DIR:-$(pwd)/data/annot/plan/user1}

USER2_CONTAINER=${USER2_CONTAINER:-ctai_app_user2}
USER2_HOST_PORT=${USER2_HOST_PORT:-8082}
USER2_ANNOT_DIR=${USER2_ANNOT_DIR:-$(pwd)/data/annot/plan/user2}

USER3_CONTAINER=${USER3_CONTAINER:-ctai_app_user3}
USER3_HOST_PORT=${USER3_HOST_PORT:-8083}
USER3_ANNOT_DIR=${USER3_ANNOT_DIR:-$(pwd)/data/annot/plan/user3}

USER4_CONTAINER=${USER4_CONTAINER:-ctai_app_user4}
USER4_HOST_PORT=${USER4_HOST_PORT:-8084}
USER4_ANNOT_DIR=${USER4_ANNOT_DIR:-$(pwd)/data/annot/plan/user4}

USER5_CONTAINER=${USER5_CONTAINER:-ctai_app_user5}
USER5_HOST_PORT=${USER5_HOST_PORT:-8085}
USER5_ANNOT_DIR=${USER5_ANNOT_DIR:-$(pwd)/data/annot/plan/user5}

USER6_CONTAINER=${USER6_CONTAINER:-ctai_app_user6}
USER6_HOST_PORT=${USER6_HOST_PORT:-8086}
USER6_ANNOT_DIR=${USER6_ANNOT_DIR:-$(pwd)/data/annot/plan/user6}

# --- Check container ---
# No annotation mount: check mode reads only test data.
# - tests/ holds the fixture list (tests/test_pmr_basis.py) consumed at runtime.
# - .git is needed by _perf_git_log / _perf_git_head for the F1-per-commit table.
# - data/tests holds _performance.json and the per-fixture business JSONs
#   (read/write, the image copy is shadowed by the host copy).
# - data/svgs holds the fixture SVGs (read-only).
CHECK_CONTAINER=${CHECK_CONTAINER:-ctai_app_check}
CHECK_HOST_PORT=${CHECK_HOST_PORT:-8081}
TESTS_DIR=${TESTS_DIR:-$(pwd)/tests}
GIT_DIR=${GIT_DIR:-$(pwd)/.git}
CHECK_REF_DIR=${CHECK_REF_DIR:-$(pwd)/data/tests}
SVGS_DIR=${SVGS_DIR:-$(pwd)/data/svgs}

# --- Launch annotation containers ---
for i in 1 2 3 4 5 6; do
  eval "CONTAINER=\${USER${i}_CONTAINER}"
  eval "HOST_PORT=\${USER${i}_HOST_PORT}"
  eval "ANNOT_DIR=\${USER${i}_ANNOT_DIR}"

  echo "=== Running ${CONTAINER} (annotation, user${i}) on :${HOST_PORT} ==="
  docker run -d \
    --name "${CONTAINER}" \
    -e PORT="${APP_PORT}" \
    -e ANNOTATION=true \
    -e PASSWORD="${PASSWORD}" \
    -p "${HOST_PORT}:${APP_PORT}" \
    -v "${ANNOT_DIR}:/app/annotation" \
    ${IMAGE_NAME}:dev
done

echo "=== Running ${CHECK_CONTAINER} (check) on :${CHECK_HOST_PORT} ==="
docker run -d \
  --name "${CHECK_CONTAINER}" \
  -e PORT="${APP_PORT}" \
  -e CHECK=true \
  -e PASSWORD="${PASSWORD}" \
  -p "${CHECK_HOST_PORT}:${APP_PORT}" \
  -v "${TESTS_DIR}:/app/tests:ro" \
  -v "${GIT_DIR}:/app/.git:ro" \
  -v "${CHECK_REF_DIR}:/app/data/tests" \
  -v "${SVGS_DIR}:/app/data/svgs:ro" \
  ${IMAGE_NAME}:dev

#!/bin/bash

set -uo pipefail

if [ -f .env ]; then
  set -a
  source .env
  set +a
fi

USER1_CONTAINER=${USER1_CONTAINER:-ctai_app_user1}
USER2_CONTAINER=${USER2_CONTAINER:-ctai_app_user2}
USER3_CONTAINER=${USER3_CONTAINER:-ctai_app_user3}
USER4_CONTAINER=${USER4_CONTAINER:-ctai_app_user4}
USER5_CONTAINER=${USER5_CONTAINER:-ctai_app_user5}
USER6_CONTAINER=${USER6_CONTAINER:-ctai_app_user6}
CHECK_CONTAINER=${CHECK_CONTAINER:-ctai_app_check}

# Host paths mounted read/write by the run script. Kept in sync with
# 3_run_dockers.sh so we can chown them back to the host user after the
# containers stop.
USER1_ANNOT_DIR=${USER1_ANNOT_DIR:-$(pwd)/data/annot/plan/user1}
USER2_ANNOT_DIR=${USER2_ANNOT_DIR:-$(pwd)/data/annot/plan/user2}
USER3_ANNOT_DIR=${USER3_ANNOT_DIR:-$(pwd)/data/annot/plan/user3}
USER4_ANNOT_DIR=${USER4_ANNOT_DIR:-$(pwd)/data/annot/plan/user4}
USER5_ANNOT_DIR=${USER5_ANNOT_DIR:-$(pwd)/data/annot/plan/user5}
USER6_ANNOT_DIR=${USER6_ANNOT_DIR:-$(pwd)/data/annot/plan/user6}
CHECK_REF_DIR=${CHECK_REF_DIR:-$(pwd)/data/tests}

for name in "${USER1_CONTAINER}" "${USER2_CONTAINER}" "${USER3_CONTAINER}" "${USER4_CONTAINER}" "${USER5_CONTAINER}" "${USER6_CONTAINER}" "${CHECK_CONTAINER}"; do
  echo "=== Stopping ${name} ==="
  docker stop "${name}" 2>/dev/null || true
  docker rm "${name}" 2>/dev/null || true
done

# Restore host ownership on the read/write mounts. The container's
# entrypoint chowns them to the in-container app uid; without this
# pass, files written from inside Docker stay owned by that uid on
# the host and block git commits / dvc operations.
HOST_UID=$(id -u)
HOST_GID=$(id -g)

for path in "${USER1_ANNOT_DIR}" "${USER2_ANNOT_DIR}" "${USER3_ANNOT_DIR}" "${USER4_ANNOT_DIR}" "${USER5_ANNOT_DIR}" "${USER6_ANNOT_DIR}" "${CHECK_REF_DIR}"; do
  if [ -d "$path" ]; then
    echo "=== Restoring ownership of ${path} to ${HOST_UID}:${HOST_GID} ==="
    sudo chown -R "${HOST_UID}:${HOST_GID}" "$path"
  fi
done

"""Per-run memoization for analyze_* functions.

Many ``analyze_*`` functions in :mod:`src.geom` recursively call each other
with the same ``svg_text``. During a single PMR check pass, the same
threshold/door/room analysis can be recomputed dozens of times.

This module provides an opt-in cache that is only active inside an
``analysis_cache()`` context. Outside that context the decorated functions
behave exactly as before — the decorator is transparent.

Usage::

    from src.geom._run_cache import analysis_cache, cached_per_run

    @cached_per_run
    def analyze_door_threshold(svg_text, *, door_class_ids=None):
        ...

    with analysis_cache():
        compute_pmr_check(svg_text)  # all decorated calls share one cache

The cache is keyed on the function identity plus its arguments. ``svg_text``
is keyed by ``id()`` rather than content hash: a single PMR pass keeps a live
reference to the string, so the id is stable for the duration of the context.
Sets are normalized to ``frozenset``, lists to ``tuple``.
"""
from __future__ import annotations

import functools
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Any, Callable

# Per-context cache. None means "no active context, run normally".
_cache_ctx: ContextVar[dict | None] = ContextVar("_run_cache", default=None)


@contextmanager
def analysis_cache():
    """Enable memoization of @cached_per_run functions for the duration."""
    cache: dict = {}
    token = _cache_ctx.set(cache)
    try:
        yield cache
    finally:
        _cache_ctx.reset(token)


def _normalize(value: Any) -> Any:
    """Make argument values hashable and stable for cache keys.

    - ``str``: keyed by ``id()`` (svg_text is large; identity is enough
      because the active context holds a live reference).
    - ``set`` / ``frozenset``: converted to ``frozenset``.
    - ``list`` / ``tuple``: converted to ``tuple`` of normalized items.
    - ``dict``: converted to a sorted tuple of normalized ``(k, v)`` pairs.
    - other types: returned as-is (must be hashable).
    """
    if isinstance(value, str):
        return ("str", id(value))
    if isinstance(value, (set, frozenset)):
        return frozenset(value)
    if isinstance(value, (list, tuple)):
        return tuple(_normalize(v) for v in value)
    if isinstance(value, dict):
        return tuple(sorted((k, _normalize(v)) for k, v in value.items()))
    return value


def cached_per_run(fn: Callable) -> Callable:
    """Memoize ``fn`` per active :func:`analysis_cache` context.

    Outside an active context the call is uncached and the original function
    runs as-is.
    """
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        cache = _cache_ctx.get()
        if cache is None:
            return fn(*args, **kwargs)
        key = (
            fn.__module__,
            fn.__qualname__,
            tuple(_normalize(a) for a in args),
            tuple(sorted((k, _normalize(v)) for k, v in kwargs.items())),
        )
        if key in cache:
            return cache[key]
        result = fn(*args, **kwargs)
        cache[key] = result
        return result
    return wrapper

