# ── Check mode: business validation against test_pmr_basis fixtures ─────────

CHECK_REF_DIR = Path("data/tests")
_CHECK_LAST_FIXTURE_PATH = CHECK_REF_DIR / "_current_check_fixture.txt"
_CHECK_VALID_STATUSES = {"none", "ok", "ko"}


def _check_load_fixtures() -> list[Path]:
    """Return the SVG fixtures listed in tests/test_pmr_basis.py.

    The list is the source of truth for both the unit test and the check
    panel — we read it from the test module rather than duplicating the
    paths here. We first try a normal import (works in dev where pytest
    is installed); if that fails (e.g. minimal runtime images that skip
    dev deps), we fall back to parsing the source with ast so the UI
    stays populated without shipping pytest in production.
    """
    import importlib.util

    test_path = Path("tests/test_pmr_basis.py")
    if not test_path.is_file():
        return []
    spec = importlib.util.spec_from_file_location("_test_pmr_basis_for_check", test_path)
    if spec is not None and spec.loader is not None:
        module = importlib.util.module_from_spec(spec)
        try:
            spec.loader.exec_module(module)
            fixtures = getattr(module, "SVG_FIXTURES", None)
            if fixtures:
                return [Path(p) for p in fixtures]
        except Exception:
            pass

    # AST fallback: resolve `SVG_DIR = Path("...")` and the list elements
    # `SVG_DIR / "filename.svg"` without executing module-level imports.
    import ast

    try:
        tree = ast.parse(test_path.read_text(encoding="utf-8"))
    except Exception:
        return []
    svg_dir: Path | None = None
    fixture_list: list[Path] = []
    for node in tree.body:
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if not isinstance(target, ast.Name):
                continue
            if target.id == "SVG_DIR":
                val = node.value
                if (isinstance(val, ast.Call) and isinstance(val.func, ast.Name)
                        and val.func.id == "Path" and val.args
                        and isinstance(val.args[0], ast.Constant)
                        and isinstance(val.args[0].value, str)):
                    svg_dir = Path(val.args[0].value)
            elif target.id == "SVG_FIXTURES" and isinstance(node.value, ast.List):
                for elt in node.value.elts:
                    if (isinstance(elt, ast.BinOp) and isinstance(elt.op, ast.Div)
                            and isinstance(elt.left, ast.Name) and elt.left.id == "SVG_DIR"
                            and isinstance(elt.right, ast.Constant)
                            and isinstance(elt.right.value, str)
                            and svg_dir is not None):
                        fixture_list.append(svg_dir / elt.right.value)
    return fixture_list


def _check_business_path(svg_path: Path) -> Path:
    """Return the business JSON path for a given SVG fixture."""
    return CHECK_REF_DIR / f"{svg_path.stem}_business.json"


def _pmr_cache_load(svg_path: Path) -> dict | None:
    """Load PMR incidents from the cache written by the unit tests."""
    path = CHECK_REF_DIR / f"{svg_path.stem}_pmr_cache.json"
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else None
    except Exception:
        return None


_CHECK_COMMENTS_KEY = "_comments"


def _check_default_business() -> dict:
    """Return a fresh empty business state (no decisions yet)."""
    return {_CHECK_COMMENTS_KEY: {}}


def _check_load_business(svg_path: Path) -> dict:
    """Load instance-level business state for a fixture.

    New format: {rule_code: {"0": "ok"|"ko"|"none", ...}, "_comments": {rule_code: {"0": text, ...}}}.
    Old format (plain string per rule) is ignored/invalidated.
    """
    business: dict = {_CHECK_COMMENTS_KEY: {}}
    json_path = _check_business_path(svg_path)
    if not json_path.is_file():
        return business
    try:
        saved = json.loads(json_path.read_text(encoding="utf-8"))
    except Exception:
        return business
    if not isinstance(saved, dict):
        return business
    valid_codes = {rule["code"] for rule in PMR_RULES}
    for key, val in saved.items():
        if key == _CHECK_COMMENTS_KEY:
            if isinstance(val, dict):
                loaded: dict = {}
                for k, v in val.items():
                    if not isinstance(k, str):
                        continue
                    if isinstance(v, dict):
                        # New format: {rule_code: {idx_str: text}}
                        inner = {ik: iv for ik, iv in v.items()
                                 if isinstance(ik, str) and isinstance(iv, str) and iv.strip()}
                        if inner:
                            loaded[k] = inner
                    elif isinstance(v, str) and v.strip():
                        # Old format: {rule_code: text} — keep as-is for display
                        loaded[k] = v
                business[_CHECK_COMMENTS_KEY] = loaded
        elif key in valid_codes and isinstance(val, dict):
            # New per-instance format: {idx_str: status}
            business[key] = {
                idx: status for idx, status in val.items()
                if isinstance(idx, str) and status in _CHECK_VALID_STATUSES
            }
        # Old format (plain string value) → silently ignored
    return business


def _check_save_business(svg_path: Path, business: dict) -> None:
    """Persist instance-level business state."""
    valid_codes = {rule["code"] for rule in PMR_RULES}
    cleaned: dict = {}
    for key, val in business.items():
        if key == _CHECK_COMMENTS_KEY:
            if isinstance(val, dict):
                comments: dict = {}
                for k, v in val.items():
                    if not isinstance(k, str):
                        continue
                    if isinstance(v, dict):
                        # New format: {rule_code: {idx_str: text}}
                        inner = {ik: iv.strip() for ik, iv in v.items()
                                 if isinstance(ik, str) and isinstance(iv, str) and iv.strip()}
                        if inner:
                            comments[k] = inner
                    elif isinstance(v, str) and v.strip():
                        comments[k] = v.strip()
                if comments:
                    cleaned[_CHECK_COMMENTS_KEY] = comments
        elif key in valid_codes and isinstance(val, dict):
            instance_decisions = {
                idx: status for idx, status in val.items()
                if isinstance(idx, str) and status in _CHECK_VALID_STATUSES
            }
            if instance_decisions:
                cleaned[key] = instance_decisions
    CHECK_REF_DIR.mkdir(parents=True, exist_ok=True)
    json_path = _check_business_path(svg_path)
    json_path.write_text(
        json.dumps(cleaned, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )


def _check_rules_payload() -> list[dict]:
    """Serializable rule list for the check panel (no callables)."""
    return [
        {
            "code": rule["code"],
            "title": rule["title"],
            "description": rule.get("description", ""),
            "category": rule.get("category", ""),
        }
        for rule in PMR_RULES
    ]


def _check_fixture_url(svg_path: Path) -> str:
    """Build the URL to fetch a fixture SVG (under data/svgs/)."""
    try:
        rel = svg_path.relative_to(Path("data"))
    except ValueError:
        rel = svg_path
    return "/data/" + str(rel).replace(os.sep, "/")


